INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'What does print() do?', NULL, NULL, 'Shows a value on the screen', 'Think of console.log in JavaScript.', 'print() writes its arguments to the output (the screen / notebook cell).', NULL, 'Same job as console.log or System.out.println.', 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Sends a file to the printer', 0), (@q, 'B', 'Creates a variable', 0), (@q, 'C', 'Saves a value to disk', 0), (@q, 'D', 'Shows a value on the screen', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'code_output', 'What does this print?', 'print("Hello", "AI", sep="-")', 'python', 'Hello-AI', 'sep is what goes BETWEEN the values.', 'sep=''-'' replaces the default space between arguments, so you get Hello-AI.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'HelloAI', 0), (@q, 'B', 'Hello-AI-', 0), (@q, 'C', 'Hello-AI', 1), (@q, 'D', 'Hello AI', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Which line is a comment in Python?', NULL, NULL, '# this is a comment', 'Python uses a single symbol you also see in hashtags.', 'Everything after # on a line is ignored by Python.', NULL, NULL, 3);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '/* this is a comment */', 0), (@q, 'B', '# this is a comment', 1), (@q, 'C', '// this is a comment', 0), (@q, 'D', '-- this is a comment', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'true_false', 'Indentation (spaces at the start of a line) changes how Python code runs.', NULL, NULL, 'True', 'Python has no curly braces { } for blocks.', 'Python uses indentation to mark which lines belong to an if, loop or function. Wrong indentation = IndentationError or wrong logic.', 'if x > 0:\n    print("inside")   <- 4 spaces: part of the if\nprint("outside")      <- 0 spaces: always runs', NULL, 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'code_output', 'What does this print?', 'print(7 / 2, 7 // 2, 7 % 2)', 'python', '3.5 3 1', '/ is normal division, // drops the decimals, % is the remainder.', '7/2 = 3.5, 7//2 = 3 (floor division), 7%2 = 1 (remainder).', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3.5 4 1', 0), (@q, 'B', '3.5 3 1', 1), (@q, 'C', '3 3 1', 0), (@q, 'D', '3.5 3.5 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'code_output', 'What does this print?', 'print(2 ** 3)', 'python', '8', '** is the power operator.', '2 ** 3 means 2 to the power 3 = 2 x 2 x 2 = 8.', NULL, NULL, 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '6', 0), (@q, 'B', '23', 0), (@q, 'C', '8', 1), (@q, 'D', '9', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'running'), 1, 'mcq', 'What is the Python REPL?', NULL, NULL, 'An interactive prompt that reads one line, runs it, prints the result, and waits for the next', 'REPL is short for four steps: Read, Eval, Print, Loop.', 'You get the REPL by typing `python` with no file. It''s a live playground: type an expression, see the answer immediately.', NULL, 'Like the browser DevTools console for JavaScript.', 7);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A tool that compiles .py files into .exe files', 0), (@q, 'B', 'The command that installs Python packages', 0), (@q, 'C', 'An interactive prompt that reads one line, runs it, prints the result, and waits for the next', 1), (@q, 'D', 'A text editor that ships with Python', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'running'), 1, 'mcq', 'You saved your code in a file called hello.py. Which terminal command runs it?', NULL, NULL, 'python hello.py', 'Name the program first, then the file you want it to run.', '`python hello.py` starts the Python interpreter and runs the file from top to bottom.', NULL, 'Same shape as `node app.js`.', 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'python -run hello', 0), (@q, 'B', 'exec hello.py', 0), (@q, 'C', 'run hello.py', 0), (@q, 'D', 'python hello.py', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'running'), 1, 'true_false', 'In a Jupyter notebook, if the last line of a cell is just an expression like `2 + 3`, the notebook shows 5 even without print().', NULL, NULL, 'True', 'Notebooks are friendlier than scripts here.', 'Notebooks (and the REPL) display the value of the last expression in a cell. A script shows nothing unless you call print().', NULL, NULL, 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 1, 'code_output', 'What does this print?', 'print("a", "b", "c")', 'python', 'a b c', 'What does print put between values by default?', 'print separates its arguments with a single space by default (sep='' '').', NULL, NULL, 10);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'a,b,c', 0), (@q, 'B', 'abc', 0), (@q, 'C', '(''a'', ''b'', ''c'')', 0), (@q, 'D', 'a b c', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 1, 'code_output', 'What does this print?', 'print("Hi", end="!")\nprint("There")', 'python', 'Hi!There', 'end replaces what print normally adds at the very end.', 'Normally print ends with a newline. end=''!'' puts ''!'' there instead, so the next print continues on the same line.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Hi!\nThere', 0), (@q, 'B', 'Hi!There', 1), (@q, 'C', 'Hi There!', 0), (@q, 'D', 'Hi\n!There', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 1, 'code_output', 'What does this print?', 'print("A")\nprint()\nprint("B")', 'python', 'A\n\nB', 'print() with nothing inside still prints its ending.', 'An empty print() outputs just the newline, giving a blank line between A and B.', NULL, NULL, 12);
