INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 1, 'true_false', 'print(''Hello'') and print("Hello") produce exactly the same output.', NULL, NULL, 'True', 'Are single and double quotes different kinds of string in Python?', 'Single and double quotes both make a str. Pick one style; switch when the text itself contains a quote.', NULL, NULL, 13);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comments'), 1, 'mcq', 'What happens when Python runs this line?', 'x = 5  # set x to five', 'python', 'It sets x to 5 and ignores everything after the #', '# means ''from here to the end of the line is for humans''.', 'Everything from # to the end of the line is a comment. Python only runs `x = 5`.', NULL, NULL, 14);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It prints ''set x to five''', 0), (@q, 'B', 'It sets x to the text ''5  # set x to five''', 0), (@q, 'C', 'It sets x to 5 and ignores everything after the #', 1), (@q, 'D', 'It raises a SyntaxError because of the text', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comments'), 1, 'true_false', 'Python has a block-comment syntax like /* ... */ from Java and JavaScript.', NULL, NULL, 'False', 'Think about which single symbol Python uses for comments.', 'Python only has # line comments. For several lines, put # on each line (editors do this with Ctrl+/).', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indentation'), 1, 'mcq', 'How much indentation does the official Python style guide (PEP 8) recommend per level?', NULL, NULL, '4 spaces', 'PEP 8 is Python''s shared style guide, like a team''s lint config.', 'PEP 8 recommends 4 spaces per indentation level. Editors usually insert 4 spaces when you press Tab in a .py file.', NULL, NULL, 16);
