INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 1, 'code_output', 'What does this print?', 'print(2 + 3 * 4)', 'python', '14', 'Same order of operations as school maths.', 'Multiplication happens before addition: 3 * 4 = 12, then 2 + 12 = 14.', NULL, NULL, 20);
