INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 1, 'code_output', 'What does this print?', 'print((2 + 3) * 4)', 'python', '20', 'Parentheses go first.', 'The brackets force 2 + 3 = 5 first, then 5 * 4 = 20.', NULL, NULL, 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '9', 0), (@q, 'B', '14', 0), (@q, 'C', '24', 0), (@q, 'D', '20', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'input'), 1, 'mcq', 'A user types 42 when your program calls input(). What type of value does input() give back?', NULL, NULL, 'str (text)', 'input() can''t know whether you wanted text or a number.', 'input() always returns a string, here ''42''. Convert it yourself with int() or float() if you need a number.', NULL, NULL, 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It depends on what the user typed', 0), (@q, 'B', 'float (decimal number)', 0), (@q, 'C', 'str (text)', 1), (@q, 'D', 'int (whole number)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'introspection'), 1, 'fill_blank', 'The built-in function that shows the documentation for any object is ____.', NULL, NULL, 'help', 'Its name is what you''d ask for when stuck.', 'help(print) shows print''s signature and description. In a notebook you can also type print? and run the cell.', NULL, NULL, 23);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'execution'), 1, 'mcq', 'Which statement best describes how you run Python code?', NULL, NULL, 'You run the source file directly with the python program; there''s no separate build step you run yourself', 'Think of `node app.js` compared with `javac` + `java`.', 'Python is used like an interpreted language: `python file.py` runs the source. (Under the hood it compiles to bytecode automatically, see the expert questions.)', NULL, NULL, 24);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'You must compile it with javac first, like Java', 0), (@q, 'B', 'It only runs inside a web browser', 0), (@q, 'C', 'You must compile it to an .exe first, like C', 0), (@q, 'D', 'You run the source file directly with the python program; there''s no separate build step you run yourself', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 2, 'code_output', 'What does this print?', 'print(1, 2, 3, sep="")', 'python', '123', 'sep is the glue between the values.', 'sep='''' means nothing goes between the values, so they are printed back to back.', NULL, NULL, 25);
