INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 2, 'code_output', 'What does this print?', 'print("a", "b", sep=", ", end=".\\n")\nprint("c")', 'python', 'a, b.\nc', 'sep goes between values, end goes after the last one.', 'sep='', '' joins a and b, then end=''.\\n'' adds a full stop and a newline, so c starts on the next line.', NULL, NULL, 26);
