INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 2, 'code_output', 'What does this print?', 'nums = [1, 2, 3]\nprint(*nums, sep="|")', 'python', '1|2|3', 'The * spreads the list out into separate arguments.', 'print(*nums) is the same as print(1, 2, 3). With sep=''|'' you get 1|2|3.', NULL, 'Like the JavaScript spread operator: console.log(...nums).', 27);
