INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 2, 'code_output', 'What does this print?', 'x = print("hi")\nprint(x)', 'python', 'hi\nNone', 'print shows something on the screen, but what does it give back?', 'print returns None. The first line shows ''hi'' and stores None in x; the second line prints None.', NULL, NULL, 28);
