INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 2, 'code_output', 'What does this print?', 'print(-7 // 2)', 'python', '-4', '// rounds down, and ''down'' means toward minus infinity.', '-7 / 2 is -3.5; floor division rounds it down to -4. Java and C would truncate to -3.', '   -4      -3.5     -3\n  --|-------*-------|--->\n  floor     |     truncate\n  (Python)  |     (Java/C)', NULL, 29);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '-3.5', 0), (@q, 'B', '-4', 1), (@q, 'C', '-3', 0), (@q, 'D', '-3.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 2, 'code_output', 'What does this print?', 'print(-7 % 3)', 'python', '2', 'In Python the remainder has the same sign as the number you divide BY.', '-7 // 3 is -3 (floor), and -3 * 3 + 2 == -7, so -7 % 3 is 2. JavaScript''s -7 % 3 gives -1.', NULL, NULL, 30);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '-2', 0), (@q, 'B', '1', 0), (@q, 'C', '-1', 0), (@q, 'D', '2', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 2, 'code_output', 'What does this print?', 'print(type(10 // 2), type(10 / 2))', 'python', '<class ''int''> <class ''float''>', 'Only one of these operators always returns a float.', '10 // 2 on two ints stays an int (5); 10 / 2 is always a float (5.0).', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '<class ''int''> <class ''int''>', 0), (@q, 'B', '<class ''float''> <class ''int''>', 0), (@q, 'C', '<class ''float''> <class ''float''>', 0), (@q, 'D', '<class ''int''> <class ''float''>', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 2, 'code_output', 'What does this print?', 'print(2 ** -1, 4 ** 0.5)', 'python', '0.5 2.0', 'A negative power means ''one over''; a power of 0.5 is a square root.', '2 ** -1 = 1/2 = 0.5, and 4 ** 0.5 = sqrt(4) = 2.0 (a float, because the exponent is a float).', NULL, NULL, 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '-2 2.0', 0), (@q, 'B', '0.5 2.0', 1), (@q, 'C', '0.5 2', 0), (@q, 'D', 'Error', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 2, 'code_output', 'What does this print?', 'print(2 ** 3 ** 2)', 'python', '512', 'With ** Python works from the right.', '** is right-associative: 2 ** (3 ** 2) = 2 ** 9 = 512, not (2 ** 3) ** 2 = 64.', NULL, NULL, 33);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '36', 0), (@q, 'B', '512', 1), (@q, 'C', '18', 0), (@q, 'D', '64', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 2, 'code_output', 'What does this print?', 'print(-2 ** 2)', 'python', '-4', 'Which binds tighter: the minus sign or the power?', '** binds before the unary minus, so this is -(2 ** 2) = -4. Write (-2) ** 2 to get 4.', NULL, NULL, 34);
