INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 2, 'code_output', 'What does this print?', 'print(not 1 == 2)', 'python', 'True', 'Does `not` apply to 1, or to the whole comparison?', '`not` has lower precedence than ==, so this is not (1 == 2) = not False = True.', NULL, NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Error', 0), (@q, 'B', '-1', 0), (@q, 'C', 'True', 1), (@q, 'D', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 2, 'code_output', 'What does this print?', 'print(7 // 2 * 2 + 7 % 2)', 'python', '7', '//, * and % have the same precedence and go left to right; + comes last.', '(7 // 2) * 2 = 6 and 7 % 2 = 1, so 6 + 1 = 7. This is the identity a == (a // b) * b + a % b.', NULL, NULL, 36);
