INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comments'), 2, 'mcq', 'What is a docstring?', NULL, NULL, 'A string written as the first statement of a function, class or module; Python stores it as the object''s documentation', 'It''s what help() shows you.', 'A string literal as the first statement becomes the object''s __doc__, which help() displays. Usually written with triple quotes.', NULL, 'Like a JSDoc / Javadoc comment, except Python keeps it at runtime.', 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A comment that starts with ##', 0), (@q, 'B', 'Any string longer than one line', 0), (@q, 'C', 'A string written as the first statement of a function, class or module; Python stores it as the object''s documentation', 1), (@q, 'D', 'A special file that documents a package', 0);
