INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 3, 'code_output', 'What does this print?', 'x = 1 if False else 2 + 10\nprint(x)', 'python', '12', 'The conditional expression `a if cond else b` has very low precedence.', 'It parses as 1 if False else (2 + 10), and the condition is False, so x = 12.', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1', 0), (@q, 'B', '2', 0), (@q, 'C', '11', 0), (@q, 'D', '12', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 3, 'code_output', 'What does this print?', 'import sys\nprint("loading...", file=sys.stderr)\nprint("result")', 'python', 'result', 'There are two output streams: standard output and standard error.', 'file=sys.stderr sends the first line to the error stream. Only stdout is captured here, so just ''result'' appears. Notebooks show stderr with a red background.', 'print(...)                 -> stdout  (normal output)\nprint(..., file=sys.stderr) -> stderr  (warnings, progress)\npython train.py > out.txt  -> only stdout goes to the file', NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'loading...', 0), (@q, 'B', 'loading...\nresult', 0), (@q, 'C', 'result\nloading...', 0), (@q, 'D', 'result', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 3, 'mcq', 'You run `nohup python train.py > log.txt &` and the per-epoch print() lines don''t appear in log.txt for minutes. Most likely reason?', NULL, NULL, 'stdout is buffered when it''s a file, not a terminal; use print(..., flush=True) or python -u', 'Python collects output in memory before writing it out.', 'When stdout isn''t a terminal it''s block-buffered, so lines wait in a buffer. flush=True, python -u, or PYTHONUNBUFFERED=1 write them immediately.', NULL, 'Like a database driver batching writes until the batch is full.', 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'print() doesn''t work when output is redirected', 0), (@q, 'B', 'stdout is buffered when it''s a file, not a terminal; use print(..., flush=True) or python -u', 1), (@q, 'C', 'nohup deletes output until the process stops', 0), (@q, 'D', 'The log file is only written when the script ends with exit code 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 3, 'code_output', 'What does this print?', 'print("data" "set", "ok")', 'python', 'dataset ok', 'Two string literals written side by side with no comma...', 'Adjacent string literals are joined at compile time, so ''data'' ''set'' is ''dataset''. A forgotten comma in a list of strings silently merges two items this way.', NULL, NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'dataset ok', 1), (@q, 'B', 'data set ok', 0), (@q, 'C', 'SyntaxError', 0), (@q, 'D', 'datasetok', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'input'), 3, 'mcq', 'A script calls input() but is run with its stdin connected to an empty file (`python app.py < empty.txt`). What happens?', NULL, NULL, 'input() raises EOFError', 'There is no line to read at all.', 'When the input stream ends with nothing to read, input() raises EOFError. An empty line typed by a user returns '''' instead.', NULL, NULL, 58);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'input() raises EOFError', 1), (@q, 'B', 'input() waits forever', 0), (@q, 'C', 'input() returns ''\\n''', 0), (@q, 'D', 'input() returns None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'running'), 3, 'true_false', 'In a notebook, deleting a cell that defined `df` also removes `df` from memory.', NULL, NULL, 'False', 'The notebook kernel is a long-running process.', 'The kernel keeps every variable until you restart it or `del` the name. This ''hidden state'' is why a notebook can work for you but fail top-to-bottom after Restart & Run All.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'running'), 3, 'true_false', 'If two modules both run `import config`, the top-level code in config.py runs only once per process.', NULL, NULL, 'True', 'Python keeps a registry of modules it has already loaded.', 'The first import executes the module and stores it in sys.modules; later imports reuse that object. That''s why editing a module needs a kernel restart or importlib.reload.', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'running'), 3, 'true_false', 'In the interactive REPL, the variable `_` holds the result of the last expression you evaluated.', NULL, NULL, 'True', 'Try typing 2 + 3 and then _ * 10 in the REPL.', 'The REPL stores the last displayed result in `_`. In a script `_` is just an ordinary name, often used for values you ignore.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comments'), 3, 'mcq', 'What does the first line of this file do?', '#!/usr/bin/env python3\nprint("hello")', 'python', 'On Linux/macOS it tells the shell which interpreter to use when you run ./script.py; Python itself treats it as a comment', 'It starts with #, so what does Python think of it?', 'The #! ''shebang'' line is read by the operating system when the file is executed directly. To Python it''s just a comment, and on Windows it''s mostly ignored.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It makes the file run faster', 0), (@q, 'B', 'It imports the python3 module', 0), (@q, 'C', 'It is required at the top of every Python file', 0), (@q, 'D', 'On Linux/macOS it tells the shell which interpreter to use when you run ./script.py; Python itself treats it as a comment', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'introspection'), 3, 'code_output', 'What does this print?', 'print([name for name in dir("") if name.startswith("up")])', 'python', '[''upper'']', 'dir('''') lists the attributes of a string.', 'Among str''s attributes only ''upper'' starts with ''up''. Filtering dir() like this is a quick way to discover methods.', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'upper', 0), (@q, 'B', '[''update'', ''upper'']', 0), (@q, 'C', '[]', 0), (@q, 'D', '[''upper'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'introspection'), 3, 'code_output', 'What does this print?', 'print(callable(print), callable("hi"))', 'python', 'True False', 'Can you put () after it?', 'callable(x) is True when x can be called like a function. print can be called; a string can''t.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True False', 1), (@q, 'B', 'False True', 0), (@q, 'C', 'False False', 0), (@q, 'D', 'True True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'execution'), 3, 'code_output', 'What does this print?', 'print("start")\nx = (1 +\nprint("end")', 'python', 'SyntaxError', 'When does Python check the grammar of the file?', 'Python compiles the whole file to bytecode before running any of it. The unclosed bracket is a SyntaxError, so not even ''start'' is printed.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SyntaxError', 1), (@q, 'B', 'start\nend', 0), (@q, 'C', 'start', 0), (@q, 'D', 'start\nSyntaxError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'execution'), 3, 'code_output', 'What does this print?', 'def report():\n    return undefined_name\n\nprint("defined")', 'python', 'defined', 'Is the function body executed here?', 'A misspelt name is a runtime error, not a syntax error. It only fails when report() is called, which never happens here.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'defined', 1), (@q, 'B', 'SyntaxError', 0), (@q, 'C', 'defined\nNameError', 0), (@q, 'D', 'NameError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'execution'), 3, 'fill_blank', 'The standard-library module that shows the bytecode instructions of a function is called ____.', NULL, NULL, 'dis', 'Short for ''disassemble''.', 'import dis; dis.dis(f) prints the bytecode CPython runs for f. Handy for seeing what a line really does.', NULL, NULL, 67);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 4, 'mcq', 'Why is `-7 // 2 == -4` in Python while Java''s `-7 / 2 == -3`?', NULL, NULL, 'Python''s // floors toward minus infinity so that a == (a // b) * b + a % b holds with % taking the divisor''s sign', 'Think about which identity Python wants // and % to satisfy together.', 'Guido chose floor division so that a % b always has the sign of b (useful for things like clock arithmetic). Java truncates toward zero, so its % takes the sign of a.', NULL, NULL, 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It''s a known bug kept for backwards compatibility', 0), (@q, 'B', 'Python converts to float first and rounds to the nearest integer', 0), (@q, 'C', 'Python''s // floors toward minus infinity so that a == (a // b) * b + a % b holds with % taking the divisor''s sign', 1), (@q, 'D', 'Python rounds away from zero', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 4, 'code_output', 'What does this print?', 'print(7 % -3, -7 % -3)', 'python', '-2 -1', 'The remainder takes the sign of the divisor, which is negative in both.', '7 // -3 is -3, and 7 - (-3 * -3) = -2. -7 // -3 is 2, and -7 - (2 * -3) = -1.', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 -1', 0), (@q, 'B', '-2 -1', 1), (@q, 'C', '-2 2', 0), (@q, 'D', '1 2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 4, 'code_output', 'What does this print?', 'print(10 ** 400 // 10 ** 399, 10 ** 400 / 10 ** 399)\nprint(float(10 ** 400))', 'python', '10 10.0\nOverflowError', 'Int true division is done carefully; converting a huge int to float is not.', 'int / int is computed with a correctly rounded algorithm, so the 10.0 result is fine even though both operands are too big for a float. float(10**400) exceeds the double range and raises OverflowError.', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '10 inf\nOverflowError', 0), (@q, 'B', 'OverflowError', 0), (@q, 'C', '10 10.0\ninf', 0), (@q, 'D', '10 10.0\nOverflowError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 4, 'code_output', 'What does this print?', 'print(2 ** -1 ** 2)', 'python', '0.5', 'The right operand of ** may itself start with a minus, and ** is right-associative.', 'The grammar parses this as 2 ** (-(1 ** 2)): the minus applies to 1 ** 2 = 1, and -1 becomes the exponent of 2. So the answer is 2 ** -1 = 0.5.', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4', 0), (@q, 'B', '-4', 0), (@q, 'C', '0.5', 1), (@q, 'D', '0.25', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'print'), 4, 'code_output', 'What does this print?', 'print("a", "b", sep=None, end=None)\nprint("c")', 'python', 'a b\nc', 'What does None usually mean for an optional parameter?', 'print treats sep=None and end=None as ''use the default'' (a space and a newline). Useful when forwarding optional arguments.', NULL, NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'a b\nc', 1), (@q, 'B', 'TypeError', 0), (@q, 'C', 'abc', 0), (@q, 'D', 'ab\nc', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indentation'), 4, 'true_false', 'Python''s tokenizer turns changes in indentation into INDENT and DEDENT tokens, which is why dedenting to a column that no open block started at raises an IndentationError.', NULL, NULL, 'True', 'Indentation plays the role of { and }, so something must produce those ''braces''.', 'The tokenizer keeps a stack of indentation levels. A dedent must return to a level on the stack; otherwise it reports ''unindent does not match any outer indentation level''.', 'col 0  if a:          stack [0]\ncol 4      if b:      INDENT -> [0, 4]\ncol 8          x()    INDENT -> [0, 4, 8]\ncol 2    y()          DEDENT to 2? not in stack -> error', NULL, 73);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'execution'), 4, 'mcq', 'What is stored in the .pyc files inside a __pycache__ folder?', NULL, NULL, 'Compiled bytecode for an imported module, reused while the source file is unchanged', 'It saves a step at import time, not at run time.', 'CPython caches the bytecode of imported modules (checked against the source''s timestamp or hash). It speeds up startup only: the same bytecode is still interpreted. The script you run directly is not cached.', NULL, NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A backup copy of the source in case you delete it', 0), (@q, 'B', 'Cached results of the functions you called', 0), (@q, 'C', 'Compiled bytecode for an imported module, reused while the source file is unchanged', 1), (@q, 'D', 'Native machine code that runs faster than Python', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'execution'), 4, 'true_false', 'In CPython 3.13, running a script normally compiles it to bytecode and then interprets that bytecode in a virtual machine loop; the experimental JIT is off unless CPython was built with it and you enable it.', NULL, NULL, 'True', 'CPython is the standard interpreter from python.org and Anaconda.', 'Source -> AST -> bytecode -> evaluation loop. 3.13 ships an experimental JIT as a build-time option, disabled by default; PyPy is the implementation with a mature JIT.', NULL, NULL, 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'execution'), 4, 'code_output', 'What does this print?', 'def area():\n    return 60 * 60 * 24\n\nprint(area.__code__.co_consts[-1])', 'python', '86400', 'The compiler can do simple maths on constants before the program even runs.', 'CPython''s optimizer folds 60 * 60 * 24 into the single constant 86400 at compile time, so no multiplication happens when area() runs.', NULL, NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None', 0), (@q, 'B', '24', 0), (@q, 'C', '86400', 1), (@q, 'D', '60', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'execution'), 4, 'mcq', 'What does running a script with `python -O` change?', NULL, NULL, 'assert statements are removed and __debug__ becomes False', 'The flag is about debug-only code.', '-O strips assert statements (and `if __debug__:` blocks). That''s why you should never use assert for input validation in production code.', NULL, NULL, 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The code is compiled to machine code', 0), (@q, 'B', 'assert statements are removed and __debug__ becomes False', 1), (@q, 'C', 'Type hints are enforced', 0), (@q, 'D', 'Unused imports are deleted', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'execution'), 4, 'mcq', 'What happens, in order, the FIRST time a process runs `import mymod`?', NULL, NULL, 'Find mymod''s file, load cached bytecode or compile the source, create a module object and register it in sys.modules, run the module''s top-level code', 'Think: locate, compile, register, execute.', 'Import finds the module, gets bytecode (from __pycache__ or a fresh compile), puts the module in sys.modules before running it, then executes its top level. Later imports just return the cached module.', 'import mymod\n  -> find   mymod.py on sys.path\n  -> load   __pycache__/mymod.*.pyc or compile\n  -> cache  sys.modules[''mymod''] = module\n  -> exec   top-level code of mymod', NULL, 78);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Run mymod in a separate process and return its globals', 0), (@q, 'B', 'Compile mymod to machine code and link it into the interpreter', 0), (@q, 'C', 'Find mymod''s file, load cached bytecode or compile the source, create a module object and register it in sys.modules, run the module''s top-level code', 1), (@q, 'D', 'Copy the source of mymod into the current file, then run the combined file', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'introspection'), 4, 'fill_blank', 'A function''s compiled bytecode and constants live on its code object, reached as f.____.', NULL, NULL, '__code__', 'A ''dunder'' (double-underscore) attribute.', 'f.__code__ is the code object: co_code (bytecode), co_consts, co_varnames and more. dis.dis(f) reads it for you.', NULL, NULL, 79);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'In Python, what is a variable?', NULL, NULL, 'A name that points to a value', 'x = 5 sticks the label ''x'' on the value 5.', 'A variable is a name bound to a value. You can rebind it to another value any time.', '  x  ----->  [ 5 ]\n  name       value', 'Like a sticky label on a box, not the box itself.', 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A type of loop', 0), (@q, 'B', 'A box that can hold only numbers', 0), (@q, 'C', 'A fixed constant', 0), (@q, 'D', 'A name that points to a value', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'code_output', 'What does this print?', 'x = 5\nx = x + 2\nprint(x)', 'python', '7', 'The right side is computed first, then stored back into x.', 'x + 2 is 7, and that new value is assigned to x.', NULL, NULL, 2);
