INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'code_output', 'What does this print?', 'print("5" + "5")', 'python', '55', 'The quotes make these strings, not numbers.', '+ on strings joins (concatenates) them: ''5'' + ''5'' = ''55''.', NULL, NULL, 4);
