INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'code_output', 'What does this print?', 'print(int("5") + 2)', 'python', '7', 'int() converts text to a whole number.', 'int(''5'') becomes the number 5, then 5 + 2 = 7.', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '52', 0), (@q, 'B', '5.2', 0), (@q, 'C', '7', 1), (@q, 'D', 'Error', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Which value is a bool?', NULL, NULL, 'True', 'Booleans have exactly two values and no quotes.', 'True and False (capitalised, no quotes) are Python''s booleans. ''True'' with quotes is a string.', NULL, NULL, 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1.0', 0), (@q, 'B', 'True', 1), (@q, 'C', 'None', 0), (@q, 'D', '''True''', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'fill_blank', 'The special value that means ''nothing / no value'' in Python is ____.', NULL, NULL, 'None', 'It''s like null in JavaScript or Java.', 'None is Python''s null. A function with no return gives back None.', NULL, NULL, 7);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'naming'), 1, 'mcq', 'Which of these is a valid Python variable name?', NULL, NULL, 'user_name', 'Names can''t start with a digit, can''t contain a dash, and can''t be a reserved word.', 'user_name uses letters and an underscore. 2users starts with a digit, user-name reads as ''user minus name'', and class is a keyword.', NULL, NULL, 8);
