INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'naming'), 1, 'true_false', 'In Python, `Age` and `age` are two different variables.', NULL, NULL, 'True', 'Python cares about capital letters in names.', 'Names are case-sensitive, just like in JavaScript and Java. By convention, variables are all lowercase.', NULL, NULL, 9);
