INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binding'), 3, 'code_output', 'What does this print?', 'a = [1]\nb = a\ndel a\nprint(b)', 'python', '[1]', 'del removes a name, not necessarily the object.', 'del a removes the label a. The list still has another name (b) pointing at it, so it stays alive. It''s freed only when no references remain.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', '[1]', 1), (@q, 'C', '[]', 0), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binding'), 3, 'code_output', 'What does this print?', 'def f(a, b):\n    a = a + [1]\n    b.append(1)\n\nx, y = [], []\nf(x, y)\nprint(x, y)', 'python', '[] [1]', 'One line rebinds a local name, the other mutates the shared object.', 'Python passes object references (''call by sharing''). a = a + [1] makes a new list for the local name only; b.append(1) changes the caller''s list.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1] [1]', 0), (@q, 'B', '[1] []', 0), (@q, 'C', '[] []', 0), (@q, 'D', '[] [1]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'core-types'), 3, 'code_output', 'What does this print?', 'print(bool(None), None == 0, None is None)', 'python', 'False False True', 'None is falsy, but is it equal to zero?', 'bool(None) is False, None is not equal to 0 (unlike some languages'' null), and there''s only one None, so None is None is True.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False False False', 0), (@q, 'B', 'False False True', 1), (@q, 'C', 'False True True', 0), (@q, 'D', 'True False True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 3, 'code_output', 'What does this print?', 'print(int("0x1A", 16), int("101", 2), int("1_000"))', 'python', '26 5 1000', 'The second argument to int() is the number base.', 'Base 16: 0x1A = 26. Base 2: 101 = 5. int() also accepts underscores between digits, like the literal 1_000.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1A 5 1_000', 0), (@q, 'B', 'ValueError', 0), (@q, 'C', '26 101 1000', 0), (@q, 'D', '26 5 1000', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 3, 'code_output', 'What does this print?', 'print(int(-3.7), round(-3.7), -7 // 2)', 'python', '-3 -4 -4', 'One of these chops toward zero, the others don''t.', 'int() truncates toward zero (-3); round() goes to the nearest (-4); // floors toward minus infinity (-4).', NULL, NULL, 51);
