INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'immutability'), 3, 'mcq', 'Why are Python strings immutable?', NULL, NULL, 'So they can be hashed and used as dict keys, shared safely between variables and threads, and interned', 'Think about what a dict needs from its keys.', 'A dict key''s hash must never change, so keys must be immutable. Immutability also lets two names share one string with no risk. Java''s String is immutable for the same reasons.', NULL, NULL, 53);
