INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fstrings'), 3, 'code_output', 'What does this print?', 'print(f"{42:08.3f}|{255:x}|{255:#b}")', 'python', '0042.000|ff|0b11111111', '08 means ''width 8, pad with zeros''; the width includes the decimal point.', '08.3f gives ''0042.000'' (8 characters). x is lowercase hex, and # adds the base prefix to binary: 0b11111111.', '{42:08.3f}\n    | | ||\n    | | |+-- f: fixed-point float\n    | | +--- .3: three decimals\n    | +----- 8: total width\n    +------- 0: pad with zeros', NULL, 59);
