INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fstrings'), 3, 'code_output', 'What does this print?', 'print("{1}-{0}".format("a", "b"))', 'python', 'b-a', 'The numbers in the braces pick which argument goes where.', 'str.format fills {0} with the first argument and {1} with the second. f-strings replaced most uses of format(), but you still meet it in older code and templates.', NULL, NULL, 62);
