INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 3, 'code_output', 'What does this print?', 'print(b"abc"[0], b"abc"[0:1])', 'python', '97 b''a''', 'bytes is a sequence of small integers.', 'Indexing bytes gives an int (the byte value, 97 for ''a''); slicing gives a bytes object. A str index gives a 1-character str.', NULL, NULL, 65);
