INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'escapes'), 4, 'code_output', 'What does this print?', 'print(r"C:\\folder\\")', 'python', 'SyntaxError', 'In a raw string, a backslash still stops the next quote from closing the string.', 'A raw string can''t end with an odd number of backslashes: \\" doesn''t close the string, so the literal is unterminated. Use ''C:\\\\folder\\\\'' or pathlib instead.', NULL, NULL, 82);
