INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'escapes'), 4, 'code_output', 'What does this print?', 'print(len("\\d+"))', 'python', '3', '\\d is not a recognised escape in normal strings.', 'Unknown escapes are kept as backslash + letter, so the string is 3 characters. Since 3.12 this gives a SyntaxWarning and may become an error: write regex patterns as r''\\d+''.', NULL, NULL, 83);
