INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fstrings'), 4, 'true_false', 'In Python 3.12+, `f"{row["name"]}"` (reusing the same quote type inside the braces) is valid syntax.', NULL, NULL, 'True', 'PEP 701 changed how f-strings are parsed.', 'From 3.12, f-strings are parsed by the real grammar, so the expression inside braces may reuse the outer quotes, span lines and contain backslashes. Before 3.12 this was a SyntaxError.', NULL, NULL, 84);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'interning'), 4, 'true_false', '`x is "hello"` can be True for a literal but False for the same text read from a file, which is why == is the only correct way to compare string contents.', NULL, NULL, 'True', 'Which strings does CPython intern automatically?', 'Identifier-like literals are interned at compile time; strings from files, input() or joins are new objects. `is` tests identity, == tests content. Python even emits a SyntaxWarning for `is` with a literal.', NULL, NULL, 85);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'split-join'), 1, 'fill_blank', 'The string method that cuts a string into a list of pieces at a separator is ____.', NULL, NULL, 'split', 'It''s the opposite of join.', 's.split(sep) returns a list of the pieces between separators; sep.join(pieces) puts them back together.', NULL, NULL, 86);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'operators'), 1, 'true_false', '''Hello'' == ''hello'' is True in Python.', NULL, NULL, 'False', 'Is H the same character as h?', 'String comparison is case-sensitive. For a case-insensitive check compare a.lower() == b.lower() (or casefold()).', NULL, NULL, 87);
