INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 2, 'true_false', 'For a non-empty string s, s[len(s) - 1] and s[-1] are the same character.', NULL, NULL, 'True', 'Both point at one particular end of the string.', 'The last index is len(s) - 1, and -1 is Python''s shortcut for it.', NULL, NULL, 89);
