INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 2, 'fill_blank', 'The method that removes whitespace from both ends of a string is ____.', NULL, NULL, 'strip', 'Think of stripping paint off both edges.', 's.strip() trims both ends; lstrip and rstrip do one side each.', NULL, NULL, 90);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 2, 'fill_blank', 'To turn the str s into bytes you call s.____("utf-8").', NULL, NULL, 'encode', 'bytes.decode goes the other way.', 's.encode(''utf-8'') -> bytes; b.decode(''utf-8'') -> str. Encode on the way out (files, network), decode on the way in.', NULL, NULL, 91);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'escapes'), 2, 'mcq', 'You need the Windows path C:\\new\\data.csv in your code. Which option is safe?', NULL, NULL, 'r"C:\\new\\data.csv" or "C:/new/data.csv"', 'What does \\n mean inside a normal string?', 'In a normal (or f-) string \\n becomes a newline and the path breaks silently. A raw string keeps the backslashes, and Windows also accepts forward slashes. pathlib.Path is the modern choice.', NULL, NULL, 92);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '"C:\\new\\data.csv"', 0), (@q, 'B', 'r"C:\\new\\data.csv" or "C:/new/data.csv"', 1), (@q, 'C', 'f"C:\\new\\data.csv"', 0), (@q, 'D', '''C:\\new\\data.csv''', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 3, 'mcq', 'open(''sales.csv'').read() fails with UnicodeDecodeError: ''utf-8'' codec can''t decode byte 0x92. What''s the best first move?', NULL, NULL, 'The file isn''t UTF-8: find its real encoding (often cp1252 for Excel exports on Windows) and pass encoding= to open()', 'Decoding needs to know how the bytes were written.', '0x92 is a curly apostrophe in cp1252. Decode with the encoding the file was written in. errors=''ignore'' silently deletes data, which is a nasty bug in an ML dataset.', NULL, NULL, 93);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The file isn''t UTF-8: find its real encoding (often cp1252 for Excel exports on Windows) and pass encoding= to open()', 1), (@q, 'B', 'Always add errors=''ignore'' so the error goes away', 0), (@q, 'C', 'Encode the file name with .encode(''ascii'')', 0), (@q, 'D', 'Convert the str to bytes before reading', 0);
