INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 2, 'code_output', 'What does this print?', 'grid = [[0] * 3 for _ in range(2)]\ngrid[0][0] = 1\nprint(grid)', 'python', '[[1, 0, 0], [0, 0, 0]]', 'The comprehension runs [0] * 3 once per row.', 'Each row is a brand-new list, so changing grid[0][0] only touches the first row. This is the safe way to build a grid.', NULL, NULL, 37);
