INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-queue'), 2, 'mcq', 'You process a to-do queue by calling `tasks.pop(0)` on a Python list of 1 million items. What''s the problem?', NULL, NULL, 'Each pop(0) shifts every remaining item left, so it''s O(n) per call', 'What has to happen to the items after index 0?', 'A list is a contiguous array, so removing the front means moving all other items. Use collections.deque and popleft() for O(1).', NULL, NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'pop(0) raises an error on long lists', 0), (@q, 'B', 'Nothing; pop(0) is O(1) like pop()', 0), (@q, 'C', 'pop(0) removes the last item, not the first', 0), (@q, 'D', 'Each pop(0) shifts every remaining item left, so it''s O(n) per call', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 2, 'mcq', 'What''s the typical time complexity of `x in my_list` for a list of n items?', NULL, NULL, 'O(n): it checks items one by one', 'Does a list know where a value is without looking?', 'A list has no index by value, so `in` scans from the start. For many membership checks convert to a set (O(1) average).', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'O(n): it checks items one by one', 1), (@q, 'B', 'O(1): lists are hashed', 0), (@q, 'C', 'O(n log n)', 0), (@q, 'D', 'O(log n): lists are kept sorted', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 2, 'true_false', 'Appending to the end of a Python list is O(1) on average (amortised).', NULL, NULL, 'True', 'The list reserves some spare room.', 'Lists over-allocate spare capacity, so most appends just fill a free slot; the occasional resize is spread across many appends.', NULL, NULL, 44);
