INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-defaults'), 2, 'code_output', 'What does this print?', 'def add(item, bucket=[]):\n    bucket.append(item)\n    return bucket\n\nadd(1)\nprint(add(2))', 'python', '[1, 2]', 'Is a new empty list made on every call?', 'The default [] is created once when def runs and reused, so the second call sees the 1 from the first call.', NULL, NULL, 45);
