INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'code_output', 'What does this print?', 'a = [1, 2, 3]\nalias = a\na = []\nprint(alias)\nb = [1, 2, 3]\nalias2 = b\nb.clear()\nprint(alias2)', 'python', '[1, 2, 3]\n[]', 'Rebinding a name vs emptying the object.', 'a = [] points a at a new empty list; the old one (still held by alias) is untouched. b.clear() empties the shared object, so alias2 sees [].', NULL, NULL, 51);
