INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'code_output', 'What does this print?', 'rows = [("bob", 30), ("amy", 25), ("cat", 30)]\nprint(sorted(rows, key=lambda r: r[1]))', 'python', '[(''amy'', 25), (''bob'', 30), (''cat'', 30)]', 'Python''s sort is stable.', 'Sort by age; bob and cat tie at 30, and a stable sort keeps their original order (bob before cat).', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[(''amy'', 25), (''bob'', 30), (''cat'', 30)]', 1), (@q, 'B', '[(''bob'', 30), (''cat'', 30), (''amy'', 25)]', 0), (@q, 'C', '[(''amy'', 25), (''cat'', 30), (''bob'', 30)]', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'code_output', 'What does this print?', 'rows = [("bob", 30), ("amy", 25), ("cat", 30)]\nprint(sorted(rows, key=lambda r: (-r[1], r[0])))', 'python', '[(''bob'', 30), (''cat'', 30), (''amy'', 25)]', 'Tuples compare item by item; the minus flips one direction.', 'Key (-age, name): age descending first, then name ascending to break ties: bob, cat, then amy.', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[(''bob'', 30), (''cat'', 30), (''amy'', 25)]', 1), (@q, 'B', '[(''cat'', 30), (''bob'', 30), (''amy'', 25)]', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', '[(''amy'', 25), (''bob'', 30), (''cat'', 30)]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'code_output', 'What does this print?', 'print(sorted(["banana", "Apple", "cherry"]))', 'python', '[''Apple'', ''banana'', ''cherry'']', 'Strings compare by character code.', 'Uppercase letters have smaller codes than lowercase, so ''Apple'' comes first. Use key=str.lower for case-insensitive order.', NULL, NULL, 61);
