INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'code_output', 'What does this print?', 'print(sorted([3, "1", 2]))', 'python', 'TypeError', 'Can Python decide whether 3 < ''1''?', 'Python 3 refuses to order int against str and raises TypeError (JS would coerce silently).', NULL, NULL, 62);
