INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'mcq', 'You need to check `user_id in seen` 100,000 times against 100,000 ids. Which is the right fix if `seen` is a list?', NULL, NULL, 'Convert seen to a set once, then check membership', 'Which container has O(1) average lookup?', 'List membership is O(n), so 100k checks is ~10^10 steps. A set is hashed: O(1) average per check.', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Use seen.index(user_id) instead', 0), (@q, 'B', 'Use a tuple instead of a list', 0), (@q, 'C', 'Convert seen to a set once, then check membership', 1), (@q, 'D', 'Sort the list first', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'mcq', 'Which operation on a list of n items is O(n), not O(1)?', NULL, NULL, 'a.insert(0, x)', 'Which one forces everything to shift?', 'Inserting at the front moves all n items one slot right. Append, pop from the end and index assignment don''t move anything.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'a[i] = x', 0), (@q, 'B', 'a.insert(0, x)', 1), (@q, 'C', 'a.append(x)', 0), (@q, 'D', 'a.pop()', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-defaults'), 3, 'code_output', 'What does this print?', 'def add(item, bucket=None):\n    if bucket is None:\n        bucket = []\n    bucket.append(item)\n    return bucket\n\nadd(1)\nprint(add(2))', 'python', '[2]', 'Where is the list created now?', 'With the None sentinel, a fresh list is created inside each call, so the calls don''t share state.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2]', 1), (@q, 'B', 'None', 0), (@q, 'C', '[1, 2]', 0), (@q, 'D', '[None, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'true_false', 'A Python list of 1,000 floats stores the 1,000 float values directly next to each other in memory, like a C double array.', NULL, NULL, 'False', 'Each item is a full Python object.', 'A list stores pointers (references) to float objects that live elsewhere. That''s why NumPy arrays, which store raw values contiguously, are much smaller and faster.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'code_output', 'What does this print?', 'x = [0]\na = [x, x]\na[0].append(1)\nprint(a)', 'python', '[[0, 1], [0, 1]]', 'Both slots hold a reference to the same object.', 'a contains the same list x twice; mutating it through a[0] is visible through a[1].', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[0, 1], [0, 1]]', 1), (@q, 'B', '[[0, 1]]', 0), (@q, 'C', '[[0, 1], [0]]', 0), (@q, 'D', '[[0], [0], 1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 4, 'code_output', 'What does this print?', 't = ([1],)\ntry:\n    t[0] += [2]\nexcept TypeError:\n    print("TypeError")\nprint(t)', 'python', 'TypeError\n([1, 2],)', '`x += y` is two steps: call x.__iadd__(y), then assign the result back.', 'list.__iadd__ extends the list in place first; then storing the result back into t[0] fails because tuples are immutable. So it raises AND the list is changed.', NULL, NULL, 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '([1, 2],)', 0), (@q, 'B', '([1],)', 0), (@q, 'C', 'TypeError\n([1],)', 0), (@q, 'D', 'TypeError\n([1, 2],)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing-slicing'), 4, 'code_output', 'What does this print?', 'a = [1, 2, 3]\na[:0] = [0]\na[len(a):] = [4]\nprint(a)', 'python', '[0, 1, 2, 3, 4]', 'An empty slice is a position you can insert into.', 'a[:0] is the empty slice before index 0 (prepend); a[len(a):] is the empty slice after the end (append).', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 1, 2, 3, 4]', 1), (@q, 'B', 'ValueError', 0), (@q, 'C', '[[0], 1, 2, 3, [4]]', 0), (@q, 'D', '[1, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing-slicing'), 4, 'code_output', 'What does this print?', 'a = list(range(10))\ns = slice(1, 8, 3)\nprint(a[s], s.indices(5))', 'python', '[1, 4, 7] (1, 5, 3)', 'indices(n) clips the slice to a sequence of length n.', 'a[1:8:3] is 1, 4, 7. slice.indices(5) clamps stop 8 to the length 5, giving (1, 5, 3).', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 4, 7, 10] (1, 5, 3)', 0), (@q, 'B', '[1, 4, 7] (1, 5, 3)', 1), (@q, 'C', '[1, 4] (1, 5, 3)', 0), (@q, 'D', '[1, 4, 7] (1, 8, 3)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 4, 'code_output', 'What does this print?', 'nums = [2, 4, 6, 8]\nfor n in nums:\n    if n % 2 == 0:\n        nums.remove(n)\nprint(nums)', 'python', '[4, 8]', 'The loop walks by index; removing shifts items left under it.', 'Removing 2 shifts 4 into index 0, but the loop moves to index 1 (now 6), skipping 4. Same for 8. Iterate over a copy or build a new list.', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[]', 0), (@q, 'B', '[2, 4, 6, 8]', 0), (@q, 'C', '[4, 8]', 1), (@q, 'D', 'RuntimeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 4, 'code_output', 'What does this print?', 'rows = [[]] * 3\nrows[0].append("x")\nrows[1] = ["y"]\nprint(rows)', 'python', '[[''x''], [''y''], [''x'']]', 'Mutating an inner list vs replacing a slot are different things.', 'All three slots start pointing at one shared list, so append shows ''x'' everywhere. rows[1] = [''y''] rebinds only slot 1 to a new list.', NULL, NULL, 72);
