INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 2, 'code_output', 'What does this print?', 'a = {"x": 1}\nb = {"x": 2, "y": 3}\nprint({**a, **b}, a)', 'python', '{''x'': 2, ''y'': 3} {''x'': 1}', '** unpacks a dict into the new literal, in order.', 'b''s x overwrites a''s; the result is a brand-new dict, so a is unchanged.', NULL, NULL, 35);
