INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 2, 'code_output', 'What does this print?', 'from collections import Counter\nwords = "the cat the dog the end".split()\nprint(Counter(words).most_common(1))', 'python', '[(''the'', 3)]', 'most_common(n) returns a list of (item, count) pairs.', '''the'' appears 3 times; most_common(1) gives a one-item list [(''the'', 3)].', NULL, NULL, 36);
