INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 3, 'code_output', 'What does this print?', 'prices = {"tea": 20, "juice": 50, "coffee": 30}\nby_price = sorted(prices.items(), key=lambda kv: kv[1], reverse=True)\nprint(by_price[0])', 'python', '(''juice'', 50)', 'Sort the pairs by their second element.', 'items() gives (name, price) pairs; key=kv[1] sorts by price; reverse=True puts the highest first.', NULL, NULL, 45);
