INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'mcq', 'You have 1 million known-bad URLs and must check 1 million incoming URLs. Which is the best choice for the known-bad collection?', NULL, NULL, 'A set: each check is O(1) on average', 'Which container''s `in` doesn''t scan?', 'A set lookup is O(1) average, so a million checks is about a million steps. With a list it''s around 10^12 comparisons.', NULL, NULL, 58);
