INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'if-structure'), 1, 'true_false', 'In Python, `elif` is short for ''else if''.', NULL, NULL, 'True', 'JS and Java write two words for it.', 'Python uses `elif` for ''else if''. You can have as many elif branches as you need, and else is optional.', NULL, NULL, 20);
