INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'logic-ops'), 2, 'code_output', 'What does this print?', 'print(0 or "default", "set" or "default")', 'python', 'default set', '`or` hands back one of its operands.', '`or` returns the first truthy operand (or the last one). 0 is falsy so you get ''default''; ''set'' is truthy so you get ''set''.', NULL, NULL, 27);
