INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'range'), 1, 'code_output', 'What does this print?', 'print(list(range(1, 5)))', 'python', '[1, 2, 3, 4]', 'The stop value is never included.', 'range(1, 5) starts at 1 and stops BEFORE 5. A very common off-by-one trap.', ' range(1, 5)\n 1  2  3  4  | 5   <- stop is excluded', NULL, 11);
