INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutating'), 2, 'code_output', 'What does this print?', 'nums = [1, 2, 2, 3]\nfor n in nums:\n    if n == 2:\n        nums.remove(n)\nprint(nums)', 'python', '[1, 2, 3]', 'After a removal, everything shifts left but the loop''s position moves on.', 'Removing the first 2 shifts the second 2 into the slot already visited, so it''s skipped. Lists don''t raise; they silently skip.', ' index:  0  1  2  3\n before [1, 2, 2, 3]   loop at index 1 -> remove 2\n after  [1, 2, 3]      loop moves to index 2 -> sees 3', NULL, 37);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 3]', 0), (@q, 'B', 'RuntimeError', 0), (@q, 'C', '[1, 2, 3]', 1), (@q, 'D', '[1, 2, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iterators'), 2, 'code_output', 'What does this print?', 'it = iter([1, 2, 3])\nprint(next(it))\nprint(list(it))', 'python', '1\n[2, 3]', 'An iterator remembers how far it has got.', 'next(it) takes 1. list(it) collects whatever is left: [2, 3].', NULL, NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1\n[2, 3]', 1), (@q, 'B', '1\n[1, 2, 3]', 0), (@q, 'C', '1\n[]', 0), (@q, 'D', '[1, 2, 3]\n[]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iterators'), 2, 'code_output', 'What does this print?', 'squares = map(lambda x: x * x, [1, 2, 3])\nprint(sum(squares))\nprint(sum(squares))', 'python', '14\n0', 'map gives back an iterator, not a list.', 'The first sum uses up the iterator. The second sees nothing and returns 0. Wrap in list() if you need it twice.', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '14\n28', 0), (@q, 'B', '14\n14', 0), (@q, 'C', '14\n0', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generators'), 2, 'code_output', 'What does this print?', 'def countdown(n):\n    while n > 0:\n        yield n\n        n -= 1\n\nprint(list(countdown(3)))', 'python', '[3, 2, 1]', 'yield hands out one value and pauses.', 'countdown is a generator function. list() keeps asking for values: 3, 2, 1, then the function ends.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3, 2, 1, 0]', 0), (@q, 'B', 'None', 0), (@q, 'C', '3', 0), (@q, 'D', '[3, 2, 1]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generators'), 2, 'mcq', 'What does calling a function that contains `yield` return?', NULL, NULL, 'A generator object; the body hasn''t run yet', 'Nothing inside runs until you ask for a value.', 'Calling a generator function only creates a generator. Code runs when next() (or a for loop) asks for a value.', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The first yielded value', 0), (@q, 'B', 'A list of all yielded values', 0), (@q, 'C', 'None', 0), (@q, 'D', 'A generator object; the body hasn''t run yet', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'itertools'), 2, 'code_output', 'What does this print?', 'from itertools import chain\nprint(list(chain([1, 2], (3,), "ab")))', 'python', '[1, 2, 3, ''a'', ''b'']', 'chain glues iterables end to end.', 'chain yields every item of the first, then the second, then the third. The string contributes its characters.', NULL, NULL, 42);
