INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'range'), 3, 'code_output', 'What does this print?', 'r = range(0, 10, 2)\nprint(r[-1], 7 in r, list(r) == list(r))', 'python', '8 False True', 'range is a sequence: indexable and re-iterable.', 'The last element is 8; 7 isn''t on the even grid; range can be looped any number of times (unlike an iterator).', NULL, NULL, 46);
