INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'while'), 3, 'mcq', '`x = 0.0` then `while x != 1.0: x += 0.1`. What happens?', NULL, NULL, 'It loops forever, because 0.1 added ten times is not exactly 1.0', 'Try 0.1 + 0.2 == 0.3 in your head.', 'Floats can''t represent 0.1 exactly; after ten additions x is 0.9999999999999999, then jumps past 1.0. Use `while x < 1.0` or loop over a count.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It raises FloatingPointError', 0), (@q, 'B', 'It loops forever, because 0.1 added ten times is not exactly 1.0', 1), (@q, 'C', 'It stops after 10 passes', 0), (@q, 'D', 'It stops after 11 passes', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'while'), 3, 'code_output', 'What does this print?', 'tries = 0\nwhile True:\n    tries += 1\n    value = tries * 3\n    if value % 4 == 0:\n        break\nprint(tries, value)', 'python', '4 12', 'This is a ''do-while'': the body always runs at least once.', 'values: 3, 6, 9, 12. 12 is the first multiple of 4, reached on try 4.', NULL, NULL, 50);
