INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'break-continue'), 3, 'code_output', 'What does this print?', 'for i in range(3):\n    for j in range(3):\n        if j == 1:\n            break\n        print(i, j)', 'python', '0 0\n1 0\n2 0', 'Which loop does break leave?', 'break only exits the inner loop. The outer loop carries on, so each i prints only j = 0.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0 0\n0 1\n1 0\n1 1\n2 0\n2 1', 0), (@q, 'B', '0 0', 0), (@q, 'C', '0 0\n1 1\n2 2', 0), (@q, 'D', '0 0\n1 0\n2 0', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 3, 'mcq', 'You need to stop BOTH loops as soon as a target is found in a 2D grid. Which approach is cleanest?', NULL, NULL, 'Put the loops in a function and `return` when found', 'Python has no labelled break like Java''s `break outer;`.', 'return exits every loop in the function at once. A found-flag checked by the outer loop also works but is noisier.', NULL, 'Java''s labelled `break outer;` does not exist in Python.', 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Use `break` twice on the same line', 0), (@q, 'B', 'Put the loops in a function and `return` when found', 1), (@q, 'C', 'Raise and catch a KeyboardInterrupt', 0), (@q, 'D', 'Use `continue` in the inner loop', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loop-else'), 3, 'code_output', 'What does this print?', 'for i in range(3):\n    for j in range(3):\n        if i * j == 2:\n            break\n    else:\n        continue\n    break\nprint(i, j)', 'python', '1 2', 'The inner else runs only when the inner loop didn''t break.', 'If the inner loop finishes, `continue` moves the outer on; if it breaks, the outer `break` runs. First i*j == 2 is i=1, j=2.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2 1', 0), (@q, 'B', '0 0', 0), (@q, 'C', '1 2', 1), (@q, 'D', '2 2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loop-else'), 3, 'code_output', 'What does this print?', 'for x in []:\n    break\nelse:\n    print("else ran")', 'python', 'else ran', 'Did a break happen?', 'A loop with zero iterations never breaks, so else runs. else means ''no break'', not ''loop was empty''.', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SyntaxError', 0), (@q, 'B', 'Nothing is printed', 0), (@q, 'C', 'else ran', 1), (@q, 'D', 'NameError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'enumerate-zip'), 3, 'code_output', 'What does this print?', 'print(list(zip([1, 2, 3], "ab", strict=True)))', 'python', 'ValueError', 'strict=True changes the shortest-wins rule.', 'With strict=True (Python 3.10+), zip raises ValueError when lengths differ. Great for catching misaligned features and labels.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[(1, ''a''), (2, ''b'')]', 0), (@q, 'B', '[(1, ''a''), (2, ''b''), (3, None)]', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', 'ValueError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'enumerate-zip'), 3, 'code_output', 'What does this print?', 'pairs = [("a", 1), ("b", 2), ("c", 3)]\nletters, nums = zip(*pairs)\nprint(letters, nums)', 'python', '(''a'', ''b'', ''c'') (1, 2, 3)', '*pairs passes each pair as a separate argument to zip.', 'zip(*pairs) is zip((''a'',1), (''b'',2), (''c'',3)), which transposes rows into columns. zip gives tuples.', NULL, NULL, 56);
