INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutating'), 3, 'code_output', 'What does this print?', 'nums = [1, 2, 2, 3]\nfor n in nums[:]:\n    if n == 2:\n        nums.remove(n)\nprint(nums)', 'python', '[1, 3]', 'nums[:] is a copy.', 'Looping over a copy means removals don''t disturb the iteration. Even simpler: nums = [n for n in nums if n != 2].', NULL, NULL, 57);
