INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutating'), 3, 'true_false', 'Changing the VALUES of existing keys while looping over a dict is safe.', 'd = {"a": 1, "b": 2}\nfor k in d:\n    d[k] *= 10\nprint(d)', 'python', 'True', 'Which change breaks iteration: size or values?', 'd[k] = new_value for an existing key doesn''t change the key set, so iteration is fine. Adding or deleting keys is what raises.', NULL, NULL, 59);
