INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iterators'), 3, 'code_output', 'What does this print?', 'it = iter([7])\nprint(next(it))\nprint(next(it, "done"))', 'python', '7\ndone', 'next() takes an optional second argument.', 'When the iterator is exhausted, next(it, default) returns the default instead of raising StopIteration.', NULL, NULL, 61);
