INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generators'), 3, 'code_output', 'What does this print?', 'def gen():\n    print("start")\n    yield 1\n    print("end")\n\ng = gen()\nprint("created")\nprint(next(g))', 'python', 'created\nstart\n1', 'When does the body begin running?', 'gen() only builds the generator. next(g) runs up to the first yield. "end" isn''t printed because nobody asked for a second value.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'created\nstart\n1\nend', 0), (@q, 'B', 'start\ncreated\n1', 0), (@q, 'C', 'start\nend\ncreated\n1', 0), (@q, 'D', 'created\nstart\n1', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generators'), 3, 'mcq', 'You need the sum of squares of 100 million numbers. Why prefer `sum(x*x for x in range(N))` over `sum([x*x for x in range(N)])`?', NULL, NULL, 'The generator version keeps one value in memory at a time instead of a 100-million-element list', 'Think about what has to exist in RAM at once.', 'The list version builds the whole list first (gigabytes). The generator streams values with O(1) memory.', NULL, 'Streaming a video vs downloading the whole file first.', 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The generator version keeps one value in memory at a time instead of a 100-million-element list', 1), (@q, 'B', 'The generator version is always several times faster', 0), (@q, 'C', 'sum() can''t take a list', 0), (@q, 'D', 'The list version gives a different answer', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'itertools'), 3, 'code_output', 'What does this print?', 'from itertools import groupby\nprint([(k, len(list(g))) for k, g in groupby("aabaa")])', 'python', '[(''a'', 2), (''b'', 1), (''a'', 2)]', 'groupby looks at runs of equal neighbours.', 'groupby only groups CONSECUTIVE equal keys, like Unix `uniq`. Sort first to group all equal keys together.', NULL, NULL, 64);
