INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'itertools'), 3, 'code_output', 'What does this print?', 'from itertools import product, accumulate\nprint(len(list(product("ab", repeat=3))), list(accumulate([1, 2, 3, 4])))', 'python', '8 [1, 3, 6, 10]', 'product with repeat=3 is like three nested loops; accumulate is a running total.', '2 choices ^ 3 positions = 8 combinations. accumulate gives running sums 1, 3, 6, 10.', NULL, NULL, 65);
