INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'def-return'), 1, 'fill_blank', 'The keyword that starts a function definition in Python is ____.', NULL, NULL, 'def', 'Short for ''define''.', '`def name(params):` defines a function; the indented lines below are its body.', NULL, 'Like `function name(params) { ... }` in JavaScript.', 7);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'def-return'), 1, 'code_output', 'What does this print?', 'def double(n):\n    return n * 2\n\nresult = double(4) + 1\nprint(result)', 'python', '9', 'A call is replaced by the value it returns.', 'double(4) returns 8, so result = 8 + 1 = 9.', NULL, NULL, 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Error', 0), (@q, 'B', '8', 0), (@q, 'C', '10', 0), (@q, 'D', '9', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'def-return'), 1, 'code_output', 'What does this print?', 'def check(n):\n    if n > 0:\n        return "positive"\n    return "not positive"\n\nprint(check(5))', 'python', 'positive', 'return ends the function straight away.', 'Once `return "positive"` runs, the function stops; the second return never runs.', NULL, NULL, 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'not positive', 0), (@q, 'B', 'positive', 1), (@q, 'C', 'None', 0), (@q, 'D', 'positive\nnot positive', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'def-return'), 1, 'true_false', 'Defining a function with `def` also runs its body.', 'def hello():\n    print("hi")', 'python', 'False', 'Is anything printed if you only write the def?', 'def just creates the function. The body runs only when you call it with parentheses: name().', NULL, NULL, 10);
