INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arguments'), 1, 'code_output', 'What does this print?', 'def area(width, height):\n    return width * height\n\nprint(area(height=2, width=5))', 'python', '10', 'Keyword arguments are matched by name, not position.', 'width=5 and height=2 regardless of order, so 5 * 2 = 10.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Error', 0), (@q, 'B', '25', 0), (@q, 'C', '7', 0), (@q, 'D', '10', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arguments'), 1, 'code_output', 'What does this print?', 'def greet(name, greeting="Hello"):\n    return f"{greeting}, {name}"\n\nprint(greet("Ana"))\nprint(greet("Bo", "Hey"))', 'python', 'Hello, Ana\nHey, Bo', 'A default is used only when you leave that argument out.', 'The first call uses the default "Hello"; the second passes "Hey" positionally.', NULL, NULL, 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Ana, Hello\nBo, Hey', 0), (@q, 'B', 'Hello, Ana\nHello, Bo', 0), (@q, 'C', 'Error', 0), (@q, 'D', 'Hello, Ana\nHey, Bo', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arguments'), 1, 'code_output', 'What does this print?', 'def add(a, b):\n    return a + b\n\nprint(add(1))', 'python', 'TypeError', 'b has no default value.', 'Calling with too few arguments raises TypeError: missing 1 required positional argument: ''b''.', NULL, NULL, 13);
