INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'args-kwargs'), 1, 'code_output', 'What does this print?', 'def total(*nums):\n    return sum(nums)\n\nprint(total(1, 2, 3))', 'python', '6', '*nums collects all the arguments.', '*nums packs every positional argument into a tuple (1, 2, 3); sum adds them.', NULL, NULL, 14);
