INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 1, 'code_output', 'What does this print?', 'x = 10\n\ndef show():\n    x = 99\n\nshow()\nprint(x)', 'python', '10', 'The x inside the function is a new, local name.', 'Assigning inside a function creates a local variable. The global x is untouched.', ' global:  x = 10\n show():  x = 99   (local, gone when show returns)', NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'UnboundLocalError', 0), (@q, 'B', '99', 0), (@q, 'C', '10', 1), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 1, 'code_output', 'What does this print?', 'rate = 3\n\ndef cost(n):\n    return n * rate\n\nprint(cost(2))', 'python', '6', 'Can a function read a variable defined outside it?', 'Reading a global is fine: rate isn''t found locally, so Python looks in the module (global) scope.', NULL, NULL, 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2', 0), (@q, 'B', 'None', 0), (@q, 'C', '6', 1), (@q, 'D', 'NameError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'first-class'), 1, 'code_output', 'What does this print?', 'def shout(s):\n    return s.upper()\n\nyell = shout\nprint(yell("hi"))', 'python', 'HI', 'No parentheses after shout means you''re not calling it.', 'Functions are values. yell = shout makes another name for the same function.', NULL, 'Like `const yell = shout;` in JavaScript.', 17);
