INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'param-kinds'), 2, 'code_output', 'What does this print?', 'def connect(host, *, port=80):\n    return f"{host}:{port}"\n\nprint(connect("db", 5432))', 'python', 'TypeError', 'What does a bare * in the parameter list mean?', 'Everything after * is keyword-only. You must write connect("db", port=5432).', NULL, NULL, 30);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 1), (@q, 'B', 'db:80', 0), (@q, 'C', 'db:5432', 0), (@q, 'D', 'SyntaxError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-default'), 2, 'code_output', 'What does this print?', 'def add_item(item, basket=[]):\n    basket.append(item)\n    return basket\n\nadd_item("apple")\nprint(add_item("pear"))', 'python', '[''apple'', ''pear'']', 'When is the default list created?', 'The [] default is created once, when def runs, and shared by every call. The second call sees the apple from the first.', ' def time:  basket -> [ ]  (one list object)\n call 1:    [ ''apple'' ]\n call 2:    [ ''apple'', ''pear'' ]  <- same list', NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''apple'']', 0), (@q, 'B', '[''apple'', ''pear'']', 1), (@q, 'C', '[''pear'']', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 2, 'code_output', 'What does this print?', 'count = 0\n\ndef bump():\n    global count\n    count += 1\n\nbump()\nbump()\nprint(count)', 'python', '2', 'global lets the function rebind the module-level name.', 'With `global count`, count += 1 changes the module variable. Without it, you''d get UnboundLocalError.', NULL, NULL, 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0', 0), (@q, 'B', '1', 0), (@q, 'C', 'UnboundLocalError', 0), (@q, 'D', '2', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'closures'), 2, 'code_output', 'What does this print?', 'def make_multiplier(k):\n    def mul(x):\n        return x * k\n    return mul\n\ntriple = make_multiplier(3)\nprint(triple(5))', 'python', '15', 'mul remembers k even after make_multiplier has returned.', 'That memory is a closure: the inner function keeps a reference to k = 3.', NULL, 'A factory that bakes a setting into the function it returns, like a configured middleware.', 33);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '15', 1), (@q, 'B', 'NameError', 0), (@q, 'C', '8', 0), (@q, 'D', 'TypeError', 0);
