INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'decorators'), 2, 'code_output', 'What does this print?', 'def loud(func):\n    def wrapper():\n        return func().upper() + "!"\n    return wrapper\n\n@loud\ndef hi():\n    return "hi"\n\nprint(hi())', 'python', 'HI!', '@loud above def hi means hi = loud(hi).', 'hi is replaced by wrapper, which calls the original and changes its result.', NULL, 'Like Express middleware wrapping a route handler.', 36);
