INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'recursion'), 2, 'code_output', 'What does this print?', 'def countdown(n):\n    if n == 0:\n        return [0]\n    return [n] + countdown(n - 1)\n\nprint(countdown(3))', 'python', '[3, 2, 1, 0]', 'Build it from the inside out: countdown(0) is [0].', '[3] + ([2] + ([1] + [0])) = [3, 2, 1, 0].', NULL, NULL, 40);
