INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'args-kwargs'), 3, 'code_output', 'What does this print?', 'def log(*args, **kwargs):\n    return args, kwargs\n\nprint(log(1, 2, sep="-"))', 'python', '((1, 2), {''sep'': ''-''})', 'One collects into a tuple, the other into a dict.', 'Positional extras go to args (a tuple); keyword extras go to kwargs (a dict).', NULL, NULL, 44);
