INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-default'), 3, 'code_output', 'What does this print?', 'def add_item(item, basket=None):\n    if basket is None:\n        basket = []\n    basket.append(item)\n    return basket\n\nadd_item("apple")\nprint(add_item("pear"))', 'python', '[''pear'']', 'A fresh list is made inside the function now.', 'The None sentinel pattern: the default is immutable None, and a new list is created on each call that needs one.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '[''pear'']', 1), (@q, 'C', '[''apple'', ''pear'']', 0), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-default'), 3, 'code_output', 'What does this print?', 'def f(x, acc=[]):\n    acc.append(x)\n    return len(acc)\n\nf(1)\nf(2)\nprint(f.__defaults__)', 'python', '([1, 2],)', 'The default lives on the function object.', 'Defaults are stored in f.__defaults__, a tuple. The shared list has been mutated by both calls.', NULL, NULL, 48);
