INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'decorators'), 3, 'code_output', 'What does this print?', 'def repeat(n):\n    def deco(func):\n        def wrapper(*args, **kwargs):\n            return [func(*args, **kwargs) for _ in range(n)]\n        return wrapper\n    return deco\n\n@repeat(2)\ndef hi(name):\n    return "hi " + name\n\nprint(hi("Bo"))', 'python', '[''hi Bo'', ''hi Bo'']', '@repeat(2) first calls repeat(2), which returns the real decorator.', 'A decorator with arguments is a factory: hi = repeat(2)(hi). *args/**kwargs let the wrapper pass any arguments through.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''hi Bo'', ''hi Bo'']', 1), (@q, 'B', '[''hi Bo'']', 0), (@q, 'C', 'hi Bo', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'functools'), 3, 'code_output', 'What does this print?', 'def deco(func):\n    def wrapper(*args):\n        return func(*args)\n    return wrapper\n\n@deco\ndef train():\n    """Train the model."""\n\nprint(train.__name__, train.__doc__)', 'python', 'wrapper None', 'train now IS the wrapper.', 'Without functools.wraps, the decorated function reports the wrapper''s name and docstring. That breaks logging, debugging and docs.', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'wrapper None', 1), (@q, 'B', 'train None', 0), (@q, 'C', 'train Train the model.', 0), (@q, 'D', 'wrapper Train the model.', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'functools'), 3, 'code_output', 'What does this print?', 'from functools import lru_cache\n\n@lru_cache(maxsize=None)\ndef fib(n):\n    return n if n < 2 else fib(n - 1) + fib(n - 2)\n\nprint(fib(30), fib.cache_info().misses)', 'python', '832040 31', 'With a cache, each n is computed only once.', 'fib(0)..fib(30) are each a cache miss once: 31 misses. Without the cache, fib(30) makes over a million calls.', NULL, NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '832040 31', 1), (@q, 'B', 'RecursionError', 0), (@q, 'C', '832040 30', 0), (@q, 'D', '832040 1664079', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hints-docs'), 3, 'code_output', 'What does this print?', 'def double(x: int) -> int:\n    return x * 2\n\nprint(double("ab"))', 'python', 'abab', 'Does Python check type hints when you call the function?', 'Hints are not enforced at runtime. "ab" * 2 is "abab". Tools like mypy would flag it before you run.', NULL, 'Like TypeScript types erased at runtime: the JS still runs.', 58);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0', 0), (@q, 'B', 'abab', 1), (@q, 'C', 'TypeError', 0), (@q, 'D', 'ab', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hints-docs'), 3, 'code_output', 'What does this print?', 'def f(a: int, b: str = "x") -> bool:\n    return True\n\nprint(f.__annotations__)', 'python', '{''a'': <class ''int''>, ''b'': <class ''str''>, ''return'': <class ''bool''>}', 'Annotations are stored on the function object.', '__annotations__ maps parameter names (and ''return'') to the hint objects. Libraries like FastAPI and pydantic read them.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(int, str, bool)', 0), (@q, 'B', '{''a'': ''int'', ''b'': ''str''}', 0), (@q, 'C', '{}', 0), (@q, 'D', '{''a'': <class ''int''>, ''b'': <class ''str''>, ''return'': <class ''bool''>}', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'recursion'), 3, 'code_output', 'What does this print?', 'def depth(n):\n    return depth(n + 1)\n\ndepth(0)', 'python', 'RecursionError', 'CPython guards its call stack.', 'There''s no base case. CPython stops at the recursion limit (default 1000) with RecursionError.', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Runs forever', 0), (@q, 'B', 'RecursionError', 1), (@q, 'C', 'StackOverflowError', 0), (@q, 'D', 'MemoryError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'param-kinds'), 4, 'code_output', 'What does this print?', 'def f(a, /, **kw):\n    return a, kw\n\nprint(f(1, a=2))', 'python', '(1, {''a'': 2})', 'Because a is positional-only, the keyword name ''a'' is free.', 'a can only be filled by position, so a=2 isn''t a duplicate; it lands in **kw. This is why dict(self, /, **kwargs)-style APIs use /.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '(2, {})', 0), (@q, 'C', '(1, {''a'': 2})', 1), (@q, 'D', 'SyntaxError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'param-kinds'), 4, 'mcq', 'Which signature is valid Python?', NULL, NULL, 'def f(a, /, b, *, c, **kw):', 'The order is: positional-only, /, normal, *, keyword-only, **kwargs.', '/ must come before *, **kwargs must be last, and a bare * must be followed by at least one named parameter.', ' def f(pos_only, /, normal, *, kw_only, **kwargs)\n       \\_______/    \\____/     \\_____/   \\______/\n       by position  either     by name   extras', NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'def f(*, **kw):', 0), (@q, 'B', 'def f(a, /, b, *, c, **kw):', 1), (@q, 'C', 'def f(**kw, *args):', 0), (@q, 'D', 'def f(a, *, b, /, c):', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-default'), 4, 'code_output', 'What does this print?', 'def fib(n, memo={}):\n    if n in memo:\n        return memo[n]\n    memo[n] = n if n < 2 else fib(n - 1) + fib(n - 2)\n    return memo[n]\n\nfib(20)\nprint(len(fib.__defaults__[0]))', 'python', '21', 'The shared default persists between calls on purpose here.', 'The ''trap'' is used deliberately as a cache: memo keeps fib(0)..fib(20), 21 entries, across all calls. Clear but surprising; lru_cache is the cleaner tool.', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0', 0), (@q, 'B', '20', 0), (@q, 'C', '1', 0), (@q, 'D', '21', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 4, 'code_output', 'What does this print?', 'def outer():\n    n = 0\n    def inc():\n        n += 1\n        return n\n    return inc\n\nprint(outer()())', 'python', 'UnboundLocalError', 'Rebinding a closed-over int needs a declaration.', 'n += 1 makes n local to inc, so it''s read before assignment. Add `nonlocal n` to rebind the enclosing variable.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0', 0), (@q, 'B', 'UnboundLocalError', 1), (@q, 'C', 'NameError', 0), (@q, 'D', '1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'closures'), 4, 'code_output', 'What does this print?', 'def outer():\n    data = []\n    def add(x):\n        data.append(x)\n        return len(data)\n    return add\n\nadd = outer()\nadd("a")\nprint(add("b"), add.__closure__[0].cell_contents)', 'python', '2 [''a'', ''b'']', 'Mutating a captured object is not rebinding its name.', 'data.append only reads the name, so no nonlocal is needed. The closure keeps data in a cell, visible via __closure__.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2 [''a'', ''b'']', 1), (@q, 'B', '1 [''b'']', 0), (@q, 'C', '2 []', 0), (@q, 'D', 'UnboundLocalError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'decorators'), 4, 'code_output', 'What does this print?', 'def a(f):\n    def w():\n        return "a(" + f() + ")"\n    return w\n\ndef b(f):\n    def w():\n        return "b(" + f() + ")"\n    return w\n\n@a\n@b\ndef g():\n    return "g"\n\nprint(g())', 'python', 'a(b(g))', 'The decorator nearest the def is applied first.', 'Stacking means g = a(b(g)): b wraps g, then a wraps that. a''s wrapper runs outermost.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'g', 0), (@q, 'B', 'a(b(g))', 1), (@q, 'C', 'a(g)', 0), (@q, 'D', 'b(a(g))', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'decorators'), 4, 'code_output', 'What does this print?', 'def register(func):\n    print("registering", func.__name__)\n    return func\n\n@register\ndef task():\n    print("running")\n\nprint("end")', 'python', 'registering task\nend', 'When does a decorator body run?', 'The decorator runs at definition (import) time, not when task is called. That''s how Flask''s @app.route registers routes.', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'registering task\nrunning\nend', 0), (@q, 'B', 'end', 0), (@q, 'C', 'registering task\nend', 1), (@q, 'D', 'running\nend', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'functools'), 4, 'code_output', 'What does this print?', 'from functools import lru_cache\n\n@lru_cache\ndef total(xs):\n    return sum(xs)\n\nprint(total([1, 2, 3]))', 'python', 'TypeError', 'The cache stores calls in a dict keyed by the arguments.', 'Lists aren''t hashable, so lru_cache can''t build the key: TypeError. Pass a tuple instead.', NULL, NULL, 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None', 0), (@q, 'B', 'TypeError', 1), (@q, 'C', 'KeyError', 0), (@q, 'D', '6', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'functools'), 4, 'mcq', 'Why is `@lru_cache` on an instance method a known memory-leak risk?', NULL, NULL, 'The cache key includes self, so the cache holds a strong reference to every instance it has seen and they are never garbage-collected', 'What''s in the cache key for obj.method(x)?', 'The cache lives on the class-level function and keys include self, keeping objects alive. Use functools.cached_property or a per-instance cache.', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The cache key includes self, so the cache holds a strong reference to every instance it has seen and they are never garbage-collected', 1), (@q, 'B', 'Methods can''t be cached at all and raise TypeError', 0), (@q, 'C', 'The cache is per-instance and grows with each new attribute', 0), (@q, 'D', 'lru_cache copies the whole object on every call', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'functools'), 4, 'code_output', 'What does this print?', 'from functools import wraps\n\ndef deco(func):\n    @wraps(func)\n    def wrapper(*a, **k):\n        return func(*a, **k) * 2\n    return wrapper\n\n@deco\ndef three():\n    return 3\n\nprint(three(), three.__wrapped__())', 'python', '6 3', 'wraps adds a link back to the original.', 'wraps copies the name and docstring and sets __wrapped__ to the undecorated function, which inspect.signature and testing tools use.', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '6 3', 1), (@q, 'B', '6 6', 0), (@q, 'C', 'AttributeError', 0), (@q, 'D', '3 3', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'recursion'), 4, 'true_false', 'CPython optimises tail calls, so `def f(n): return f(n - 1) if n else 0` can safely recurse 100,000 times.', NULL, NULL, 'False', 'Check what f(100000) raises.', 'CPython has no tail-call optimisation; every call adds a frame and you hit RecursionError. Rewrite as a loop for deep recursion.', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'first-class'), 4, 'mcq', 'Why can''t `lambda x: return x * 2` be written?', NULL, NULL, 'A lambda body must be a single expression; return, assignments and other statements are not allowed', 'What does a lambda automatically do with its body?', 'lambda args: expr returns expr implicitly. Statements (return, =, if-blocks) are a SyntaxError. Use def for anything bigger.', NULL, NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Lambdas must be assigned to a name first', 0), (@q, 'B', 'A lambda body must be a single expression; return, assignments and other statements are not allowed', 1), (@q, 'C', 'x * 2 is not allowed in a lambda', 0), (@q, 'D', 'Lambdas can''t take arguments', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'first-class'), 4, 'code_output', 'What does this print?', 'people = [("Bo", 30), ("Ana", 25), ("Cy", 30)]\nprint(sorted(people, key=lambda p: p[1], reverse=True))', 'python', '[(''Bo'', 30), (''Cy'', 30), (''Ana'', 25)]', 'Python''s sort is stable, even with reverse=True.', 'Equal keys keep their original order: Bo stays before Cy. reverse=True does not flip ties.', NULL, NULL, 73);
