INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 1, 'code_output', 'What does this print?', 'print([0 for _ in range(3)])', 'python', '[0, 0, 0]', '_ is just a variable name meaning ''I don''t use this''.', 'The expression is always 0, repeated three times. `_` is a convention for an unused loop variable.', NULL, NULL, 10);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 1, 2]', 0), (@q, 'B', '[0, 0, 0]', 1), (@q, 'C', '[]', 0), (@q, 'D', 'SyntaxError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'code_output', 'What does this print?', 'print([w for w in ["cat", "dog", "cow"] if w.startswith("c")])', 'python', '[''cat'', ''cow'']', 'The if at the end decides what''s kept.', 'Only words starting with ''c'' pass the filter. The kept items are the words themselves, not True/False.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''cat'', ''dog'', ''cow'']', 0), (@q, 'B', '[''cat'', ''cow'']', 1), (@q, 'C', '[''dog'']', 0), (@q, 'D', '[True, False, True]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'true_false', 'A comprehension with an `if` at the end can return a shorter list than its input.', NULL, NULL, 'True', 'What happens to items where the condition is False?', 'The trailing if is a filter: items that fail it are dropped.', NULL, NULL, 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'mcq', 'In `[x * 2 for x in nums if x > 0]`, which part decides whether an item is kept?', NULL, NULL, 'if x > 0', 'One part transforms, one part loops, one part filters.', 'x * 2 transforms, `for x in nums` loops, `if x > 0` filters.', ' [ x * 2    for x in nums    if x > 0 ]\n   ^make    ^loop            ^keep?', NULL, 13);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'for x in nums', 0), (@q, 'B', 'The square brackets', 0), (@q, 'C', 'if x > 0', 1), (@q, 'D', 'x * 2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 1, 'code_output', 'What does this print?', 'print({x: x * x for x in range(3)})', 'python', '{0: 0, 1: 1, 2: 4}', 'key: value inside curly braces.', 'A dict comprehension: each x becomes a key mapped to its square.', NULL, NULL, 14);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 1, 4]', 0), (@q, 'B', '{0, 1, 4}', 0), (@q, 'C', '{0: 0, 1: 1, 2: 4}', 1), (@q, 'D', '{1: 1, 2: 4, 3: 9}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 1, 'code_output', 'What does this print?', 'print(sorted({n % 3 for n in range(10)}))', 'python', '[0, 1, 2]', 'Curly braces without a colon make a set. Sets drop duplicates.', 'n % 3 only gives 0, 1 or 2; the set keeps one of each. sorted() turns it into a list.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 3]', 0), (@q, 'B', '[0, 1, 2, 0, 1, 2, 0, 1, 2, 0]', 0), (@q, 'C', '[0, 1, 2]', 1), (@q, 'D', '[3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 1, 'mcq', 'Which one is a SET comprehension?', NULL, NULL, '{w.lower() for w in words}', 'Look for curly braces and no colon.', '{...} without key: value is a set. With a colon it''s a dict; [] is a list; () is a generator.', NULL, NULL, 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{w: w.lower() for w in words}', 0), (@q, 'B', '[w.lower() for w in words]', 0), (@q, 'C', '{w.lower() for w in words}', 1), (@q, 'D', '(w.lower() for w in words)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 1, 'mcq', 'What does `(x * 2 for x in nums)` create?', NULL, NULL, 'A generator that produces values one at a time when asked', 'There''s no ''tuple comprehension'' in Python.', 'Round brackets make a generator expression: lazy, nothing is computed until you loop over it.', NULL, NULL, 17);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A generator that produces values one at a time when asked', 1), (@q, 'B', 'A list', 0), (@q, 'C', 'A tuple', 0), (@q, 'D', 'A syntax error', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 1, 'code_output', 'What does this print?', 'print(sum(x for x in [1, 2, 3]))', 'python', '6', 'sum can consume a generator directly.', 'The generator produces 1, 2, 3 and sum adds them. No list is built.', NULL, NULL, 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '6', 1), (@q, 'C', '3', 0), (@q, 'D', '[1, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 1, 'code_output', 'What does this print?', 'print([k for k in {"a": 1, "b": 2}])', 'python', '[''a'', ''b'']', 'Looping over a dict gives keys.', 'Same rule as a for loop: iterating a dict yields its keys. Use .items() for pairs.', NULL, NULL, 19);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''a'', ''b'']', 1), (@q, 'B', '[''a'', 1, ''b'', 2]', 0), (@q, 'C', '[(''a'', 1), (''b'', 2)]', 0), (@q, 'D', '[1, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 1, 'true_false', '`[s * 3 for s in words]` and a for-loop that appends `s * 3` to an empty list produce the same result.', 'words = ["a", "b"]\nres = []\nfor s in words:\n    res.append(s * 3)\nassert res == [s * 3 for s in words]', 'python', 'True', 'A comprehension is shorthand for which pattern?', 'A list comprehension is the ''empty list + loop + append'' pattern written in one expression.', NULL, NULL, 20);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 2, 'code_output', 'What does this print?', 'print(["even" if n % 2 == 0 else "odd" for n in range(3)])', 'python', '[''even'', ''odd'', ''even'']', 'if-else in front transforms every item; it doesn''t drop any.', 'Each n becomes ''even'' or ''odd'', so the result has the same length as the input.', NULL, NULL, 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''even'', ''even'']', 0), (@q, 'B', '[''even'', ''odd'', ''even'']', 1), (@q, 'C', 'SyntaxError', 0), (@q, 'D', '[''odd'', ''even'', ''odd'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 2, 'mcq', 'You want to replace negative numbers with 0 and keep everything else. Which works?', NULL, NULL, '[x if x > 0 else 0 for x in xs]', 'You want to keep every item, so it''s a transform, not a filter.', 'The if-else (a conditional expression) goes before `for`. The trailing-if version drops items; the else-at-the-end version is a SyntaxError.', NULL, NULL, 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[x for x in xs if x > 0]', 0), (@q, 'B', '[x if x > 0 else 0 for x in xs]', 1), (@q, 'C', '[x for x in xs if x > 0 else 0]', 0), (@q, 'D', '[if x > 0: x else 0 for x in xs]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 2, 'code_output', 'What does this print?', 'xs = [3, -1, 4]\nprint([x for x in xs if x > 0], [x if x > 0 else 0 for x in xs])', 'python', '[3, 4] [3, 0, 4]', 'One filters, one transforms.', 'Trailing if drops -1 (length 2). The if-else in front keeps every item and maps -1 to 0 (length 3).', NULL, NULL, 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3, 0, 4] [3, 0, 4]', 0), (@q, 'B', '[3, 0, 4] [3, 4]', 0), (@q, 'C', '[3, 4] [3, 4]', 0), (@q, 'D', '[3, 4] [3, 0, 4]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 2, 'code_output', 'What does this print?', 'print([x for x in range(20) if x % 2 == 0 if x % 3 == 0])', 'python', '[0, 6, 12, 18]', 'Two ifs in a row both have to pass.', 'Chained ifs act like `and`: divisible by both 2 and 3, i.e. multiples of 6 (0 included).', NULL, NULL, 24);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[6, 12, 18]', 0), (@q, 'B', 'SyntaxError', 0), (@q, 'C', '[0, 2, 3, 4, 6, 8, 9]', 0), (@q, 'D', '[0, 6, 12, 18]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 2, 'code_output', 'What does this print?', 'print([x for x in range(10) if 2 < x < 6])', 'python', '[3, 4, 5]', 'Python allows chained comparisons.', '2 < x < 6 means 2 < x and x < 6, so 3, 4, 5.', NULL, NULL, 25);
