INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 2, 'code_output', 'What does this print?', 'prices = {"tea": 2, "cake": 5, "pie": 4}\nprint({k: v for k, v in prices.items() if v > 3})', 'python', '{''cake'': 5, ''pie'': 4}', 'A dict comprehension can filter too.', 'Only entries with value above 3 are kept, with their original keys.', NULL, NULL, 27);
