INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 2, 'code_output', 'What does this print?', 'grid = [[1, 2], [3], [4, 5]]\nprint([x for row in grid for x in row])', 'python', '[1, 2, 3, 4, 5]', 'Read the for clauses left to right like nested loops.', 'for row in grid (outer), then for x in row (inner): it flattens the 2D list.', ' for row in grid:        <- 1st for\n     for x in row:       <- 2nd for\n         result.append(x)', NULL, 30);
