INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 2, 'code_output', 'What does this print?', 'print(tuple(x for x in range(3)))', 'python', '(0, 1, 2)', 'Pass the generator to the tuple constructor.', 'tuple(...) consumes the generator. That''s the way to ''build a tuple with a comprehension''.', NULL, NULL, 32);
