INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 2, 'code_output', 'What does this print?', 'x = 10\nsquares = [x * x for x in range(3)]\nprint(x)', 'python', '10', 'Does the comprehension''s x touch the outer x?', 'In Python 3 a comprehension has its own scope, so its loop variable doesn''t leak or overwrite x. (A plain for loop would set x to 2.)', NULL, NULL, 34);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '10', 1), (@q, 'B', 'NameError', 0), (@q, 'C', '2', 0), (@q, 'D', '4', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'walrus'), 2, 'code_output', 'What does this print?', 'data = [1, 2, 3]\nprint([y for x in data if (y := x * 10) > 15])', 'python', '[20, 30]', ':= assigns and returns the value in one step.', 'The walrus stores x * 10 in y during the filter, and the expression reuses y: no computing it twice.', NULL, NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SyntaxError', 0), (@q, 'B', '[20, 30]', 1), (@q, 'C', '[2, 3]', 0), (@q, 'D', '[10, 20, 30]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 2, 'mcq', 'Which is equivalent to `[x * 2 for x in xs if x > 0]`?', NULL, NULL, 'list(map(lambda x: x * 2, filter(lambda x: x > 0, xs)))', 'Filter first, then transform.', 'The comprehension filters (filter) then transforms (map). Most Python style guides prefer the comprehension for readability.', NULL, NULL, 36);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[x * 2 for x in filter(xs, x > 0)]', 0), (@q, 'B', 'list(map(lambda x: x > 0, xs)) * 2', 0), (@q, 'C', 'list(map(lambda x: x * 2, filter(lambda x: x > 0, xs)))', 1), (@q, 'D', 'list(filter(lambda x: x * 2, map(lambda x: x > 0, xs)))', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 2, 'code_output', 'What does this print?', 'print([w.strip().lower() for w in [" Hi", "YO "]])', 'python', '[''hi'', ''yo'']', 'Methods can be chained in the expression.', 'strip() removes surrounding spaces, then lower() lower-cases. A common text-cleaning pattern.', NULL, NULL, 37);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''Hi'', ''YO'']', 0), (@q, 'B', '[''HI'', ''YO'']', 0), (@q, 'C', '[''hi'', ''yo'']', 1), (@q, 'D', '['' hi'', ''yo '']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 3, 'code_output', 'What does this print?', 'xs = [-1, -2, 3]\nprint([x if x > 0 else 0 for x in xs if x != -1])', 'python', '[0, 3]', 'Filter first, then transform what''s left.', 'The trailing if removes -1. The front if-else maps -2 to 0 and keeps 3.', NULL, NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3]', 0), (@q, 'B', '[0, 3]', 1), (@q, 'C', '[0, 0, 3]', 0), (@q, 'D', 'SyntaxError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 3, 'code_output', 'What does this print?', 'print([x for x in range(3) if x > 0 else 0])', 'python', 'SyntaxError', 'A filter can''t have an else.', 'The trailing if is a filter clause, not an expression, so `else` there is invalid syntax. Move it to the front: [x if x > 0 else 0 for x in ...].', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 1, 2, 0]', 0), (@q, 'B', '[0, 1, 2]', 0), (@q, 'C', 'SyntaxError', 1), (@q, 'D', '[1, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 3, 'code_output', 'What does this print?', 'def show(tag, v):\n    print(tag, v)\n    return v\n\nr = [show("make", x) for x in range(3) if show("test", x) % 2 == 0]', 'python', 'test 0\nmake 0\ntest 1\ntest 2\nmake 2', 'Per item: filter first, then (only if it passes) the expression.', 'Each item is tested, and the expression runs only for items that pass. Item by item, not ''all filters then all expressions''.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'test 0\nmake 0\ntest 1\ntest 2\nmake 2', 1), (@q, 'B', 'make 0\nmake 2', 0), (@q, 'C', 'test 0\ntest 1\ntest 2\nmake 0\nmake 2', 0), (@q, 'D', 'make 0\ntest 0\nmake 1\ntest 1\nmake 2\ntest 2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 3, 'code_output', 'What does this print?', 'print({len(w): w for w in ["ab", "cd", "e"]})', 'python', '{2: ''cd'', 1: ''e''}', 'What happens when two items produce the same key?', 'Both ''ab'' and ''cd'' map to key 2; the later one overwrites. No error is raised. Use a dict of lists to group.', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '{2: [''ab'', ''cd''], 1: [''e'']}', 0), (@q, 'C', '{2: ''ab'', 1: ''e''}', 0), (@q, 'D', '{2: ''cd'', 1: ''e''}', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 3, 'code_output', 'What does this print?', 'print([(i, c) for i in range(2) for c in "ab"])', 'python', '[(0, ''a''), (0, ''b''), (1, ''a''), (1, ''b'')]', 'The rightmost for changes fastest.', 'Same order as nested loops: for i (outer), for c (inner). The result is flat, not a list of lists.', NULL, NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[(0, ''a''), (0, ''b''), (1, ''a''), (1, ''b'')]', 1), (@q, 'B', '[(0, ''a''), (1, ''b'')]', 0), (@q, 'C', '[[(0, ''a''), (0, ''b'')], [(1, ''a''), (1, ''b'')]]', 0), (@q, 'D', '[(0, ''a''), (1, ''a''), (0, ''b''), (1, ''b'')]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 3, 'code_output', 'What does this print?', 'print([[i * j for j in range(3)] for i in range(2)])', 'python', '[[0, 0, 0], [0, 1, 2]]', 'A comprehension inside the expression builds one row per outer item.', 'The inner comprehension is the expression, so each i gives a row of length 3. This builds a 2x3 matrix.', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[0, 1, 2], [0, 2, 4]]', 0), (@q, 'B', '[[0, 0], [0, 1], [0, 2]]', 0), (@q, 'C', '[[0, 0, 0], [0, 1, 2]]', 1), (@q, 'D', '[0, 0, 0, 0, 1, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 3, 'code_output', 'What does this print?', 'm = [[1, 2], [3, 4], [5, 6]]\nprint([[row[i] for row in m] for i in range(2)])', 'python', '[[1, 3, 5], [2, 4, 6]]', 'The outer loop picks a column index; the inner one walks rows.', 'This is a transpose: 3x2 becomes 2x3. list(zip(*m)) does the same (giving tuples).', NULL, NULL, 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 3, 5, 2, 4, 6]', 0), (@q, 'B', '[[1, 2, 3], [4, 5, 6]]', 0), (@q, 'C', '[[1, 2], [3, 4], [5, 6]]', 0), (@q, 'D', '[[1, 3, 5], [2, 4, 6]]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 3, 'code_output', 'What does this print?', 'def check(x):\n    print("checking", x)\n    return x > 1\n\nprint(any(check(x) for x in [1, 2, 3]))', 'python', 'checking 1\nchecking 2\nTrue', 'any() stops once it knows the answer.', 'With a generator, any() pulls items one at a time and stops at the first True. 3 is never checked.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'checking 1\nFalse', 0), (@q, 'B', 'checking 1\nchecking 2\nchecking 3\nTrue', 0), (@q, 'C', 'True', 0), (@q, 'D', 'checking 1\nchecking 2\nTrue', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 3, 'code_output', 'What does this print?', 'def check(x):\n    print("checking", x)\n    return x > 1\n\nprint(any([check(x) for x in [1, 2, 3]]))', 'python', 'checking 1\nchecking 2\nchecking 3\nTrue', 'The square brackets change when the work happens.', 'The list is fully built (all three checks) BEFORE any() sees it. Drop the brackets to short-circuit.', NULL, NULL, 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'checking 3\nTrue', 0), (@q, 'B', 'checking 1\nchecking 2\nchecking 3\nTrue', 1), (@q, 'C', 'checking 1\nchecking 2\nTrue', 0), (@q, 'D', 'True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 3, 'code_output', 'What does this print?', 'import sys\ng = (x for x in range(10**6))\nl = [x for x in range(10**6)]\nprint(sys.getsizeof(g) < 1000, sys.getsizeof(l) > 1_000_000)', 'python', 'True True', 'One stores a million references, one stores a recipe.', 'The generator is a small fixed-size object (about 200 bytes); the list holds a million pointers (~8 MB).', NULL, 'A stream vs an array fully loaded into memory.', 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True False', 0), (@q, 'B', 'False False', 0), (@q, 'C', 'False True', 0), (@q, 'D', 'True True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 3, 'code_output', 'What does this print?', 'x = 5\nprint([x for x in range(x)])', 'python', '[0, 1, 2, 3, 4]', 'Which x does range(x) see?', 'The outermost iterable range(x) is evaluated in the surrounding scope (x = 5); the comprehension''s x is separate.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 1, 2, 3, 4]', 1), (@q, 'B', 'UnboundLocalError', 0), (@q, 'C', '[]', 0), (@q, 'D', '[5, 5, 5, 5, 5]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'walrus'), 3, 'code_output', 'What does this print?', 'data = [1, 5, 3]\nbig = [y for x in data if (y := x * 2) > 4]\nprint(big, y)', 'python', '[10, 6] 6', 'Unlike the loop variable, a walrus target escapes.', 'y is bound in the enclosing scope and keeps the last value assigned (3 * 2 = 6), whether or not that item passed the filter.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2, 10, 6] 6', 0), (@q, 'B', '[10, 6] NameError', 0), (@q, 'C', '[10, 6] 10', 0), (@q, 'D', '[10, 6] 6', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'walrus'), 3, 'mcq', '`results = [y for x in rows if (y := parse(x)) is not None]`. Why use the walrus here?', NULL, NULL, 'parse(x) runs once per row and its result is both tested and kept', 'What would the version without := look like?', 'Without it you''d write [parse(x) for x in rows if parse(x) is not None], calling parse twice per row.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It makes parse run lazily', 0), (@q, 'B', 'parse(x) runs once per row and its result is both tested and kept', 1), (@q, 'C', 'It prevents y from leaking', 0), (@q, 'D', 'It''s required to filter on None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 3, 'code_output', 'What does this print?', 'print([print(x) for x in [1, 2]])', 'python', '1\n2\n[None, None]', 'What does print() return?', 'Each print runs (side effect) and returns None, so you also build a useless [None, None]. Use a plain for loop for side effects.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2]', 0), (@q, 'B', '[None, None]', 0), (@q, 'C', '1\n2\n[None, None]', 1), (@q, 'D', '1\n2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 3, 'mcq', 'Why is `[x * 2 for x in xs]` usually faster than a for-loop that calls `res.append(x * 2)`?', NULL, NULL, 'The comprehension uses a dedicated add-to-list bytecode instead of looking up and calling .append each iteration', 'Count the work per iteration in the loop version.', 'The loop does an attribute lookup plus a method call every pass. Both are still interpreted, so the gain is modest (often 1.2-2x).', NULL, NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Comprehensions run in parallel on several cores', 0), (@q, 'B', 'The loop version copies the list each time', 0), (@q, 'C', 'Comprehensions are compiled to C', 0), (@q, 'D', 'The comprehension uses a dedicated add-to-list bytecode instead of looking up and calling .append each iteration', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 3, 'mcq', 'Which is the BEST reason to rewrite a comprehension as a regular loop?', NULL, NULL, 'It has three nested fors with conditions, or needs try/except per item', 'Comprehensions are for simple transforms.', 'Once a reader has to untangle it, or you need statements (try, logging), a loop is clearer. Readability counts more than one line.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It builds a dict', 0), (@q, 'B', 'It has a single filter', 0), (@q, 'C', 'It uses enumerate', 0), (@q, 'D', 'It has three nested fors with conditions, or needs try/except per item', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 4, 'code_output', 'What does this print?', 'class Config:\n    scale = 10\n    values = [scale * i for i in range(3)]\n\nprint(Config.values)', 'python', 'NameError', 'A class body is not an enclosing scope for nested code.', 'Names defined in a class body are invisible to functions and comprehensions inside it (outside the outermost iterable). scale is not found: NameError.', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 10, 20]', 0), (@q, 'B', 'NameError', 1), (@q, 'C', '[0, 1, 2]', 0), (@q, 'D', 'AttributeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 4, 'code_output', 'What does this print?', 'n = 5\n\nclass C:\n    n = 2\n    xs = [i for i in range(n)]\n\nprint(C.xs)', 'python', '[0, 1]', 'The outermost iterable is special.', 'range(n) is evaluated in the class body, where n is 2. Only the rest of the comprehension is cut off from class names.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', '[]', 0), (@q, 'C', '[0, 1]', 1), (@q, 'D', '[0, 1, 2, 3, 4]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 4, 'code_output', 'What does this print?', 'g1 = (y for x in [1] for y in missing)\nprint("created")\ntry:\n    g2 = (x for x in missing)\nexcept NameError:\n    print("NameError at creation")', 'python', 'created\nNameError at creation', 'Which part of a generator expression runs immediately?', 'Only the outermost iterable is evaluated when the genexp is created. The inner `missing` in g1 is looked up only when iterated, so it doesn''t fail yet.', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', 'created\nNameError at creation', 1), (@q, 'C', 'created', 0), (@q, 'D', 'NameError at creation', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 4, 'code_output', 'What does this print?', 'n = 1\nlst = [0, 1, 2]\ng = (x * n for x in lst)\nn = 10\nlst = [7]\nprint(list(g))', 'python', '[0, 10, 20]', 'One name is captured at creation, the other is read later.', 'lst was evaluated when g was created (so rebinding lst doesn''t matter), but n is looked up when each item is produced (so n = 10 applies).', NULL, NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 1, 2]', 0), (@q, 'B', '[0, 10, 20]', 1), (@q, 'C', '[7]', 0), (@q, 'D', '[70]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'walrus'), 4, 'code_output', 'What does this print?', 'print([(i := i + 1) for i in range(3)])', 'python', 'SyntaxError', 'There''s a special rule about walrus and the iteration variable.', 'An assignment expression cannot rebind a comprehension iteration variable; Python rejects this at compile time.', NULL, NULL, 58);
