INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(3)\nr = [x * 2 for x in a]\nprint(type(r).__name__, type(r[0]).__name__)', 'python', 'list int64', 'A comprehension always builds a Python list.', 'Iterating a NumPy array yields NumPy scalars one by one, so you get a list of np.int64 and lose all vectorisation. Write a * 2 instead.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'list int', 0), (@q, 'B', 'ndarray int', 0), (@q, 'C', 'ndarray int64', 0), (@q, 'D', 'list int64', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 4, 'mcq', 'A teammate replaced `np.sqrt(arr)` (10 million floats) with `[math.sqrt(x) for x in arr]` because ''comprehensions are fast''. What''s the effect?', NULL, NULL, 'Much slower (often 10x+) and returns a list of Python floats instead of an array', 'A comprehension is still a Python-level loop.', 'Comprehensions beat append-loops, but they still execute interpreter code per element. np.sqrt runs one C loop over the buffer.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Faster, because comprehensions skip NumPy overhead', 0), (@q, 'B', 'Much slower (often 10x+) and returns a list of Python floats instead of an array', 1), (@q, 'C', 'It raises TypeError because math.sqrt can''t take NumPy scalars', 0), (@q, 'D', 'About the same speed, same result type', 0);
