INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'debugging'), 1, 'mcq', 'What does putting `breakpoint()` on a line do when the script runs?', NULL, NULL, 'Pauses the program there and opens the pdb debugger so you can inspect variables', 'It''s the Python version of the `debugger;` statement in JavaScript.', 'breakpoint() starts pdb at that line. You can print variables (p x), step (n), continue (c) or quit (q).', NULL, NULL, 26);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Pauses the program there and opens the pdb debugger so you can inspect variables', 1), (@q, 'B', 'Marks the line in the editor but does nothing at runtime', 0), (@q, 'C', 'Stops the program permanently with an error', 0), (@q, 'D', 'Prints all variables and continues', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tracebacks'), 2, 'mcq', 'The traceback below comes from your training script. Where should you look first to fix the bug?', 'Traceback (most recent call last):\n  File "train.py", line 40, in <module>\n    X = prep(df)\n  File "prep.py", line 8, in prep\n    return df["lable"]\n  File ".../pandas/core/frame.py", line 4102, in __getitem__\n  File ".../pandas/core/indexes/base.py", line 3812, in get_loc\nKeyError: ''lable''', 'text', 'prep.py line 8, the last frame from your own code', 'Library frames show how pandas reacted; your frame shows what you asked it to do.', 'The error is raised deep inside pandas, but the cause is what your code passed in. Find the lowest frame that''s in your file: there you asked for the column ''lable''.', NULL, NULL, 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Reinstall pandas: errors inside libraries are library bugs', 0), (@q, 'B', 'prep.py line 8, the last frame from your own code', 1), (@q, 'C', 'train.py line 40, the first line of the traceback', 0), (@q, 'D', 'The pandas frames, because that''s where the error was raised', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 2, 'code_output', 'What does this print?', 'try:\n    print("try")\nexcept ValueError:\n    print("except")\nelse:\n    print("else")\nfinally:\n    print("finally")', 'python', 'try\nelse\nfinally', 'Nothing raises here. Which of the three extra blocks still run?', 'No exception: except is skipped, else runs because try finished cleanly, finally always runs.', 'try --ok----> else ----+\n |                      +--> finally\n +--error--> except --+', NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'try\nexcept\nelse\nfinally', 0), (@q, 'B', 'try\nelse', 0), (@q, 'C', 'try\nfinally', 0), (@q, 'D', 'try\nelse\nfinally', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 2, 'code_output', 'What does this print?', 'try:\n    print("try")\n    1 / 0\nexcept ZeroDivisionError:\n    print("except")\nelse:\n    print("else")\nfinally:\n    print("finally")', 'python', 'try\nexcept\nfinally', 'else is the ''it worked'' block.', 'The division raises, so except runs; else is skipped because try did not finish cleanly; finally always runs.', NULL, NULL, 29);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'try\nexcept\nfinally', 1), (@q, 'B', 'try\nfinally', 0), (@q, 'C', 'try\nexcept\nelse\nfinally', 0), (@q, 'D', 'try\nelse\nfinally', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'catching'), 2, 'code_output', 'What does this print?', 'try:\n    int("x")\nexcept Exception:\n    print("general")\nexcept ValueError:\n    print("value")', 'python', 'general', 'Python checks except clauses top to bottom and stops at the first match.', 'ValueError is a subclass of Exception, so the first clause matches and the second is unreachable. Always put the more specific exception first.', NULL, NULL, 30);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'general', 1), (@q, 'B', 'ValueError', 0), (@q, 'C', 'general\nvalue', 0), (@q, 'D', 'value', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 2, 'code_output', 'What does this print?', 'try:\n    [][0]\nexcept (KeyError, IndexError) as e:\n    print(type(e).__name__)', 'python', 'IndexError', 'A tuple of types catches any one of them; e is the actual error.', 'Indexing an empty list raises IndexError. `type(e).__name__` reports the real class, not the tuple.', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'IndexError', 1), (@q, 'B', 'LookupError', 0), (@q, 'C', '(KeyError, IndexError)', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 2, 'code_output', 'What does this print?', 'try:\n    1 / 0\nexcept ZeroDivisionError as e:\n    pass\nprint(e)', 'python', 'NameError', 'Python cleans up the `as` name when the except block ends.', 'At the end of an except block Python deletes `e` (to avoid a reference cycle with the traceback). Using it afterwards raises NameError. Copy it to another variable if you need it later.', NULL, NULL, 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 1), (@q, 'B', 'ZeroDivisionError', 0), (@q, 'C', 'None', 0), (@q, 'D', 'division by zero', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'catching'), 2, 'mcq', 'Which class is the direct parent of KeyboardInterrupt (raised when you press Ctrl+C)?', NULL, NULL, 'BaseException', 'It''s deliberately kept out of the normal ''error'' family.', 'KeyboardInterrupt, SystemExit and GeneratorExit inherit directly from BaseException, so `except Exception:` does not catch them and Ctrl+C still works.', 'BaseException\n|-- KeyboardInterrupt\n|-- SystemExit\n|-- GeneratorExit\n`-- Exception\n    |-- ValueError\n    |-- TypeError\n    `-- LookupError -> KeyError, IndexError', NULL, 33);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SystemExit', 0), (@q, 'B', 'Exception', 0), (@q, 'C', 'BaseException', 1), (@q, 'D', 'RuntimeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'catching'), 2, 'true_false', '`except Exception:` will catch a KeyboardInterrupt from pressing Ctrl+C.', NULL, NULL, 'False', 'Look at where KeyboardInterrupt sits in the class tree.', 'KeyboardInterrupt inherits from BaseException, not Exception, so `except Exception` lets it through. Only a bare `except:` or `except BaseException:` would swallow it.', NULL, NULL, 34);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 2, 'code_output', 'What does this print?', 'def load():\n    try:\n        int("x")\n    except ValueError:\n        print("logging")\n        raise\n\ntry:\n    load()\nexcept ValueError:\n    print("caller")', 'python', 'logging\ncaller', 'A bare `raise` inside except throws the same error again.', 'load() logs and then re-raises the same ValueError, which the caller catches. Log-and-re-raise is the standard pattern when you can''t fully handle an error.', NULL, NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'caller', 0), (@q, 'B', 'logging', 0), (@q, 'C', 'logging\nValueError', 0), (@q, 'D', 'logging\ncaller', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 2, 'true_false', '`raise ValueError` (no parentheses) is valid Python and raises a ValueError with an empty message.', NULL, NULL, 'True', 'Python can create the instance for you.', 'If you raise a class, Python calls it with no arguments. `raise ValueError()` and `raise ValueError` are equivalent.', NULL, NULL, 36);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'custom-exceptions'), 2, 'code_output', 'What does this print?', 'class DataError(Exception):\n    pass\n\nclass MissingColumn(DataError):\n    pass\n\ntry:\n    raise MissingColumn("label")\nexcept DataError as e:\n    print(type(e).__name__, e)', 'python', 'MissingColumn label', 'Catching a base class catches all of its subclasses too.', 'MissingColumn is a DataError, so the clause matches. type(e) is still the real class, and str(e) is the message.', NULL, 'Like catching IOException in Java and receiving a FileNotFoundException.', 37);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'MissingColumn: label', 0), (@q, 'B', 'MissingColumn', 0), (@q, 'C', 'DataError label', 0), (@q, 'D', 'MissingColumn label', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'custom-exceptions'), 2, 'mcq', 'Why do libraries define one base exception (e.g. `class DataError(Exception)`) and several subclasses under it?', NULL, NULL, 'Callers can catch every error from the library with one clause, or a single specific one when they need to', 'Think about the person calling your code.', 'A shared base lets callers write `except DataError` for ''anything from this library'', while subclasses allow precise handling. requests (RequestException) and SQLAlchemy work this way.', NULL, NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Python requires at least two levels of exceptions', 0), (@q, 'B', 'It makes the exceptions faster to raise', 0), (@q, 'C', 'Subclasses make the error message longer', 0), (@q, 'D', 'Callers can catch every error from the library with one clause, or a single specific one when they need to', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 2, 'mcq', 'In `with ctx as x:`, what gets bound to `x`?', NULL, NULL, 'Whatever ctx.__enter__() returns', 'It''s often the same object, but not always.', '`as x` receives the return value of __enter__. open() returns the file itself; other managers can return something else.', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The return value of ctx.__exit__()', 0), (@q, 'B', 'ctx itself, always', 0), (@q, 'C', 'Whatever ctx.__enter__() returns', 1), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 2, 'code_output', 'What does this print?', 'class Timer:\n    def __enter__(self):\n        print("enter")\n        return self\n    def __exit__(self, exc_type, exc, tb):\n        print("exit")\n\nwith Timer():\n    print("body")', 'python', 'enter\nbody\nexit', 'One method runs on the way in, the other on the way out.', '`with` calls __enter__, runs the body, then calls __exit__.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'enter\nbody', 0), (@q, 'B', 'body\nenter\nexit', 0), (@q, 'C', 'enter\nexit\nbody', 0), (@q, 'D', 'enter\nbody\nexit', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 2, 'code_output', 'What does this print?', 'class Guard:\n    def __enter__(self):\n        print("enter")\n    def __exit__(self, exc_type, exc, tb):\n        print("exit", exc_type.__name__)\n\ntry:\n    with Guard():\n        raise KeyError("k")\nexcept KeyError:\n    print("caught")', 'python', 'enter\nexit KeyError\ncaught', '__exit__ is told about the error before it continues outward.', '__exit__ runs even when the body raises and receives the exception type. It returns None (falsy), so the KeyError keeps propagating to the outer except.', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'enter\nexit KeyError', 0), (@q, 'B', 'enter\ncaught\nexit KeyError', 0), (@q, 'C', 'enter\nexit KeyError\ncaught', 1), (@q, 'D', 'enter\ncaught', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 2, 'code_output', 'What does this print?', 'it = iter([])\nprint(next(it))', 'python', 'StopIteration', 'This is how a for loop knows an iterator is finished.', 'next() on an exhausted iterator raises StopIteration. Use next(it, default) to get a default value instead.', NULL, NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'IndexError', 0), (@q, 'B', 'ValueError', 0), (@q, 'C', 'StopIteration', 1), (@q, 'D', 'None', 0);
