INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 3, 'code_output', 'What does this print?', 'def f():\n    try:\n        return "try"\n    finally:\n        print("cleanup")\n\nprint(f())', 'python', 'cleanup\ntry', 'finally runs before the function actually hands back its value.', 'The return value is computed, then finally runs (printing ''cleanup''), and only then does f return ''try'' to print.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'cleanup\ntry', 1), (@q, 'B', 'try', 0), (@q, 'C', 'cleanup', 0), (@q, 'D', 'try\ncleanup', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 3, 'code_output', 'What does this print?', 'try:\n    try:\n        x = 1\n    except ValueError:\n        print("inner except")\n    else:\n        int("bad")\nexcept ValueError:\n    print("outer")', 'python', 'outer', 'Is the else block protected by the except right above it?', 'Errors in else are NOT caught by that try''s except clauses; that''s the point of else. The ValueError escapes to the outer handler.', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', 'inner except', 0), (@q, 'C', 'inner except\nouter', 0), (@q, 'D', 'outer', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 3, 'code_output', 'What does this print?', 'try:\n    try:\n        int("x")\n    except ValueError as e:\n        raise RuntimeError("bad config") from e\nexcept RuntimeError as err:\n    print(type(err.__cause__).__name__)', 'python', 'ValueError', '`from e` records the original error on the new one.', '`raise X from e` sets X.__cause__ = e, so the root cause stays attached when you wrap a low-level error.', 'RuntimeError(''bad config'')\n   .__cause__   -> ValueError (explicit: raise ... from e)\n   .__context__ -> ValueError (set automatically)', 'Like Java''s `new RuntimeException("bad config", cause)`.', 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Exception', 0), (@q, 'B', 'RuntimeError', 0), (@q, 'C', 'NoneType', 0), (@q, 'D', 'ValueError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 3, 'code_output', 'What does this print?', 'try:\n    try:\n        int("x")\n    except ValueError:\n        raise RuntimeError("bad config")\nexcept RuntimeError as err:\n    print(err.__cause__, type(err.__context__).__name__)', 'python', 'None ValueError', 'No `from` was used. Python still remembers something.', 'Without `from`, __cause__ stays None, but Python automatically sets __context__ to the error being handled (implicit chaining).', NULL, NULL, 58);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None None', 0), (@q, 'B', 'ValueError None', 0), (@q, 'C', 'None ValueError', 1), (@q, 'D', 'ValueError ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 3, 'mcq', 'What does `raise ConfigError("missing key") from None` do?', NULL, NULL, 'Raises ConfigError and hides the original error from the printed traceback', 'It''s about what the traceback shows.', '`from None` suppresses the ''During handling of the above exception'' section, so users see only the clean error. Use it when the low-level error would just confuse them.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Deletes the original error object from memory', 0), (@q, 'B', 'Raises ConfigError with no message', 0), (@q, 'C', 'Raises nothing; `from None` cancels the raise', 0), (@q, 'D', 'Raises ConfigError and hides the original error from the printed traceback', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'custom-exceptions'), 3, 'code_output', 'What does this print?', 'class HTTPError(Exception):\n    def __init__(self, status, msg):\n        super().__init__(msg)\n        self.status = status\n\ntry:\n    raise HTTPError(404, "not found")\nexcept HTTPError as e:\n    print(e.status, e, e.args)', 'python', '404 not found (''not found'',)', 'args holds whatever was passed to super().__init__.', 'The extra field lives on self.status. Only msg went to Exception.__init__, so str(e) is ''not found'' and e.args is (''not found'',).', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '404 not found (''not found'',)', 1), (@q, 'B', 'not found 404 ()', 0), (@q, 'C', '404 (404, ''not found'') (''not found'',)', 0), (@q, 'D', '404 not found (404, ''not found'')', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'custom-exceptions'), 3, 'code_output', 'What does this print?', 'class Stop(BaseException):\n    pass\n\ntry:\n    try:\n        raise Stop()\n    except Exception:\n        print("caught by Exception")\nexcept BaseException:\n    print("escaped")', 'python', 'escaped', 'Where does Stop sit in the tree relative to Exception?', 'Stop inherits from BaseException, not Exception, so the inner clause doesn''t match. That''s why custom errors should subclass Exception: otherwise normal handlers miss them.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Stop', 0), (@q, 'B', 'escaped', 1), (@q, 'C', 'caught by Exception\nescaped', 0), (@q, 'D', 'caught by Exception', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 3, 'code_output', 'What does this print?', 'class Quiet:\n    def __enter__(self):\n        return self\n    def __exit__(self, exc_type, exc, tb):\n        return True\n\nwith Quiet():\n    1 / 0\nprint("after with")', 'python', 'after with', 'What does a truthy return value from __exit__ mean?', 'If __exit__ returns a truthy value, the exception is suppressed and execution continues after the with. Returning True by accident hides real errors.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ZeroDivisionError', 0), (@q, 'B', 'nothing is printed', 0), (@q, 'C', 'after with', 1), (@q, 'D', 'inf\nafter with', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 3, 'code_output', 'What does this print?', 'from contextlib import contextmanager\n\n@contextmanager\ndef stage(name):\n    print("start", name)\n    try:\n        yield\n    finally:\n        print("end", name)\n\nwith stage("load"):\n    print("working")', 'python', 'start load\nworking\nend load', 'Code before yield is __enter__, code after is __exit__.', '@contextmanager turns a generator into a context manager: it runs up to yield, runs the body, then resumes after yield.', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'start load\nworking', 0), (@q, 'B', 'start load\nworking\nend load', 1), (@q, 'C', 'working\nstart load\nend load', 0), (@q, 'D', 'start load\nend load\nworking', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 3, 'code_output', 'What does this print?', 'from contextlib import suppress\n\nd = {}\nwith suppress(KeyError):\n    d["x"]\n    print("inside")\nprint("continue")', 'python', 'continue', 'suppress swallows the named error, but where does execution resume?', 'd[''x''] raises KeyError, which ends the with block immediately (skipping ''inside''). suppress swallows it, and the program continues after the block.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', 'inside', 0), (@q, 'C', 'inside\ncontinue', 0), (@q, 'D', 'continue', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'assert-warnings'), 3, 'mcq', 'You run a script with `python -O train.py`. What happens to `assert batch.shape[0] > 0` inside it?', NULL, NULL, 'The assert is removed and never checked', '-O means ''optimise''. What is considered optional?', 'With -O, Python sets __debug__ to False and compiles assert statements away. Asserts are for internal sanity checks, not required validation.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It becomes a warning', 0), (@q, 'B', 'It is checked twice', 0), (@q, 'C', 'It raises a SyntaxError', 0), (@q, 'D', 'The assert is removed and never checked', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'assert-warnings'), 3, 'code_output', 'What does this print?', 'x = -1\nassert (x > 0, "x must be positive")\nprint("passed")', 'python', 'passed', 'Look closely at the parentheses: what kind of object is being asserted?', 'The parentheses make a 2-element tuple, and a non-empty tuple is always truthy, so this assert can never fail. Write `assert x > 0, "msg"` without the brackets.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'x must be positive', 0), (@q, 'B', 'AssertionError', 0), (@q, 'C', 'passed', 1), (@q, 'D', 'SyntaxError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'assert-warnings'), 3, 'code_output', 'What does this print?', 'import warnings\n\nwith warnings.catch_warnings(record=True) as caught:\n    warnings.simplefilter("always")\n    warnings.warn("old API", DeprecationWarning)\n    print("still running")\nprint(len(caught), caught[0].category.__name__)', 'python', 'still running\n1 DeprecationWarning', 'A warning is not an exception: does the code stop?', 'warnings.warn reports a problem but lets the program keep going. catch_warnings(record=True) collects them in a list.', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'still running\n1 DeprecationWarning', 1), (@q, 'B', 'still running\n0 DeprecationWarning', 0), (@q, 'C', 'DeprecationWarning', 0), (@q, 'D', '1 DeprecationWarning', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'assert-warnings'), 3, 'mcq', 'When should you use `warnings.warn(...)` instead of `raise`?', NULL, NULL, 'When the code can still continue correctly but the caller should change something (e.g. a deprecated argument)', 'Libraries like NumPy and pandas use this for features that will be removed.', 'Warnings are for ''this works now but is risky or going away''. If continuing would produce a wrong result, raise.', NULL, NULL, 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only inside except blocks', 0), (@q, 'B', 'Whenever you want the program to stop', 0), (@q, 'C', 'When the input is invalid and the result would be wrong', 0), (@q, 'D', 'When the code can still continue correctly but the caller should change something (e.g. a deprecated argument)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'debugging'), 3, 'mcq', 'In the pdb debugger, what is the difference between `n` and `s`?', NULL, NULL, 'n runs the current line and stops at the next one; s steps into a function call on the current line', 'Think ''next'' versus ''step into''.', 'n (next) steps over function calls; s (step) goes inside them. c continues, p x prints x, q quits.', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'There is no difference', 0), (@q, 'B', 'n means ''no'' and s means ''save''', 0), (@q, 'C', 'n runs the current line and stops at the next one; s steps into a function call on the current line', 1), (@q, 'D', 'n continues to the end; s stops immediately', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'debugging'), 3, 'mcq', 'A Jupyter cell just crashed deep inside a function. What does running `%debug` in the next cell do?', NULL, NULL, 'Opens pdb at the frame where the exception happened, so you can inspect the local variables at the crash', 'It''s called post-mortem debugging.', '%debug starts a post-mortem pdb session on the last exception: you can `p` the variables of the frame that failed and move `u`/`d` through the stack.', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Restarts the kernel in debug mode', 0), (@q, 'B', 'Re-runs the previous cell with extra logging', 0), (@q, 'C', 'Opens pdb at the frame where the exception happened, so you can inspect the local variables at the crash', 1), (@q, 'D', 'Turns on debug-level logging for the notebook', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'debugging'), 3, 'mcq', 'Inside `except` you call `logger.exception("failed to load batch")`. What gets logged?', NULL, NULL, 'The message at ERROR level plus the full traceback of the current exception', 'It''s meant to be called from inside an except block.', 'logger.exception is logger.error with exc_info=True: the message plus the traceback, without stopping the program.', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only the traceback, at DEBUG level', 0), (@q, 'B', 'Nothing; it raises the exception again', 0), (@q, 'C', 'Only the message, at EXCEPTION level', 0), (@q, 'D', 'The message at ERROR level plus the full traceback of the current exception', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'catching'), 3, 'mcq', 'Which style is called EAFP and is considered idiomatic Python?', NULL, NULL, 'try: value = d[key]\nexcept KeyError: value = default', 'EAFP = ''easier to ask forgiveness than permission''.', 'EAFP tries the operation and handles the failure. LBYL (look before you leap) checks first, which can race when, for example, a file is deleted between the check and the open.', NULL, NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'value = d[key] if d else default', 0), (@q, 'B', 'try: value = d[key]\nexcept KeyError: value = default', 1), (@q, 'C', 'assert key in d; value = d[key]', 0), (@q, 'D', 'if key in d: value = d[key]\nelse: value = default', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'catching'), 3, 'code_output', 'What does this print?', 'import sys\n\ntry:\n    sys.exit(1)\nexcept Exception:\n    print("A")\nexcept SystemExit as e:\n    print("exit", e.code)', 'python', 'exit 1', 'sys.exit doesn''t kill the process directly. It raises something.', 'sys.exit raises SystemExit, which inherits from BaseException, so `except Exception` skips it. This is why a bare except can stop a script from exiting.', NULL, NULL, 73);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'exit 1', 1), (@q, 'B', 'nothing is printed', 0), (@q, 'C', 'A', 0), (@q, 'D', 'A\nexit 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'catching'), 3, 'code_output', 'What does this print?', 'def gen():\n    try:\n        yield 1\n    finally:\n        print("cleanup")\n\ng = gen()\nnext(g)\ng.close()\nprint("closed")', 'python', 'cleanup\nclosed', 'close() throws something into the paused generator.', 'g.close() raises GeneratorExit at the paused yield, so finally runs. GeneratorExit is a BaseException, so an `except Exception` inside the generator won''t accidentally swallow it.', NULL, NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'GeneratorExit', 0), (@q, 'B', 'cleanup\nclosed', 1), (@q, 'C', 'closed\ncleanup', 0), (@q, 'D', 'closed', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'exception-groups'), 3, 'mcq', 'What is an ExceptionGroup (Python 3.11+)?', NULL, NULL, 'One exception that carries several unrelated exceptions, e.g. from tasks that failed in parallel', 'Think of five downloads running at once and three of them failing.', 'ExceptionGroup(msg, [e1, e2, ...]) bundles several exceptions so none are lost. asyncio.TaskGroup raises one when child tasks fail.', NULL, NULL, 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A logging handler that groups repeated errors', 0), (@q, 'B', 'The base class of all built-in exceptions', 0), (@q, 'C', 'A tuple of exception classes used in `except (A, B):`', 0), (@q, 'D', 'One exception that carries several unrelated exceptions, e.g. from tasks that failed in parallel', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'exception-groups'), 3, 'code_output', 'What does this print?', 'eg = ExceptionGroup("batch", [ValueError("a"), TypeError("b")])\nprint(len(eg.exceptions), type(eg.exceptions[1]).__name__)', 'python', '2 TypeError', 'Creating an exception does not raise it.', 'The group stores its members in .exceptions, in the order given.', NULL, NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '1 ExceptionGroup', 0), (@q, 'C', '2 ValueError', 0), (@q, 'D', '2 TypeError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 4, 'code_output', 'What does this print?', 'def f():\n    try:\n        return 1\n    finally:\n        return 2\n\nprint(f())', 'python', '2', 'Which return statement runs last?', 'finally runs after the try''s return has been scheduled, and a return in finally replaces it. Python 3.14 even warns about this (PEP 765) because it is almost always a bug.', NULL, NULL, 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SyntaxError', 0), (@q, 'B', '1\n2', 0), (@q, 'C', '2', 1), (@q, 'D', '1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 4, 'code_output', 'What does this print?', 'def f():\n    try:\n        1 / 0\n    finally:\n        return "swallowed"\n\nprint(f())', 'python', 'swallowed', 'A return in finally ends the function no matter what was in flight.', 'The ZeroDivisionError is discarded silently because finally returns. This is how real bugs vanish.', 'try:     1 / 0      -> ZeroDivisionError in flight\nfinally: return ... -> replaces it with a normal return\ncaller:  sees ''swallowed'', never the error', NULL, 78);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'swallowed', 1), (@q, 'B', 'swallowed\nZeroDivisionError', 0), (@q, 'C', 'None', 0), (@q, 'D', 'ZeroDivisionError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 4, 'code_output', 'What does this print?', 'def f():\n    x = [1]\n    try:\n        return x\n    finally:\n        x.append(2)\n\nprint(f())', 'python', '[1, 2]', 'The return value is a reference to an object. Can finally still change that object?', 'return x captures a reference to the list; finally then mutates the same list before the caller sees it.', NULL, NULL, 79);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2]', 1), (@q, 'B', '[2]', 0), (@q, 'C', '[1]', 0), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 4, 'code_output', 'What does this print?', 'def f():\n    x = 1\n    try:\n        return x\n    finally:\n        x = 2\n\nprint(f())', 'python', '1', 'Rebinding a name is not the same as mutating an object.', 'The value 1 was already evaluated for the return. Reassigning x in finally doesn''t change what''s returned (compare the list version).', NULL, NULL, 80);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1', 1), (@q, 'B', 'None', 0), (@q, 'C', '1\n2', 0), (@q, 'D', '2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 4, 'code_output', 'What does this print?', 'for i in range(3):\n    try:\n        raise ValueError("boom")\n    finally:\n        break\nprint("done", i)', 'python', 'done 0', 'break in finally behaves like return in finally.', 'The break in finally discards the in-flight ValueError and exits the loop on the first iteration.', NULL, NULL, 81);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', 'done 0\nValueError', 0), (@q, 'C', 'done 2', 0), (@q, 'D', 'done 0', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 4, 'mcq', 'Inside `except ValueError as e:`, what is the practical difference between a bare `raise` and `raise e`?', NULL, NULL, 'Both re-raise the same object, but `raise e` adds the current line as an extra traceback frame; bare raise re-raises exactly as it was', 'Same object either way. Look at the traceback.', 'Both raise the same exception instance. `raise e` appends the re-raise line to e.__traceback__, while bare `raise` leaves it untouched, which is why bare raise is preferred for log-and-re-raise.', NULL, NULL, 82);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '`raise e` resets __cause__ and __context__ to None', 0), (@q, 'B', '`raise e` creates a new ValueError and loses the original message', 0), (@q, 'C', 'Both re-raise the same object, but `raise e` adds the current line as an extra traceback frame; bare raise re-raises exactly as it was', 1), (@q, 'D', 'Bare `raise` only works outside an except block', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 4, 'code_output', 'What does this print?', 'try:\n    try:\n        int("x")\n    except ValueError:\n        raise KeyError("cfg") from None\nexcept KeyError as err:\n    print(err.__cause__, err.__context__ is not None, err.__suppress_context__)', 'python', 'None True True', '`from None` hides the context. Does it delete it?', 'from None sets __cause__ = None and __suppress_context__ = True, but __context__ still holds the ValueError. Only the traceback display hides it.', NULL, NULL, 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError True True', 0), (@q, 'B', 'None False False', 0), (@q, 'C', 'None True True', 1), (@q, 'D', 'None False True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 4, 'code_output', 'What does this print?', 'try:\n    raise ValueError("bad row")\nexcept ValueError as e:\n    e.add_note("row 17 in train.csv")\n    print(e.__notes__, str(e))', 'python', '[''row 17 in train.csv''] bad row', 'add_note (3.11+) stores extra context separately from the message.', 'Notes are kept in e.__notes__ and printed below the error in tracebacks; str(e) is unchanged.', NULL, NULL, 84);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''row 17 in train.csv''] bad row', 1), (@q, 'B', 'AttributeError', 0), (@q, 'C', '[''row 17 in train.csv''] bad row row 17 in train.csv', 0), (@q, 'D', 'row 17 in train.csv bad row', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'custom-exceptions'), 4, 'code_output', 'What does this print?', 'import copy\n\nclass APIError(Exception):\n    def __init__(self, code, msg):\n        super().__init__(msg)\n        self.code = code\n\ne = APIError(500, "server down")\nprint(copy.copy(e).code)', 'python', 'TypeError', 'copy and pickle rebuild an exception by calling cls(*e.args).', 'e.args is (''server down'',), so copying (or unpickling) calls APIError(''server down'') and the missing msg argument raises TypeError. This bites when errors cross process boundaries (multiprocessing, DataLoader workers). Pass all args to super().__init__.', NULL, NULL, 85);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '500', 0), (@q, 'B', 'TypeError', 1), (@q, 'C', 'None', 0), (@q, 'D', 'AttributeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'custom-exceptions'), 4, 'mcq', 'A team defines `class RetryableError(BaseException)` so that ''nobody accidentally swallows it''. What is the real effect?', NULL, NULL, 'Generic `except Exception` handlers (logging middleware, frameworks, retry wrappers) let it escape, so it can crash the process and skip cleanup that only handles Exception', 'BaseException is reserved for ''stop the program'' signals.', 'Only exit-like signals (KeyboardInterrupt, SystemExit, GeneratorExit, asyncio.CancelledError) should bypass `except Exception`. Application errors should subclass Exception.', NULL, NULL, 86);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Generic `except Exception` handlers (logging middleware, frameworks, retry wrappers) let it escape, so it can crash the process and skip cleanup that only handles Exception', 1), (@q, 'B', 'It becomes impossible to catch', 0), (@q, 'C', 'Python refuses to raise it outside the main thread', 0), (@q, 'D', 'Nothing: BaseException and Exception behave the same', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 4, 'code_output', 'What does this print?', 'try:\n    {}["a"]\nexcept KeyError as e:\n    print(e, ValueError("a"))', 'python', '''a'' a', 'KeyError formats its message differently from other exceptions.', 'KeyError.__str__ uses repr of the key (so an empty-string key is visible as ''''), while ValueError''s str is the plain message.', NULL, NULL, 87);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'a a', 0), (@q, 'B', '''a'' ''a''', 0), (@q, 'C', 'KeyError: ''a'' a', 0), (@q, 'D', '''a'' a', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 4, 'code_output', 'What does this print?', 'try:\n    open("no_such_file_for_quiz_9431.csv")\nexcept OSError as e:\n    print(type(e).__name__, e.errno)', 'python', 'FileNotFoundError 2', 'Python maps errno codes to specific OSError subclasses.', 'OSError picks a subclass from the errno: ENOENT (2) becomes FileNotFoundError. Catching OSError covers FileNotFoundError, PermissionError, IsADirectoryError and friends.', NULL, NULL, 88);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'FileNotFoundError 2', 1), (@q, 'B', 'OSError 2', 0), (@q, 'C', 'IOError 2', 0), (@q, 'D', 'FileNotFoundError None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 4, 'code_output', 'What does this print?', 'from contextlib import contextmanager\n\n@contextmanager\ndef stage():\n    print("before")\n    yield\n    print("after")\n\ntry:\n    with stage():\n        raise ValueError("boom")\nexcept ValueError:\n    print("caught")', 'python', 'before\ncaught', 'The body''s error is thrown back into the generator at the yield.', 'The exception is raised at the yield, so ''after'' never runs. Wrap the yield in try/finally if cleanup must always happen.', NULL, NULL, 89);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'caught', 0), (@q, 'B', 'before\ncaught', 1), (@q, 'C', 'before\nafter', 0), (@q, 'D', 'before\nafter\ncaught', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 4, 'code_output', 'What does this print?', 'from contextlib import ExitStack\n\nwith ExitStack() as stack:\n    stack.callback(print, "close first")\n    stack.callback(print, "close second")\n    print("body")', 'python', 'body\nclose second\nclose first', 'Cleanups unwind like a stack.', 'ExitStack runs registered callbacks in LIFO order when the block ends, just like nested with blocks would. Useful for opening a variable number of files.', 'push: close first\npush: close second\nexit: pop -> close second\n      pop -> close first', NULL, 90);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'body', 0), (@q, 'B', 'body\nclose second\nclose first', 1), (@q, 'C', 'body\nclose first\nclose second', 0), (@q, 'D', 'close first\nclose second\nbody', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'assert-warnings'), 4, 'code_output', 'What does this print?', 'import warnings\n\nwith warnings.catch_warnings():\n    warnings.simplefilter("error")\n    try:\n        warnings.warn("lossy cast")\n    except UserWarning as w:\n        print("raised", type(w).__name__)', 'python', 'raised UserWarning', 'The ''error'' filter changes what warn() does.', 'With simplefilter(''error''), warnings become exceptions. warn() with no category uses UserWarning. `python -W error` does the same for a whole test run.', NULL, NULL, 91);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'raised Warning', 0), (@q, 'B', 'nothing is printed', 0), (@q, 'C', 'lossy cast', 0), (@q, 'D', 'raised UserWarning', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'debugging'), 4, 'mcq', 'Why is `logger.debug("batch stats %s", compute_stats(batch))` still slow even when DEBUG is off, and what is the fix?', NULL, NULL, 'compute_stats runs before debug() is called; guard it with `if logger.isEnabledFor(logging.DEBUG):`', 'Python evaluates every argument before calling a function.', 'Lazy %s formatting only skips building the string. The argument expression is still evaluated. For expensive values, check isEnabledFor first. (An f-string would be worse: it also formats the string.)', NULL, NULL, 92);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'compute_stats runs before debug() is called; guard it with `if logger.isEnabledFor(logging.DEBUG):`', 1), (@q, 'B', 'The logger writes to disk even when disabled; remove the handler', 0), (@q, 'C', '%s formatting is slower than f-strings; switch to an f-string', 0), (@q, 'D', 'debug() is always slow; use print instead', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'debugging'), 4, 'code_output', 'What does this print?', 'import logging, sys\n\nparent = logging.getLogger("quiz_app")\nparent.setLevel(logging.ERROR)\nparent.addHandler(logging.StreamHandler(sys.stdout))\nparent.propagate = False\n\nchild = logging.getLogger("quiz_app.data")\nchild.warning("w")\nchild.error("e")', 'python', 'e', 'The child has no level or handler of its own.', 'Loggers form a dotted hierarchy. The child''s level is NOTSET, so its effective level comes from the parent (ERROR); the error record then propagates up to the parent''s handler.', 'root\n `-- quiz_app        level=ERROR, handler -> stdout\n      `-- quiz_app.data   level=NOTSET (inherits)', NULL, 93);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'w', 0), (@q, 'B', 'e', 1), (@q, 'C', 'nothing is printed', 0), (@q, 'D', 'w\ne', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'catching'), 4, 'mcq', 'In a layered app (data loader -> service -> HTTP handler), where should a `FileNotFoundError` from the loader usually be caught?', NULL, NULL, 'At the layer that can decide what to do: wrap it in a domain error (`raise DatasetMissing(...) from e`) and let the HTTP layer turn it into a 404/500', 'Catch where you can act; translate at boundaries.', 'Handle errors where there is enough context to recover; otherwise translate them into meaningful domain errors with chaining, and let one top-level boundary log and respond. Logging at every layer produces duplicate noise.', NULL, NULL, 94);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Nowhere: never catch exceptions in production', 0), (@q, 'B', 'In every layer, logging it each time', 0), (@q, 'C', 'Immediately in the loader, with `except: pass`, so the app never crashes', 0), (@q, 'D', 'At the layer that can decide what to do: wrap it in a domain error (`raise DatasetMissing(...) from e`) and let the HTTP layer turn it into a 404/500', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'exception-groups'), 4, 'code_output', 'What does this print?', 'try:\n    raise ExceptionGroup("g", [ValueError("a"), TypeError("b"), ValueError("c")])\nexcept* ValueError as eg:\n    print("V", len(eg.exceptions))\nexcept* TypeError as eg:\n    print("T", len(eg.exceptions))', 'python', 'V 2\nT 1', 'Unlike plain except, more than one except* clause can run.', 'except* splits the group: the first clause gets a sub-group with both ValueErrors, the second gets the TypeError. Each runs once.', 'ExceptionGroup g: [ValueError a, TypeError b, ValueError c]\n  except* ValueError -> group [a, c]\n  except* TypeError  -> group [b]\n  leftover           -> nothing, so nothing re-raised', NULL, 95);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'V 2', 0), (@q, 'B', 'V 1\nT 1\nV 1', 0), (@q, 'C', 'ExceptionGroup', 0), (@q, 'D', 'V 2\nT 1', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'exception-groups'), 4, 'code_output', 'What does this print?', 'try:\n    try:\n        raise ExceptionGroup("g", [ValueError("a"), TypeError("b")])\n    except* ValueError:\n        print("handled V")\nexcept Exception as rest:\n    print(type(rest).__name__, [type(x).__name__ for x in rest.exceptions])', 'python', 'handled V\nExceptionGroup [''TypeError'']', 'What happens to the part of the group no clause matched?', 'Unmatched exceptions are re-raised automatically, still wrapped in an ExceptionGroup containing only what''s left.', NULL, NULL, 96);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ExceptionGroup [''ValueError'', ''TypeError'']', 0), (@q, 'B', 'handled V\nExceptionGroup [''TypeError'']', 1), (@q, 'C', 'handled V', 0), (@q, 'D', 'handled V\nTypeError []', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'exception-groups'), 4, 'true_false', 'You can mix plain `except ValueError:` and `except* TypeError:` clauses on the same try statement.', NULL, NULL, 'False', 'Python wants one style per try.', 'A try uses either except or except*, not both; mixing them is a SyntaxError. Also, `except* ExceptionGroup` is not allowed.', NULL, NULL, 97);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 2, 'true_false', '`__exit__` still runs when the body of a `with` block raises an exception.', NULL, NULL, 'True', 'That guarantee is the whole point of a context manager.', '__exit__ is called on every exit path (normal end, exception, return, break) and receives the exception details.', NULL, NULL, 98);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
