INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 2, 'fill_blank', 'To write a context manager as a generator function, you decorate it with `@contextlib._____`.', NULL, NULL, 'contextmanager', 'It''s a single word: the thing you are making plus nothing else.', '@contextlib.contextmanager turns a function with one `yield` into a context manager.', NULL, NULL, 100);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 3, 'fill_blank', 'After `raise NewError() from old`, the original error is stored in the attribute `new_error._____`.', NULL, NULL, '__cause__', 'Dunder name meaning ''the reason''.', 'Explicit chaining sets __cause__; implicit chaining (raising inside except) sets __context__.', NULL, NULL, 101);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'debugging'), 3, 'fill_blank', 'In pdb, the one-letter command that continues running until the next breakpoint is `_____`.', NULL, NULL, 'c', 'First letter of ''continue''.', 'c continues; n next line; s step into; p expr prints; q quits; l lists source.', NULL, NULL, 102);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'debugging'), 3, 'true_false', 'Calling `logging.basicConfig(level=logging.DEBUG)` a second time does nothing if the root logger already has handlers.', NULL, NULL, 'True', 'basicConfig is meant to run once, at startup.', 'basicConfig is a no-op once the root logger has handlers (unless you pass force=True). In notebooks this is why changing the level ''doesn''t work'' after an earlier call.', NULL, NULL, 103);
