INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 1, 'mcq', 'What is an exception in Python?', NULL, NULL, 'An object describing an error that stops the normal flow unless some code catches it', 'Same idea as in Java or JavaScript.', 'When something goes wrong Python raises an exception object. If no try/except handles it, the program stops and prints a traceback.', NULL, NULL, 105);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'An object describing an error that stops the normal flow unless some code catches it', 1), (@q, 'B', 'A function that runs at the end of the program', 0), (@q, 'C', 'A warning that is printed and ignored', 0), (@q, 'D', 'A special kind of comment', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 2, 'mcq', 'How is a SyntaxError different from errors like KeyError or TypeError?', NULL, NULL, 'It is raised while Python reads (parses) the code, so no line of that file runs at all', 'Think ''compile error'' versus ''runtime error''.', 'A SyntaxError (missing colon, unclosed bracket) is found before execution, and the caret ^ points at the spot. Other errors happen while lines run.', NULL, 'Like a TypeScript compile error versus an exception thrown at runtime.', 106);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It only happens inside functions', 0), (@q, 'B', 'It is raised after the program finishes', 0), (@q, 'C', 'It is raised while Python reads (parses) the code, so no line of that file runs at all', 1), (@q, 'D', 'It can''t be shown in a traceback', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 2, 'mcq', 'What does `with torch.no_grad():` guarantee in an evaluation loop?', NULL, NULL, 'Gradient tracking is off inside the block and restored when the block ends, even if an error is raised', 'It''s a context manager. What do they always do on exit?', 'no_grad''s __enter__ turns autograd off and its __exit__ restores the previous setting on every exit path, so a crash can''t leave autograd disabled.', NULL, NULL, 107);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Exceptions inside the block are ignored', 0), (@q, 'B', 'The model weights are frozen forever', 0), (@q, 'C', 'The GPU memory is freed', 0), (@q, 'D', 'Gradient tracking is off inside the block and restored when the block ends, even if an error is raised', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 3, 'mcq', 'When should you write `raise SomeError(...) from e` instead of plain `raise SomeError(...)` inside an except block?', NULL, NULL, 'When you are translating a low-level error into a higher-level one on purpose, and want the traceback to say it was the direct cause', 'One says ''I meant to wrap this'', the other says ''something else broke while handling''.', '`from e` documents intent (direct cause). Without it the traceback says ''During handling ... another exception occurred'', which reads like a bug in the handler.', NULL, NULL, 108);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only when e is a KeyError', 0), (@q, 'B', 'When you are translating a low-level error into a higher-level one on purpose, and want the traceback to say it was the direct cause', 1), (@q, 'C', 'Always; plain raise inside except is a syntax error', 0), (@q, 'D', 'When you want to hide e from the traceback', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'catching'), 4, 'true_false', 'Since Python 3.8, `asyncio.CancelledError` inherits from BaseException, so a generic `except Exception:` does not swallow task cancellation.', NULL, NULL, 'True', 'Cancellation is a ''stop'' signal, like KeyboardInterrupt.', 'It was moved out of Exception in 3.8 precisely because retry loops with except Exception kept cancelled tasks alive.', NULL, NULL, 109);
