INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'class-instance'), 1, 'code_output', 'What does this print?', 'class Point:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n\np = Point(2, 3)\nprint(p.x + p.y)', 'python', '5', '__init__ stored both numbers on the object.', 'Point(2, 3) runs __init__, which saves x=2 and y=3 on p. p.x + p.y is 5.', NULL, NULL, 6);
