INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inheritance'), 1, 'mcq', 'How do you say ''Dog inherits from Animal'' in Python?', NULL, NULL, 'class Dog(Animal):', 'The parent goes in brackets.', 'Python puts the parent class in parentheses after the class name. There is no extends keyword.', NULL, NULL, 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'class Dog extends Animal:', 0), (@q, 'B', 'class Dog : Animal', 0), (@q, 'C', 'class Dog inherits Animal:', 0), (@q, 'D', 'class Dog(Animal):', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inheritance'), 1, 'code_output', 'What does this print?', 'class Animal:\n    pass\n\nclass Dog(Animal):\n    pass\n\nprint(isinstance(Dog(), Animal))', 'python', 'True', 'Is every Dog also an Animal?', 'isinstance checks the whole family tree, so a Dog counts as an Animal too.', NULL, NULL, 19);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'TypeError', 0), (@q, 'C', 'False', 0), (@q, 'D', 'Dog', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 1, 'mcq', 'What are ''dunder'' methods like `__init__` and `__len__`?', NULL, NULL, 'Special methods with double underscores that Python calls for you, e.g. len(x) calls x.__len__()', 'Dunder = double underscore.', 'Dunder (magic) methods hook your class into Python''s syntax: __init__ for creation, __len__ for len(), __str__ for print, and so on.', NULL, NULL, 20);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Special methods with double underscores that Python calls for you, e.g. len(x) calls x.__len__()', 1), (@q, 'B', 'Private methods that can''t be called', 0), (@q, 'C', 'Deprecated methods kept for old code', 0), (@q, 'D', 'Methods that run twice', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 1, 'code_output', 'What does this print?', 'class Batch:\n    def __len__(self):\n        return 32\n\nprint(len(Batch()))', 'python', '32', 'len(x) asks the object for its length.', 'len() calls the object''s __len__ method, which returns 32.', NULL, NULL, 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '0', 0), (@q, 'C', '32', 1), (@q, 'D', '1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 1, 'code_output', 'What does this print?', 'class User:\n    def __init__(self, name):\n        self.name = name\n    def __str__(self):\n        return "User: " + self.name\n\nprint(User("ravi"))', 'python', 'User: ravi', 'print looks for one particular dunder method.', 'print() calls __str__ to get a readable string. Without it you''d see something like <__main__.User object at 0x...>.', NULL, NULL, 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '<User object>', 0), (@q, 'B', 'User', 0), (@q, 'C', 'ravi', 0), (@q, 'D', 'User: ravi', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dataclasses'), 1, 'code_output', 'What does this print?', 'from dataclasses import dataclass\n\n@dataclass\nclass Point:\n    x: int\n    y: int\n\nprint(Point(1, 2))', 'python', 'Point(x=1, y=2)', '@dataclass writes some methods for you.', '@dataclass generates __init__ and a readable __repr__ from the annotated fields, so you get Point(x=1, y=2) for free.', NULL, 'Like a Java record or a Lombok @Data class.', 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(1, 2)', 0), (@q, 'B', '<Point object>', 0), (@q, 'C', 'Point(x=1, y=2)', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duck-typing'), 1, 'mcq', 'What does ''duck typing'' mean in Python?', NULL, NULL, 'If an object has the method you need, you can use it, whatever its class is', '''If it walks like a duck and quacks like a duck...''', 'Python checks behaviour at the moment of use: anything with .read() can be treated like a file, anything with __len__ works with len().', NULL, 'Like JavaScript: you call obj.render() without checking what class obj is.', 24);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Python converts types automatically', 0), (@q, 'B', 'If an object has the method you need, you can use it, whatever its class is', 1), (@q, 'C', 'Variables must declare their type', 0), (@q, 'D', 'Every class must inherit from a Duck base class', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'composition'), 1, 'mcq', 'A `Car` holds an `Engine` object in `self.engine`. Which relationship is this?', NULL, NULL, 'Composition: a Car has an Engine', 'Has-a or is-a?', 'Storing another object as an attribute is composition (has-a). Inheritance is for is-a: a Dog is an Animal.', NULL, NULL, 25);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Name mangling', 0), (@q, 'B', 'Duck typing', 0), (@q, 'C', 'Inheritance: a Car is an Engine', 0), (@q, 'D', 'Composition: a Car has an Engine', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nn-module'), 1, 'mcq', 'In a PyTorch model class, which method do you write to describe how the input turns into the output?', NULL, NULL, 'forward', 'It''s the ''forward pass''.', 'Layers are created in __init__; the actual computation goes in forward(self, x).', NULL, NULL, 26);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '__init__', 0), (@q, 'B', 'predict', 0), (@q, 'C', 'forward', 1), (@q, 'D', 'run', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 2, 'code_output', 'What does this print?', 'class Model:\n    layers = []\n    def add(self, layer):\n        self.layers.append(layer)\n\na = Model()\nb = Model()\na.add("conv")\nprint(b.layers)', 'python', '[''conv'']', 'Where does the list actually live?', 'layers is a class attribute: one list shared by every Model. Appending through a changes the list b sees too. Create per-object lists in __init__: self.layers = [].', 'Model.layers ---> [ ''conv'' ]\n   ^        ^\n   a        b    (both read the same list)', 'Like a static List field in Java: one copy for all instances.', 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[]', 0), (@q, 'B', 'None', 0), (@q, 'C', 'AttributeError', 0), (@q, 'D', '[''conv'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 2, 'code_output', 'What does this print?', 'class C:\n    n = 0\n\na = C()\na.n = 5\nprint(C.n, a.n)', 'python', '0 5', 'Assigning through an instance creates something new on that instance.', 'a.n = 5 creates an instance attribute on a that hides the class attribute. C.n is still 0.', NULL, NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '5 5', 0), (@q, 'B', '0 5', 1), (@q, 'C', '0 0', 0), (@q, 'D', '5 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 2, 'code_output', 'What does this print?', 'class User:\n    count = 0\n    def __init__(self):\n        User.count += 1\n\nUser()\nUser()\nUser()\nprint(User.count)', 'python', '3', 'The counter is updated on the class, not on self.', 'Writing User.count changes the shared class attribute, so it counts every instance created.', NULL, NULL, 29);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1', 0), (@q, 'B', '3', 1), (@q, 'C', 'AttributeError', 0), (@q, 'D', '0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 2, 'code_output', 'What does this print?', 'class Temp:\n    def __init__(self, c):\n        self.c = c\n\n    @classmethod\n    def from_f(cls, f):\n        return cls((f - 32) * 5 / 9)\n\nprint(Temp.from_f(212).c)', 'python', '100.0', 'cls is the class, so cls(...) builds a new Temp.', 'A classmethod receives the class as cls; it''s the usual way to write alternative constructors. / always gives a float, so 100.0.', NULL, NULL, 30);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '100', 0), (@q, 'B', '212', 0), (@q, 'C', '100.0', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 2, 'code_output', 'What does this print?', 'class MathU:\n    @staticmethod\n    def add(a, b):\n        return a + b\n\nprint(MathU.add(2, 3), MathU().add(2, 3))', 'python', '5 5', 'A staticmethod doesn''t receive self or cls.', 'A staticmethod is a plain function living in the class namespace. It works the same whether called on the class or an instance.', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '5 5', 1), (@q, 'B', 'TypeError', 0), (@q, 'C', '5 TypeError', 0), (@q, 'D', 'None None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 2, 'mcq', 'You want `Config.from_json(path)` that returns a new Config, and it should also work for subclasses. Which decorator?', NULL, NULL, '@classmethod', 'Which decorator tells the method which class it was called on?', '@classmethod passes cls, so SubConfig.from_json(...) builds a SubConfig. A staticmethod would hard-code the class name.', NULL, NULL, 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'No decorator, a normal method', 0), (@q, 'B', '@staticmethod', 0), (@q, 'C', '@property', 0), (@q, 'D', '@classmethod', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'property-encapsulation'), 2, 'code_output', 'What does this print?', 'class Circle:\n    def __init__(self, r):\n        self.r = r\n\n    @property\n    def area(self):\n        return 3 * self.r ** 2\n\nprint(Circle(2).area)', 'python', '12', '@property lets you read a method like an attribute, without ().', 'area is computed on access. 3 * 2**2 = 12 (** binds tighter than *).', NULL, 'Like a getter in JavaScript: get area() { ... }.', 33);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '12', 1), (@q, 'C', '36', 0), (@q, 'D', '<bound method>', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'property-encapsulation'), 2, 'code_output', 'What does this print?', 'class Circle:\n    def __init__(self, r):\n        self.r = r\n\n    @property\n    def area(self):\n        return 3 * self.r ** 2\n\nc = Circle(2)\nc.area = 50', 'python', 'AttributeError', 'Did the class say how to set area?', 'A property without a setter is read-only, so assigning to it raises AttributeError.', NULL, NULL, 34);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'AttributeError', 1), (@q, 'C', 'nothing is printed', 0), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'property-encapsulation'), 2, 'code_output', 'What does this print?', 'class Circle:\n    def __init__(self, r):\n        self.r = r\n\n    @property\n    def area(self):\n        return 3 * self.r ** 2\n\nprint(Circle(2).area())', 'python', 'TypeError', 'c.area already gives you the number. Then you call that number.', 'c.area evaluates to 12, and 12() fails with TypeError: ''int'' object is not callable. Properties are used without parentheses.', NULL, NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 1), (@q, 'B', 'AttributeError', 0), (@q, 'C', '12', 0), (@q, 'D', '<bound method>', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'property-encapsulation'), 2, 'code_output', 'What does this print?', 'class Account:\n    def __init__(self):\n        self._balance = 0\n\n    @property\n    def balance(self):\n        return self._balance\n\n    @balance.setter\n    def balance(self, value):\n        if value < 0:\n            raise ValueError("negative")\n        self._balance = value\n\na = Account()\na.balance = 50\ntry:\n    a.balance = -5\nexcept ValueError:\n    print("rejected", a.balance)', 'python', 'rejected 50', 'The setter runs on every assignment to a.balance.', 'The first assignment passes validation; the second raises in the setter before changing anything, so the balance stays 50.', NULL, NULL, 36);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'rejected 50', 1), (@q, 'B', 'rejected -5', 0), (@q, 'C', 'ValueError', 0), (@q, 'D', 'rejected 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'property-encapsulation'), 2, 'code_output', 'What does this print?', 'class Account:\n    def __init__(self):\n        self.__balance = 100\n\na = Account()\nprint(a.__balance)', 'python', 'AttributeError', 'Two leading underscores make Python rename the attribute.', 'Inside the class, __balance is stored as _Account__balance (name mangling), so a.__balance doesn''t exist from outside.', NULL, NULL, 37);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SyntaxError', 0), (@q, 'B', 'None', 0), (@q, 'C', 'AttributeError', 1), (@q, 'D', '100', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inheritance'), 2, 'code_output', 'What does this print?', 'class Base:\n    def __init__(self, name):\n        self.name = name\n\nclass Child(Base):\n    def __init__(self, name, age):\n        super().__init__(name)\n        self.age = age\n\nc = Child("ana", 3)\nprint(c.name, c.age)', 'python', 'ana 3', 'super().__init__ runs the parent''s setup.', 'Child first lets Base set name, then sets its own age.', NULL, NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'AttributeError', 0), (@q, 'B', 'ana None', 0), (@q, 'C', 'None 3', 0), (@q, 'D', 'ana 3', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inheritance'), 2, 'code_output', 'What does this print?', 'class Base:\n    def __init__(self):\n        self.name = "base"\n\nclass Child(Base):\n    def __init__(self, age):\n        self.age = age\n\nprint(Child(3).name)', 'python', 'AttributeError', 'Defining __init__ in the child replaces the parent''s one.', 'Child.__init__ never calls super().__init__(), so Base never sets name: AttributeError. Unlike Java, Python doesn''t call the parent constructor for you.', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'base', 0), (@q, 'B', '3', 0), (@q, 'C', 'None', 0), (@q, 'D', 'AttributeError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 2, 'code_output', 'What does this print?', 'class P:\n    def __repr__(self):\n        return "P(1)"\n    def __str__(self):\n        return "point 1"\n\np = P()\nprint(p)\nprint([p])', 'python', 'point 1\n[P(1)]', 'A list shows its items with a different dunder than print uses.', 'print(p) uses __str__ (for humans). Containers display their items with __repr__ (for developers).', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'point 1\n[''point 1'']', 0), (@q, 'B', 'P(1)\n[P(1)]', 0), (@q, 'C', 'point 1\n[P(1)]', 1), (@q, 'D', 'point 1\n[point 1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 2, 'code_output', 'What does this print?', 'class Point:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n\nprint(Point(1, 2) == Point(1, 2))', 'python', 'False', 'Without __eq__, what does == compare?', 'The default __eq__ compares identity (same object in memory), like == on objects in Java. Two separate objects are not equal.', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'False', 1), (@q, 'C', 'True', 0), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 2, 'code_output', 'What does this print?', 'class Dataset:\n    def __init__(self):\n        self.data = [10, 20, 30]\n    def __len__(self):\n        return len(self.data)\n    def __getitem__(self, i):\n        return self.data[i] * 2\n\nds = Dataset()\nprint(ds[1], len(ds))', 'python', '40 3', 'ds[1] calls __getitem__(1).', 'Square brackets call __getitem__, len calls __len__. This pair is exactly what a PyTorch map-style Dataset needs.', NULL, NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '20 3', 0), (@q, 'C', '40 6', 0), (@q, 'D', '40 3', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 2, 'code_output', 'What does this print?', 'class Scale:\n    def __init__(self, k):\n        self.k = k\n    def __call__(self, x):\n        return x * self.k\n\ndouble = Scale(2)\nprint(double(21))', 'python', '42', 'Which dunder makes an object usable like a function?', 'Defining __call__ lets you write obj(args). PyTorch layers work this way: layer(x).', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Scale', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', '42', 1), (@q, 'D', '21', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dataclasses'), 2, 'code_output', 'What does this print?', 'from dataclasses import dataclass\n\n@dataclass\nclass Point:\n    x: int\n    y: int\n\nprint(Point(1, 2) == Point(1, 2))', 'python', 'True', '@dataclass writes more than just __init__.', 'Dataclasses generate __eq__ that compares the fields in order, so two points with equal fields are equal.', NULL, NULL, 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'False', 0), (@q, 'C', 'True', 1), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dataclasses'), 2, 'code_output', 'What does this print?', 'from dataclasses import dataclass\n\n@dataclass\nclass Config:\n    lr: float = 0.01\n    epochs: int = 10\n\nprint(Config(epochs=5))', 'python', 'Config(lr=0.01, epochs=5)', 'Keyword arguments set only the field you name.', 'Fields with defaults become optional __init__ parameters. epochs=5 overrides one, lr keeps its default.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Config(lr=0.01, epochs=5)', 1), (@q, 'B', 'TypeError', 0), (@q, 'C', 'Config(epochs=5)', 0), (@q, 'D', 'Config(lr=5, epochs=10)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duck-typing'), 2, 'code_output', 'What does this print?', 'class Dog:\n    def speak(self):\n        return "woof"\n\nclass Robot:\n    def speak(self):\n        return "beep"\n\nfor thing in [Dog(), Robot()]:\n    print(thing.speak())', 'python', 'woof\nbeep', 'The two classes share no parent. Does Python care?', 'Python only needs each object to have a speak method when it''s called. No shared base class or interface is required.', NULL, NULL, 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'woof\nbeep', 1), (@q, 'B', 'beep\nwoof', 0), (@q, 'C', 'woof', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duck-typing'), 2, 'code_output', 'What does this print?', 'class Box:\n    pass\n\nprint(len(Box()))', 'python', 'TypeError', 'len() needs a particular dunder method.', 'Box has no __len__, so len() raises TypeError: object of type ''Box'' has no len().', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0', 0), (@q, 'B', 'AttributeError', 0), (@q, 'C', '1', 0), (@q, 'D', 'TypeError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'composition'), 2, 'mcq', 'You need a `Trainer` that uses a model, an optimiser and a logger. Which design is usually best?', NULL, NULL, 'Store them as attributes (self.model, self.optimizer, self.logger), i.e. composition', 'A trainer HAS a model; it isn''t one.', 'Composition keeps each part swappable and testable (pass in a fake logger). Inheriting from all three mixes unrelated APIs into one class.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Store them as attributes (self.model, self.optimizer, self.logger), i.e. composition', 1), (@q, 'B', 'Make Trainer inherit from Logger and copy the rest in', 0), (@q, 'C', 'class Trainer(Model, Optimizer, Logger) with multiple inheritance', 0), (@q, 'D', 'Put everything in global variables', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nn-module'), 2, 'code_output', 'What does this print?', 'import torch\nimport torch.nn as nn\n\nclass Net(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.fc = nn.Linear(4, 2)\n    def forward(self, x):\n        return self.fc(x)\n\ntorch.manual_seed(0)\nnet = Net()\nprint(net(torch.zeros(3, 4)).shape)', 'python', 'torch.Size([3, 2])', 'Linear(4, 2) maps each row of 4 numbers to 2 numbers.', 'The batch of 3 rows passes through Linear(4 -> 2), giving shape (3, 2). net(x) calls forward(x) for you.', 'x: (3, 4) --> Linear(4 -> 2) --> (3, 2)\n   3 rows       per row: 4 in, 2 out', NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'torch.Size([2])', 0), (@q, 'B', 'torch.Size([3, 2])', 1), (@q, 'C', 'torch.Size([3, 4])', 0), (@q, 'D', 'torch.Size([4, 2])', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nn-module'), 2, 'mcq', 'Why do PyTorch users write `model(x)` instead of `model.forward(x)`?', NULL, NULL, 'model(x) goes through nn.Module.__call__, which runs registered hooks and then forward', 'Which dunder method makes model(x) work?', 'nn.Module defines __call__, which handles hooks around your forward. Calling forward directly skips them.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'model(x) is faster because it skips forward', 0), (@q, 'B', 'There is no difference at all', 0), (@q, 'C', 'forward is private and can''t be called', 0), (@q, 'D', 'model(x) goes through nn.Module.__call__, which runs registered hooks and then forward', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'class-instance'), 2, 'true_false', 'Methods defined in a class are shared by all its instances, while the values stored on `self` belong to each instance.', NULL, NULL, 'True', 'Where does the function live, and where does the data live?', 'Methods are class attributes (one function object); self.x data is per instance. a.f() just passes a as self.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 3, 'code_output', 'What does this print?', 'class Bag:\n    def __init__(self, items=[]):\n        self.items = items\n\na = Bag()\nb = Bag()\na.items.append(1)\nprint(b.items)', 'python', '[1]', 'When is the default value [] created?', 'Default values are evaluated once, when the function is defined, so every Bag() without an argument shares one list. Use items=None and self.items = items if items is not None else [].', NULL, NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[]', 0), (@q, 'B', 'None', 0), (@q, 'C', '[1]', 1), (@q, 'D', 'AttributeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 3, 'code_output', 'What does this print?', 'class C:\n    x = 1\n    def __init__(self):\n        self.y = 2\n\nprint(C().__dict__)', 'python', '{''y'': 2}', '__dict__ holds only what was stored on this object.', 'An instance''s __dict__ contains its own attributes. x lives in C.__dict__, and instance lookup falls back to the class.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''x'': 1}', 0), (@q, 'B', '{''y'': 2}', 1), (@q, 'C', '{''x'': 1, ''y'': 2}', 0), (@q, 'D', '{}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 3, 'code_output', 'What does this print?', 'class C:\n    n = 0\n\na = C()\na.n += 1\nprint(C.n, a.n)', 'python', '0 1', 'a.n += 1 means a.n = a.n + 1. Where does the assignment go?', 'Reading a.n finds the class''s 0, then assigning creates an instance attribute a.n = 1. Integers are immutable, so the class value is untouched (compare appending to a class list, which mutates the shared object).', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0 1', 1), (@q, 'B', '0 0', 0), (@q, 'C', '1 0', 0), (@q, 'D', '1 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'code_output', 'What does this print?', 'class Base:\n    @classmethod\n    def create(cls):\n        return cls()\n\nclass Sub(Base):\n    pass\n\nprint(type(Sub.create()).__name__)', 'python', 'Sub', 'cls is the class the method was called on.', 'Called as Sub.create(), cls is Sub, so it builds a Sub. This is why alternative constructors are classmethods.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'type', 0), (@q, 'B', 'Sub', 1), (@q, 'C', 'Base', 0), (@q, 'D', 'NoneType', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'code_output', 'What does this print?', 'class A:\n    def f(self):\n        return "f"\n\na = A()\nm = a.f\nprint(m.__self__ is a, A.f(a), m())', 'python', 'True f f', 'a.f is a ''bound method'': the function plus the object.', 'Looking up a.f binds the function to a (stored in m.__self__). Calling m() is the same as A.f(a).', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True f TypeError', 0), (@q, 'B', 'False f f', 0), (@q, 'C', 'True f f', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'class-instance'), 3, 'code_output', 'What does this print?', 'class C:\n    def __new__(cls):\n        print("new")\n        return super().__new__(cls)\n    def __init__(self):\n        print("init")\n\nC()', 'python', 'new\ninit', 'One creates the object, the other fills it in.', '__new__ creates and returns the instance, then Python calls __init__ on it. You rarely need __new__ (immutable types, singletons).', NULL, NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'new', 0), (@q, 'B', 'init\nnew', 0), (@q, 'C', 'new\ninit', 1), (@q, 'D', 'init', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inheritance'), 3, 'code_output', 'What does this print?', 'class A:\n    def who(self):\n        return "A"\nclass B(A):\n    def who(self):\n        return "B"\nclass C(A):\n    def who(self):\n        return "C"\nclass D(B, C):\n    pass\n\nprint(D().who(), [k.__name__ for k in D.__mro__])', 'python', 'B [''D'', ''B'', ''C'', ''A'', ''object'']', 'Python searches left to right, but a shared base comes after all its children.', 'The C3 linearisation puts A after both B and C: D, B, C, A, object. The first who found is B''s.', '      A\n     / \\\n    B   C\n     \\ /\n      D      MRO: D -> B -> C -> A -> object', NULL, 58);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'B [''D'', ''B'', ''C'', ''A'', ''object'']', 1), (@q, 'B', 'B [''D'', ''B'', ''A'', ''C'', ''object'']', 0), (@q, 'C', 'C [''D'', ''C'', ''B'', ''A'', ''object'']', 0), (@q, 'D', 'A [''D'', ''B'', ''C'', ''A'', ''object'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inheritance'), 3, 'code_output', 'What does this print?', 'class A:\n    def __init__(self):\n        print("A")\nclass B(A):\n    def __init__(self):\n        print("B")\n        super().__init__()\nclass C(A):\n    def __init__(self):\n        print("C")\n        super().__init__()\nclass D(B, C):\n    def __init__(self):\n        print("D")\n        super().__init__()\n\nD()', 'python', 'D\nB\nC\nA', 'Each super() goes to the next class in D''s MRO.', 'With cooperative super(), every __init__ runs exactly once in MRO order: D, B, C, A. A runs once, not twice.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'D\nB\nA\nC\nA', 0), (@q, 'B', 'D\nC\nB\nA', 0), (@q, 'C', 'D\nB\nC\nA', 1), (@q, 'D', 'D\nB\nA', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inheritance'), 3, 'mcq', 'Why is `isinstance(x, Animal)` usually preferred over `type(x) == Animal`?', NULL, NULL, 'isinstance also accepts subclasses, so a Dog passes; type() == only matches the exact class', 'What does each say for a Dog?', 'isinstance respects inheritance (substitutability). type(x) == Animal is False for a Dog, which usually breaks subclasses.', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'isinstance also accepts subclasses, so a Dog passes; type() == only matches the exact class', 1), (@q, 'B', 'They are identical', 0), (@q, 'C', 'isinstance is the only one that works on None', 0), (@q, 'D', 'type() doesn''t work on user-defined classes', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 3, 'code_output', 'What does this print?', 'class P:\n    def __init__(self, x):\n        self.x = x\n    def __eq__(self, other):\n        return self.x == other.x\n\nprint(len({P(1)}))', 'python', 'TypeError', 'What happens to __hash__ when you define only __eq__?', 'Defining __eq__ without __hash__ sets __hash__ to None, so instances are unhashable and can''t go in a set or be dict keys.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 1), (@q, 'B', 'AttributeError', 0), (@q, 'C', '0', 0), (@q, 'D', '1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 3, 'code_output', 'What does this print?', 'class Vec:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n    def __add__(self, o):\n        return Vec(self.x + o.x, self.y + o.y)\n    def __repr__(self):\n        return f"Vec({self.x}, {self.y})"\n\nprint(Vec(1, 2) + Vec(3, 4))', 'python', 'Vec(4, 6)', 'a + b calls a.__add__(b).', 'Operator overloading: + calls __add__, which returns a new Vec. print falls back to __repr__ because there is no __str__.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Vec(1, 2, 3, 4)', 0), (@q, 'B', '<Vec object>', 0), (@q, 'C', 'Vec(4, 6)', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 3, 'code_output', 'What does this print?', 'class P:\n    def __init__(self, x):\n        self.x = x\n    def __eq__(self, other):\n        if not isinstance(other, P):\n            return NotImplemented\n        return self.x == other.x\n\nprint(P(1) == P(1), P(1) == 1)', 'python', 'True False', 'NotImplemented tells Python to try the other side, then fall back.', 'Returning NotImplemented lets Python try int''s __eq__ and finally fall back to identity, giving False instead of crashing on other.x.', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True TypeError', 0), (@q, 'B', 'True False', 1), (@q, 'C', 'True NotImplemented', 0), (@q, 'D', 'False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 3, 'code_output', 'What does this print?', 'class Dataset:\n    def __init__(self):\n        self.data = [10, 20, 30]\n    def __getitem__(self, i):\n        return self.data[i] * 2\n\nprint(list(Dataset()))', 'python', '[20, 40, 60]', 'There''s no __iter__. Python has an older fallback.', 'Without __iter__, iteration calls __getitem__(0), (1), (2)... until IndexError, which ends the loop quietly.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'IndexError', 0), (@q, 'B', '[20, 40, 60]', 1), (@q, 'C', 'TypeError', 0), (@q, 'D', '[10, 20, 30]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 3, 'code_output', 'What does this print?', 'class Batch:\n    def __init__(self, items):\n        self.items = items\n    def __len__(self):\n        return len(self.items)\n\nprint(bool(Batch([])), bool(Batch([1])))', 'python', 'False True', 'With no __bool__, truthiness falls back to another dunder.', 'If __bool__ is missing, Python uses __len__: length 0 is falsy. So `if batch:` means ''not empty''.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True', 1), (@q, 'B', 'True True', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', 'False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dataclasses'), 3, 'code_output', 'What does this print?', 'from dataclasses import dataclass\n\n@dataclass\nclass Run:\n    tags: list = []', 'python', 'ValueError', 'Dataclasses know about the mutable default trap.', '@dataclass refuses list, dict and set defaults (ValueError: mutable default ... use default_factory) to stop instances sharing one list.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'nothing is printed', 0), (@q, 'C', 'AttributeError', 0), (@q, 'D', 'ValueError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dataclasses'), 3, 'code_output', 'What does this print?', 'from dataclasses import dataclass, field\n\n@dataclass\nclass Run:\n    tags: list = field(default_factory=list)\n\na = Run()\nb = Run()\na.tags.append("baseline")\nprint(b.tags)', 'python', '[]', 'default_factory is called again for every new object.', 'field(default_factory=list) calls list() per instance, so each Run gets its own list.', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None', 0), (@q, 'B', '[''baseline'']', 0), (@q, 'C', '[]', 1), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dataclasses'), 3, 'code_output', 'What does this print?', 'from dataclasses import dataclass\n\n@dataclass(frozen=True)\nclass Point:\n    x: int\n\np = Point(1)\ntry:\n    p.x = 2\nexcept Exception as e:\n    print(type(e).__name__)', 'python', 'FrozenInstanceError', 'frozen means immutable.', 'frozen=True makes assignment raise dataclasses.FrozenInstanceError (a subclass of AttributeError). Frozen dataclasses are also hashable.', NULL, NULL, 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'FrozenInstanceError', 1), (@q, 'B', 'AttributeError', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', 'nothing is printed', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dataclasses'), 3, 'code_output', 'What does this print?', 'from dataclasses import dataclass, field\n\n@dataclass\nclass Split:\n    total: int\n    train_frac: float = 0.8\n    n_train: int = field(init=False)\n\n    def __post_init__(self):\n        self.n_train = int(self.total * self.train_frac)\n\nprint(Split(1000))', 'python', 'Split(total=1000, train_frac=0.8, n_train=800)', '__post_init__ runs right after the generated __init__.', 'init=False keeps n_train out of the constructor, __post_init__ computes it, and it still appears in the repr.', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Split(total=1000, n_train=800)', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', 'Split(total=1000, train_frac=0.8)', 0), (@q, 'D', 'Split(total=1000, train_frac=0.8, n_train=800)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dataclasses'), 3, 'code_output', 'What does this print?', 'from dataclasses import dataclass\n\n@dataclass\nclass Point:\n    x: int\n\nprint(hash(Point(1)))', 'python', 'TypeError', '@dataclass generated __eq__. What does that do to __hash__?', 'A plain @dataclass has eq=True, which sets __hash__ = None. Use frozen=True (or unsafe_hash=True) to make it hashable.', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 1), (@q, 'B', 'AttributeError', 0), (@q, 'C', '1', 0), (@q, 'D', 'a large integer', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duck-typing'), 3, 'code_output', 'What does this print?', 'from typing import Protocol, runtime_checkable\n\n@runtime_checkable\nclass Sized(Protocol):\n    def __len__(self) -> int: ...\n\nprint(isinstance([1, 2], Sized), isinstance(5, Sized))', 'python', 'True False', 'list never inherits from this Sized. Does that matter for a Protocol?', 'A Protocol is structural: any object with the right methods matches. list has __len__, int doesn''t.', NULL, 'Like TypeScript interfaces: shape matters, not the declared class.', 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True False', 1), (@q, 'B', 'True True', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', 'False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duck-typing'), 3, 'code_output', 'What does this print?', 'from abc import ABC, abstractmethod\n\nclass Model(ABC):\n    @abstractmethod\n    def predict(self, x): ...\n\nModel()', 'python', 'TypeError', 'What''s the point of an abstract class?', 'A class with unimplemented abstract methods can''t be instantiated: TypeError. Subclasses must implement predict first.', NULL, 'Like an abstract class in Java.', 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'nothing is printed', 0), (@q, 'B', 'TypeError', 1), (@q, 'C', 'NotImplementedError', 0), (@q, 'D', 'AttributeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'property-encapsulation'), 3, 'code_output', 'What does this print?', 'class Account:\n    def __init__(self):\n        self.__balance = 100\n\na = Account()\nprint(a._Account__balance)', 'python', '100', 'What did name mangling rename the attribute to?', '__balance inside class Account is stored as _Account__balance. Mangling avoids name clashes in subclasses; it isn''t real privacy.', NULL, NULL, 73);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '100', 1), (@q, 'B', 'None', 0), (@q, 'C', 'SyntaxError', 0), (@q, 'D', 'AttributeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'composition'), 3, 'mcq', 'Why do many style guides say ''prefer composition over inheritance''?', NULL, NULL, 'Subclasses depend on the parent''s internals, so changing the base class can silently break them (fragile base class); composed parts can be swapped independently', 'Think about what happens when the parent class changes.', 'Inheritance couples you to the whole parent API and its implementation details. Composition depends only on the interface of the part you hold.', NULL, NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Inheritance is slower at runtime', 0), (@q, 'B', 'Python doesn''t fully support inheritance', 0), (@q, 'C', 'Composition uses less memory in every case', 0), (@q, 'D', 'Subclasses depend on the parent''s internals, so changing the base class can silently break them (fragile base class); composed parts can be swapped independently', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'mcq', 'What is `__slots__ = ("x", "y")` in a class body for?', NULL, NULL, 'It fixes the allowed attribute names and stores them without a per-instance __dict__, saving memory for millions of small objects', 'Think memory per object.', 'Slots replace the per-instance dict with fixed storage. Useful for many small objects; side effect: you can''t add other attributes.', NULL, NULL, 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It makes x and y class attributes shared by all instances', 0), (@q, 'B', 'It speeds up method calls by caching them', 0), (@q, 'C', 'It fixes the allowed attribute names and stores them without a per-instance __dict__, saving memory for millions of small objects', 1), (@q, 'D', 'It makes x and y private', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nn-module'), 3, 'code_output', 'What does this print?', 'import torch.nn as nn\n\nclass Net(nn.Module):\n    def __init__(self):\n        self.fc = nn.Linear(4, 2)\n\nNet()', 'python', 'AttributeError', 'Something is missing at the top of __init__.', 'Without super().__init__(), nn.Module''s internal registries don''t exist yet, so assigning a layer fails: AttributeError: cannot assign module before Module.__init__() call.', NULL, NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'RuntimeError', 0), (@q, 'B', 'AttributeError', 1), (@q, 'C', 'nothing is printed', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nn-module'), 3, 'code_output', 'What does this print?', 'import torch\nimport torch.nn as nn\n\ntorch.manual_seed(0)\nlayer = nn.Linear(4, 2)\nprint(sum(p.numel() for p in layer.parameters()))', 'python', '10', 'Count the weight matrix and the bias.', 'The weight is 2x4 = 8 numbers and the bias has 2: 10 parameters.', NULL, NULL, 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '10', 1), (@q, 'B', '6', 0), (@q, 'C', '2', 0), (@q, 'D', '8', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nn-module'), 3, 'code_output', 'What does this print?', 'import torch.nn as nn\n\nclass A(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.layers = [nn.Linear(2, 2), nn.Linear(2, 2)]\n\nclass B(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.layers = nn.ModuleList([nn.Linear(2, 2), nn.Linear(2, 2)])\n\nprint(len(list(A().parameters())), len(list(B().parameters())))', 'python', '0 4', 'nn.Module only registers attributes that are Modules (or Parameters).', 'A plain Python list is invisible to nn.Module, so A has no parameters: the optimiser won''t train them and .to(device) won''t move them. ModuleList registers both layers (weight + bias each = 4 tensors).', NULL, NULL, 78);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0 4', 1), (@q, 'B', '2 2', 0), (@q, 'C', '0 2', 0), (@q, 'D', '4 4', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'class-instance'), 4, 'code_output', 'What does this print?', 'class C:\n    def __new__(cls):\n        return 42\n    def __init__(self):\n        print("init")\n\nprint(C())', 'python', '42', '__init__ only runs if __new__ returns an instance of the class.', 'Python calls __init__ only when __new__ returns an instance of cls. Here it returns an int, so __init__ is skipped and C() is 42.', NULL, NULL, 79);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'init\n<C object>', 0), (@q, 'B', 'init\n42', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', '42', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 4, 'code_output', 'What does this print?', 'class C:\n    n = 1\n\na = C()\nC.n = 5\nprint(a.n)', 'python', '5', 'Instances don''t copy class attributes; they look them up.', 'a has no own n, so every a.n lookup goes to the class at that moment. Changing C.n is visible through all instances (that don''t shadow it).', NULL, NULL, 80);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '5', 1), (@q, 'B', 'None', 0), (@q, 'C', '1', 0), (@q, 'D', 'AttributeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 4, 'code_output', 'What does this print?', 'class Plugin:\n    registry = []\n    def __init_subclass__(cls, **kwargs):\n        super().__init_subclass__(**kwargs)\n        Plugin.registry.append(cls.__name__)\n\nclass CSVLoader(Plugin):\n    pass\n\nclass JSONLoader(Plugin):\n    pass\n\nprint(Plugin.registry)', 'python', '[''CSVLoader'', ''JSONLoader'']', 'This hook runs when a subclass is defined, not when an instance is created.', '__init_subclass__ is called once per subclass definition, so a base class can auto-register plugins without decorators or metaclasses.', NULL, NULL, 81);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '[''Plugin'', ''CSVLoader'', ''JSONLoader'']', 0), (@q, 'C', '[''CSVLoader'', ''JSONLoader'']', 1), (@q, 'D', '[]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inheritance'), 4, 'code_output', 'What does this print?', 'class A:\n    def hi(self):\n        return "A"\nclass B(A):\n    def hi(self):\n        return "B>" + super().hi()\nclass C(A):\n    def hi(self):\n        return "C>" + super().hi()\nclass D(B, C):\n    def hi(self):\n        return "D>" + super().hi()\n\nprint(D().hi())', 'python', 'D>B>C>A', 'Inside B, does super() mean A?', 'super() means ''next in the MRO of the actual object'' (D, B, C, A). So B''s super() goes to C, a class B doesn''t even know about.', NULL, NULL, 82);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'D>B>A', 0), (@q, 'B', 'D>B>C>A', 1), (@q, 'C', 'D>B>A>C>A', 0), (@q, 'D', 'D>C>B>A', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inheritance'), 4, 'code_output', 'What does this print?', 'class A:\n    pass\nclass B(A):\n    pass\nclass C(A, B):\n    pass', 'python', 'TypeError', 'Can Python put A both before B (as listed) and after B (B is A''s child)?', 'C3 can''t build a consistent order (A must come before B as listed, but after B as B''s parent): TypeError: Cannot create a consistent method resolution order.', NULL, NULL, 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'RecursionError', 0), (@q, 'B', 'nothing is printed', 0), (@q, 'C', 'SyntaxError', 0), (@q, 'D', 'TypeError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'property-encapsulation'), 4, 'code_output', 'What does this print?', 'class A:\n    def __init__(self):\n        self.__x = 1\n\nclass B(A):\n    def get(self):\n        return self.__x\n\nprint(B().get())', 'python', 'AttributeError', 'Mangling uses the name of the class where the code is written.', 'In A, self.__x becomes self._A__x. In B, self.__x becomes self._B__x, which doesn''t exist. That''s the point: subclasses can''t clash with it by accident.', NULL, NULL, 84);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SyntaxError', 0), (@q, 'B', 'None', 0), (@q, 'C', '1', 0), (@q, 'D', 'AttributeError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 4, 'code_output', 'What does this print?', 'class P:\n    def __init__(self, x):\n        self.x = x\n    def __eq__(self, o):\n        return self.x == o.x\n    def __hash__(self):\n        return hash(self.x)\n\np = P(1)\ns = {p}\np.x = 2\nprint(p in s, P(1) in s)', 'python', 'False False', 'The set filed p under the hash it had when inserted.', 'After the mutation p hashes to a different bucket, so p isn''t found. P(1) lands in the right bucket but isn''t equal (p.x is now 2). Hash only immutable state.', 'insert: hash(1) -> bucket 1 holds p\nmutate: p.x = 2\nlookup p:    hash(2) -> bucket 2 (empty)\nlookup P(1): bucket 1 -> p, but p.x != 1', NULL, 85);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True', 0), (@q, 'B', 'False False', 1), (@q, 'C', 'True False', 0), (@q, 'D', 'True True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 4, 'code_output', 'What does this print?', 'class Cfg:\n    lr = 0.1\n    def __getattr__(self, name):\n        return "missing " + name\n\nc = Cfg()\nprint(c.lr, c.epochs)', 'python', '0.1 missing epochs', '__getattr__ is a fallback, not a filter.', '__getattr__ is only called when normal lookup fails. __getattribute__ is the one that intercepts every access.', NULL, NULL, 86);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.1 missing epochs', 1), (@q, 'B', 'missing lr missing epochs', 0), (@q, 'C', '0.1 AttributeError', 0), (@q, 'D', 'AttributeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 4, 'code_output', 'What does this print?', 'class Vec:\n    def __init__(self, x):\n        self.x = x\n    def __add__(self, o):\n        return Vec(self.x + o.x)\n\nprint(sum([Vec(1), Vec(2)]).x)', 'python', 'TypeError', 'sum() starts from 0, so the first operation is 0 + Vec(1).', 'int.__add__(Vec) returns NotImplemented, so Python tries Vec.__radd__, which doesn''t exist: TypeError. Add `def __radd__(self, o): return self if o == 0 else self + o`, or call sum(vs, start=Vec(0)).', NULL, NULL, 87);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 1), (@q, 'B', '3', 0), (@q, 'C', 'AttributeError', 0), (@q, 'D', '0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dataclasses'), 4, 'code_output', 'What does this print?', 'from dataclasses import dataclass\n\n@dataclass\nclass Base:\n    name: str = "run"\n\n@dataclass\nclass Child(Base):\n    epochs: int', 'python', 'TypeError', 'The generated __init__ lists parent fields first, then the child''s.', 'Child''s __init__ would be (name=''run'', epochs), a required parameter after a default one: TypeError: non-default argument ''epochs'' follows default argument. Fix with a default or @dataclass(kw_only=True).', NULL, NULL, 88);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 1), (@q, 'B', 'nothing is printed', 0), (@q, 'C', 'AttributeError', 0), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duck-typing'), 4, 'mcq', '`typing.Protocol` and `abc.ABC` can both describe ''something with a predict method''. What is the key difference?', NULL, NULL, 'A Protocol matches any class with the right methods (structural typing); an ABC only matches classes that inherit from it or are registered (nominal typing)', 'Does a third-party class have to know about your type?', 'Protocols let you type existing code (e.g. sklearn estimators) without changing it. ABCs force explicit subclassing but can enforce abstract methods at instantiation.', NULL, NULL, 89);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A Protocol matches any class with the right methods (structural typing); an ABC only matches classes that inherit from it or are registered (nominal typing)', 1), (@q, 'B', 'Protocols can''t have methods', 0), (@q, 'C', 'There is no difference; Protocol is an alias of ABC', 0), (@q, 'D', 'ABCs only work at type-check time, Protocols only at runtime', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'composition'), 4, 'mcq', '`class Square(Rectangle)` overrides `set_width` to also change the height. Code that does `r.set_width(5); r.set_height(2); assert r.area() == 10` fails for a Square. What principle is broken, and what''s the usual fix?', NULL, NULL, 'Liskov substitution: a subclass must work wherever the parent is expected. Don''t inherit; make Square and Rectangle separate (maybe sharing a Shape interface)', 'Can a Square be used everywhere a Rectangle is?', 'Square changes Rectangle''s behavioural contract, so it isn''t a true is-a. Composition or a common interface avoids the broken substitution.', NULL, NULL, 90);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Single responsibility: split area() into two methods', 0), (@q, 'B', 'Liskov substitution: a subclass must work wherever the parent is expected. Don''t inherit; make Square and Rectangle separate (maybe sharing a Shape interface)', 1), (@q, 'C', 'Encapsulation: make width private', 0), (@q, 'D', 'DRY: move set_height into Square', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'composition'), 4, 'code_output', 'What does this print?', 'class Wrapper:\n    def __init__(self, inner):\n        self._inner = inner\n    def __getattr__(self, name):\n        return getattr(self._inner, name)\n    def append(self, x):\n        self._inner.append(x * 10)\n\nw = Wrapper([])\nw.append(1)\nprint(w.count(10), len(w._inner))', 'python', '1 1', 'Own methods win; everything else is forwarded.', 'append is found on Wrapper and stores 10. count isn''t, so __getattr__ forwards it to the list. Delegation like this is composition with a thin proxy. Note: len(w) would still fail, because dunders are looked up on the type, not via __getattr__.', NULL, NULL, 91);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 1', 1), (@q, 'B', '1 0', 0), (@q, 'C', '0 1', 0), (@q, 'D', 'AttributeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'code_output', 'What does this print?', 'class P:\n    __slots__ = ("x",)\n    def __init__(self, x):\n        self.x = x\n\np = P(1)\np.y = 2', 'python', 'AttributeError', 'Slots fix the set of attribute names.', 'With __slots__ there''s no per-instance __dict__, so assigning an undeclared attribute raises AttributeError.', NULL, NULL, 92);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', 'AttributeError', 1), (@q, 'D', 'nothing is printed', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'code_output', 'What does this print?', 'class P:\n    __slots__ = ("x",)\n\nclass Q:\n    pass\n\nprint(hasattr(P(), "__dict__"), hasattr(Q(), "__dict__"))', 'python', 'False True', 'Where would a slotted instance keep a dict?', 'Slotted instances store attributes in fixed slots (descriptors on the class) and have no __dict__, which is where the memory saving comes from.', NULL, NULL, 93);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True', 0), (@q, 'B', 'False True', 1), (@q, 'C', 'True False', 0), (@q, 'D', 'False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'code_output', 'What does this print?', 'class Positive:\n    def __set_name__(self, owner, name):\n        self.name = "_" + name\n    def __get__(self, obj, objtype=None):\n        return getattr(obj, self.name)\n    def __set__(self, obj, value):\n        if value <= 0:\n            raise ValueError(self.name)\n        setattr(obj, self.name, value)\n\nclass Opt:\n    lr = Positive()\n\no = Opt()\no.lr = 0.1\ntry:\n    o.lr = -1\nexcept ValueError as e:\n    print("bad", e, o.lr)', 'python', 'bad _lr 0.1', 'Positive sits on the class and intercepts o.lr reads and writes.', 'A descriptor (object with __get__/__set__ as a class attribute) controls attribute access. __set_name__ tells it the field name. This is how @property, Django model fields and dataclass fields work.', NULL, NULL, 94);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', 'bad _lr -1', 0), (@q, 'C', 'bad lr -1', 0), (@q, 'D', 'bad _lr 0.1', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'code_output', 'What does this print?', 'class Circle:\n    def __init__(self, r):\n        self.r = r\n    @property\n    def area(self):\n        return 3 * self.r ** 2\n\nc = Circle(1)\nc.__dict__["area"] = 99\nprint(c.area)', 'python', '3', 'A property is a data descriptor. Who wins: it or the instance dict?', 'Data descriptors (with __set__ or __delete__, like property) take priority over the instance __dict__, so the property still computes 3.', NULL, NULL, 95);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'AttributeError', 0), (@q, 'B', '3', 1), (@q, 'C', 'TypeError', 0), (@q, 'D', '99', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'code_output', 'What does this print?', 'from functools import cached_property\n\nclass Data:\n    @cached_property\n    def stats(self):\n        print("computing")\n        return 4\n\nd = Data()\nprint(d.stats)\nprint(d.stats)\nprint("stats" in d.__dict__)', 'python', 'computing\n4\n4\nTrue', 'cached_property is a non-data descriptor: it has no __set__.', 'The first access computes and stores the result in the instance __dict__. Later lookups find the dict entry first, so it never recomputes.', NULL, NULL, 96);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'computing\n4\ncomputing\n4\nFalse', 0), (@q, 'B', '4\n4\nTrue', 0), (@q, 'C', 'computing\n4\n4\nTrue', 1), (@q, 'D', 'computing\n4\n4\nFalse', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nn-module'), 4, 'mcq', 'How does `nn.Module` know that `self.fc = nn.Linear(4, 2)` in your `__init__` is a layer whose parameters must be trained?', NULL, NULL, 'nn.Module overrides __setattr__: assigning a Module or Parameter stores it in internal dicts (_modules, _parameters) that .parameters() walks', 'Which dunder runs on every `self.something = value`?', 'Module.__setattr__ checks the type of the value and files Modules/Parameters into registries. That''s why super().__init__() must come first and why a plain list of layers is invisible.', NULL, NULL, 97);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It inspects forward() at the first call to see which layers are used', 0), (@q, 'B', 'It scans the source code of __init__ for nn.* calls', 0), (@q, 'C', 'Every nn.Linear registers itself in a global list when it''s created', 0), (@q, 'D', 'nn.Module overrides __setattr__: assigning a Module or Parameter stores it in internal dicts (_modules, _parameters) that .parameters() walks', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nn-module'), 4, 'code_output', 'What does this print?', 'import torch\nimport torch.nn as nn\n\nclass Net(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.drop = nn.Dropout(0.5)\n    def forward(self, x):\n        return self.drop(x)\n\nnet = Net()\nnet.eval()\nprint(net.training, net.drop.training)', 'python', 'False False', 'eval() walks the module tree.', 'eval() is train(False), which sets .training on the module and recursively on every registered child, so dropout turns off everywhere.', NULL, NULL, 98);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True', 0), (@q, 'B', 'False True', 0), (@q, 'C', 'True False', 0), (@q, 'D', 'False False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nn-module'), 4, 'code_output', 'What does this print?', 'import torch\nimport torch.nn as nn\n\ntorch.manual_seed(0)\nnet = nn.Linear(2, 2)\ncalls = []\nnet.register_forward_hook(lambda m, inp, out: calls.append(1))\n\nx = torch.zeros(1, 2)\nnet(x)\nnet.forward(x)\nprint(len(calls))', 'python', '1', 'Hooks are run by __call__, not by forward.', 'net(x) goes through Module.__call__, which runs forward and then the forward hooks. Calling forward directly bypasses hooks, which breaks tools built on them (feature extraction, some profilers).', NULL, NULL, 99);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1', 1), (@q, 'B', '2', 0), (@q, 'C', '0', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'class-instance'), 1, 'true_false', 'Every object created from a class gets its own copy of the attributes that `__init__` sets on `self`.', NULL, NULL, 'True', '__init__ runs once per object.', 'Each call to the class runs __init__ on a brand-new object, so self.x = ... creates a separate value for each instance.', NULL, NULL, 100);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dataclasses'), 1, 'fill_blank', 'The decorator that writes `__init__` and `__repr__` for you from type-annotated fields is `@_____`.', NULL, NULL, 'dataclass', 'It lives in the dataclasses module.', 'from dataclasses import dataclass, then put @dataclass above the class.', NULL, NULL, 101);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inheritance'), 2, 'fill_blank', 'To run the parent class''s constructor from a subclass, you write `_____().__init__(...)`.', NULL, NULL, 'super', 'It means ''the class above me''.', 'super().__init__(...) runs the parent''s __init__ on the same object.', NULL, NULL, 102);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 2, 'mcq', 'For an instance `d` of class `Dog`, what is `d.bark()` shorthand for?', NULL, NULL, 'Dog.bark(d)', 'Where does self come from?', 'Python looks up bark on the class and passes the instance as the first argument. That''s all self is.', 'd.bark()\n  -> lookup ''bark'' on type(d) = Dog\n  -> Dog.bark(d)     # d becomes self', NULL, 103);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Dog.bark(d)', 1), (@q, 'B', 'Dog.bark()', 0), (@q, 'C', 'bark(Dog, d)', 0), (@q, 'D', 'd.bark(Dog)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'property-encapsulation'), 2, 'true_false', 'Python enforces privacy: an attribute named `_secret` cannot be read from outside the class.', NULL, NULL, 'False', 'Python''s motto: ''we are all consenting adults''.', 'Single underscore is only a convention. Even __secret is just renamed to _Class__secret, not locked.', NULL, NULL, 104);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 2, 'mcq', 'Which dunder method does `"cat" in my_vocab` call on your object?', NULL, NULL, '__contains__', 'The name describes what the object does: it ___ things.', '`x in obj` calls obj.__contains__(x). If it''s missing, Python falls back to iterating via __iter__ or __getitem__.', NULL, NULL, 105);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '__has__', 0), (@q, 'B', '__contains__', 1), (@q, 'C', '__in__', 0), (@q, 'D', '__getitem__ only', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'composition'), 2, 'mcq', 'Which is a good use of inheritance?', NULL, NULL, 'class CSVLoader(BaseLoader), where any CSVLoader can be used anywhere a BaseLoader is expected', 'Use the is-a test, and ask whether it is substitutable.', 'Inheritance fits a true is-a with the same contract. Inheriting just to borrow a method (Trainer from Logger) is better done by holding a logger.', NULL, NULL, 106);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'class Config(dict) so you can attach training code to it', 0), (@q, 'B', 'class Trainer(Logger) just to reuse the log() method', 0), (@q, 'C', 'class CSVLoader(BaseLoader), where any CSVLoader can be used anywhere a BaseLoader is expected', 1), (@q, 'D', 'class Model(list) because the model has several layers', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'property-encapsulation'), 3, 'mcq', 'You start with a plain attribute `self.lr`. Later you need validation every time it''s set. What does @property buy you?', NULL, NULL, 'You can add a getter/setter without changing any caller code: obj.lr = 0.1 still works', 'In Java you write getters up front just in case. Why don''t Python devs?', 'Because a property keeps attribute syntax, Python code starts with plain attributes and upgrades to properties only when needed.', NULL, NULL, 107);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It makes lr faster to read', 0), (@q, 'B', 'You can add a getter/setter without changing any caller code: obj.lr = 0.1 still works', 1), (@q, 'C', 'Nothing; callers must switch to obj.get_lr() and obj.set_lr()', 0), (@q, 'D', 'It makes lr a class attribute', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dunder'), 3, 'true_false', 'Ideally `__repr__` returns a string that looks like the Python expression that would recreate the object, e.g. `Point(x=1, y=2)`.', NULL, NULL, 'True', 'repr is for developers in a debugger or REPL.', 'That''s the convention (dataclasses follow it). __str__ is the friendly version for end users; when it''s missing, print uses __repr__.', NULL, NULL, 108);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inheritance'), 3, 'fill_blank', 'The class attribute that holds the method resolution order as a tuple is `ClassName._____`.', NULL, NULL, '__mro__', 'Three letters, wrapped in double underscores.', 'D.__mro__ (or D.mro()) shows the order Python searches for methods and super() follows.', NULL, NULL, 109);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nn-module'), 3, 'mcq', 'Which two methods must a PyTorch map-style `Dataset` subclass implement so a DataLoader can use it?', NULL, NULL, '__len__ and __getitem__', 'The DataLoader asks ''how many?'' and ''give me item i''.', 'A map-style Dataset is just the sequence protocol: len(ds) and ds[i]. The DataLoader picks indices, calls ds[i], and batches the results.', NULL, NULL, 110);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '__len__ and __getitem__', 1), (@q, 'B', '__iter__ and __next__', 0), (@q, 'C', '__init__ and __repr__', 0), (@q, 'D', 'forward and __call__', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'mcq', 'When is a `@staticmethod` a better choice than a module-level function?', NULL, NULL, 'When the helper is tightly tied to the class and you want it grouped there (or overridable in subclasses), but it needs no self or cls', 'It''s about organisation, not capability.', 'A staticmethod has no access to instance or class; it''s namespacing. Many Python devs simply use a module function unless grouping really helps.', NULL, NULL, 111);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Whenever a function needs access to self', 0), (@q, 'B', 'Never; staticmethod is deprecated', 0), (@q, 'C', 'When the helper is tightly tied to the class and you want it grouped there (or overridable in subclasses), but it needs no self or cls', 1), (@q, 'D', 'When the function must be faster', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'true_false', 'Assigning `obj.__len__ = lambda: 5` on one instance makes `len(obj)` return 5.', NULL, NULL, 'False', 'Where does Python look up special methods for built-in operations?', 'Implicit dunder lookups (len, +, ==, iteration) go to the type, not the instance dict. You must define __len__ on the class.', NULL, NULL, 112);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'true_false', 'A plain function defined in a class body is a descriptor: its `__get__` is what turns `a.f` into a bound method with `a` as self.', NULL, NULL, 'True', 'Functions have a __get__ method.', 'Accessing a.f calls f.__get__(a, A), which returns a bound method. That is the whole mechanism behind self.', NULL, NULL, 113);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'What is the core difference between normal programming and machine learning?', NULL, NULL, 'In ML the computer learns the rules from examples', 'Who writes the if/else rules in each case?', 'Normal code: you write rules, data goes in, answers come out. ML: you give data + answers, and the rules (the model) come out.', ' Programming:  rules + data   --> answers\n ML:           data + answers --> rules (model)', 'A model is a function the computer wrote for you from examples.', 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Normal programs can''t use data', 0), (@q, 'B', 'ML doesn''t use code', 0), (@q, 'C', 'ML is always faster', 0), (@q, 'D', 'In ML the computer learns the rules from examples', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'In SDE terms, what is ''training'' a model closest to?', NULL, NULL, 'A slow compile step that produces the model''s weights', 'It''s done once, takes time, and produces an artifact.', 'Training is a slow, expensive build that turns data into weights; inference is running that build.', NULL, 'Weights = compiled binary; training = compile; inference = run.', 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Running unit tests', 0), (@q, 'B', 'A slow compile step that produces the model''s weights', 1), (@q, 'C', 'Writing documentation', 0), (@q, 'D', 'Deploying to production', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'What is ''inference''?', NULL, NULL, 'Using a trained model to make predictions', 'It happens after training, every time a user asks something.', 'Inference = calling the trained model on new input to get an output.', NULL, NULL, 3);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Using a trained model to make predictions', 1), (@q, 'B', 'Choosing a model', 0), (@q, 'C', 'Cleaning data', 0), (@q, 'D', 'Collecting data', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'true_false', 'A model''s ''weights'' (parameters) are the numbers learned during training.', NULL, NULL, 'True', 'They''re what gets saved to disk after training.', 'Weights are the learned numbers; the model file is mostly weights.', NULL, NULL, 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 1, 'mcq', 'A spam filter that you build by writing `if ''lottery'' in subject: spam = True` by hand is an example of:', NULL, NULL, 'Rule-based programming', 'Who wrote the if-statement: you, or the computer?', 'You wrote the rule yourself, so it''s ordinary rule-based code. ML would learn which words matter from labelled emails.', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Reinforcement learning', 0), (@q, 'B', 'Deep learning', 0), (@q, 'C', 'Rule-based programming', 1), (@q, 'D', 'Machine learning', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 1, 'true_false', 'In machine learning, a ''model'' is basically a function: input goes in, a prediction comes out.', NULL, NULL, 'True', 'Think of what you call after training: model.predict(x).', 'A trained model maps inputs to outputs, just like a function, except its internal logic was learned from data.', NULL, 'A model is a function whose body was written by the training process, not by you.', 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 1, 'mcq', 'What do you give an ML algorithm so it can learn a rule like ''which houses are expensive''?', NULL, NULL, 'Many examples, each with the correct answer', 'Learning needs examples to learn from.', 'You provide examples plus their answers (labels); the algorithm finds the rule that maps one to the other.', NULL, NULL, 7);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Many examples, each with the correct answer', 1), (@q, 'B', 'Only the column names', 0), (@q, 'C', 'A list of programming languages', 0), (@q, 'D', 'The finished if/else rules', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 1, 'mcq', 'Which of these is a hyperparameter (a setting YOU choose before training)?', NULL, NULL, 'The maximum depth of a decision tree', 'Hyperparameter = a knob you set; parameter = a number the model learns.', 'max_depth is chosen before training. Slopes, weights and intercepts are learned from data, so they are parameters.', NULL, NULL, 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The slope learned by linear regression', 0), (@q, 'B', 'The weights of a neural network', 0), (@q, 'C', 'The intercept of a fitted line', 0), (@q, 'D', 'The maximum depth of a decision tree', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 1, 'true_false', 'Hyperparameters are learned automatically from the data during training.', NULL, NULL, 'False', 'Who sets the value of max_depth or the learning rate?', 'Hyperparameters are set before training (and tuned by trying several values). Parameters are what training learns.', NULL, NULL, 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 1, 'code_output', 'What does this print?', 'from sklearn.linear_model import LinearRegression\nimport numpy as np\nX = np.array([[1], [2], [3], [4]])\ny = np.array([3, 5, 7, 9])\nm = LinearRegression().fit(X, y)\nprint(round(m.coef_[0], 2), round(m.intercept_, 2))', 'python', '2.0 1.0', 'Look at the pattern: y goes 3, 5, 7, 9 as x goes 1, 2, 3, 4.', 'The data follows y = 2x + 1, so the learned slope (coef_) is 2 and the intercept is 1. Those two numbers ARE the model.', NULL, NULL, 10);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1.0 2.0', 0), (@q, 'B', '2.0 1.0', 1), (@q, 'C', '2.0 0.0', 0), (@q, 'D', '3.0 0.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 1, 'mcq', 'You trained a model last week. Today a user asks for a prediction. What happens to the model''s weights?', NULL, NULL, 'Nothing: they are used as-is to compute the answer', 'Inference reads the weights; it doesn''t change them.', 'At inference the weights are frozen. The model just runs its learned function on the new input.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Nothing: they are used as-is to compute the answer', 1), (@q, 'B', 'They are re-learned from scratch', 0), (@q, 'C', 'They are randomly reset', 0), (@q, 'D', 'They are deleted after each prediction', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 1, 'mcq', 'Which step usually takes the most compute: training or a single prediction?', NULL, NULL, 'Training', 'One step looks at the whole dataset many times.', 'Training passes over the whole dataset (often many times). One prediction runs the learned function once.', NULL, 'Training is the slow build; inference is running the binary.', 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Training', 1), (@q, 'B', 'They always cost the same', 0), (@q, 'C', 'A single prediction', 0), (@q, 'D', 'Neither uses compute', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 1, 'mcq', 'What is the usual order of an ML project?', NULL, NULL, 'Frame the problem -> get data -> train -> evaluate -> deploy -> monitor', 'You can''t train before you know the question and have the data.', 'First decide what you''re predicting, then gather data, train, check it on unseen data, ship it, and keep watching it.', ' frame -> data -> features -> train -> evaluate\n                                          |\n   retrain <- monitor <- deploy <---------+', NULL, 13);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Train -> get data -> deploy -> frame the problem', 0), (@q, 'B', 'Get data -> deploy -> train -> frame the problem', 0), (@q, 'C', 'Frame the problem -> get data -> train -> evaluate -> deploy -> monitor', 1), (@q, 'D', 'Deploy -> train -> evaluate -> get data', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 1, 'true_false', 'Once a model is deployed, the ML work is finished.', NULL, NULL, 'False', 'Does the world stop changing after you ship?', 'Data changes over time, so deployed models are monitored and retrained. Deployment is a step in a loop, not the end.', NULL, NULL, 14);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 1, 'mcq', 'Which task does NOT need machine learning?', NULL, NULL, 'Calculating GST at a fixed 18% on an invoice', 'Is there an exact formula?', 'GST is a fixed formula: price * 0.18. Write the formula. ML is for patterns too fuzzy to write down by hand.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Recommending movies', 0), (@q, 'B', 'Translating Hindi to English', 0), (@q, 'C', 'Recognising faces in photos', 0), (@q, 'D', 'Calculating GST at a fixed 18% on an invoice', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 1, 'mcq', 'How do AI, ML and Deep Learning (DL) relate?', NULL, NULL, 'DL is a part of ML, and ML is a part of AI', 'Think of nested circles, biggest first.', 'AI is the broad goal (smart machines). ML is one way to get there (learn from data). DL is ML using deep neural networks.', ' +------------- AI ---------------+\n |  +---------- ML -------------+ |\n |  |  +------- DL ----------+  | |\n |  |  |  +--- GenAI ---+    |  | |\n |  |  |  +-------------+    |  | |\n |  |  +---------------------+  | |\n |  +---------------------------+ |\n +--------------------------------+', NULL, 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ML is a part of DL', 0), (@q, 'B', 'AI is a part of ML', 0), (@q, 'C', 'DL is a part of ML, and ML is a part of AI', 1), (@q, 'D', 'They are three unrelated fields', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 1, 'mcq', 'A chat LLM that writes new text is an example of:', NULL, NULL, 'Generative AI (built with deep learning)', 'It generates new content.', 'Chat LLMs are deep neural networks that generate content, i.e. generative AI.', NULL, NULL, 17);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A rule-based expert system', 0), (@q, 'B', 'A spreadsheet formula', 0), (@q, 'C', 'Unsupervised clustering', 0), (@q, 'D', 'Generative AI (built with deep learning)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 1, 'mcq', 'What does it mean for a model to ''generalise'' well?', NULL, NULL, 'It makes good predictions on new data it never saw', 'The goal is to do well in the real world, after training.', 'Generalisation = performance on unseen data. Doing well only on training data is memorisation.', NULL, 'A student who understood the subject vs one who memorised last year''s paper.', 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It remembers every training example', 0), (@q, 'B', 'It uses many features', 0), (@q, 'C', 'It makes good predictions on new data it never saw', 1), (@q, 'D', 'It trains very fast', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 1, 'true_false', 'Every ML model makes some assumptions about what the true pattern looks like.', NULL, NULL, 'True', 'A straight-line model assumes something about the data''s shape.', 'These built-in assumptions are called the inductive bias. Without any assumptions, a model can''t guess beyond its training data.', NULL, NULL, 19);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 1, 'mcq', 'A linear regression model with 3 input features always stores 4 learned numbers, no matter if you train it on 100 or 1 million rows. This kind of model is called:', NULL, NULL, 'Parametric', 'Does its size depend on the amount of data?', 'Parametric models have a fixed number of parameters (here 3 weights + 1 intercept), regardless of dataset size.', NULL, NULL, 20);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Non-parametric', 0), (@q, 'B', 'Parametric', 1), (@q, 'C', 'Unsupervised', 0), (@q, 'D', 'Generative', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 1, 'mcq', 'A shop wants to know ''how many units of each product will we sell next week?''. What is the target (the thing to predict)?', NULL, NULL, 'Units sold next week per product', 'The target is the answer to the business question.', 'The target is the quantity you want the model to output: next week''s units sold for each product.', NULL, NULL, 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Units sold next week per product', 1), (@q, 'B', 'Last week''s weather', 0), (@q, 'C', 'The shop''s address', 0), (@q, 'D', 'The product name', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 1, 'fill_blank', 'After calling fit, scikit-learn''s LinearRegression stores the learned slopes in the attribute ____.', NULL, NULL, 'coef_', 'Short for coefficients, with sklearn''s trailing-underscore convention.', 'coef_ holds the learned weights; intercept_ holds the bias. Attributes ending in _ only exist after fit.', NULL, NULL, 22);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 2, 'code_output', 'What does this print?', 'from sklearn.tree import DecisionTreeClassifier\nX = [[10], [20], [30], [60], [70], [80]]\ny = [0, 0, 0, 1, 1, 1]\nt = DecisionTreeClassifier(max_depth=1).fit(X, y)\nprint(t.tree_.threshold[0])', 'python', '45.0', 'The tree picks a cut point between the last 0 and the first 1.', 'The tree learned the rule `if x <= 45: class 0 else class 1`. 45 is the midpoint of 30 and 60. You never wrote that if-statement; training did.', NULL, 'Training wrote the if/else for you and picked the magic number.', 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '60.0', 0), (@q, 'B', '45.0', 1), (@q, 'C', '50.0', 0), (@q, 'D', '30.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 2, 'mcq', 'A fraud team has 200 hand-written rules that keep breaking as fraudsters change tactics. Why might ML help?', NULL, NULL, 'It can re-learn the patterns from fresh labelled data instead of someone rewriting rules', 'What happens when the pattern changes?', 'When patterns shift often and are too complex to hand-code, retraining on new labelled examples is cheaper than maintaining rules.', NULL, NULL, 24);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ML never makes mistakes', 0), (@q, 'B', 'It can re-learn the patterns from fresh labelled data instead of someone rewriting rules', 1), (@q, 'C', 'ML needs no data', 0), (@q, 'D', 'ML rules are easier to read than if-statements', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 2, 'code_output', 'What does this print?', 'from sklearn.tree import DecisionTreeClassifier\nm = DecisionTreeClassifier(max_depth=2)\nprint(m.get_params()["max_depth"], hasattr(m, "tree_"))', 'python', '2 False', 'The model has been configured but not fitted yet.', 'max_depth is a hyperparameter, set at construction. tree_ is a learned attribute; it doesn''t exist until fit runs.', NULL, NULL, 25);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None False', 0), (@q, 'B', '2 True', 0), (@q, 'C', 'None True', 0), (@q, 'D', '2 False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 2, 'fill_blank', 'A linear regression model trained on 10 numeric features learns ____ numbers in total (weights plus intercept).', NULL, NULL, '11', 'One weight per feature, plus one more.', '10 weights (one per feature) + 1 intercept = 11 parameters.', NULL, NULL, 26);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 2, 'code_output', 'What does this print?', 'from sklearn.linear_model import LinearRegression\nm = LinearRegression()\nr = m.fit([[0], [1], [2]], [1, 3, 5])\nprint(r is m)', 'python', 'True', 'Why can you write LinearRegression().fit(X, y).predict(...) on one line?', 'fit trains the object in place and returns self, which is what allows method chaining.', NULL, NULL, 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False', 0), (@q, 'B', 'None', 0), (@q, 'C', 'True', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 2, 'code_output', 'What does this print?', 'from sklearn.linear_model import LinearRegression\nm = LinearRegression()\nm.predict([[1]])', 'python', 'NotFittedError', 'There are no learned weights yet.', 'Calling predict before fit raises sklearn''s NotFittedError: there is no learned function to run.', NULL, NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', 'NotFittedError', 1), (@q, 'C', '[0.]', 0), (@q, 'D', 'AttributeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 2, 'code_output', 'What does this print?', 'import pickle\nfrom sklearn.linear_model import LinearRegression\nm = LinearRegression().fit([[0], [1], [2]], [1, 3, 5])\nblob = pickle.dumps(m)\nm2 = pickle.loads(blob)\nprint(m2.predict([[10]]))', 'python', '[21.]', 'Saving a model saves its learned weights.', 'The learned line is y = 2x + 1. Pickling saves the fitted weights, so the reloaded model predicts 21 for x = 10 without retraining.', NULL, 'Like shipping a compiled binary: build once, run anywhere.', 29);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[20.]', 0), (@q, 'B', 'NotFittedError', 0), (@q, 'C', '[10.]', 0), (@q, 'D', '[21.]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 2, 'true_false', 'If you tell a chat LLM a fact during a conversation, its weights are updated so it permanently learns that fact.', NULL, NULL, 'False', 'Is the model being trained while it answers you?', 'At inference the weights are frozen. The fact only lives in the conversation context and is gone in a fresh chat.', NULL, NULL, 30);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 2, 'mcq', 'In a typical real-world ML project, where does most of the time go?', NULL, NULL, 'Collecting, cleaning and understanding data', 'Garbage in, garbage out.', 'Data work (getting labels, cleaning, fixing errors, building features) usually dominates. Model choice is often the smaller part.', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Writing the training loop', 0), (@q, 'B', 'Picking the GPU', 0), (@q, 'C', 'Collecting, cleaning and understanding data', 1), (@q, 'D', 'Choosing between model libraries', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 2, 'code_output', 'What does this print?', 'from sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.linear_model import LogisticRegression\npipe = Pipeline([("scale", StandardScaler()), ("model", LogisticRegression())])\nprint(list(pipe.named_steps))', 'python', '[''scale'', ''model'']', 'named_steps is keyed by the names you gave each step.', 'A Pipeline bundles preprocessing and the model so the exact same steps run in training and at inference, in order.', NULL, NULL, 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''StandardScaler'', ''LogisticRegression'']', 0), (@q, 'B', '[]', 0), (@q, 'C', '[''scale'', ''model'']', 1), (@q, 'D', '[''model'', ''scale'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 2, 'mcq', 'You have 30 labelled examples, and the business needs a decision tomorrow. What''s the most sensible first move?', NULL, NULL, 'Use a simple rule or heuristic and collect more data', 'How reliable can a model trained on 30 rows be?', 'With tiny data, a simple heuristic is often as good and far cheaper. Ship it, log outcomes, and revisit ML when data exists.', NULL, NULL, 33);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Use a simple rule or heuristic and collect more data', 1), (@q, 'B', 'Train a large deep neural network', 0), (@q, 'C', 'Wait until you have a perfect model', 0), (@q, 'D', 'Fine-tune an LLM on the 30 rows', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 2, 'true_false', 'A hospital needs a dosage calculator that must be exactly correct every time for a known formula. ML is a good fit here.', NULL, NULL, 'False', 'ML gives statistical answers, not guaranteed ones.', 'When the formula is known and errors are unacceptable, use the formula. ML is right when the rule is unknown and some error is OK.', NULL, NULL, 34);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 2, 'true_false', 'A 1990s rule-based expert system for diagnosing diseases is AI but not machine learning.', NULL, NULL, 'True', 'Did it learn anything from data?', 'Expert systems encode human-written rules. They are AI (they act intelligently) but don''t learn, so they aren''t ML.', NULL, NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 2, 'mcq', 'A model scores 100% on its training data and 61% on new data. What is most likely happening?', NULL, NULL, 'It memorised the training data (overfitting)', 'Big gap between train and unseen performance.', 'A big train/test gap means the model learned quirks of the training set rather than the real pattern.', NULL, 'Like unit tests that hard-code the expected outputs: all green, but the code is still wrong.', 36);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It memorised the training data (overfitting)', 1), (@q, 'B', 'It is underfitting', 0), (@q, 'C', 'It is a perfect model', 0), (@q, 'D', 'The new data is too easy', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.tree import DecisionTreeRegressor\nfrom sklearn.model_selection import train_test_split\nrng = np.random.default_rng(0)\nX = rng.uniform(0, 10, size=(200, 1))\ny = np.sin(X[:, 0]) + rng.normal(0, 0.5, 200)\nXtr, Xte, ytr, yte = train_test_split(X, y, random_state=0)\nt = DecisionTreeRegressor(random_state=0).fit(Xtr, ytr)\nprint(t.score(Xtr, ytr), t.score(Xte, yte) < 0.9)', 'python', '1.0 True', 'An unlimited-depth tree can give every training point its own leaf.', 'An unpruned tree memorises the noisy training data (R^2 = 1.0) but scores clearly worse on held-out data.', NULL, NULL, 37);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1.0 True', 1), (@q, 'B', '0.5 True', 0), (@q, 'C', '1.0 False', 0), (@q, 'D', '0.9 False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 2, 'code_output', 'What does this print?', 'from sklearn.linear_model import LogisticRegression\nfrom sklearn.tree import DecisionTreeClassifier\nX = [[0, 0], [0, 1], [1, 0], [1, 1]]\ny = [0, 1, 1, 0]\nlin = LogisticRegression().fit(X, y).score(X, y)\ntree = DecisionTreeClassifier(random_state=0).fit(X, y).score(X, y)\nprint(lin, tree)', 'python', '0.5 1.0', 'XOR can''t be separated by a single straight line.', 'Logistic regression assumes a straight decision boundary, which can''t separate XOR (it gets 0.5). A tree''s axis-aligned splits can.', ' x2\n 1 | 1   0      no single line puts\n 0 | 0   1      both 1s on one side\n   +-------- x1\n     0   1', NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.5 1.0', 1), (@q, 'B', '1.0 0.5', 0), (@q, 'C', '1.0 1.0', 0), (@q, 'D', '0.75 0.75', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.neighbors import KNeighborsRegressor\nrng = np.random.default_rng(0)\nfor n in (100, 10000):\n    X = rng.normal(size=(n, 3)); y = X.sum(axis=1)\n    lr = LinearRegression().fit(X, y)\n    knn = KNeighborsRegressor().fit(X, y)\n    print(lr.coef_.size, knn.n_samples_fit_)', 'python', '3 100\n3 10000', 'One model stores weights; the other stores the training rows.', 'Linear regression keeps 3 weights whatever n is (parametric). kNN keeps every training sample to search at predict time (non-parametric).', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3 100\n3 10000', 1), (@q, 'B', '3 3\n3 3', 0), (@q, 'C', '100 100\n10000 10000', 0), (@q, 'D', '3 100\n3 100', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 2, 'code_output', 'What does this print?', 'from sklearn.dummy import DummyClassifier\nimport numpy as np\nX = np.zeros((100, 1))\ny = np.array([0] * 95 + [1] * 5)\nd = DummyClassifier(strategy="most_frequent").fit(X, y)\nprint(d.score(X, y))', 'python', '0.95', 'It always predicts the most common class.', 'Predicting ''not fraud'' for everyone already scores 95% accuracy. Any real model must beat this baseline, and accuracy is a poor metric here.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.05', 0), (@q, 'B', '1.0', 0), (@q, 'C', '0.95', 1), (@q, 'D', '0.5', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 2, 'mcq', 'An e-commerce site wants to ''reduce returns''. Which is the best-framed ML task?', NULL, NULL, 'At checkout, predict the probability this order will be returned within 30 days', 'A good framing says when you predict, what exactly, and over what window.', 'A precise framing fixes the prediction point (checkout), the target (returned or not) and the window (30 days).', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Predict returns', 0), (@q, 'B', 'Cluster all products', 0), (@q, 'C', 'Use AI to improve returns', 0), (@q, 'D', 'At checkout, predict the probability this order will be returned within 30 days', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 3, 'mcq', 'A learned model says a transaction is ''fraud'' with 0.97 probability. How should an engineer treat that output compared with a hand-written rule?', NULL, NULL, 'As a statistical estimate that can be wrong and needs evaluation and monitoring', 'Learned rules come from patterns in past data.', 'Model outputs are estimates from past data. They can be confidently wrong, especially on inputs unlike the training data.', NULL, NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'As something that never changes', 0), (@q, 'B', 'As less reliable than any rule', 0), (@q, 'C', 'As a guaranteed fact, because it was learned from data', 0), (@q, 'D', 'As a statistical estimate that can be wrong and needs evaluation and monitoring', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 3, 'mcq', 'Where should hyperparameters like max_depth be tuned?', NULL, NULL, 'On a validation set (or with cross-validation on the training data)', 'The test set must stay untouched until the very end.', 'Tuning on the test set leaks it into your choices, so the final score is optimistic. Tune with validation or cross-validation.', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'On the training set score alone', 0), (@q, 'B', 'On the test set', 0), (@q, 'C', 'On a validation set (or with cross-validation on the training data)', 1), (@q, 'D', 'They should never be tuned', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 3, 'mcq', 'Which of these is a hyperparameter of kNN, not a parameter?', NULL, NULL, 'k, the number of neighbours', 'What do you pass to the constructor?', 'k is chosen by you (n_neighbors). kNN has no learned weights; it stores the data and uses k at predict time.', NULL, NULL, 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The distance between two specific points', 0), (@q, 'B', 'The stored training points', 0), (@q, 'C', 'The predicted label', 0), (@q, 'D', 'k, the number of neighbours', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 3, 'mcq', 'A recommendation model is retrained nightly on a GPU cluster, then serves 50,000 requests per second. Which concern belongs to inference rather than training?', NULL, NULL, 'Latency per request (e.g. under 20 ms)', 'What does the user waiting for a response care about?', 'Inference is about latency, throughput and cost per request. Epochs, learning rates and dataset size are training concerns.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Latency per request (e.g. under 20 ms)', 1), (@q, 'B', 'Number of epochs', 0), (@q, 'C', 'Size of the training dataset', 0), (@q, 'D', 'Learning rate schedule', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 3, 'mcq', 'Why should you build a dumb baseline (majority class, last value, a simple rule) before a complex model?', NULL, NULL, 'It shows whether the complex model adds real value and catches pipeline bugs', 'How would you know your 92% accuracy is good?', 'If a baseline already gets 90%, your 92% model may not be worth the cost. A model that loses to the baseline usually has a bug.', NULL, 'Like benchmarking a new service against the old one before migrating.', 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It makes training faster', 0), (@q, 'B', 'It shows whether the complex model adds real value and catches pipeline bugs', 1), (@q, 'C', 'Complex models need a baseline to train', 0), (@q, 'D', 'Baselines are always good enough', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 3, 'true_false', 'If monitoring shows the input data in production has drifted away from the training data, the usual fix is to retrain on recent data, which sends you back into the workflow loop.', NULL, NULL, 'True', 'The workflow is a cycle, not a line.', 'Drift is caught by monitoring and triggers retraining (and sometimes re-framing), closing the loop.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 3, 'mcq', 'A team is deciding between a hand-tuned heuristic that gets 88% and an ML model that gets 89%. Which factor most strongly favours the heuristic?', NULL, NULL, 'The ML model needs data pipelines, retraining and monitoring for a 1-point gain', 'ML has an ongoing running cost.', 'ML systems carry maintenance cost (data, retraining, monitoring, debugging). A tiny gain rarely justifies it.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ML models can''t reach 89%', 0), (@q, 'B', 'Heuristics can''t be tested', 0), (@q, 'C', 'The ML model needs data pipelines, retraining and monitoring for a 1-point gain', 1), (@q, 'D', 'The heuristic is older', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 3, 'mcq', 'Which is the strongest reason NOT to use ML for a decision?', NULL, NULL, 'Each decision must be fully explainable by a fixed, auditable rule', 'Three of these are reasons FOR ML.', 'Lots of data, complex patterns and high volume favour ML. A hard requirement for exact, auditable rules favours explicit logic.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The pattern is complex', 0), (@q, 'B', 'Each decision must be fully explainable by a fixed, auditable rule', 1), (@q, 'C', 'The task is repeated millions of times', 0), (@q, 'D', 'You have lots of labelled data', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 3, 'mcq', 'GPT-style LLMs are best described as:', NULL, NULL, 'Deep learning models trained to generate text by predicting the next token', 'What does the model actually output at each step?', 'An LLM is a deep neural network (transformer) that generates text one token at a time, learned from huge amounts of text.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Unsupervised clustering models', 0), (@q, 'B', 'Classical ML models like decision trees', 0), (@q, 'C', 'Deep learning models trained to generate text by predicting the next token', 1), (@q, 'D', 'Rule-based systems with a huge dictionary', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 3, 'mcq', 'A model is too simple for the problem (e.g. a straight line for a curved pattern). Adding 10x more training data will:', NULL, NULL, 'Barely help, because the model still can''t represent the curve (high bias)', 'Is the problem the amount of data or what the model can express?', 'More data reduces variance, not bias. A straight line stays a straight line however much data you give it.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Make it overfit', 0), (@q, 'B', 'Fix it completely', 0), (@q, 'C', 'Make training error go to zero', 0), (@q, 'D', 'Barely help, because the model still can''t represent the curve (high bias)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 3, 'mcq', 'Which pair correctly matches the problem with the fix?', NULL, NULL, 'High variance -> more data or stronger regularisation; high bias -> a more flexible model or better features', 'Variance = over-reacting to the sample; bias = too-simple assumptions.', 'Overfitting (variance) is reduced by more data or constraints; underfitting (bias) needs more capacity or more informative features.', ' error\n  |\\                 /  total\n  | \\  bias^2    __/\n  |  \\_______ _/  variance\n  +------------------> model complexity\n     underfit   sweet   overfit', NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'High variance -> fewer training examples; high bias -> more regularisation', 0), (@q, 'B', 'High variance -> a more flexible model; high bias -> more data', 0), (@q, 'C', 'High variance -> more data or stronger regularisation; high bias -> a more flexible model or better features', 1), (@q, 'D', 'Both are fixed only by training longer', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.tree import DecisionTreeRegressor\nX = np.arange(10).reshape(-1, 1)\ny = 2 * X[:, 0]\nlr = LinearRegression().fit(X, y)\ndt = DecisionTreeRegressor().fit(X, y)\nprint(round(lr.predict([[20]])[0]), dt.predict([[20]])[0])', 'python', '40 18.0', 'x = 20 is outside the training range 0..9.', 'The linear model assumes a line and extrapolates to 40. A tree can only output values it saw in a leaf, so it returns 18 (the last leaf).', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '40 18.0', 1), (@q, 'B', '18 18.0', 0), (@q, 'C', '20 20.0', 0), (@q, 'D', '40 40.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 3, 'mcq', 'Which statement describes kNN''s inductive bias?', NULL, NULL, 'Points that are close together in feature space tend to have the same label', 'How does kNN make a prediction?', 'kNN predicts from the nearest training points, so it assumes nearby means similar. Linear = line; Naive Bayes = independence; CNN = locality.', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Features are independent given the class', 0), (@q, 'B', 'The output is a linear function of the inputs', 0), (@q, 'C', 'Nearby pixels matter more than distant ones', 0), (@q, 'D', 'Points that are close together in feature space tend to have the same label', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 3, 'true_false', 'A k-nearest-neighbours model does almost no work in fit and most of its work in predict.', NULL, NULL, 'True', 'What does kNN store, and when does it search?', 'kNN is a ''lazy learner'': fit just stores the data; predict computes distances to the stored points. That''s why its inference is slow on big data.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 3, 'mcq', 'Which of these models is non-parametric?', NULL, NULL, 'A decision tree with no depth limit', 'Which one can keep growing as you add more data?', 'An unlimited tree adds more splits and leaves as data grows. The others have a size fixed before training.', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Logistic regression', 0), (@q, 'B', 'Linear regression', 0), (@q, 'C', 'A neural network with a fixed architecture', 0), (@q, 'D', 'A decision tree with no depth limit', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 3, 'mcq', 'A bank wants to catch fraud. Missing a fraud costs about 50,000 rupees; flagging a good transaction costs about 50 rupees of support time. Which metric fits best?', NULL, NULL, 'Recall on fraud (at an acceptable precision), or expected cost', 'Which mistake is 1000x more expensive?', 'Misses are very costly, so you care about catching most frauds (recall) while keeping false alarms tolerable, ideally scoring by expected cost.', NULL, NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Recall on fraud (at an acceptable precision), or expected cost', 1), (@q, 'B', 'Mean squared error', 0), (@q, 'C', 'Plain accuracy', 0), (@q, 'D', 'Training loss', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 4, 'mcq', 'A loan-approval product uses an ML risk score, but a lawyer insists some applicants must always be rejected (e.g. under 18). What is the sound design?', NULL, NULL, 'Hard rules as guardrails before/after the model, with the model handling the fuzzy cases', 'Some requirements are not statistical.', 'Legal or safety invariants should be enforced by deterministic code. A model can learn ''usually'', never ''always''.', NULL, 'Like validation in a backend: you don''t trust the client, you enforce the invariant on the server.', 58);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Hard rules as guardrails before/after the model, with the model handling the fuzzy cases', 1), (@q, 'B', 'Add age as a feature and trust the model to learn the rule', 0), (@q, 'C', 'Drop the model and only use rules', 0), (@q, 'D', 'Retrain until the model never approves minors', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 4, 'mcq', 'You try 200 hyperparameter settings and pick the one with the best validation score. Why might that score still be optimistic?', NULL, NULL, 'You overfit to the validation set by selecting the luckiest setting; a separate test set (or nested CV) is needed', 'Selection itself is a form of fitting.', 'Picking the max of many noisy scores biases the result upwards. Keep an untouched test set or use nested cross-validation for an honest estimate.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'You overfit to the validation set by selecting the luckiest setting; a separate test set (or nested CV) is needed', 1), (@q, 'B', '200 trials is too few to matter', 0), (@q, 'C', 'Validation scores are always pessimistic', 0), (@q, 'D', 'Hyperparameters don''t affect generalisation', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 4, 'mcq', 'A model scores well offline, but in production its accuracy is much lower. Investigation shows the training pipeline computed ''average order value'' with pandas, while the serving code recomputes it in Java with a different rounding and time window. This is:', NULL, NULL, 'Training-serving skew', 'The same feature is computed differently in two places.', 'When features are computed differently at train and serve time, the model sees inputs it wasn''t trained on. Share one feature pipeline (or a feature store).', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Overfitting', 0), (@q, 'B', 'Class imbalance', 0), (@q, 'C', 'Training-serving skew', 1), (@q, 'D', 'Underfitting', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 4, 'mcq', 'A news app''s model ranks articles; it is retrained every week on what users clicked. Over months, it shows mostly one type of article and the click data reflects only that. What has gone wrong?', NULL, NULL, 'A feedback loop: the model''s own outputs now shape its training labels', 'Where does the training data come from?', 'Users can only click what the model showed them, so the labels are biased by past predictions. Add exploration or log what was shown, not just what was clicked.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Training-serving skew', 0), (@q, 'B', 'A feedback loop: the model''s own outputs now shape its training labels', 1), (@q, 'C', 'Overfitting to the test set', 0), (@q, 'D', 'The learning rate is too high', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 4, 'true_false', 'A deployed model can degrade silently: the service keeps returning 200 OK with valid-looking predictions while accuracy drops.', NULL, NULL, 'True', 'ML failures aren''t exceptions.', 'Unlike a crash, a wrong prediction looks normal. That''s why you monitor input distributions, prediction distributions and, when labels arrive, real accuracy.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 4, 'mcq', 'Why is ML a risky fit for spam/fraud detection compared with, say, weather forecasting?', NULL, NULL, 'The data is adversarial: attackers change behaviour to beat the model, so the distribution shifts on purpose', 'The weather doesn''t try to fool your forecast.', 'Adversaries probe and adapt, so a model decays faster and must be paired with rules, fast retraining and monitoring.', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The data is adversarial: attackers change behaviour to beat the model, so the distribution shifts on purpose', 1), (@q, 'B', 'There''s never any labelled data', 0), (@q, 'C', 'The costs of errors are always zero', 0), (@q, 'D', 'The patterns are too simple', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 4, 'true_false', 'Because ''AI'' appears in a product''s name, it must contain a model learned from data.', NULL, NULL, 'False', 'Recall what counts as AI but not ML.', 'Plenty of ''AI'' features are rules, search or heuristics. AI is the goal; ML is just one way to reach it.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 4, 'mcq', 'For squared-error regression, the expected test error at a point can be split into which three parts?', NULL, NULL, 'bias^2 + variance + irreducible noise', 'One part can''t be removed by any model.', 'Bias^2 (wrong assumptions) + variance (sensitivity to the sample) + noise (randomness in the labels themselves).', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'bias^2 + variance + irreducible noise', 1), (@q, 'B', 'training error + validation error + test error', 0), (@q, 'C', 'precision + recall + F1', 0), (@q, 'D', 'bias + variance - noise', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 4, 'true_false', 'Given enough data and a powerful enough model, test error can always be driven to zero.', NULL, NULL, 'False', 'What if two identical inputs have different true outcomes?', 'Irreducible noise remains: if the label isn''t fully determined by the features (e.g. same profile, different outcome), no model can be perfect.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 4, 'mcq', 'What does the No Free Lunch theorem actually say?', NULL, NULL, 'Averaged over ALL possible problems, every learning algorithm performs the same; any advantage comes from matching assumptions to a problem class', 'It''s a statement about an average over every imaginable problem.', 'NFL doesn''t say algorithms are equal on YOUR problem. It says no algorithm wins everywhere, so you choose one whose inductive bias fits the data.', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Deep learning is always the best algorithm', 0), (@q, 'B', 'All algorithms perform equally on every real dataset', 0), (@q, 'C', 'You can''t get good results without paying for cloud compute', 0), (@q, 'D', 'Averaged over ALL possible problems, every learning algorithm performs the same; any advantage comes from matching assumptions to a problem class', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 4, 'mcq', 'Convolutional neural networks work well on images mainly because their architecture builds in which inductive bias?', NULL, NULL, 'Locality and translation equivariance: nearby pixels matter together and a pattern means the same thing anywhere', 'A small filter slides across the whole image with the same weights.', 'Small shared filters assume local structure and that a cat''s ear is an ear wherever it appears. That''s the assumption that matches images.', NULL, NULL, 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Every pixel is equally related to every other pixel', 0), (@q, 'B', 'Feature independence', 0), (@q, 'C', 'Linear separability', 0), (@q, 'D', 'Locality and translation equivariance: nearby pixels matter together and a pattern means the same thing anywhere', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 4, 'true_false', 'A transformer with 70 billion weights is a non-parametric model because it has so many parameters.', NULL, NULL, 'False', 'Parametric is about whether the size grows with the data, not how big it is.', 'Its number of weights is fixed by the architecture before training, so it''s parametric, just very large.', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 4, 'true_false', '''Non-parametric'' means the model has no parameters at all.', NULL, NULL, 'False', 'Think of a decision tree''s thresholds.', 'Non-parametric models do have parameters (tree thresholds, stored points); their NUMBER grows with the data rather than being fixed.', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 4, 'mcq', 'A support team is rewarded on ''average ticket close time'', which a model is trained to predict and minimise. Agents start closing tickets early without solving them. This is an example of:', NULL, NULL, 'Goodhart''s law: a proxy metric stops measuring what you care about once you optimise it', 'When a measure becomes a target...', 'The proxy (close time) diverged from the goal (solved problems). Choose targets and guard-rail metrics that are hard to game.', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Goodhart''s law: a proxy metric stops measuring what you care about once you optimise it', 1), (@q, 'B', 'Overfitting', 0), (@q, 'C', 'Training-serving skew', 0), (@q, 'D', 'Data leakage', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 4, 'mcq', 'A churn model gets 0.99 AUC offline. One feature is ''number of support calls in the 30 days after the prediction date''. What is wrong?', NULL, NULL, 'Label leakage: the feature uses information from the future that won''t exist at prediction time', 'Ask: would this value be known at the moment you make the prediction?', 'Features must be computed only from data available at the prediction point. Future information makes offline scores great and production useless.', ' past data  | prediction point |  future (label window)\n features OK|        ^         |  NOT allowed as features', NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Label leakage: the feature uses information from the future that won''t exist at prediction time', 1), (@q, 'B', 'The model is underfitting', 0), (@q, 'C', 'AUC can''t be 0.99', 0), (@q, 'D', 'Nothing, it''s a strong feature', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 4, 'fill_blank', 'The principle ''when a measure becomes a target, it ceases to be a good measure'' is called ____''s law.', NULL, NULL, 'Goodhart', 'Named after a British economist.', 'Goodhart''s law: optimising a proxy hard enough makes it drift from the real goal (e.g. clicks -> clickbait).', NULL, NULL, 73);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Predicting house prices from past sales with known prices is which type of learning?', NULL, NULL, 'Supervised', 'Do the training examples come with the right answer?', 'Each example has a label (the price), so it''s supervised learning.', NULL, NULL, 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Unsupervised', 0), (@q, 'B', 'None', 0), (@q, 'C', 'Supervised', 1), (@q, 'D', 'Reinforcement', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Grouping customers into segments with no labels given is:', NULL, NULL, 'Unsupervised (clustering)', 'No right answers are provided; the model finds structure itself.', 'No labels -> unsupervised. Clustering finds natural groups.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Unsupervised (clustering)', 1), (@q, 'B', 'Regression', 0), (@q, 'C', 'Reinforcement', 0), (@q, 'D', 'Supervised (classification)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'An agent learning to play a game from rewards and penalties is:', NULL, NULL, 'Reinforcement learning', 'Think trial and error with a score.', 'RL learns by acting, getting a reward, and improving its policy.', '   +-------- action ------->+\n Agent                  Environment\n   +<--- reward, state -----+', NULL, 3);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Supervised learning', 0), (@q, 'B', 'Reinforcement learning', 1), (@q, 'C', 'Transfer learning', 0), (@q, 'D', 'Unsupervised learning', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Classification vs regression: which is regression?', NULL, NULL, 'Predicting tomorrow''s temperature in degrees', 'Regression predicts a number; classification predicts a category.', 'Temperature is a continuous number -> regression.', NULL, NULL, 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Fraud yes/no', 0), (@q, 'B', 'Predicting tomorrow''s temperature in degrees', 1), (@q, 'C', 'Spam or not spam', 0), (@q, 'D', 'Cat, dog or bird', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 2, 'true_false', 'Large language models are pre-trained with self-supervised learning: the ''label'' is just the next word in the text.', NULL, NULL, 'True', 'Nobody hand-labels the internet.', 'The text supplies its own labels (next token), which is why LLMs can train on so much data.', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 1, 'mcq', '''Supervised'' learning gets its name because:', NULL, NULL, 'Each training example comes with the correct answer, like a teacher marking work', 'What extra column does supervised data have?', 'Supervised data has labels: the right answer for each example. The model learns to map inputs to those answers.', NULL, NULL, 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A human watches the model train', 0), (@q, 'B', 'It only works in supervised environments', 0), (@q, 'C', 'Each training example comes with the correct answer, like a teacher marking work', 1), (@q, 'D', 'The model is checked by a supervisor program', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 1, 'mcq', 'Which of these is a CLASSIFICATION task?', NULL, NULL, 'Deciding if an X-ray shows pneumonia: yes or no', 'Classification picks from a fixed set of categories.', 'Yes/no is a category. Rent, minutes and revenue are numbers, so those are regression.', NULL, NULL, 7);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Predicting a flat''s rent in rupees', 0), (@q, 'B', 'Forecasting next month''s revenue', 0), (@q, 'C', 'Deciding if an X-ray shows pneumonia: yes or no', 1), (@q, 'D', 'Estimating a delivery time in minutes', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 1, 'true_false', 'Predicting a customer''s age in years from their purchases is a regression task.', NULL, NULL, 'True', 'Is the output a category or a number?', 'Age is a number on a continuous scale, so it''s regression.', NULL, NULL, 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 1, 'mcq', 'Sorting emails into ''Primary'', ''Social'' or ''Promotions'' (exactly one each) is:', NULL, NULL, 'Multiclass classification', 'How many possible categories, and how many per email?', 'More than two classes, exactly one per example = multiclass.', NULL, NULL, 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Regression', 0), (@q, 'B', 'Multiclass classification', 1), (@q, 'C', 'Binary classification', 0), (@q, 'D', 'Clustering', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 1, 'mcq', 'In unsupervised learning, the training data has:', NULL, NULL, 'No labels: the model has to find structure by itself', '''Un''-supervised: no teacher.', 'There are no correct answers given. The model looks for groups, patterns or compressed representations.', NULL, NULL, 10);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only images', 0), (@q, 'B', 'No labels: the model has to find structure by itself', 1), (@q, 'C', 'Rewards for every action', 0), (@q, 'D', 'Labels for every row', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 1, 'mcq', 'A bank wants to flag card transactions that look very unusual compared with normal ones, without having labelled fraud examples. This is:', NULL, NULL, 'Anomaly detection (usually unsupervised)', 'It''s about finding the odd ones out.', 'Anomaly detection learns what ''normal'' looks like and flags points that don''t fit; it doesn''t need labelled anomalies.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Anomaly detection (usually unsupervised)', 1), (@q, 'B', 'Regression', 0), (@q, 'C', 'Multiclass classification', 0), (@q, 'D', 'Reinforcement learning', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 1, 'mcq', 'In reinforcement learning, what is the ''reward''?', NULL, NULL, 'A number the environment gives the agent saying how good its last action was', 'Think of points in a video game.', 'The reward is a score signal from the environment. The agent learns actions that collect more reward over time.', '        action\n Agent ---------> Environment\n   ^                  |\n   +-- state, reward -+', NULL, 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The model''s accuracy on the test set', 0), (@q, 'B', 'The correct label for each example', 0), (@q, 'C', 'A number the environment gives the agent saying how good its last action was', 1), (@q, 'D', 'The learning rate', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 1, 'mcq', 'In reinforcement learning, the ''policy'' is:', NULL, NULL, 'The agent''s strategy: which action to take in each situation', 'It''s what the agent is trying to improve.', 'A policy maps state -> action. RL is about learning a good policy.', NULL, 'Like a request router: given the current state, decide what to do next.', 13);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The training dataset', 0), (@q, 'B', 'The reward the environment gives', 0), (@q, 'C', 'The agent''s strategy: which action to take in each situation', 1), (@q, 'D', 'The list of all states', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 1, 'mcq', 'A model that is updated a little bit every time a new data point arrives is doing:', NULL, NULL, 'Online learning', 'It learns continuously, piece by piece.', 'Online (incremental) learning updates as data streams in. Batch learning retrains on the whole dataset at once.', NULL, NULL, 14);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Batch learning', 0), (@q, 'B', 'Transfer learning', 0), (@q, 'C', 'Unsupervised learning', 0), (@q, 'D', 'Online learning', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 1, 'true_false', '''Online learning'' means the model is served behind a web API.', NULL, NULL, 'False', 'It''s about how the model learns, not where it runs.', 'Online learning = updating the model incrementally as new data arrives. A batch-trained model served via an API is still batch learning.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'transfer'), 1, 'mcq', 'Transfer learning means:', NULL, NULL, 'Starting from a model already trained on a big task and adapting it to your task', 'Reuse what was already learned.', 'A pretrained model already knows general patterns (edges, words). You adapt it with a little data instead of training from zero.', NULL, 'Like forking a mature open-source library instead of writing one from scratch.', 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Starting from a model already trained on a big task and adapting it to your task', 1), (@q, 'B', 'Training two models at the same time', 0), (@q, 'C', 'Moving a model from Python to Java', 0), (@q, 'D', 'Copying data from one server to another', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'gen-disc'), 1, 'mcq', 'Which model can CREATE new examples, like brand-new images of faces?', NULL, NULL, 'A generative model', 'One family ''generates''.', 'Generative models learn what the data looks like, so they can sample new data. Discriminative models only separate classes.', NULL, NULL, 17);
