INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scenarios'), 1, 'true_false', 'Grouping news articles by topic without knowing the topics in advance is unsupervised learning.', NULL, NULL, 'True', 'Are topic labels given?', 'No labels are given; the model groups similar articles (clustering or topic modelling).', NULL, NULL, 20);
