INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'gen-disc'), 2, 'true_false', 'Generative models are only useful for creating images or text; they can''t classify.', NULL, NULL, 'False', 'Naive Bayes is generative.', 'Generative models can classify by using Bayes'' rule: pick the class y that makes x most likely. Naive Bayes is a classic spam classifier.', NULL, NULL, 37);
