INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'outliers'), 1, 'mcq', 'In a table of salaries where almost everyone earns 5-30 lakh, one row says 900 lakh. That row is:', NULL, NULL, 'An outlier: far from the rest of the data', 'It sits far away from everything else.', 'An outlier is a point far from the others. It might be a typo or a real (rare) CEO salary; you must check which.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A label', 0), (@q, 'B', 'A categorical feature', 0), (@q, 'C', 'An outlier: far from the rest of the data', 1), (@q, 'D', 'A missing value', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'imbalance'), 1, 'mcq', 'A fraud dataset has 9,900 normal transactions and 100 frauds. This is called:', NULL, NULL, 'Class imbalance', 'One class is much rarer than the other.', 'When one class is much rarer (here 1%), the data is imbalanced. Models tend to ignore the rare class unless you correct for it.', NULL, NULL, 16);
