INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'features-labels'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"rooms": [2, 3, 4], "area": [800, 1200, 1500], "price": [50, 75, 95]})\nX = df.drop(columns="price")\ny = df["price"]\nprint(X.shape, y.shape)', 'python', '(3, 2) (3,)', 'drop removes the label column from the features.', 'X keeps 3 rows and the 2 feature columns; y is a single column (a Series), shape (3,).', NULL, NULL, 20);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(3, 2) (3, 1)', 0), (@q, 'B', '(3, 3) (3,)', 0), (@q, 'C', '(3, 2) (3,)', 1), (@q, 'D', '(2, 3) (3,)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'feature-types'), 1, 'fill_blank', 'A feature like colour (red, green, blue) whose categories have NO natural order is called ____.', NULL, NULL, 'nominal', 'Nominal comes from ''name'': just names.', 'Nominal = unordered categories. Ordinal = ordered (small < medium < large).', NULL, NULL, 21);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'features-labels'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.model_selection import train_test_split\nX = np.arange(20).reshape(10, 2)\ny = np.arange(10)\nXtr, Xte, ytr, yte = train_test_split(X, y, test_size=0.25, random_state=0)\nprint(Xtr.shape, Xte.shape)', 'python', '(7, 2) (3, 2)', '25% of 10 is 2.5; which way does sklearn round the test set?', 'sklearn rounds the test size UP: ceil(2.5) = 3 test rows, 7 train rows. Columns are unchanged.', NULL, NULL, 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(7, 1) (3, 1)', 0), (@q, 'B', '(8, 2) (2, 2)', 0), (@q, 'C', '(7, 2) (2, 2)', 0), (@q, 'D', '(7, 2) (3, 2)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'data-kinds'), 2, 'code_output', 'What does this print?', 'import numpy as np\nbatch = np.zeros((32, 64, 64, 3))\nprint(batch.ndim, batch[0].shape)', 'python', '4 (64, 64, 3)', '(batch, height, width, colour channels).', 'A batch of 32 RGB images of 64x64 is a 4-D array. One image is (64, 64, 3): height, width and 3 colour channels.', NULL, NULL, 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4 (64, 64, 3)', 1), (@q, 'B', '4 (64, 3)', 0), (@q, 'C', '4 (32, 64, 64)', 0), (@q, 'D', '3 (64, 64, 3)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'data-kinds'), 2, 'mcq', 'Before a model can use raw text like ''great product, fast delivery'', you must first:', NULL, NULL, 'Turn it into numbers, e.g. tokenise and map tokens to IDs or vectors', 'Models only do arithmetic.', 'Text is tokenised (split into pieces) and converted to numbers (IDs, counts like TF-IDF, or embeddings).', NULL, NULL, 24);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Store it in a bigger column', 0), (@q, 'B', 'Turn it into numbers, e.g. tokenise and map tokens to IDs or vectors', 1), (@q, 'C', 'Remove all vowels', 0), (@q, 'D', 'Sort the words alphabetically', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'feature-types'), 2, 'true_false', 'A 6-digit PIN code like 560001 should be treated as a numeric feature, since it''s a number.', NULL, NULL, 'False', 'Is 560002 ''one more'' than 560001 in any meaningful way?', 'PIN codes, user IDs and phone numbers are identifiers. Their numeric size means nothing, so treat them as categorical (or derive features like region).', NULL, NULL, 25);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'encoding'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["BLR", "MUM", "DEL", "BLR"]})\nprint(pd.get_dummies(df, columns=["city"]).columns.tolist())', 'python', '[''city_BLR'', ''city_DEL'', ''city_MUM'']', 'get_dummies sorts the categories and prefixes the column name.', 'One column per distinct city, sorted alphabetically and prefixed with ''city_''.', NULL, NULL, 26);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''city_BLR'', ''city_DEL'', ''city_MUM'']', 1), (@q, 'B', '[''city_BLR'', ''city_MUM'', ''city_DEL'']', 0), (@q, 'C', '[''city'']', 0), (@q, 'D', '[''BLR'', ''DEL'', ''MUM'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'encoding'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.preprocessing import OneHotEncoder\nX = np.array([["red"], ["green"], ["blue"], ["green"]])\nenc = OneHotEncoder(drop="first", sparse_output=False).fit(X)\nprint(enc.transform(X).shape)', 'python', '(4, 2)', '3 categories, minus the dropped one.', 'drop=''first'' removes one column (here ''blue''), so 3 colours become 2 columns. That avoids perfectly redundant columns for linear models.', NULL, NULL, 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(4, 2)', 1), (@q, 'B', '(4, 3)', 0), (@q, 'C', '(3, 4)', 0), (@q, 'D', '(4, 1)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'encoding'), 2, 'true_false', 'Encoding a nominal feature city as BLR=0, DEL=1, MUM=2 and feeding it to linear regression is fine, because the numbers are just labels.', NULL, NULL, 'False', 'What does a linear model do with the value 2 vs 0?', 'A linear model treats the numbers as quantities: MUM becomes ''2x BLR-to-DEL''. That fake order misleads it. Use one-hot for nominal features.', NULL, NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scaling'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.preprocessing import StandardScaler\nX = np.array([[1.0], [2.0], [3.0]])\nprint(np.round(StandardScaler().fit_transform(X).ravel(), 2))', 'python', '[-1.22  0.    1.22]', 'Mean 2; std computed with ddof=0 is sqrt(2/3).', 'StandardScaler does (x - mean) / std with the population std (ddof=0) = 0.816, so the values are about -1.22, 0, 1.22.', NULL, NULL, 29);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0.  0.5 1. ]', 0), (@q, 'B', '[-1.22  0.    1.22]', 1), (@q, 'C', '[1. 2. 3.]', 0), (@q, 'D', '[-1.  0.  1.]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scaling'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.preprocessing import MinMaxScaler\ntrain = np.array([[0.0], [5.0], [10.0]])\ntest = np.array([[20.0]])\ns = MinMaxScaler().fit(train)\nprint(s.transform(test))', 'python', '[[2.]]', 'The min and max come from the training data only.', 'Train min = 0, max = 10, so (20 - 0) / 10 = 2.0. Test values can fall outside [0, 1]; the scaler doesn''t clip.', NULL, NULL, 30);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[1.]]', 0), (@q, 'B', 'ValueError', 0), (@q, 'C', '[[2.]]', 1), (@q, 'D', '[[0.5]]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 2, 'code_output', 'What does this print?', 'import numpy as np\nimport pandas as pd\ns = pd.Series([1.0, np.nan, 3.0])\nprint(s.mean(), np.mean(s.to_numpy()))', 'python', '2.0 nan', 'One library skips NaN by default; the other propagates it.', 'pandas skips NaN (skipna=True), giving 2.0. NumPy''s np.mean on the raw array returns nan; use np.nanmean instead.', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2.0 2.0', 0), (@q, 'B', '2.0 nan', 1), (@q, 'C', '1.3333333333333333 nan', 0), (@q, 'D', 'nan nan', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.impute import SimpleImputer\nX = np.array([[1.0], [np.nan], [3.0], [100.0]])\nprint(SimpleImputer(strategy="median").fit_transform(X).ravel())', 'python', '[  1.   3.   3. 100.]', 'Median of the observed values 1, 3, 100.', 'The median of [1, 3, 100] is 3, so the gap becomes 3. The mean (34.7) would be dragged by the 100.', NULL, NULL, 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[  1.          34.66666667   3.         100.        ]', 0), (@q, 'B', '[  1.   3.   3. 100.]', 1), (@q, 'C', '[  1.   0.   3. 100.]', 0), (@q, 'D', '[  1.   2.   3. 100.]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 2, 'true_false', 'Filling every missing value with 0 is always a safe default.', NULL, NULL, 'False', 'What if 0 is a real, meaningful value?', 'If 0 means something (balance = 0, age 0), filling with 0 blends missing with real values. Prefer median/mode or a learned imputer, often with an ''is_missing'' flag.', NULL, NULL, 33);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'outliers'), 2, 'code_output', 'What does this print?', 'import numpy as np\nx = np.array([10, 12, 11, 13, 12, 500])\nprint(np.mean(x), np.median(x))', 'python', '93.0 12.0', 'Which one is pulled by the 500?', 'The single outlier drags the mean to 93, while the median stays at 12, a robust centre.', NULL, NULL, 34);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '12.0 12.0', 0), (@q, 'B', '93.0 12.0', 1), (@q, 'C', '11.6 12.0', 0), (@q, 'D', '93.0 93.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'outliers'), 2, 'code_output', 'What does this print?', 'import numpy as np\nx = np.array([10, 12, 11, 13, 12, 14, 11, 60])\nq1, q3 = np.percentile(x, [25, 75])\niqr = q3 - q1\nmask = (x < q1 - 1.5 * iqr) | (x > q3 + 1.5 * iqr)\nprint(x[mask])', 'python', '[60]', 'IQR rule: further than 1.5 * IQR beyond the quartiles.', 'Q1 = 11, Q3 = 13.25, IQR = 2.25, so the fence is [7.6, 16.6]. Only 60 falls outside.', '   Q1-1.5IQR   Q1   Q3   Q3+1.5IQR\n ------|--------[====]--------|------- * 60\n     normal range of the box        outlier', NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[]', 0), (@q, 'B', '[60]', 1), (@q, 'C', '[13 14 60]', 0), (@q, 'D', '[10 60]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'imbalance'), 2, 'mcq', 'A model for a 99:1 imbalanced fraud dataset reports 99% accuracy. What''s the first thing to check?', NULL, NULL, 'Whether it just predicts ''not fraud'' for everything: look at recall and precision on the fraud class', 'What does a do-nothing model score here?', 'Always predicting the majority class already gives 99%. This is the accuracy paradox; check fraud-class recall, precision and PR-AUC.', NULL, NULL, 36);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Nothing, 99% is excellent', 0), (@q, 'B', 'Whether it just predicts ''not fraud'' for everything: look at recall and precision on the fraud class', 1), (@q, 'C', 'Whether the dataset is too small', 0), (@q, 'D', 'Whether the learning rate is too low', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'imbalance'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.model_selection import train_test_split\ny = np.array([0] * 90 + [1] * 10)\nX = np.arange(100).reshape(-1, 1)\n_, _, _, yte = train_test_split(X, y, test_size=0.2, stratify=y, random_state=0)\nprint(len(yte), int(yte.sum()))', 'python', '20 2', 'stratify keeps the class ratio the same in each split.', '10% of the data is class 1, so a stratified 20-row test set gets exactly 2 positives. Without stratify you could easily get 0 or 5.', NULL, NULL, 37);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '20 0', 0), (@q, 'B', '10 2', 0), (@q, 'C', '20 2', 1), (@q, 'D', '20 10', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'quality'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"text": ["good", "bad", "good", "ok"], "label": [1, 0, 0, 1]})\nconflicts = df.groupby("text")["label"].nunique()\nprint(conflicts[conflicts > 1].index.tolist())', 'python', '[''good'']', 'Same input, more than one distinct label.', '''good'' appears with labels 1 and 0: a conflicting (noisy) label. Finding these is a cheap data-quality check.', NULL, NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[]', 0), (@q, 'B', '[''bad'']', 0), (@q, 'C', '[''good'', ''ok'']', 0), (@q, 'D', '[''good'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'feature-eng'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"ts": pd.to_datetime(["2026-11-14 09:30", "2026-11-15 22:10"])})\ndf["dow"] = df["ts"].dt.dayofweek\ndf["hour"] = df["ts"].dt.hour\nprint(df[["dow", "hour"]].values.tolist())', 'python', '[[5, 9], [6, 22]]', 'dayofweek counts Monday as 0. 14 Nov 2026 is a Saturday.', 'Saturday = 5, Sunday = 6, plus the hour. Turning a raw timestamp into day-of-week and hour is classic feature engineering.', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[6, 9], [0, 22]]', 0), (@q, 'B', '[[14, 9], [15, 22]]', 0), (@q, 'C', '[[5, 9], [6, 22]]', 1), (@q, 'D', '[[5, 30], [6, 10]]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'features-labels'), 3, 'mcq', 'Why use stratify=y in train_test_split for a classification problem with a rare class?', NULL, NULL, 'So train and test keep the same class proportions and the rare class isn''t missing from the test set', 'A random split of 1% positives can easily give 0 positives in a small test set.', 'Stratification preserves the class ratio in each split. It does NOT balance the classes; it just keeps the original ratio.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'So train and test keep the same class proportions and the rare class isn''t missing from the test set', 1), (@q, 'B', 'To balance the classes 50/50', 0), (@q, 'C', 'To make the split faster', 0), (@q, 'D', 'To remove duplicates', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'data-kinds'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([100, 120, 130, 125], index=pd.date_range("2026-01-01", periods=4))\ndf = pd.DataFrame({"sales": s, "lag1": s.shift(1)})\nprint(df["lag1"].tolist())', 'python', '[nan, 100.0, 120.0, 130.0]', 'shift(1) moves values one step later in time.', 'A lag feature gives each day yesterday''s value. The first day has no yesterday, so it''s NaN (and the ints become floats).', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[120.0, 130.0, 125.0, nan]', 0), (@q, 'B', '[nan, 100.0, 120.0, 130.0]', 1), (@q, 'C', '[100, 120, 130, 125]', 0), (@q, 'D', '[nan, nan, 100.0, 120.0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'data-kinds'), 3, 'mcq', 'For predicting next month''s sales from 3 years of monthly data, how should you split?', NULL, NULL, 'Train on the earlier months, test on the most recent months (no shuffling)', 'In production you''ll always predict the future from the past.', 'A random split lets the model see the future during training (leakage). Time-ordered splits mimic real use.', ' time --->\n [=========== train ===========][== test ==]\n shuffle split would mix future rows into train', NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Train on the earlier months, test on the most recent months (no shuffling)', 1), (@q, 'B', 'Use every other month as test', 0), (@q, 'C', 'Shuffle all months randomly, then split 80/20', 0), (@q, 'D', 'Test on the oldest months', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'encoding'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.preprocessing import OrdinalEncoder\nX = np.array([["low"], ["medium"], ["high"]])\nprint(OrdinalEncoder().fit_transform(X).ravel())', 'python', '[1. 2. 0.]', 'OrdinalEncoder doesn''t know English; it sorts strings.', 'Without categories=..., it sorts alphabetically: high=0, low=1, medium=2. So low->1, medium->2, high->0, which breaks the real order.', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1. 2. 0.]', 1), (@q, 'B', '[0. 1. 2.]', 0), (@q, 'C', '[2. 1. 0.]', 0), (@q, 'D', '[0. 2. 1.]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'encoding'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.preprocessing import OrdinalEncoder\nenc = OrdinalEncoder(categories=[["low", "medium", "high"]])\nprint(enc.fit_transform(np.array([["low"], ["medium"], ["high"]])).ravel())', 'python', '[0. 1. 2.]', 'You told it the order explicitly.', 'Passing categories=[[...]] fixes the order you want, so low=0 < medium=1 < high=2.', NULL, NULL, 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2. 1. 0.]', 0), (@q, 'B', 'ValueError', 0), (@q, 'C', '[1. 2. 0.]', 0), (@q, 'D', '[0. 1. 2.]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'encoding'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.preprocessing import OneHotEncoder\nenc = OneHotEncoder(sparse_output=False).fit(np.array([["BLR"], ["MUM"]]))\nprint(enc.transform(np.array([["DEL"]])))', 'python', 'ValueError', 'DEL never appeared during fit. What''s the default for unknown categories?', 'handle_unknown defaults to ''error'', so an unseen category raises ValueError at inference.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[0. 0.]]', 0), (@q, 'B', '[[1. 0.]]', 0), (@q, 'C', '[[0. 0. 1.]]', 0), (@q, 'D', 'ValueError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'encoding'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.preprocessing import OneHotEncoder\nenc = OneHotEncoder(handle_unknown="ignore", sparse_output=False).fit(np.array([["BLR"], ["MUM"]]))\nprint(enc.transform(np.array([["DEL"], ["MUM"]])))', 'python', '[[0. 0.]\n [0. 1.]]', '''ignore'' means: no column lights up.', 'With handle_unknown=''ignore'', an unseen category becomes an all-zeros row; known ones encode normally. Production pipelines usually need this.', NULL, NULL, 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[1. 0.]\n [0. 1.]]', 0), (@q, 'B', '[[0. 0. 1.]\n [0. 1. 0.]]', 0), (@q, 'C', '[[0. 0.]\n [0. 1.]]', 1), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scaling'), 3, 'mcq', 'A colleague runs StandardScaler().fit_transform(X) on the whole dataset, then splits into train and test. What is wrong?', NULL, NULL, 'The test set''s mean and std leaked into the training features (data leakage)', 'The test set should be unseen in every way.', 'Fit preprocessing on training data only, then transform test. Better: put the scaler in a Pipeline so cross-validation refits it per fold.', NULL, 'Like letting a load test peek at production traffic to tune caches, then reporting the numbers as if blind.', 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The test set''s mean and std leaked into the training features (data leakage)', 1), (@q, 'B', 'Nothing, scaling doesn''t affect the score', 0), (@q, 'C', 'StandardScaler can''t be used before a split', 0), (@q, 'D', 'The scaler should be fit on the test set', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scaling'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.model_selection import train_test_split\nX = np.arange(10, dtype=float).reshape(-1, 1)\nXtr, Xte = train_test_split(X, test_size=0.3, random_state=0)\ns = StandardScaler().fit(Xtr)\nprint(s.mean_[0] == Xtr.mean(), s.mean_[0] == X.mean())', 'python', 'True False', 'The scaler only saw Xtr.', 'The scaler remembers the training mean only. That''s what you want: test is transformed with statistics it never contributed to.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True', 0), (@q, 'B', 'False False', 0), (@q, 'C', 'True True', 0), (@q, 'D', 'True False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scaling'), 3, 'mcq', 'Which model does NOT need feature scaling to work well?', NULL, NULL, 'A decision tree / random forest', 'Which one only asks ''is x above some threshold?''', 'Trees split on thresholds per feature, so rescaling doesn''t change their splits. Distance- and gradient-based models are sensitive to scale.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A decision tree / random forest', 1), (@q, 'B', 'k-nearest neighbours', 0), (@q, 'C', 'Logistic regression trained with gradient descent', 0), (@q, 'D', 'An SVM with an RBF kernel', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 3, 'mcq', 'You impute missing ''income'' with the median. Why also add a 0/1 column ''income_missing''?', NULL, NULL, 'The fact that a value is missing can itself carry signal (e.g. people who skip the question differ)', 'Who tends to leave income blank?', 'Missingness is often informative. The indicator lets the model use it, while the imputed value keeps the column numeric. sklearn: SimpleImputer(add_indicator=True).', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'So the scaler works', 0), (@q, 'B', 'The fact that a value is missing can itself carry signal (e.g. people who skip the question differ)', 1), (@q, 'C', 'Because imputation fails without it', 0), (@q, 'D', 'To make the dataset bigger', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'outliers'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.preprocessing import RobustScaler, StandardScaler\nx = np.array([[1.0], [2.0], [3.0], [4.0], [1000.0]])\nr = RobustScaler().fit_transform(x).ravel()\ns = StandardScaler().fit_transform(x).ravel()\nprint(np.round(r[:4], 2), np.round(s[:4], 2))', 'python', '[-1.  -0.5  0.   0.5] [-0.5 -0.5 -0.5 -0.5]', 'One scaler uses median and IQR, the other mean and std.', 'RobustScaler (median 3, IQR 2) keeps the normal points spread out. StandardScaler''s std is inflated by 1000, squashing them all to about -0.5.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[-1.  -0.5  0.   0.5] [-1.  -0.5  0.   0.5]', 0), (@q, 'B', '[-0.5 -0.5 -0.5 -0.5] [-1.  -0.5  0.   0.5]', 0), (@q, 'C', '[0. 0. 0. 0.] [0. 0. 0. 0.]', 0), (@q, 'D', '[-1.  -0.5  0.   0.5] [-0.5 -0.5 -0.5 -0.5]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'imbalance'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.utils.class_weight import compute_class_weight\ny = np.array([0] * 90 + [1] * 10)\nw = compute_class_weight("balanced", classes=np.array([0, 1]), y=y)\nprint(np.round(w, 2))', 'python', '[0.56 5.  ]', 'weight_c = n_samples / (n_classes * count_c).', '100 / (2 * 90) = 0.56 and 100 / (2 * 10) = 5.0. Mistakes on the rare class now cost 9x more in the loss.', NULL, NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1. 9.]', 0), (@q, 'B', '[0.9 0.1]', 0), (@q, 'C', '[0.56 5.  ]', 1), (@q, 'D', '[0.5 0.5]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'imbalance'), 3, 'mcq', 'When is it correct to oversample the minority class (e.g. random oversampling or SMOTE)?', NULL, NULL, 'After splitting, on the training set only (inside each CV fold)', 'What happens if a copied row lands in both train and test?', 'Oversampling before the split puts copies (or near-copies) of the same point in train and test, inflating the score. The test set must keep the real ratio.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Before splitting, on the whole dataset', 0), (@q, 'B', 'On both train and test, so they match', 0), (@q, 'C', 'On the test set only', 0), (@q, 'D', 'After splitting, on the training set only (inside each CV fold)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'quality'), 3, 'mcq', 'After deduplicating, you find 8% of test-set rows also appear exactly in the training set. What does this do to your test score?', NULL, NULL, 'Inflates it: the model is partly graded on examples it memorised', 'Tests that already appear in the training data...', 'Train/test overlap makes the test set partly a memory test. Deduplicate before splitting (and dedupe near-duplicates for text/images).', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Inflates it: the model is partly graded on examples it memorised', 1), (@q, 'B', 'Makes it more reliable', 0), (@q, 'C', 'Lowers it', 0), (@q, 'D', 'Nothing, duplicates are harmless', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'quality'), 3, 'true_false', 'If 5% of training labels are randomly flipped, a very flexible model trained to 100% training accuracy will have memorised those wrong labels.', NULL, NULL, 'True', '100% training accuracy means it fits every label, right or wrong.', 'Fitting noisy labels perfectly is overfitting to noise. Regularisation, early stopping and cleaning labels reduce the harm.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'feature-eng'), 3, 'code_output', 'What does this print?', 'import numpy as np\nrng = np.random.default_rng(0)\nfor d in (2, 1000):\n    X = rng.uniform(size=(200, d))\n    dist = np.linalg.norm(X[1:] - X[0], axis=1)\n    print(d, round(dist.max() / dist.min(), 1) > 2)', 'python', '2 True\n1000 False', 'In very high dimensions, are ''near'' and ''far'' still different?', 'In 2-D the farthest point is many times further than the nearest. In 1000-D all distances are nearly equal, so ''nearest neighbour'' loses meaning: the curse of dimensionality.', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2 True\n1000 False', 1), (@q, 'B', '2 False\n1000 False', 0), (@q, 'C', '2 True\n1000 True', 0), (@q, 'D', '2 False\n1000 True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'feature-eng'), 3, 'code_output', 'What does this print?', 'import numpy as np\nincome = np.array([20_000, 50_000, 80_000, 10_000_000])\nprint(np.round(np.log10(income), 1))', 'python', '[4.3 4.7 4.9 7. ]', 'log10 counts powers of ten.', 'A log transform squeezes a long right tail: the 10-million value becomes 7, close to the rest. Common for income, prices and counts.', NULL, NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2.3 2.7 2.9 5. ]', 0), (@q, 'B', '[20000. 50000. 80000. 10000000.]', 0), (@q, 'C', '[9.9 10.8 11.3 16.1]', 0), (@q, 'D', '[4.3 4.7 4.9 7. ]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'shift'), 3, 'mcq', 'A model is trained in 2024; in 2026 the share of customers aged 18-25 doubled, but for any given age the chance of buying is unchanged. This is:', NULL, NULL, 'Covariate shift: p(x) changed, p(y given x) did not', 'What changed: the inputs'' distribution, or the rule linking inputs to labels?', 'Only the input distribution moved. Concept drift would mean the same customer now behaves differently.', NULL, NULL, 58);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Class imbalance', 0), (@q, 'B', 'Covariate shift: p(x) changed, p(y given x) did not', 1), (@q, 'C', 'Label noise', 0), (@q, 'D', 'Concept drift: p(y given x) changed', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'shift'), 3, 'mcq', 'During COVID, the same browsing behaviour suddenly predicted very different purchases than before. This is:', NULL, NULL, 'Concept drift: the relationship between features and label changed', 'Same x, different y.', 'When p(y | x) changes, the learned rule is simply out of date. You need fresh labels and retraining, not just reweighting.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Sampling bias at collection time', 0), (@q, 'B', 'Concept drift: the relationship between features and label changed', 1), (@q, 'C', 'Covariate shift only', 0), (@q, 'D', 'A missing-data problem', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'versioning'), 3, 'mcq', 'Why should training data be versioned, just like code?', NULL, NULL, 'A model is produced by data + code; without the exact data version you can''t reproduce or debug it', 'Your model changed but the code didn''t. Why?', 'Same code + different data = a different model. Versioning data lets you reproduce, compare and roll back models.', NULL, 'Data is a build input like a dependency lockfile: pin it or builds aren''t reproducible.', 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It makes training faster', 0), (@q, 'B', 'A model is produced by data + code; without the exact data version you can''t reproduce or debug it', 1), (@q, 'C', 'Data never changes, so versioning is just a formality', 0), (@q, 'D', 'Git stores large datasets efficiently', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'features-labels'), 4, 'mcq', 'A loan model doesn''t use ''race'', but uses PIN code, and still produces racially skewed decisions. Why?', NULL, NULL, 'PIN code acts as a proxy feature strongly correlated with the protected attribute', 'Removing a column doesn''t remove information correlated with it.', 'Proxy features (PIN code, school, name) can encode a protected attribute. Fairness needs measuring outcomes by group, not just dropping columns.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'PIN codes are random', 0), (@q, 'B', 'The model secretly reads the race column', 0), (@q, 'C', 'Because of class weights', 0), (@q, 'D', 'PIN code acts as a proxy feature strongly correlated with the protected attribute', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'data-kinds'), 4, 'mcq', 'A model predicts patient readmission. Each patient has many visits; you randomly split visits into train/test and get great scores, but performance on new patients is poor. What''s the fix?', NULL, NULL, 'Group-based split (e.g. GroupKFold by patient) so a patient''s visits are all in train or all in test', 'The model recognises patients it already met.', 'Visits of the same patient are correlated. Splitting by group measures what you actually care about: performance on unseen patients.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Use a bigger test set', 0), (@q, 'B', 'Shuffle the data more', 0), (@q, 'C', 'Group-based split (e.g. GroupKFold by patient) so a patient''s visits are all in train or all in test', 1), (@q, 'D', 'Use stratify=y', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'feature-types'), 4, 'code_output', 'What does this print?', 'import numpy as np\nhours = np.array([0, 6, 12, 23])\nsin_h = np.sin(2 * np.pi * hours / 24)\ncos_h = np.cos(2 * np.pi * hours / 24)\nd = lambda a, b: np.hypot(sin_h[a] - sin_h[b], cos_h[a] - cos_h[b])\nprint(round(d(0, 3), 2), round(d(0, 2), 2))', 'python', '0.26 2.0', 'On a clock, 23:00 is right next to 00:00.', 'Encoding the hour as (sin, cos) puts it on a circle: 23:00 is 0.26 away from midnight, 12:00 is the opposite side (2.0). As a raw number, 23 looks far from 0.', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.26 2.0', 1), (@q, 'B', '2.0 0.26', 0), (@q, 'C', '0.26 0.26', 0), (@q, 'D', '23 12', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'encoding'), 4, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.preprocessing import TargetEncoder\nrng = np.random.default_rng(0)\nX = rng.choice(["a", "b", "c", "d"], size=(200, 1))\ny = rng.integers(0, 2, size=200)\nenc = TargetEncoder(random_state=0)\na = enc.fit_transform(X, y)\nb = enc.transform(X)\nprint(np.allclose(a, b))', 'python', 'False', 'fit_transform for TargetEncoder uses cross-fitting.', 'fit_transform encodes each training row using folds that exclude it, so it doesn''t see its own label. transform uses the full-data means, so they differ by design.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'ValueError', 0), (@q, 'C', 'NotFittedError', 0), (@q, 'D', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'encoding'), 4, 'mcq', 'Why is naive target encoding (replace each category with the mean label over the whole training set) dangerous for a high-cardinality feature like user_id?', NULL, NULL, 'Rare categories get an encoding that is basically their own label, leaking y into X and causing overfitting', 'A user who appears once: their encoded value equals their label.', 'For rare categories, the mean label IS the row''s label. Use cross-fitting (as sklearn''s TargetEncoder.fit_transform does) and smoothing towards the global mean.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It can''t handle strings', 0), (@q, 'B', 'It only works for regression', 0), (@q, 'C', 'Rare categories get an encoding that is basically their own label, leaking y into X and causing overfitting', 1), (@q, 'D', 'It makes the data too large', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scaling'), 4, 'mcq', 'You run cross_val_score on a Pipeline(StandardScaler, SVC) instead of scaling first and then cross-validating an SVC. Why is the pipeline version more honest?', NULL, NULL, 'The scaler is refit inside each fold on that fold''s training part only, so the validation fold never leaks into preprocessing', 'Where does each fold''s scaler get its mean and std from?', 'Preprocessing fitted outside CV has seen the validation folds. A Pipeline makes every fit/transform happen per fold, exactly like in production.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It uses a different SVM', 0), (@q, 'B', 'There is no difference', 0), (@q, 'C', 'Pipelines train faster', 0), (@q, 'D', 'The scaler is refit inside each fold on that fold''s training part only, so the validation fold never leaks into preprocessing', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 4, 'mcq', 'A clinic''s ''last cholesterol test'' is missing mostly for healthy patients whose doctors didn''t order the test. This missingness is:', NULL, NULL, 'Missing not at random (MNAR): missingness depends on the patient''s health itself', 'Is the missingness related to the thing you''re trying to predict?', 'When the reason a value is missing depends on the outcome, imputing a mean hides real signal. A missing-indicator or modelling the process is needed.', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Missing not at random (MNAR): missingness depends on the patient''s health itself', 1), (@q, 'B', 'Not a problem for any model', 0), (@q, 'C', 'Fixed by mean imputation', 0), (@q, 'D', 'Missing completely at random', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'outliers'), 4, 'true_false', 'In a fraud model, you should remove all outliers from the training data to improve the model.', NULL, NULL, 'False', 'What does a fraudulent transaction usually look like?', 'Fraud often IS the outlier. Remove only errors (typos, sensor glitches); keep real extremes, especially when they''re the signal.', NULL, NULL, 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'imbalance'), 4, 'mcq', 'You trained with class_weight=''balanced'' on 1:99 data. The predicted probabilities are now much higher than the real fraud rate. What''s the best way to use the model?', NULL, NULL, 'Choose the decision threshold on validation data for the business cost, and recalibrate probabilities if they''re consumed as probabilities', 'Weighting changes the effective class prior the model learns.', 'Class weights shift outputs towards the rare class, so probabilities are no longer calibrated. Tune the threshold for cost and calibrate (e.g. CalibratedClassifierCV) if needed.', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Always use 0.5 as the threshold', 0), (@q, 'B', 'Retrain without any weights and ignore the rare class', 0), (@q, 'C', 'Report accuracy only', 0), (@q, 'D', 'Choose the decision threshold on validation data for the business cost, and recalibrate probabilities if they''re consumed as probabilities', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'quality'), 4, 'mcq', 'Your image classifier keeps failing on a few classes. A review finds ~10% of those training labels are wrong. Which approach targets the root cause?', NULL, NULL, 'Find likely mislabels (e.g. examples where out-of-fold predictions confidently disagree with the label) and send them for relabelling', 'Fix the data, not the model.', 'Out-of-fold predicted probabilities that confidently disagree with the given label (the ''confident learning'' idea) flag the rows most likely to be mislabelled.', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Train a bigger model', 0), (@q, 'B', 'Add more epochs', 0), (@q, 'C', 'Find likely mislabels (e.g. examples where out-of-fold predictions confidently disagree with the label) and send them for relabelling', 1), (@q, 'D', 'Increase the learning rate', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'feature-eng'), 4, 'mcq', 'You have 500 rows and 2,000 features. What is the most sensible response?', NULL, NULL, 'Reduce dimensions (feature selection, regularisation like L1, or PCA) and validate carefully; the model can easily fit noise', 'More columns than rows.', 'With p >> n, many models can fit the training data perfectly by chance. Constrain the model and validate honestly; kNN suffers most from high dimensions.', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Add more features to help the model', 0), (@q, 'B', 'Use kNN, since it handles high dimensions best', 0), (@q, 'C', 'Nothing, more features always help', 0), (@q, 'D', 'Reduce dimensions (feature selection, regularisation like L1, or PCA) and validate carefully; the model can easily fit noise', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'shift'), 4, 'mcq', 'To check if production data has shifted away from training data, you label train rows 0 and production rows 1 and train a classifier to tell them apart. Its AUC is 0.93. What does that mean?', NULL, NULL, 'Strong shift: the two datasets are easy to tell apart; its top features show what moved', 'If there were no shift, could any classifier tell them apart?', 'This is adversarial validation. AUC near 0.5 = indistinguishable (no shift); 0.93 = clearly different. Feature importances point to the drifting columns.', NULL, NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'No shift at all', 0), (@q, 'B', 'The model is overfitting', 0), (@q, 'C', 'The labels are noisy', 0), (@q, 'D', 'Strong shift: the two datasets are easy to tell apart; its top features show what moved', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'versioning'), 4, 'code_output', 'What does this print?', 'import hashlib\nimport pandas as pd\ndef h(df):\n    return hashlib.sha256(df.to_csv(index=False).encode()).hexdigest()[:8]\na = pd.DataFrame({"x": [1, 2, 3]})\nb = pd.DataFrame({"x": [1, 2, 3]})\nc = pd.DataFrame({"x": [1, 2, 4]})\nprint(h(a) == h(b), h(a) == h(c))', 'python', 'True False', 'A content hash depends only on the bytes.', 'Same content -> same hash; any change -> a new hash. Tools like DVC store a hash pointer in git and the data itself in remote storage.', NULL, NULL, 73);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True', 0), (@q, 'B', 'False False', 0), (@q, 'C', 'True True', 0), (@q, 'D', 'True False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'versioning'), 4, 'mcq', 'A model in production misbehaves. To reproduce exactly how it was built, which set of things must you have recorded?', NULL, NULL, 'Data version (hash), code commit, config/hyperparameters, random seeds and library versions', 'Training = function(data, code, config, randomness, environment).', 'All five inputs determine the trained model. Lineage tools (DVC, MLflow) tie each model to the exact data hash and commit that made it.', NULL, NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only the code commit', 0), (@q, 'B', 'Data version (hash), code commit, config/hyperparameters, random seeds and library versions', 1), (@q, 'C', 'Only the model file', 0), (@q, 'D', 'Only the dataset name', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scaling'), 3, 'fill_blank', 'sklearn''s StandardScaler computes the standard deviation with ddof = ____.', NULL, NULL, '0', 'Population vs sample standard deviation.', 'StandardScaler uses the population std (ddof=0), like np.std''s default. pandas .std() defaults to ddof=1, so the numbers differ slightly.', NULL, NULL, 75);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'imbalance'), 2, 'fill_blank', 'Upweighting the rare class in the loss, e.g. LogisticRegression(class_weight=''____''), sets weights inversely proportional to class frequency.', NULL, NULL, 'balanced', 'The option name says what it tries to make the classes.', 'class_weight=''balanced'' uses n_samples / (n_classes * count_c) per class.', NULL, NULL, 76);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Why do we keep a test set the model never trains on?', NULL, NULL, 'To measure how it does on unseen data', 'A student who saw the exam paper beforehand...', 'The test set is a fair, unseen exam. Scoring on training data only shows memorisation.', ' |------------ data -------------|\n |  train 70%  | val 15% |test 15%|\n   learn here    tune      final score', 'Evals are the test suite; testing on training data is like tests that hard-code the answers.', 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'To measure how it does on unseen data', 1), (@q, 'B', 'To make the dataset smaller', 0), (@q, 'C', 'Because the data is wrong', 0), (@q, 'D', 'To train faster', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'What is the validation set used for?', NULL, NULL, 'Tuning settings and choosing between models', 'It sits between train and test.', 'Validation helps pick hyperparameters; test is touched once at the end.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The final score you report', 0), (@q, 'B', 'Training the weights', 0), (@q, 'C', 'Storing labels', 0), (@q, 'D', 'Tuning settings and choosing between models', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 2, 'true_false', 'It''s fine to look at test-set results many times while tuning your model.', NULL, NULL, 'False', 'If you tune on it, is it still ''unseen''?', 'Tuning on the test set leaks information; your score becomes optimistic. Use validation for tuning.', NULL, NULL, 3);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 2, 'mcq', 'What is ''data leakage''?', NULL, NULL, 'Information from the test/future sneaking into training', 'Think of a feature that secretly contains the answer.', 'Leakage makes offline scores look great and production results bad.', NULL, NULL, 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Too little data', 0), (@q, 'B', 'Information from the test/future sneaking into training', 1), (@q, 'C', 'Losing data from disk', 0), (@q, 'D', 'Sharing data publicly', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'purpose'), 1, 'mcq', 'Which part of the data does the model actually learn its weights from?', NULL, NULL, 'The training set', 'Weights = what gets adjusted during learning.', 'Only the training set is used to fit weights. Validation is for choosing settings, test is for the final score.', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The training set', 1), (@q, 'B', 'The validation set', 0), (@q, 'C', 'All three equally', 0), (@q, 'D', 'The test set', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'purpose'), 1, 'mcq', 'You report one final number to your manager: ''the model is 91% accurate on new data''. Which set should that number come from?', NULL, NULL, 'The test set, used once at the end', 'Which set has had no influence on any decision?', 'The test set is the untouched final exam. Validation scores are slightly optimistic because you picked the model that did best on them.', NULL, 'Like a release check on a staging box nobody has been tweaking: it tells you how prod will behave.', 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The training set', 0), (@q, 'B', 'The validation set you tuned on', 0), (@q, 'C', 'Whichever set gives the best number', 0), (@q, 'D', 'The test set, used once at the end', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'purpose'), 1, 'true_false', 'A ''hyperparameter'' is a setting you choose before training (like tree depth), not a weight the model learns.', NULL, NULL, 'True', 'Who sets it: you or the training loop?', 'Hyperparameters are knobs you pick (depth, learning rate, regularisation strength). The validation set helps you pick them.', NULL, NULL, 7);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'purpose'), 1, 'mcq', 'A model gets 100% on the training set. What does that tell you about how it will do on new data?', NULL, NULL, 'Almost nothing on its own: it may have memorised', 'Can a lookup table also score 100% on data it has seen?', 'Training accuracy only says the model fits what it saw. A held-out set is needed to measure generalisation (doing well on unseen data).', NULL, 'A unit test that checks a hard-coded return value passes, but proves nothing about real inputs.', 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The test set is now unnecessary', 0), (@q, 'B', 'It will also get about 100%', 0), (@q, 'C', 'Almost nothing on its own: it may have memorised', 1), (@q, 'D', 'It will get about 50%', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'purpose'), 1, 'fill_blank', 'The set used to compare models and pick hyperparameters, between train and test, is the ________ set.', NULL, NULL, 'validation', 'Also called the dev set.', 'Train fits weights, validation picks settings, test gives the final unbiased score.', NULL, NULL, 9);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'purpose'), 2, 'mcq', 'Why is it a problem to choose hyperparameters using the test set?', NULL, NULL, 'The test score is then biased upward: it no longer measures unseen data', 'Each time you pick based on a score, that score stops being ''unseen''.', 'Every decision made by looking at a set leaks a little information from it. Keep the test set for one final check.', NULL, NULL, 10);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'sklearn raises an error', 0), (@q, 'B', 'The test score is then biased upward: it no longer measures unseen data', 1), (@q, 'C', 'The test set becomes smaller', 0), (@q, 'D', 'It makes training slower', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'purpose'), 3, 'mcq', 'After tuning on validation and checking the test set once, what is a common and acceptable final step before deploying?', NULL, NULL, 'Retrain the chosen configuration on train + validation (or all data) and ship that', 'Once decisions are frozen, more data usually helps.', 'With the configuration fixed, refitting on more data typically gives a slightly better model. The test score you already measured is the estimate you report.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Retrain the chosen configuration on train + validation (or all data) and ship that', 1), (@q, 'B', 'Keep tuning until the test score improves', 0), (@q, 'C', 'Throw away the test set and report the validation score', 0), (@q, 'D', 'Train a new model on the test set only', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ratios'), 1, 'mcq', 'Which split is a common default for a medium-sized dataset (say 10,000 rows)?', NULL, NULL, '70 / 15 / 15 (train / val / test)', 'Most data goes to learning.', 'Most rows train the model; enough are held back for reliable validation and test scores. 70/15/15 or 80/10/10 are typical.', NULL, NULL, 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '10 / 10 / 80', 0), (@q, 'B', '70 / 15 / 15 (train / val / test)', 1), (@q, 'C', '99 / 1 / 0', 0), (@q, 'D', '50 / 0 / 50', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ratios'), 1, 'code_output', 'What does this print?', 'from sklearn.model_selection import train_test_split\nX = list(range(100))\nX_train, X_test = train_test_split(X, test_size=0.2, random_state=0)\nprint(len(X_train), len(X_test))', 'python', '80 20', 'test_size=0.2 means 20% of 100.', 'test_size is the fraction held out: 20 rows for test, the other 80 for training.', NULL, NULL, 13);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '80 20', 1), (@q, 'B', '100 20', 0), (@q, 'C', '80 19', 0), (@q, 'D', '20 80', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ratios'), 2, 'code_output', 'What does this print?', 'from sklearn.model_selection import train_test_split\nX = list(range(10))\na, b = train_test_split(X, test_size=0.25, random_state=0)\nprint(len(a), len(b))', 'python', '7 3', '0.25 x 10 = 2.5. Which way does sklearn round the test side?', 'sklearn rounds the test size UP (ceil(2.5) = 3) and gives the rest to train.', NULL, NULL, 14);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '7.5 2.5', 0), (@q, 'B', '7 3', 1), (@q, 'C', '8 2', 0), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ratios'), 2, 'mcq', 'You have 10 million labelled rows. Why might a 98 / 1 / 1 split be perfectly sensible?', NULL, NULL, '1% is still 100,000 rows, plenty for a stable score', 'What matters for a reliable score: the percentage or the count?', 'The noise in a measured accuracy depends on the number of test examples, not the percentage. With huge data, a small fraction is already a large count.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Validation is not needed for large data', 0), (@q, 'B', '1% is still 100,000 rows, plenty for a stable score', 1), (@q, 'C', 'Big datasets must always use 98/1/1', 0), (@q, 'D', 'Test sets above 1% cause overfitting', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ratios'), 3, 'mcq', 'A test set has 100 examples and the model scores 90% accuracy. Roughly how uncertain is that number (one standard error)?', NULL, NULL, 'About +/- 3 percentage points', 'Standard error of a proportion is sqrt(p(1-p)/n).', 'sqrt(0.9 x 0.1 / 100) = 0.03. Two models 2 points apart on 100 test examples are not reliably different.', NULL, NULL, 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'About +/- 0.1 points', 0), (@q, 'B', 'Zero: accuracy is exact', 0), (@q, 'C', 'About +/- 3 percentage points', 1), (@q, 'D', 'About +/- 30 points', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ratios'), 3, 'code_output', 'What does this print?', 'import math\np, n = 0.9, 1000\nse = math.sqrt(p * (1 - p) / n)\nprint(round(se * 100, 1))', 'python', '0.9', 'Ten times more test rows shrinks the error by sqrt(10), not by 10.', 'sqrt(0.09/1000) = 0.0095, about 0.9 points. Going from 100 to 1000 test rows cut the error from 3.0 to about 0.9.', NULL, NULL, 17);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.9', 1), (@q, 'B', '3.0', 0), (@q, 'C', '9.0', 0), (@q, 'D', '0.3', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ratios'), 2, 'true_false', 'With a very small dataset (say 150 rows), a single 80/20 split gives a reliable estimate of model quality.', NULL, NULL, 'False', 'How many rows land in that 20%?', 'Only 30 test rows: the score swings a lot depending on which rows land there. Use k-fold cross-validation instead.', NULL, NULL, 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tts'), 1, 'mcq', 'What does random_state=42 do in train_test_split?', NULL, NULL, 'Fixes the shuffle so you get the same split every run', 'Think of it as a seed.', 'random_state seeds the shuffle. Same seed, same data, same split: results are reproducible.', NULL, 'Like pinning a dependency version so every build is the same.', 19);
