INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tts'), 1, 'mcq', 'What does stratify=y do in train_test_split?', NULL, NULL, 'Keeps the class proportions of y the same in train and test', 'Strata = layers. Each class is a layer.', 'Stratifying samples each class separately, so a 10% minority class is about 10% of both train and test. It does not rebalance.', NULL, NULL, 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Balances the classes to 50/50', 0), (@q, 'B', 'Removes rare classes', 0), (@q, 'C', 'Keeps the class proportions of y the same in train and test', 1), (@q, 'D', 'Sorts the rows by y', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tts'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.model_selection import train_test_split\ny = np.array([0] * 90 + [1] * 10)\nX = np.arange(100).reshape(-1, 1)\n_, _, _, y_te = train_test_split(X, y, test_size=0.2, stratify=y, random_state=0)\nprint(len(y_te), int(y_te.sum()))', 'python', '20 2', '10% of the rows are class 1. What is 10% of the test set?', 'Stratified: the test set keeps the 10% ratio, so 2 of its 20 rows are class 1.', NULL, NULL, 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '20 10', 0), (@q, 'B', '20 0', 0), (@q, 'C', '20 2', 1), (@q, 'D', '10 2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tts'), 2, 'true_false', 'stratify=y rebalances an imbalanced dataset so both classes are 50/50 in training.', NULL, NULL, 'False', 'Stratify copies proportions; it does not change them.', 'Stratify preserves the original ratio in each split. Rebalancing is a separate step (class weights, resampling) done on training data only.', NULL, NULL, 24);
