INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'preprocessing'), 1, 'code_output', 'What does this print?', 'text = "The Cat SAT on the Mat"\nprint(text.lower().split())', 'python', '[''the'', ''cat'', ''sat'', ''on'', ''the'', ''mat'']', 'lower() first, then split() on whitespace.', 'lower() turns every letter to lowercase, split() cuts on spaces. Nothing is removed, so both ''the''s stay.', NULL, NULL, 5);
