INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'granularity'), 1, 'code_output', 'What does this print?', 'vocab = {"i": 0, "like": 1, "cats": 2, "<unk>": 3}\nids = [vocab.get(w, vocab["<unk>"]) for w in "i like dogs".split()]\nprint(ids)', 'python', '[0, 1, 3]', 'dict.get(key, default) returns the default when the key is missing.', '''dogs'' is not in the word vocabulary, so it falls back to <unk> (id 3). A word-level tokenizer loses every unseen word this way.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 1]', 0), (@q, 'B', 'KeyError', 0), (@q, 'C', '[0, 1, 2]', 0), (@q, 'D', '[0, 1, 3]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'granularity'), 1, 'mcq', 'Which tokenisation gives the smallest vocabulary but the longest sequences?', NULL, NULL, 'Character-level', 'How many distinct letters are there versus distinct words?', 'A character vocabulary is tiny (around 100 symbols for English), but every word becomes many tokens, so sequences are long and attention is costly.', NULL, NULL, 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Character-level', 1), (@q, 'B', 'Sub-word (BPE)', 0), (@q, 'C', 'Word-level', 0), (@q, 'D', 'Sentence-level', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'granularity'), 1, 'mcq', 'What is the main weakness of word-level tokenisation?', NULL, NULL, 'New, rare or misspelled words become <unk> and their meaning is lost', 'What happens to ''doomscrollify'' or a typo like ''helo''?', 'A word vocabulary is a fixed list. Anything outside it maps to the unknown token, and the vocabulary for real text runs into millions of word forms.', NULL, NULL, 17);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It needs a GPU to run', 0), (@q, 'B', 'New, rare or misspelled words become <unk> and their meaning is lost', 1), (@q, 'C', 'Sequences become extremely long', 0), (@q, 'D', 'It cannot handle spaces', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'granularity'), 2, 'mcq', 'Why is sub-word tokenisation the default for LLMs?', NULL, NULL, 'Common words stay whole, rare words split into known pieces, so the vocabulary stays fixed and nothing is unknown', 'It is a middle ground between two extremes.', 'Sub-words combine the short sequences of word-level with the open vocabulary of character-level: ''tokenization'' might become ''token'' + ''ization''.', ' word-level : [tokenization]          1 token, OOV risk\n sub-word   : [token][ization]        2 tokens, no OOV\n char-level : [t][o][k][e][n]...      12 tokens', NULL, 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It produces the shortest possible sequences for every language', 0), (@q, 'B', 'It understands grammar rules', 0), (@q, 'C', 'Common words stay whole, rare words split into known pieces, so the vocabulary stays fixed and nothing is unknown', 1), (@q, 'D', 'It removes the need for an embedding matrix', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'granularity'), 2, 'true_false', 'A tokenizer is like the lexer in a compiler: it turns a raw string into a stream of tokens from a fixed vocabulary before the ''real'' work starts.', NULL, NULL, 'True', 'Source code -> tokens -> parser. Text -> tokens -> model.', 'Like a lexer, the tokenizer is fixed, deterministic and runs before the model. The model never sees raw characters, only token IDs.', NULL, 'tokenizer = lexer; vocabulary = the set of token kinds; token ID = the token''s enum value.', 19);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'granularity'), 3, 'mcq', 'For a fixed context window of N tokens, why does character-level tokenisation hurt a transformer?', NULL, NULL, 'Each token carries less text, so less content fits in N tokens and attention cost grows with the longer sequence', 'Self-attention compares every token with every other token.', 'Roughly 4-5x more tokens than sub-words for English, and self-attention cost grows with the square of the sequence length. You fit less text and pay more compute for it.', NULL, NULL, 20);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Characters cannot be embedded', 0), (@q, 'B', 'Attention only works on whole words', 0), (@q, 'C', 'Each token carries less text, so less content fits in N tokens and attention cost grows with the longer sequence', 1), (@q, 'D', 'Characters always produce <unk>', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 1, 'mcq', 'In one sentence, what does BPE training do?', NULL, NULL, 'Starts from single characters and repeatedly merges the most frequent adjacent pair into a new token', 'Count pairs, merge the winner, repeat.', 'BPE learns an ordered list of merges. Each merge adds one token to the vocabulary, until the target vocabulary size is reached.', NULL, NULL, 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Picks the most frequent whole words and drops the rest', 0), (@q, 'B', 'Learns token boundaries with gradient descent inside the LLM', 0), (@q, 'C', 'Starts from single characters and repeatedly merges the most frequent adjacent pair into a new token', 1), (@q, 'D', 'Splits words at random points and keeps the best splits', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 1, 'fill_blank', 'BPE stands for Byte-____ Encoding.', NULL, NULL, 'Pair', 'The algorithm merges two symbols at a time.', 'Byte-Pair Encoding: originally a compression trick that replaced the most frequent byte pair with a new symbol.', NULL, NULL, 22);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 2, 'code_output', 'What does this print?', 'def merge(word, pair):\n    out, i = [], 0\n    while i < len(word):\n        if i < len(word) - 1 and (word[i], word[i + 1]) == pair:\n            out.append(word[i] + word[i + 1]); i += 2\n        else:\n            out.append(word[i]); i += 1\n    return out\n\nprint(merge(list("newest"), ("e", "s")))', 'python', '[''n'', ''e'', ''w'', ''es'', ''t'']', 'Only the pair ''e'' followed by ''s'' is merged; the first ''e'' is followed by ''w''.', 'The merge only fires where the exact adjacent pair (e, s) appears, which is once in ''newest''.', NULL, NULL, 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''n'', ''e'', ''w'', ''es'', ''t'']', 1), (@q, 'B', '[''n'', ''es'', ''w'', ''es'', ''t'']', 0), (@q, 'C', '[''new'', ''est'']', 0), (@q, 'D', '[''n'', ''e'', ''w'', ''e'', ''s'', ''t'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 2, 'code_output', 'What does this print?', 'from collections import Counter\ncorpus = {("l","o","w"): 5, ("l","o","w","e","r"): 2,\n          ("n","e","w","e","s","t"): 6, ("w","i","d","e","s","t"): 3}\npairs = Counter()\nfor word, freq in corpus.items():\n    for a, b in zip(word, word[1:]):\n        pairs[a, b] += freq\nprint(pairs.most_common(1))', 'python', '[((''e'', ''s''), 9)]', 'Each pair is weighted by how often its word appears. ''newest'' x6 and ''widest'' x3 share a pair.', '(e,s) appears in newest (6) and widest (3) = 9; (s,t) also scores 9 but was counted later, and Counter breaks ties by insertion order. (w,e) is 6+2 = 8, (l,o) is 5+2 = 7.', ' word      freq   pairs\n l o w      5     lo ow\n l o w e r  2     lo ow we er\n n e w e s t 6    ne ew we es st\n w i d e s t 3    wi id de es st', NULL, 24);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[((''l'', ''o''), 7)]', 0), (@q, 'B', '[((''e'', ''s''), 9)]', 1), (@q, 'C', '[((''w'', ''e''), 8)]', 0), (@q, 'D', '[((''e'', ''s''), 2)]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 2, 'fill_blank', 'A BPE tokenizer starts with 100 base characters and learns 900 merges. Its vocabulary size (ignoring special tokens) is ____.', NULL, NULL, '1000', 'Each merge creates exactly one new token.', 'Vocabulary = base symbols + one new symbol per merge = 100 + 900. ''Vocabulary size'' is the knob you set; it decides how many merges to learn.', NULL, NULL, 25);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 2, 'true_false', 'In BPE, a merged token can itself be merged again later, e.g. ''e''+''s'' -> ''es'', then ''es''+''t'' -> ''est''.', NULL, NULL, 'True', 'Merges work on the current symbols, not only on single characters.', 'After a merge, the new symbol is just another symbol in the corpus, so later merges can build longer and longer pieces.', NULL, NULL, 26);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 3, 'code_output', 'What does this print?', 'def encode(word, merges):\n    toks = list(word)\n    for a, b in merges:\n        i = 0\n        while i < len(toks) - 1:\n            if toks[i] == a and toks[i + 1] == b:\n                toks[i:i + 2] = [a + b]\n            else:\n                i += 1\n    return toks\n\nprint(encode("lowest", [("e", "s"), ("es", "t"), ("l", "o")]))', 'python', '[''lo'', ''w'', ''est'']', 'Apply the learned merges one by one, in the order they were learned.', 'e+s -> es, then es+t -> est, then l+o -> lo. No merge ''lo''+''w'' was learned, so ''w'' stays alone even though ''low'' looks like a word.', NULL, NULL, 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''lowest'']', 0), (@q, 'B', '[''low'', ''est'']', 0), (@q, 'C', '[''lo'', ''w'', ''est'']', 1), (@q, 'D', '[''l'', ''o'', ''w'', ''est'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 3, 'code_output', 'What does this print?', 'def merge(word, pair):\n    out, i = [], 0\n    while i < len(word):\n        if i < len(word) - 1 and (word[i], word[i + 1]) == pair:\n            out.append(word[i] + word[i + 1]); i += 2\n        else:\n            out.append(word[i]); i += 1\n    return out\n\nprint(merge(list("aaa"), ("a", "a")))', 'python', '[''aa'', ''a'']', 'The scan goes left to right and jumps past a pair once it merges it.', 'Merges do not overlap: the first two a''s become ''aa'', the scan jumps to index 2, and the last ''a'' has no partner.', NULL, NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''a'', ''aa'']', 0), (@q, 'B', '[''aa'', ''aa'']', 0), (@q, 'C', '[''aaa'']', 0), (@q, 'D', '[''aa'', ''a'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 3, 'mcq', 'Why does a BPE tokenizer store its merges as an ORDERED list, not just a set of tokens?', NULL, NULL, 'Encoding new text replays the merges in learned order; a different order can give a different split', 'Try merging ''l''+''o'' before or after ''o''+''w'' on the word ''low''.', 'With merges [lo, ow] the word ''low'' becomes [lo, w]; with [ow, lo] it becomes [l, ow]. Tokenizers ship a merges file so encoding is reproducible.', NULL, NULL, 29);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The order decides each token''s embedding size', 0), (@q, 'B', 'Encoding new text replays the merges in learned order; a different order can give a different split', 1), (@q, 'C', 'Sets cannot hold strings', 0), (@q, 'D', 'The order is only kept for documentation', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 4, 'code_output', 'What does this print?', 'def encode(word, merges):\n    toks = list(word)\n    for a, b in merges:\n        i = 0\n        while i < len(toks) - 1:\n            if toks[i] == a and toks[i + 1] == b:\n                toks[i:i + 2] = [a + b]\n            else:\n                i += 1\n    return toks\n\nprint(encode("low", [("l", "o"), ("o", "w"), ("lo", "w")]))', 'python', '[''low'']', 'After (l, o) fires, can (o, w) still fire? Then look at the third merge.', 'l+o -> lo consumes the ''o'', so (o, w) never matches; then lo+w -> low. The (o, w) merge was learned from other words but loses here because of rank order.', NULL, NULL, 30);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''low'']', 1), (@q, 'B', '[''l'', ''o'', ''w'']', 0), (@q, 'C', '[''l'', ''ow'']', 0), (@q, 'D', '[''lo'', ''w'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 3, 'mcq', 'A BPE tokenizer is trained on English web text only. Which statement about encoding text from a new domain (say, chemistry names) is true?', NULL, NULL, 'It still encodes everything, but rare domain words split into many short pieces', 'Merges are frozen after training; the base symbols are still there.', 'Any string can fall back to the base symbols, so nothing is unknown; it just costs more tokens. That is why domain-specific models sometimes train or extend their own tokenizer.', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It refuses to encode text outside its training domain', 0), (@q, 'B', 'It still encodes everything, but rare domain words split into many short pieces', 1), (@q, 'C', 'The tokenizer learns new merges automatically at inference time', 0), (@q, 'D', 'Unknown domain words become <unk> tokens', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 3, 'true_false', 'The BPE tokenizer is trained jointly with the LLM by backpropagation, so its merges change during model training.', NULL, NULL, 'False', 'Which step happens first, and is it differentiable?', 'The tokenizer is trained once, separately and before the model, with simple counting. Its merges are frozen; the model learns embeddings for whatever tokens it is given.', NULL, NULL, 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'bpe'), 4, 'mcq', 'BPE training counts pairs only INSIDE words (after a pre-tokenisation split on spaces/punctuation). What would go wrong without that split?', NULL, NULL, 'Merges would cross word boundaries, creating tokens like ''e t'' or ''of the'' and wasting vocabulary on accidental phrases', 'Very frequent pairs like ''the'' + '' '' + ''cat'' would compete with real sub-words.', 'Pre-tokenisation (a regex split) keeps merges within word-like chunks, so the vocabulary is spent on reusable pieces rather than popular word pairs. GPT-2 does this with a regex; SentencePiece instead treats the space as a symbol.', NULL, NULL, 33);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Training would be impossible because spaces have no byte value', 0), (@q, 'B', 'The vocabulary would contain only single characters', 0), (@q, 'C', 'Merges would cross word boundaries, creating tokens like ''e t'' or ''of the'' and wasting vocabulary on accidental phrases', 1), (@q, 'D', 'Nothing; pre-tokenisation is only for speed', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'wordpiece-unigram'), 1, 'mcq', 'In BERT''s WordPiece tokens, what does the ''##'' in ''##ing'' mean?', NULL, NULL, 'The piece continues the previous token (it is not the start of a word)', 'Compare ''playing'' -> [''play'', ''##ing''].', '''##'' marks a word-internal piece, so the tokenizer knows to glue it to the previous piece when decoding.', NULL, NULL, 34);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The token is a hashtag', 0), (@q, 'B', 'The token is a number', 0), (@q, 'C', 'The token is a padding token', 0), (@q, 'D', 'The piece continues the previous token (it is not the start of a word)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'wordpiece-unigram'), 3, 'code_output', 'What does this print?', 'vocab = {"un", "##aff", "##able", "##a", "##ff", "u", "##n"}\n\ndef wordpiece(word):\n    out, start = [], 0\n    while start < len(word):\n        end = len(word)\n        while end > start:\n            piece = word[start:end] if start == 0 else "##" + word[start:end]\n            if piece in vocab:\n                break\n            end -= 1\n        else:\n            return ["[UNK]"]\n        out.append(piece); start = end\n    return out\nprint(wordpiece("unaffable"))', 'python', '[''un'', ''##aff'', ''##able'']', 'At each position it tries the LONGEST piece in the vocabulary first.', 'WordPiece encoding is greedy longest-match-first: ''un'' beats ''u'', then ''##aff'' beats ''##a'', then ''##able''.', NULL, NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''un'', ''##a'', ''##ff'', ''##able'']', 0), (@q, 'B', '[''u'', ''##n'', ''##a'', ''##ff'', ''##able'']', 0), (@q, 'C', '[''[UNK]'']', 0), (@q, 'D', '[''un'', ''##aff'', ''##able'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'wordpiece-unigram'), 4, 'code_output', 'What does this print?', 'vocab = {"un", "##aff", "##able", "##a", "##ff", "u", "##n"}\n\ndef wordpiece(word):\n    out, start = [], 0\n    while start < len(word):\n        end = len(word)\n        while end > start:\n            piece = word[start:end] if start == 0 else "##" + word[start:end]\n            if piece in vocab:\n                break\n            end -= 1\n        else:\n            return ["[UNK]"]\n        out.append(piece); start = end\n    return out\nprint(wordpiece("unafx"))', 'python', '[''[UNK]'']', 'What does the function return as soon as one position has no match?', 'BERT-style WordPiece gives up on the WHOLE word if any part cannot be matched, so ''unafx'' becomes a single [UNK]. Byte-level BPE never has this problem.', NULL, NULL, 36);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''un'', ''##a'', ''[UNK]'']', 0), (@q, 'B', '[''un'', ''##a'', ''##f'', ''##x'']', 0), (@q, 'C', '[''[UNK]'']', 1), (@q, 'D', '[''un'', ''##afx'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'wordpiece-unigram'), 3, 'mcq', 'BPE merges the most FREQUENT pair. What does WordPiece training pick instead?', NULL, NULL, 'The pair with the highest score freq(ab) / (freq(a) * freq(b)), i.e. pairs that appear together more than chance', 'It is a likelihood-style score that divides by how common each part is.', 'Dividing by the parts'' frequencies prefers pairs whose parts are mostly seen together, not pairs that are frequent only because their parts are everywhere.', NULL, NULL, 37);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A random pair weighted by frequency', 0), (@q, 'B', 'The pair that makes the longest token', 0), (@q, 'C', 'The rarest pair', 0), (@q, 'D', 'The pair with the highest score freq(ab) / (freq(a) * freq(b)), i.e. pairs that appear together more than chance', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'wordpiece-unigram'), 3, 'code_output', 'What does this print?', 'pairs = {"t+h": (40, 400, 300), "q+u": (5, 6, 10)}   # (pair, a, b) counts\nscore = {p: round(ab / (a * b), 4) for p, (ab, a, b) in pairs.items()}\nprint(score, max(score, key=score.get))', 'python', '{''t+h'': 0.0003, ''q+u'': 0.0833} q+u', 'BPE would pick the pair with count 40. WordPiece divides by the part counts.', '''q'' is almost always followed by ''u'', so the WordPiece score favours q+u even though t+h is 8x more frequent.', NULL, NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''t+h'': 0.0003, ''q+u'': 0.0833} q+u', 1), (@q, 'B', '{''t+h'': 0.0003, ''q+u'': 0.0833} t+h', 0), (@q, 'C', '{''t+h'': 0.1, ''q+u'': 0.5} q+u', 0), (@q, 'D', '{''t+h'': 40, ''q+u'': 5} t+h', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'wordpiece-unigram'), 2, 'mcq', 'In SentencePiece output like [''▁New'', ''▁Yor'', ''k''], what does the ''▁'' symbol mean?', NULL, NULL, 'A space came before this piece; SentencePiece treats the space as a normal symbol', 'SentencePiece does not split on spaces first.', 'SentencePiece replaces spaces with ''▁'' (U+2581) and tokenises the raw stream, so decoding is lossless: join the pieces and turn ''▁'' back into spaces.', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A capital letter follows', 0), (@q, 'B', 'A padding token', 0), (@q, 'C', 'The start of the whole document', 0), (@q, 'D', 'A space came before this piece; SentencePiece treats the space as a normal symbol', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'wordpiece-unigram'), 2, 'code_output', 'What does this print?', 'pieces = ["▁New", "▁Yor", "k", "▁is", "▁big"]\nprint("".join(pieces).replace("▁", " ").strip())', 'python', 'New York is big', 'Join first, then turn the marker back into a space.', 'Because the space lives inside the tokens, decoding is just concatenation. This is why SentencePiece works for languages without spaces between words, such as Japanese.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NewYorkisbig', 0), (@q, 'B', 'New York is big', 1), (@q, 'C', 'New Yor k is big', 0), (@q, 'D', '▁New▁York▁is▁big', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'wordpiece-unigram'), 3, 'mcq', 'How does a Unigram tokenizer (used via SentencePiece in T5 and ALBERT) build its vocabulary?', NULL, NULL, 'Starts with a big candidate vocabulary and repeatedly removes the pieces whose loss hurts the corpus likelihood least', 'It goes in the opposite direction to BPE.', 'BPE grows bottom-up by merging; Unigram prunes top-down. It keeps a probability for every piece and picks segmentations by likelihood.', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Copies the vocabulary of BERT', 0), (@q, 'B', 'Starts from characters and merges the most frequent pair', 0), (@q, 'C', 'Uses only whole words seen more than once', 0), (@q, 'D', 'Starts with a big candidate vocabulary and repeatedly removes the pieces whose loss hurts the corpus likelihood least', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'wordpiece-unigram'), 3, 'code_output', 'What does this print?', 'import math\np = {"hug": 0.1, "s": 0.05, "hu": 0.02, "gs": 0.01, "h": 0.03, "ug": 0.04}\nsegs = [["hu", "gs"], ["h", "ug", "s"], ["hug", "s"]]\nbest = max(segs, key=lambda s: math.prod(p[t] for t in s))\nprint(best)', 'python', '[''hug'', ''s'']', 'Multiply the piece probabilities for each split; fewer pieces usually means a bigger product.', 'hug*s = 0.005, hu*gs = 0.0002, h*ug*s = 0.00006. A Unigram tokenizer picks the most likely segmentation (found with the Viterbi algorithm on real input).', NULL, NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''h'', ''ug'', ''s'']', 0), (@q, 'B', '[''hug'', ''s'']', 1), (@q, 'C', '[''hu'', ''gs'']', 0), (@q, 'D', '[''hugs'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'wordpiece-unigram'), 3, 'true_false', 'SentencePiece is a library and a way of handling raw text (spaces as symbols); it can train either a BPE or a Unigram model.', NULL, NULL, 'True', 'Check the --model_type option.', 'SentencePiece is often confused with Unigram. It supports both: Llama 1 and 2 used SentencePiece BPE, while T5 used SentencePiece Unigram.', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'wordpiece-unigram'), 4, 'mcq', 'Unigram tokenizers support ''subword regularisation''. What is it?', NULL, NULL, 'During training, sample different valid segmentations of the same word so the model becomes robust to how text is split', 'A Unigram model gives a probability to every possible split, not just the best one.', 'Because Unigram scores all segmentations, it can sample them, a kind of data augmentation. BPE-dropout is the BPE equivalent (randomly skipping merges).', NULL, NULL, 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Adding an L2 penalty to token embeddings', 0), (@q, 'B', 'Removing rare sub-words from the vocabulary at inference time', 0), (@q, 'C', 'Forcing every word to be one token', 0), (@q, 'D', 'During training, sample different valid segmentations of the same word so the model becomes robust to how text is split', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'byte-level'), 1, 'code_output', 'What does this print?', 's = "héllo"\nprint(len(s), len(s.encode("utf-8")))', 'python', '5 6', '''é'' is one character but how many UTF-8 bytes?', 'Python len() counts characters (code points). In UTF-8, ''é'' takes 2 bytes, so the byte length is 6.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '6 5', 0), (@q, 'B', '6 6', 0), (@q, 'C', '5 5', 0), (@q, 'D', '5 6', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'byte-level'), 2, 'fill_blank', 'Byte-level BPE (GPT-2 and later) starts its vocabulary from all ____ possible byte values.', NULL, NULL, '256', 'Any text in any language is a sequence of these.', 'Starting from 256 bytes means every possible string can be encoded, so there is never an unknown token. Merges are then learned on top.', NULL, NULL, 46);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'byte-level'), 3, 'code_output', 'What does this print?', 'print(len("👍"), len("👍".encode("utf-8")), len("नमस्ते"), len("नमस्ते".encode("utf-8")))', 'python', '1 4 6 18', 'Emoji take 4 UTF-8 bytes; Devanagari characters take 3 each.', 'Scripts outside ASCII use 2-4 bytes per code point. If a byte-level tokenizer has few merges for that script, the text costs many more tokens.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 1 6 6', 0), (@q, 'B', '1 4 6 18', 1), (@q, 'C', '1 4 2 6', 0), (@q, 'D', '2 4 6 12', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'byte-level'), 2, 'true_false', 'A GPT-2 style byte-level BPE tokenizer needs an <unk> token for characters it never saw in training.', NULL, NULL, 'False', 'What is the worst case for an unseen character?', 'Any character can fall back to its raw UTF-8 bytes, and all 256 bytes are in the vocabulary. GPT-2 has no unknown token.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'byte-level'), 3, 'mcq', 'In GPT-2''s vocabulary file you see tokens like ''Ġthe''. What is ''Ġ''?', NULL, NULL, 'A printable stand-in for the space byte, so '' the'' (with leading space) is stored as ''Ġthe''', 'GPT-2 maps raw bytes to visible characters so the vocab file is readable.', 'GPT-2 maps each byte to a printable Unicode character; the space byte becomes ''Ġ''. It plays the same role as SentencePiece''s ''▁''.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The start-of-text token', 0), (@q, 'B', 'A Greek letter used in many English words', 0), (@q, 'C', 'A printable stand-in for the space byte, so '' the'' (with leading space) is stored as ''Ġthe''', 1), (@q, 'D', 'A marker for capital letters', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'byte-level'), 4, 'code_output', 'What does this print?', 'b = "é".encode("utf-8")\nprint(list(b))\nprint(b[:1].decode("utf-8", errors="replace"))', 'python', '[195, 169]\n�', 'Half of a two-byte character is not a valid character on its own.', 'A byte-level token can stop in the middle of a character. Decoding that token alone gives the replacement character U+FFFD, which is why streaming LLM output must buffer partial bytes.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[195, 169]\n�', 1), (@q, 'B', 'UnicodeDecodeError', 0), (@q, 'C', '[195, 169]\né', 0), (@q, 'D', '[233]\né', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'vocab-size'), 1, 'mcq', 'What happens to typical sequence length when you make a BPE vocabulary bigger (more merges)?', NULL, NULL, 'Sequences get shorter, because more text fits into each token', 'More merges = longer pieces available.', 'A larger vocabulary has longer tokens, so the same text needs fewer of them. The cost is a bigger embedding matrix and more rarely-seen tokens.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Sequences get shorter, because more text fits into each token', 1), (@q, 'B', 'Sequences get longer', 0), (@q, 'C', 'Sequence length does not change', 0), (@q, 'D', 'Sequences become exactly one token per word', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'vocab-size'), 2, 'mcq', 'Roughly what vocabulary sizes do modern LLM tokenizers use?', NULL, NULL, 'About 32,000 to 256,000 tokens', 'BERT ~30k, GPT-2 ~50k, Llama 3 ~128k.', 'BERT-base uses 30,522, GPT-2 50,257, GPT-4''s cl100k about 100k, Llama 3 about 128k, and some multilingual models about 256k.', NULL, NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'About 1,000 tokens', 0), (@q, 'B', 'About 10 million tokens', 0), (@q, 'C', 'About 32,000 to 256,000 tokens', 1), (@q, 'D', 'About 256 tokens', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'vocab-size'), 3, 'code_output', 'What does this print?', 'vocab, d_model, bytes_per = 256_000, 4096, 2   # bf16\nprint(round(vocab * d_model * bytes_per / 1e9, 2), "GB")', 'python', '2.1 GB', 'Rows x columns x bytes per number.', '256,000 x 4096 x 2 bytes is about 2.1 GB just for the input embedding table, and the same again for an untied output layer. Vocabulary size is not free.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1.05 GB', 0), (@q, 'B', '4.19 GB', 0), (@q, 'C', '2.1 GB', 1), (@q, 'D', '0.26 GB', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'vocab-size'), 3, 'mcq', 'Which is NOT a cost of a very large vocabulary?', NULL, NULL, 'Longer sequences for the same text', 'Three of these get worse as the vocabulary grows; one gets better.', 'A bigger vocabulary SHORTENS sequences. The costs are memory, softmax compute over every token, and under-trained rare tokens.', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A slower final softmax over all tokens at every generation step', 0), (@q, 'B', 'Many rare tokens that appear too few times to learn good embeddings', 0), (@q, 'C', 'A larger embedding matrix and output softmax', 0), (@q, 'D', 'Longer sequences for the same text', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'vocab-size'), 4, 'mcq', 'Why did tokenizers grow from ~32k (Llama 2) to ~128k (Llama 3) tokens?', NULL, NULL, 'Better compression of text, especially code and non-English languages, so more fits in the context and generation is faster', 'Fewer tokens per sentence means what for cost and context?', 'More tokens per merge budget means fewer tokens per document: cheaper inference and more effective context. The embedding table grows, but in a large model that is a small share of the parameters.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Better compression of text, especially code and non-English languages, so more fits in the context and generation is faster', 1), (@q, 'B', 'Larger vocabularies remove the need for attention', 0), (@q, 'C', 'Small vocabularies cannot encode emoji', 0), (@q, 'D', 'GPUs require the vocabulary to be a power of 10', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'vocab-size'), 4, 'true_false', 'Model code often rounds the embedding table up (e.g. to a multiple of 64), so the embedding matrix can have MORE rows than the tokenizer has tokens.', NULL, NULL, 'True', 'GPU matrix multiplies are fastest on nicely aligned shapes.', 'For example, a tokenizer with 50,257 tokens may have an embedding of 50,304 rows. The extra rows are never produced by the tokenizer, so `len(tokenizer)` and the embedding size can differ without a bug.', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'special-tokens'), 1, 'mcq', 'What is the job of an EOS (end-of-sequence) token?', NULL, NULL, 'It marks where a text ends, so the model can learn when to stop generating', 'How does a chatbot know it has finished its answer?', 'During training every document ends with EOS. At generation time, producing EOS is the model''s way of saying ''done'', and the loop stops.', NULL, NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It replaces unknown words', 0), (@q, 'B', 'It marks where a text ends, so the model can learn when to stop generating', 1), (@q, 'C', 'It marks a spelling error', 0), (@q, 'D', 'It is added between every word', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'special-tokens'), 1, 'fill_blank', 'BERT puts the special token ____ at the very start of every input; its final vector is used for classification.', NULL, NULL, '[CLS]', 'It is short for ''classification''.', '[CLS] goes first, [SEP] separates or ends segments: ''[CLS] sentence A [SEP] sentence B [SEP]''.', NULL, NULL, 58);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'special-tokens'), 1, 'mcq', 'Match the special token to its job: [PAD]', NULL, NULL, 'Fills shorter sequences so a batch has equal lengths', 'Think about stacking sequences of different lengths into one tensor.', '[PAD] is filler; the attention mask tells the model to ignore it. [UNK] = unknown, [SEP] = separator, [MASK] = the word to predict in masked language modelling.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Fills shorter sequences so a batch has equal lengths', 1), (@q, 'B', 'Hides a word the model must guess', 0), (@q, 'C', 'Marks an unknown word', 0), (@q, 'D', 'Separates two sentences', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'special-tokens'), 2, 'code_output', 'What does this print?', 'def bert_format(a, b):\n    return ["[CLS]"] + a.split() + ["[SEP]"] + b.split() + ["[SEP]"]\n\ntoks = bert_format("how are you", "fine thanks")\nprint(len(toks), toks.count("[SEP]"))', 'python', '8 2', 'Count the words, then add every special token.', '5 words + [CLS] + 2 x [SEP] = 8 tokens. Special tokens count towards the length limit too.', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '7 1', 0), (@q, 'B', '8 3', 0), (@q, 'C', '9 2', 0), (@q, 'D', '8 2', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'special-tokens'), 2, 'mcq', 'For a BERT sentence pair, what do ''token_type_ids'' (segment IDs) tell the model?', NULL, NULL, 'Which tokens belong to sentence A (0) and which to sentence B (1)', 'BERT was trained on ''is sentence B the next sentence after A?''.', 'Segment IDs add a learned ''A'' or ''B'' embedding to each token. Padding is the attention mask''s job, not the segment IDs''.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Each token''s part of speech', 0), (@q, 'B', 'Which tokens are special tokens', 0), (@q, 'C', 'Which tokens belong to sentence A (0) and which to sentence B (1)', 1), (@q, 'D', 'Which tokens are padding', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'special-tokens'), 3, 'true_false', 'If a user types the literal text ''<|endoftext|>'' into a chat app, a safe tokenizer setup encodes it as ordinary text, not as the real special token.', NULL, NULL, 'True', 'What could a user do if they could inject real control tokens?', 'Special tokens are control signals. Parsing them from user text lets users fake message boundaries or end sequences (like SQL injection). Libraries such as tiktoken refuse or escape them unless explicitly allowed.', NULL, 'Treat special tokens like SQL keywords: user input must be escaped, never parsed as control syntax.', 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'special-tokens'), 3, 'mcq', 'GPT-2 has no dedicated pad token. What is the common workaround, and its risk?', NULL, NULL, 'Set pad_token = eos_token; the risk is masking out the real EOS from the loss so the model never learns to stop', 'If PAD and EOS share one id, a rule like ''ignore every pad id'' hits both.', 'Reusing EOS as PAD is fine as long as the attention mask, not the token id, decides what is padding. Masking by id also hides the genuine EOS.', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Set pad_token = eos_token; the risk is masking out the real EOS from the loss so the model never learns to stop', 1), (@q, 'B', 'Pad with spaces; the risk is longer sequences', 0), (@q, 'C', 'Use token id 0; there is no risk', 0), (@q, 'D', 'Skip batching entirely', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'special-tokens'), 4, 'code_output', 'What does this print?', 'EOS = PAD = 2\nids = [5, 9, 7, EOS, PAD, PAD]\nlabels = [-100 if t == PAD else t for t in ids]\nprint(labels)', 'python', '[5, 9, 7, -100, -100, -100]', '-100 means ''ignore in the loss''. Which positions hold the value 2?', 'The real EOS has the same id as PAD, so it gets masked too. The model is never trained to emit EOS and rambles on at generation time. Build labels from the attention mask instead.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[5, 9, 7, -100, -100, -100]', 1), (@q, 'B', '[-100, -100, -100, 2, 2, 2]', 0), (@q, 'C', '[5, 9, 7, 2, 2, 2]', 0), (@q, 'D', '[5, 9, 7, 2, -100, -100]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ids-embedding'), 1, 'mcq', 'After tokenisation, what does the model actually receive?', NULL, NULL, 'A list of integer token IDs', 'Neural networks need numbers.', 'Each token is mapped to its index in the vocabulary. The model''s first layer turns each ID into a vector.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A list of words', 0), (@q, 'B', 'A list of integer token IDs', 1), (@q, 'C', 'An image of the text', 0), (@q, 'D', 'The raw string', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ids-embedding'), 1, 'code_output', 'What does this print?', 'import numpy as np\nE = np.arange(12).reshape(4, 3)   # 4 tokens, 3 dims\nids = np.array([2, 0, 2])\nprint(E[ids])', 'python', '[[6 7 8]\n [0 1 2]\n [6 7 8]]', 'Each ID picks one ROW of the table.', 'The embedding layer is just row indexing: ID 2 -> row 2 = [6 7 8], ID 0 -> row 0. The same token always gets the same row.', ' E (vocab x dim)     ids = [2, 0, 2]\n row0  [0 1 2]  <------ 0\n row1  [3 4 5]\n row2  [6 7 8]  <------ 2 (twice)\n row3  [9 10 11]', NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[6 7 8]\n [0 1 2]\n [6 7 8]]', 1), (@q, 'B', '[[2 0 2]]', 0), (@q, 'C', '[[0 1 2]\n [6 7 8]]', 0), (@q, 'D', '[6 7 8 0 1 2 6 7 8]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ids-embedding'), 2, 'code_output', 'What does this print?', 'import numpy as np\nE = np.zeros((50257, 768))\nids = np.zeros((4, 128), dtype=int)   # batch of 4, 128 tokens each\nprint(E[ids].shape)', 'python', '(4, 128, 768)', 'Indexing with a (4, 128) array of ids replaces each id with a 768-vector.', 'Lookup adds a last axis of size d_model: (batch, seq_len) -> (batch, seq_len, d_model). This is the tensor that enters the first transformer block.', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(512, 768)', 0), (@q, 'B', '(4, 128, 768)', 1), (@q, 'C', '(50257, 768)', 0), (@q, 'D', '(4, 128)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ids-embedding'), 2, 'true_false', 'A token ID''s numeric value carries meaning: token 500 is ''closer'' in meaning to token 501 than to token 30000.', NULL, NULL, 'False', 'Where do the IDs come from?', 'IDs are arbitrary indexes, like primary keys in a database table. All meaning lives in the learned embedding vectors.', NULL, 'A token ID is a primary key; the embedding row is the record it points to.', 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ids-embedding'), 3, 'code_output', 'What does this print?', 'import numpy as np\nE = np.arange(12).reshape(4, 3)\nonehot = np.array([0, 0, 1, 0])\nprint(np.array_equal(onehot @ E, E[2]))', 'python', 'True', 'A one-hot vector times a matrix selects one row.', 'An embedding lookup is mathematically a one-hot vector times the embedding matrix. Frameworks use indexing because it skips multiplying by thousands of zeros.', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False', 0), (@q, 'B', '[6 7 8]', 0), (@q, 'C', 'ValueError', 0), (@q, 'D', 'True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ids-embedding'), 3, 'code_output', 'What does this print?', 'import numpy as np\nE = np.arange(12).reshape(4, 3)   # vocab of 4\nids = np.array([1, 4])\nprint(E[ids])', 'python', 'IndexError', 'Valid row indexes for 4 rows are 0..3.', 'An ID outside the table raises IndexError. This is exactly what happens when you add tokens to a tokenizer but forget to resize the model''s embedding matrix (on GPU it shows up as a cryptic device-side assert).', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[3 4 5]\n [0 0 0]]', 0), (@q, 'B', '[[ 3  4  5]\n [12 13 14]]', 0), (@q, 'C', 'IndexError', 1), (@q, 'D', '[[3 4 5]]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ids-embedding'), 3, 'code_output', 'What does this print?', 'vocab, d = 50257, 768\nprint(vocab * d)', 'python', '38597376', 'Parameters = rows x columns.', 'GPT-2 small has about 38.6M of its 124M parameters in the token embedding table. GPT-2 reuses the same matrix for the output layer (weight tying), saving another 38.6M.', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '768', 0), (@q, 'B', '38597376', 1), (@q, 'C', '3859737', 0), (@q, 'D', '50257768', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ids-embedding'), 4, 'mcq', 'What is ''weight tying'' between the input embedding and the output layer of a language model?', NULL, NULL, 'Using the same vocab x d matrix to embed input tokens and to score every token at the output', 'The output layer maps d -> vocab; the embedding maps vocab -> d.', 'The output projection is the transpose of the embedding matrix. Tying saves parameters and links the ''meaning of token t'' on the input and output sides.', NULL, NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Freezing the embedding matrix during training', 0), (@q, 'B', 'Rounding the weights to integers', 0), (@q, 'C', 'Using the same vocab x d matrix to embed input tokens and to score every token at the output', 1), (@q, 'D', 'Sharing embeddings between two different tokenizers', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ids-embedding'), 4, 'mcq', 'You add 5 new special tokens to a pretrained tokenizer and call model.resize_token_embeddings(len(tokenizer)). What are the new tokens'' embeddings before fine-tuning?', NULL, NULL, 'Freshly initialised vectors the model has never learned; they mean nothing until you train on data that uses them', 'Resizing adds rows; where do their values come from?', 'New rows start random (some libraries now default to the mean of the old rows, which is a better start but still carries no specific meaning). Without fine-tuning on examples, the model cannot use them.', NULL, NULL, 73);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Freshly initialised vectors the model has never learned; they mean nothing until you train on data that uses them', 1), (@q, 'B', 'The average of all existing embeddings, guaranteed to be meaningful', 0), (@q, 'C', 'Automatically computed from the token''s spelling', 0), (@q, 'D', 'Copies of the [UNK] embedding', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'padding-masks'), 1, 'mcq', 'Why do we pad sequences in a batch?', NULL, NULL, 'A batch is one rectangular tensor, so shorter sequences are filled up to the longest one', 'A NumPy array cannot have rows of different lengths.', 'Batching needs equal lengths; padding adds filler tokens and an attention mask marks them as ''ignore''.', NULL, NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The tokenizer requires every text to be exactly 512 tokens', 0), (@q, 'B', 'Padding makes the model more accurate', 0), (@q, 'C', 'Padding hides private data', 0), (@q, 'D', 'A batch is one rectangular tensor, so shorter sequences are filled up to the longest one', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'padding-masks'), 2, 'code_output', 'What does this print?', 'batch = [[5, 8, 2], [7, 2]]\nPAD = 0\nL = max(len(s) for s in batch)\nids = [s + [PAD] * (L - len(s)) for s in batch]\nmask = [[1] * len(s) + [0] * (L - len(s)) for s in batch]\nprint(ids, mask)', 'python', '[[5, 8, 2], [7, 2, 0]] [[1, 1, 1], [1, 1, 0]]', 'Right padding; the mask is 1 for real tokens.', 'The attention mask is 1 for real tokens and 0 for padding. It keeps padding from affecting the real tokens'' representations.', NULL, NULL, 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[5, 8, 2], [0, 7, 2]] [[1, 1, 1], [0, 1, 1]]', 0), (@q, 'B', '[[5, 8, 2], [7, 2, 0]] [[1, 1, 1], [1, 1, 0]]', 1), (@q, 'C', '[[5, 8, 2], [7, 2]] [[1, 1, 1], [1, 1]]', 0), (@q, 'D', '[[5, 8, 2], [7, 2, 0]] [[0, 0, 0], [0, 0, 1]]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'padding-masks'), 1, 'true_false', 'In the attention mask, 1 means ''this is a real token, attend to it'' and 0 means ''padding, ignore it''.', NULL, NULL, 'True', 'Hugging Face convention.', 'Real tokens get 1, padding gets 0. Inside attention, the 0 positions get a large negative score so softmax gives them about zero weight.', NULL, NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'padding-masks'), 2, 'code_output', 'What does this print?', 'ids = list(range(1, 11))           # 10 content tokens\nmax_len = 6\nkept = ids[:max_len - 2]            # leave room for [CLS] and [SEP]\nprint(["CLS"] + kept + ["SEP"])', 'python', '[''CLS'', 1, 2, 3, 4, ''SEP'']', 'max_len counts the special tokens too.', 'Truncation must leave space for special tokens: 6 - 2 = 4 content tokens. Truncation silently drops text, so check how much you lose.', NULL, NULL, 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 3, 4, 5, 6]', 0), (@q, 'B', '[''CLS'', 1, 2, 3, 4, 5, 6, ''SEP'']', 0), (@q, 'C', '[''CLS'', 1, 2, 3, 4, ''SEP'']', 1), (@q, 'D', '[''CLS'', 1, 2, 3, 4, 5, ''SEP'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'padding-masks'), 3, 'mcq', 'You batch prompts for a decoder-only LLM (like GPT) to generate continuations. Which padding side is correct and why?', NULL, NULL, 'Left padding, so every prompt''s last real token sits at the end and new tokens follow directly from it', 'The model generates the next token after the LAST position in the row.', 'With right padding the model would continue after pad tokens. Left padding puts the real text flush against the generation point. (For training or encoders, right padding is fine.)', ' right pad:  [Hi  there PAD PAD] -> next token after PAD (bad)\n left pad :  [PAD PAD Hi  there] -> next token after ''there''', NULL, 78);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'No padding; decoder models reject batches', 0), (@q, 'B', 'Left padding, so every prompt''s last real token sits at the end and new tokens follow directly from it', 1), (@q, 'C', 'Either side; it never matters for generation', 0), (@q, 'D', 'Right padding, because text is read left to right', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'padding-masks'), 3, 'code_output', 'What does this print?', 'batch = [[5, 8, 2], [7, 2]]\nPAD = 0\nL = max(len(s) for s in batch)\nids = [[PAD] * (L - len(s)) + s for s in batch]\nprint([row[-1] for row in ids])', 'python', '[2, 2]', 'With left padding, where does each row''s real text end?', 'Left padding keeps every row''s last element a real token, which is the position a decoder predicts from.', NULL, NULL, 79);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 2]', 0), (@q, 'B', '[5, 7]', 0), (@q, 'C', '[2, 2]', 1), (@q, 'D', '[2, 0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'padding-masks'), 3, 'mcq', 'Your training data has lengths from 20 to 2000 tokens. Padding every batch to the global max of 2000 wastes a lot of compute. What is the standard fix?', NULL, NULL, 'Dynamic padding (pad each batch to its own longest item), often with length-bucketing so similar lengths share a batch', 'Most of the compute in a padded batch goes to tokens that are ignored.', 'Pad per batch, not per dataset, and group similar lengths together. Some setups ''pack'' several short examples into one sequence instead, which needs care so examples do not attend to each other.', NULL, NULL, 80);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Truncate everything to 20 tokens', 0), (@q, 'B', 'Use a larger vocabulary', 0), (@q, 'C', 'Dynamic padding (pad each batch to its own longest item), often with length-bucketing so similar lengths share a batch', 1), (@q, 'D', 'Remove the attention mask', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'padding-masks'), 4, 'mcq', 'You mean-pool BERT token vectors to get a sentence vector but forget to use the attention mask. What goes wrong?', NULL, NULL, 'Padding vectors are averaged in, so the same sentence gets a different vector depending on how much padding its batch had', 'Are the hidden states at pad positions zero?', 'Pad positions still produce non-zero hidden states. Without masking, embeddings depend on the batch composition: a subtle, non-deterministic-looking bug.', NULL, NULL, 81);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Padding vectors are averaged in, so the same sentence gets a different vector depending on how much padding its batch had', 1), (@q, 'B', 'The model raises an error', 0), (@q, 'C', 'Only [CLS] is used', 0), (@q, 'D', 'Nothing; padding vectors are always exactly zero', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cost-quirks'), 1, 'code_output', 'What does this print?', 'words = 3000\ntokens = words / 0.75     # rule of thumb: 1 token ~ 0.75 English words\nprint(round(tokens))', 'python', '4000', 'Each token is smaller than a word, so tokens > words.', 'With about 0.75 words per token, 3000 words is roughly 4000 tokens. It is a rough estimate for English only; code and other languages differ.', NULL, NULL, 82);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4000', 1), (@q, 'B', '3000', 0), (@q, 'C', '3750', 0), (@q, 'D', '2250', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cost-quirks'), 1, 'true_false', 'A model''s context window (e.g. 128k tokens) counts both your prompt and the model''s reply.', NULL, NULL, 'True', 'The reply is generated into the same sequence.', 'Input + output share the window. A 127k-token prompt leaves only about 1k tokens for the answer.', NULL, NULL, 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cost-quirks'), 2, 'code_output', 'What does this print?', 'in_tok, out_tok = 1500, 500\nprice_in, price_out = 3.0, 15.0   # dollars per 1M tokens\ncost = (in_tok * price_in + out_tok * price_out) / 1e6\nprint(round(cost * 1000, 2))     # cost for 1000 requests', 'python', '12.0', 'Price input and output separately; output tokens are usually priced higher.', '1500 x 3 + 500 x 15 = 12,000 per million -> $0.012 per request -> $12 per 1000. Output tokens often dominate cost even when they are fewer.', NULL, NULL, 84);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '36.0', 0), (@q, 'B', '12.0', 1), (@q, 'C', '9.0', 0), (@q, 'D', '4.5', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cost-quirks'), 2, 'mcq', 'Why do LLMs often miscount letters, e.g. ''How many r''s are in strawberry?''', NULL, NULL, 'The model sees a few sub-word tokens like ''str'' + ''aw'' + ''berry'', not individual letters', 'What does the model actually receive as input?', 'Characters are hidden inside tokens. The model must have memorised each token''s spelling to count letters; asking it to spell the word first or to use code helps.', NULL, NULL, 85);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The model always rounds numbers down', 0), (@q, 'B', 'The model has no memory', 0), (@q, 'C', 'The word is not in the vocabulary', 0), (@q, 'D', 'The model sees a few sub-word tokens like ''str'' + ''aw'' + ''berry'', not individual letters', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cost-quirks'), 2, 'mcq', 'In GPT-style tokenizers, ''hello'' at the start of a text and '' hello'' in the middle of a sentence usually become...', NULL, NULL, 'Different tokens with different IDs, because the leading space is part of the token', 'Look again at ''Ġthe'' in GPT-2''s vocabulary.', 'Most words exist in two versions: with and without a leading space (and often capitalised versions too). A prompt that ends in a trailing space can therefore push the model towards odd continuations.', NULL, NULL, 86);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'An <unk> token', 0), (@q, 'B', 'The same token, since spaces are removed', 0), (@q, 'C', 'Two tokens each: a space and ''hello''', 0), (@q, 'D', 'Different tokens with different IDs, because the leading space is part of the token', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cost-quirks'), 2, 'true_false', 'The same sentence translated into Hindi or Tamil usually costs MORE tokens than in English with a typical LLM tokenizer.', NULL, NULL, 'True', 'Where did most of the tokenizer''s training text come from?', 'Merges are learned mostly from English-heavy data, so other scripts get fewer merges and fall back to short pieces or raw bytes. Users of those languages pay more and fit less into the context.', NULL, NULL, 87);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cost-quirks'), 3, 'code_output', 'What does this print?', 'import re\nprint(re.findall(r"\\d{1,3}", "1234567"))', 'python', '[''123'', ''456'', ''7'']', 'The regex groups up to three digits at a time, scanning left to right.', 'GPT-4''s cl100k tokenizer splits numbers into chunks of up to 3 digits from the left, so the chunks do not line up with place value (thousands, millions). That is one reason LLM arithmetic is fragile.', NULL, NULL, 88);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''1'', ''234'', ''567'']', 0), (@q, 'B', '[''123'', ''456'', ''7'']', 1), (@q, 'C', '[''1'', ''2'', ''3'', ''4'', ''5'', ''6'', ''7'']', 0), (@q, 'D', '[''1234567'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cost-quirks'), 3, 'code_output', 'What does this print?', 'import re\npattern = r" ?\\w+| ?[^\\w\\s]+"\nprint(re.findall(pattern, "Hello, world!"))', 'python', '[''Hello'', '','', '' world'', ''!'']', 'An optional space is glued to the FRONT of the next word.', 'A simplified GPT-2 pre-tokenisation regex: words carry their leading space ('' world''), punctuation is split off. BPE merges then run inside each chunk.', NULL, NULL, 89);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''Hello'', '' '', '','', ''world'', ''!'']', 0), (@q, 'B', '[''Hello,'', ''world!'']', 0), (@q, 'C', '[''Hello'', '', world'', ''!'']', 0), (@q, 'D', '[''Hello'', '','', '' world'', ''!'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cost-quirks'), 3, 'mcq', 'Why do some tokenizers (e.g. Llama 1/2) split every number into single digits?', NULL, NULL, 'So that every number is built from the same 10 digit tokens, making arithmetic patterns consistent', 'Compare ''1234'' as one random token versus ''1'' ''2'' ''3'' ''4''.', 'If numbers merge arbitrarily (''1234'' as one token, ''1235'' as two), the model sees inconsistent patterns. Digit-splitting costs more tokens but helps arithmetic.', NULL, NULL, 90);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'To save vocabulary space for emoji', 0), (@q, 'B', 'So that every number is built from the same 10 digit tokens, making arithmetic patterns consistent', 1), (@q, 'C', 'Because digits are not valid UTF-8', 0), (@q, 'D', 'To make numbers cost fewer tokens', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cost-quirks'), 4, 'mcq', '''Glitch tokens'' like '' SolidGoldMagikarp'' made early GPT models behave strangely. What was the cause?', NULL, NULL, 'The token existed in the tokenizer''s training data but almost never appeared in the model''s training data, so its embedding stayed nearly untrained', 'The tokenizer and the model were trained on different datasets.', 'A token that is in the vocabulary but rare in the model''s training data gets almost no gradient updates. Its embedding is close to its random start, and the model''s output becomes unpredictable when it sees it.', NULL, NULL, 91);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The token was a special control token', 0), (@q, 'B', 'The token existed in the tokenizer''s training data but almost never appeared in the model''s training data, so its embedding stayed nearly untrained', 1), (@q, 'C', 'The token was longer than the context window', 0), (@q, 'D', 'The token contained invalid UTF-8', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cost-quirks'), 4, 'mcq', 'A prompt ends with ''The answer is '' (trailing space) and output quality drops. What is the most likely tokenizer reason?', NULL, NULL, 'Words normally carry their own leading space, so a lone space token is rare before a word and pushes the model off-distribution', 'In training data, would '' 42'' usually be one token or a space token followed by ''42''?', 'In training text, the space usually belongs to the next token ('' 42''). Ending a prompt with a bare space forces an unusual split. This ''token healing'' issue is why some libraries back up one token before generating.', NULL, NULL, 92);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Spaces cost more than other tokens', 0), (@q, 'B', 'The space becomes an EOS token', 0), (@q, 'C', 'Trailing spaces are removed before tokenisation', 0), (@q, 'D', 'Words normally carry their own leading space, so a lone space token is rare before a word and pushes the model off-distribution', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'templates-mismatch'), 1, 'mcq', 'What is a chat template?', NULL, NULL, 'The exact text format (with special tokens) that turns a list of {role, content} messages into one string the model was trained on', 'The model only sees one long token sequence, not JSON.', 'Each chat model was fine-tuned with a specific format, e.g. ''<|im_start|>user\\nHi<|im_end|>''. The template reproduces that format exactly.', NULL, NULL, 93);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The exact text format (with special tokens) that turns a list of {role, content} messages into one string the model was trained on', 1), (@q, 'B', 'A list of banned words', 0), (@q, 'C', 'A CSS theme for chat apps', 0), (@q, 'D', 'A pre-written answer the model copies', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'templates-mismatch'), 2, 'code_output', 'What does this print?', 'msgs = [{"role": "system", "content": "Be brief."},\n        {"role": "user", "content": "Hi"}]\ns = "".join(f"<|im_start|>{m[''role'']}\\n{m[''content'']}<|im_end|>\\n" for m in msgs)\ns += "<|im_start|>assistant\\n"      # generation prompt\nprint(s.count("<|im_start|>"), s.endswith("assistant\\n"))', 'python', '3 True', 'Two messages plus one more opening tag at the end.', 'The final ''<|im_start|>assistant\\n'' is the ''generation prompt'' (add_generation_prompt=True). It tells the model it is now the assistant''s turn to speak.', NULL, NULL, 94);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3 False', 0), (@q, 'B', '2 False', 0), (@q, 'C', '2 True', 0), (@q, 'D', '3 True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'templates-mismatch'), 2, 'mcq', 'You call a chat model with a plain prompt string instead of applying its chat template. What is the typical symptom?', NULL, NULL, 'Worse, rambling answers, or the model continuing your text as if it were a document, because the input does not look like its fine-tuning data', 'The model learned to follow the format it was trained on.', 'Chat models are trained on templated conversations. Without the role markers they act more like a base model doing autocomplete.', NULL, NULL, 95);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Worse, rambling answers, or the model continuing your text as if it were a document, because the input does not look like its fine-tuning data', 1), (@q, 'B', 'Exactly the same answers', 0), (@q, 'C', 'An immediate error from the model', 0), (@q, 'D', 'The model answers in a different language', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'templates-mismatch'), 2, 'true_false', 'Different model families (Llama, Mistral, Qwen) use different chat templates, so a prompt formatted for one is wrong for another.', NULL, NULL, 'True', '[INST]...[/INST] vs <|im_start|> vs <|start_header_id|>.', 'Templates differ in special tokens and layout. Always use the template shipped with the model''s own tokenizer (tokenizer.apply_chat_template).', NULL, NULL, 96);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'templates-mismatch'), 3, 'code_output', 'What does this print?', 'template_out = "<s> [INST] Hi [/INST]"     # template already adds BOS\nids = ["<s>"] + template_out.split()      # tokenizer adds BOS again\nprint(ids[:3])', 'python', '[''<s>'', ''<s>'', ''[INST]'']', 'Two different steps each add a start token.', 'The double-BOS bug: the template text already starts with <s>, then encoding with add_special_tokens=True adds another. Quality drops quietly. Tokenise template output with add_special_tokens=False.', NULL, NULL, 97);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''<s>'', ''<s>'', ''[INST]'']', 1), (@q, 'B', '[''<s>'', ''[INST]'', ''Hi'']', 0), (@q, 'C', '[''[INST]'', ''Hi'', ''[/INST]'']', 0), (@q, 'D', '[''<s>'', ''[INST]'', ''[/INST]'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'templates-mismatch'), 3, 'mcq', 'You fine-tune with one chat format and serve with a different one (e.g. a different system-prompt layout). What usually happens?', NULL, NULL, 'The model works but noticeably worse, since the serving input no longer matches the training distribution', 'Fine-tuning teaches patterns of tokens, including the formatting tokens.', 'Train/serve skew: the same bug class as a feature pipeline that differs between training and production. Keep one template and test it end-to-end.', NULL, 'Like a client and server disagreeing on the API schema: requests still arrive but are misread.', 98);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The model output becomes identical to the base model', 0), (@q, 'B', 'The model works but noticeably worse, since the serving input no longer matches the training distribution', 1), (@q, 'C', 'Nothing; models ignore formatting', 0), (@q, 'D', 'The server throws a template error', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'templates-mismatch'), 3, 'mcq', 'You load model A''s weights but accidentally use model B''s tokenizer (same vocabulary size). What happens?', NULL, NULL, 'It runs without errors but outputs garbage, because each ID now points to a different token than the model learned', 'IDs are just row numbers. Does row 1234 mean the same thing in both vocabularies?', 'The silent failure is the worst kind: shapes match, so nothing crashes. Always load the tokenizer from the same checkpoint as the model.', NULL, 'Like reading a database dump with the wrong schema: every column is filled, but with the wrong data.', 99);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It runs without errors but outputs garbage, because each ID now points to a different token than the model learned', 1), (@q, 'B', 'The tokenizer converts itself automatically', 0), (@q, 'C', 'It raises a shape error immediately', 0), (@q, 'D', 'It works fine because the sizes match', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'templates-mismatch'), 4, 'mcq', 'While fine-tuning a chat model you set labels = input_ids for the whole templated conversation. What subtle problem does this cause?', NULL, NULL, 'The model is also trained to predict the user''s messages and the system prompt, not just the assistant''s replies', 'Which parts of the conversation do you want the model to learn to write?', 'The usual fix is to set the labels to -100 for every non-assistant token (''train on completions only''). Otherwise capacity is spent imitating users, and the model can learn to write user turns itself.', NULL, NULL, 100);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Padding is ignored automatically, so nothing is wrong', 0), (@q, 'B', 'The loss cannot be computed', 0), (@q, 'C', 'The template tokens are removed', 0), (@q, 'D', 'The model is also trained to predict the user''s messages and the system prompt, not just the assistant''s replies', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'templates-mismatch'), 4, 'mcq', 'A fine-tuned model never stops generating at inference. The chat template ends assistant turns with ''<|im_end|>'', but generation is configured to stop on ''</s>''. What is the fix?', NULL, NULL, 'Make the stop/EOS token in the generation config match the turn-ending token the model was trained to emit', 'The model emits the end marker it learned; the loop is waiting for a different one.', 'A stop-token mismatch: the model correctly outputs <|im_end|>, but the loop only stops on </s>, so it keeps generating the next fake turn. Set eos_token_id (or a list of stop IDs) to match the template.', NULL, NULL, 101);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Lower the temperature', 0), (@q, 'B', 'Increase max_new_tokens', 0), (@q, 'C', 'Make the stop/EOS token in the generation config match the turn-ending token the model was trained to emit', 1), (@q, 'D', 'Add more padding', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'templates-mismatch'), 4, 'true_false', 'Counting tokens with one model''s tokenizer gives an exact cost estimate for a different provider''s model.', NULL, NULL, 'False', 'Do different models share one vocabulary?', 'Each model family has its own tokenizer, and the same text can differ by 20% or more in token count. Budget and truncate with the tokenizer of the model you are actually calling.', NULL, NULL, 102);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'What is an embedding?', NULL, NULL, 'A list of numbers (vector) that captures the meaning of text', 'Similar meanings land close together.', 'Embeddings map text to vectors so ''king'' and ''queen'' sit near each other in space.', '   ^         queen\n   |   king    .\n   |    .\n   |                    banana\n   |                      .   apple\n   +------------------------------>\n close points = similar meaning', NULL, 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A list of numbers (vector) that captures the meaning of text', 1), (@q, 'B', 'A database index', 0), (@q, 'C', 'An image', 0), (@q, 'D', 'A compressed zip of text', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Cosine similarity measures:', NULL, NULL, 'The angle between two vectors (how aligned they are)', '1 means pointing the same way.', 'cos = 1 same direction, 0 unrelated, -1 opposite. Used for semantic search and RAG.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The length of a vector', 0), (@q, 'B', 'The angle between two vectors (how aligned they are)', 1), (@q, 'C', 'The number of words', 0), (@q, 'D', 'Spelling distance', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1, 0])\nb = np.array([0, 1])\nprint(a @ b)', 'python', '0', '@ is the dot product: multiply pairs and add.', '1*0 + 0*1 = 0. These vectors are perpendicular, so cosine similarity is 0.', NULL, NULL, 3);
