INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'alerting'), 4, 'true_false', 'Replacing user emails with their SHA-256 hash in logs makes the logs fully anonymous.', NULL, NULL, 'False', 'Could someone hash a list of known emails and compare?', 'Hashes of guessable values (emails, phone numbers) can be reversed by hashing candidates and matching. That''s pseudonymisation at best; use keyed hashing, tokenisation, or don''t log them, with access control and retention limits.', NULL, NULL, 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'alerting'), 4, 'code_output', 'What does this print?', 'import re\n\nlog = "user rahul.k@example.com asked to call +91 98765 43210 about order 5512"\nlog = re.sub(r"[\\w.]+@[\\w.]+", "<EMAIL>", log)\nlog = re.sub(r"\\+?\\d[\\d ]{8,}\\d", "<PHONE>", log)\nprint(log)', 'python', 'user <EMAIL> asked to call <PHONE> about order 5512', 'The phone pattern needs at least 10 characters of digits/spaces.', 'Both PII values are masked before the line is stored; the short order number survives. Redact at write time: logs get copied to many systems and are hard to clean later.', NULL, NULL, 84);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'user <EMAIL> asked to call <PHONE> about order 5512', 1), (@q, 'B', 'user <EMAIL> asked to call <PHONE> about order <PHONE>', 0), (@q, 'C', 'user <EMAIL> asked to call +91 98765 43210 about order 5512', 0), (@q, 'D', 'user rahul.k@example.com asked to call <PHONE> about order 5512', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'why-arrays'), 1, 'mcq', 'What is the main reason ML code stores numbers in a NumPy array instead of a Python list?', NULL, NULL, 'Maths on the whole array runs in fast compiled code, with no Python loop', 'Think about who does the looping: Python or C.', 'An array is one block of same-typed numbers, so NumPy can loop over it in compiled C. Lists can hold anything, which is exactly why they are slow for maths.', NULL, 'A list is a drawer of labelled boxes you open one by one; an array is a single spreadsheet column you can apply a formula to in one go.', 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Arrays can hold any mix of types, lists cannot', 0), (@q, 'B', 'Arrays are the only way to store more than 1000 items', 0), (@q, 'C', 'Lists cannot hold decimal numbers', 0), (@q, 'D', 'Maths on the whole array runs in fast compiled code, with no Python loop', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'why-arrays'), 1, 'code_output', 'What does this print?', 'import numpy as np\nlst = [1, 2, 3]\narr = np.array([1, 2, 3])\nprint(lst * 2)\nprint(arr * 2)', 'python', '[1, 2, 3, 1, 2, 3]\n[2 4 6]', '* means something different for a list.', 'For a list, * 2 repeats the list. For an array, * 2 multiplies every element. Note arrays print without commas.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2 4 6]\n[2, 4, 6]', 0), (@q, 'B', '[2, 4, 6]\n[2 4 6]', 0), (@q, 'C', '[1, 2, 3, 1, 2, 3]\n[2 4 6]', 1), (@q, 'D', '[1, 2, 3, 1, 2, 3]\n[1 2 3 1 2 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'why-arrays'), 1, 'true_false', 'Every element of a NumPy array has the same data type (dtype).', NULL, NULL, 'True', 'One array, one ...?', 'An array has a single dtype for all elements. That uniformity is what lets NumPy store them packed together and process them fast.', NULL, NULL, 3);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'why-arrays'), 1, 'code_output', 'What does this print?', 'import numpy as np\nprint([1, 2] + [3, 4])\nprint(np.array([1, 2]) + np.array([3, 4]))', 'python', '[1, 2, 3, 4]\n[4 6]', 'List + list joins; array + array ...?', 'List + list concatenates. Array + array adds element by element.', NULL, NULL, 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[4 6]\n[1 2 3 4]', 0), (@q, 'B', '[1, 2, 3, 4]\n[4 6]', 1), (@q, 'C', '[4, 6]\n[4 6]', 0), (@q, 'D', '[1, 2, 3, 4]\n[1 2 3 4]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'why-arrays'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1, 2.5, 3])\nprint(a)', 'python', '[1.  2.5 3. ]', 'One int and one float in the same array: everything must share a type.', 'The ints are upcast to float64 so they match 2.5. NumPy pads printed floats to line up, hence ''1. '' and ''3. ''.', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1.  2.5 3. ]', 1), (@q, 'B', '[1, 2.5, 3]', 0), (@q, 'C', '[1 2.5 3]', 0), (@q, 'D', '[1 2 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'why-arrays'), 2, 'mcq', 'You store one million int64 numbers. Roughly how much memory does the NumPy array need, versus a Python list of the same numbers?', NULL, NULL, 'About 8 MB for the array; the list needs about 8 MB of pointers PLUS a separate int object per number', 'int64 = 8 bytes. What does a list actually hold?', 'The array is one raw buffer of 8-byte values. A list holds 8-byte pointers to full Python int objects (about 28 bytes each), so it uses several times more memory.', 'array:  | 1 | 2 | 3 | 4 |   raw 8-byte values, side by side\nlist:   | * | * | * | * |   pointers...\n          |   |   |   |\n         int int int int    ...to separate Python objects', NULL, 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'About 8 MB for the array; the list needs about 8 MB of pointers PLUS a separate int object per number', 1), (@q, 'B', 'The array needs 28 MB, the list 8 MB', 0), (@q, 'C', 'Both need exactly 8 MB', 0), (@q, 'D', 'The list is smaller because Python compresses ints', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'why-arrays'), 3, 'mcq', 'Why is `arr.sum()` on a big array much faster than `sum(lst)` on a list of the same numbers?', NULL, NULL, 'The array is a contiguous typed buffer summed in a C loop; the list loop unboxes a Python object at each step', 'What does each step of the list loop have to do?', 'For a list, every step must follow a pointer, check the object''s type and unbox the value. NumPy knows the dtype once and runs a tight C loop over packed memory (cache-friendly, SIMD).', NULL, NULL, 7);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NumPy caches the sum when the array is created', 0), (@q, 'B', 'The array is a contiguous typed buffer summed in a C loop; the list loop unboxes a Python object at each step', 1), (@q, 'C', 'NumPy uses the GPU by default', 0), (@q, 'D', 'Python''s sum() is written in Python', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'why-arrays'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1, "a"])\nprint(a.dtype)\nprint(a[0] + a[0])', 'python', '<U21\n11', 'Mixing a number and a string: what single type can hold both?', 'NumPy converts everything to a fixed-width unicode string (<U21, wide enough for any int64). So a[0] is the string ''1'' and ''1'' + ''1'' is ''11''.', NULL, NULL, 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '<U1\n11', 0), (@q, 'B', 'object\n2', 0), (@q, 'C', 'int64\n2', 0), (@q, 'D', '<U21\n11', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'why-arrays'), 4, 'mcq', '`np.array([1, None, 3])` creates an array of dtype `object`. What does that mean for performance?', NULL, NULL, 'It stores Python object pointers, so most operations fall back to slow per-element Python calls', 'An object array is basically a list in disguise.', 'dtype=object arrays hold pointers to Python objects. You lose the packed buffer and the C loops; maths calls each object''s Python method. Use float with np.nan for missing numbers instead.', NULL, NULL, 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It is just as fast as int64 because NumPy ignores None', 0), (@q, 'B', 'It stores Python object pointers, so most operations fall back to slow per-element Python calls', 1), (@q, 'C', 'It is converted to float64 with NaN automatically', 0), (@q, 'D', 'It raises an error, NumPy arrays cannot contain None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 1, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.arange(5))', 'python', '[0 1 2 3 4]', 'Like Python''s range(): the stop value is excluded.', 'np.arange(5) works like range(5): it starts at 0 and stops before 5.', NULL, NULL, 10);
