INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 1, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.ones(3))', 'python', '[1. 1. 1.]', 'What is the default dtype of np.ones?', 'np.zeros and np.ones default to float64, which prints as ''1.'' (the dot means float).', NULL, NULL, 11);
