INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 1, 'fill_blank', 'Complete the call to make a 3x3 array full of zeros: `np.____((3, 3))`', NULL, NULL, 'zeros', 'The name says what is inside.', 'np.zeros((3, 3)) makes a 3x3 float array of 0.0. The shape goes in as one tuple.', NULL, NULL, 12);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 1, 'code_output', 'What does this print?', 'import numpy as np\na = np.zeros(2, 3)\nprint(a.shape)', 'python', 'TypeError', 'What is the SECOND positional parameter of np.zeros?', 'np.zeros(shape, dtype). Here 3 is taken as the dtype and is not a valid one, so TypeError. Write np.zeros((2, 3)) with the shape as one tuple.', NULL, NULL, 13);
