INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.eye(2))', 'python', '[[1. 0.]\n [0. 1.]]', 'eye = ''I'', the identity matrix.', 'np.eye(n) is the n x n identity matrix: ones on the diagonal, zeros elsewhere, float by default.', NULL, NULL, 17);
