INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'mcq', 'What is inside `np.empty((2, 3))` right after you create it?', NULL, NULL, 'Whatever bytes were already in that memory: arbitrary values', '''empty'' skips a step to save time.', 'np.empty allocates memory without clearing it, so the values are leftovers. Only use it when you will overwrite every element anyway.', NULL, 'Like malloc in C versus calloc: you get the memory, not a clean slate.', 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Whatever bytes were already in that memory: arbitrary values', 1), (@q, 'B', 'All NaN', 0), (@q, 'C', 'All zeros, guaranteed', 0), (@q, 'D', 'Nothing: it has shape (0,)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'code_output', 'What does this print?', 'import numpy as np\nrng = np.random.default_rng(0)\na = rng.integers(0, 10, size=3)\nrng2 = np.random.default_rng(0)\nb = rng2.integers(0, 10, size=3)\nprint((a == b).all(), a.shape)', 'python', 'True (3,)', 'Same seed, same generator recipe.', 'Two generators built with the same seed produce the same sequence, so a and b are identical. size=3 gives shape (3,).', NULL, NULL, 19);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True (3,)', 1), (@q, 'B', 'True (1, 3)', 0), (@q, 'C', 'False (3, 1)', 0), (@q, 'D', 'False (3,)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'fill_blank', 'Which NumPy function gives `num` evenly spaced values between start and stop, including stop by default?', NULL, NULL, 'linspace', 'Think ''linear space''.', 'np.linspace(start, stop, num). Its partner np.arange takes a step instead and excludes stop.', NULL, NULL, 20);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.linspace(0, 1, 5, endpoint=False))', 'python', '[0.  0.2 0.4 0.6 0.8]', 'Without the end point, the interval is split into 5 equal steps.', 'endpoint=False splits [0, 1) into 5 steps of 0.2 and drops the 1.0.', NULL, NULL, 21);
