INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(1, 1.3, 0.1)\nprint(len(a))', 'python', '4', '0.1 is not exactly representable in binary.', 'arange computes the length as ceil((1.3 - 1) / 0.1), and (1.3 - 1) / 0.1 is 3.0000000000000004, so it rounds up to 4 and includes ~1.3. Float steps in arange are risky; use linspace.', NULL, NULL, 22);
