INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 3, 'mcq', 'What does z hold after the assignment?', 'import numpy as np\na = np.array([1, 2, 3])\nz = np.zeros_like(a)\nz[0] = 2.9\nprint(z)', 'python', '[2 0 0]', 'zeros_like copies the shape AND the dtype.', 'zeros_like(a) makes an int64 array because a is int64. Assigning 2.9 truncates to 2.', NULL, NULL, 23);
