INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 3, 'true_false', 'Calling `np.random.seed(42)` also fixes the output of a generator made with `np.random.default_rng()`.', NULL, NULL, 'False', 'Global state versus a generator object.', 'np.random.seed only seeds the old global RandomState. A Generator from default_rng() has its own state; seed it directly: default_rng(42).', NULL, NULL, 25);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 4, 'mcq', 'Why is `rng = np.random.default_rng(seed)` passed around in modern code instead of calling `np.random.rand()`?', NULL, NULL, 'Each generator owns its state, so components don''t silently share or reset one global random stream', 'Think about global mutable state in a big codebase.', 'The legacy functions share one hidden global state: any library that reseeds it changes your results. A Generator is an explicit object (dependency injection for randomness) and uses the better PCG64 algorithm.', NULL, 'Global random state is like a global mutable singleton; a Generator is an injected dependency.', 26);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Generators are faster only on GPU', 0), (@q, 'B', 'default_rng is always cryptographically secure', 0), (@q, 'C', 'np.random.rand() was removed in NumPy 2', 0), (@q, 'D', 'Each generator owns its state, so components don''t silently share or reset one global random stream', 1);
