INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 1, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([10, 20, 30, 40])\nprint(a[1:3])', 'python', '[20 30]', 'Slices include the start and exclude the stop.', 'a[1:3] takes indexes 1 and 2: [20 30].', NULL, NULL, 50);
