INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 3, 'mcq', 'What shapes do these Ellipsis indexes give?', 'import numpy as np\na = np.zeros((2, 3, 4))\nprint(a[..., 0].shape, a[0, ...].shape)', 'python', '(2, 3) (3, 4)', '... stands for ''as many : as needed''.', 'a[..., 0] = a[:, :, 0] (shape (2, 3)); a[0, ...] = a[0, :, :] (shape (3, 4)). Ellipsis is handy for code that works on any number of batch dimensions.', NULL, NULL, 57);
