INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 1, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([3, 8, 1, 9])\nprint(a > 4)', 'python', '[False  True False  True]', 'Comparison on an array is done element by element.', 'a > 4 gives a boolean array of the same shape: a ''mask''. (NumPy pads False/True to line up.)', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', '[False  True False  True]', 1), (@q, 'C', '[0 1 0 1]', 0), (@q, 'D', '[8 9]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 1, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([3, 8, 1, 9])\nprint(a[a > 4])', 'python', '[8 9]', 'A mask inside [] keeps the True positions.', 'a[mask] keeps only the elements where the mask is True. This is how you filter rows in ML code.', NULL, 'Like SQL: SELECT value FROM a WHERE value > 4.', 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1 3]', 0), (@q, 'B', '[False  True False  True]', 0), (@q, 'C', '[0 8 0 9]', 0), (@q, 'D', '[8 9]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([3, 8, 1, 9])\nprint(a[(a > 2) & (a < 9)])', 'python', '[3 8]', '& is element-wise AND.', 'Use & (and), | (or), ~ (not) on masks, with brackets around each comparison because & binds tighter than >.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3 8]', 1), (@q, 'B', 'ValueError', 0), (@q, 'C', '[3 8 9]', 0), (@q, 'D', '[8]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([3, 8, 1, 9])\nprint(a[(a > 2) and (a < 9)])', 'python', 'ValueError', 'Python''s `and` wants ONE True/False.', '`and` calls bool() on the whole array, which is ambiguous for more than one element: ValueError ''The truth value of an array ... is ambiguous''. Use & instead.', NULL, NULL, 63);
