INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 2, 'mcq', 'What is `a` after the masked assignment?', 'import numpy as np\na = np.array([3, -8, 1, -9])\na[a < 0] = 0\nprint(a)', 'python', '[3 0 1 0]', 'Masks work on the left side of = too.', 'Assigning through a mask writes into the original array. This is how you clip negatives (ReLU by hand).', NULL, NULL, 65);
