INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshaping'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1, 2, 3, 4])\nprint(a[:, np.newaxis].shape, a[np.newaxis, :].shape)', 'python', '(4, 1) (1, 4)', 'np.newaxis inserts a length-1 axis where it appears.', 'a[:, None] turns the vector into a column (4, 1); a[None, :] makes a row (1, 4). np.newaxis is just None.', NULL, NULL, 89);
