INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshaping'), 2, 'fill_blank', 'Which function adds a new axis of length 1 at a given position, as in `np.____(a, axis=0)`?', NULL, NULL, 'expand_dims', 'The opposite of squeeze.', 'np.expand_dims(a, axis=0) turns shape (3,) into (1, 3). Same as a[np.newaxis, :].', NULL, NULL, 91);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshaping'), 3, 'mcq', 'What shapes do transpose(1, 0, 2) and moveaxis(-1, 0) give?', 'import numpy as np\na = np.zeros((2, 3, 4))\nprint(a.transpose(1, 0, 2).shape, np.moveaxis(a, -1, 0).shape)', 'python', '(3, 2, 4) (4, 2, 3)', 'transpose takes the NEW order of the old axes.', 'transpose(1, 0, 2) means new axes = old axes 1, 0, 2 -> (3, 2, 4). moveaxis(-1, 0) moves the last axis to the front -> (4, 2, 3), e.g. channels-last to channels-first.', NULL, NULL, 92);
