INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 1, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1, 5, 10])\nprint(np.clip(a, 2, 8))', 'python', '[2 5 8]', 'clip squashes values into a range.', 'Values below 2 become 2, values above 8 become 8, the rest stay. Common for keeping probabilities away from 0 and 1.', NULL, NULL, 38);
