INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 1, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([-2, 3, -1, 4])\nprint(np.where(a > 0, a, 0))', 'python', '[0 3 0 4]', 'np.where(condition, if_true, if_false).', 'Element by element: keep a where it is positive, otherwise 0. This is the ReLU activation.', NULL, 'It is a vectorised ternary: cond ? a : 0 for every element.', 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3 4]', 0), (@q, 'B', '[-2 0 -1 0]', 0), (@q, 'C', '[0 3 0 4]', 1), (@q, 'D', '[1 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 1, 'true_false', '`np.array([1, 2]) == np.array([1, 3])` returns a single True or False.', NULL, NULL, 'False', 'Comparisons are element-wise too.', 'It returns [ True False]. Use (a == b).all() or np.array_equal(a, b) for one answer.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 2, 'mcq', 'What does np.where return when given only a condition?', 'import numpy as np\na = np.array([5, 1, 7, 9])\nprint(np.where(a > 4))', 'python', '(array([0, 2, 3]),)', 'With ONE argument, np.where tells you WHERE.', 'np.where(cond) returns a tuple with one index array per axis (same as np.nonzero). For a 1D input that is a 1-tuple, which is why you often see np.where(...)[0].', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[5 7 9]', 0), (@q, 'B', '(array([0, 2, 3]),)', 1), (@q, 'C', '[0 2 3]', 0), (@q, 'D', '[ True False  True  True]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1, -2, 3])\nprint(np.any(a < 0), np.all(a > 0), (a > 0).sum())', 'python', 'True False 2', 'any = at least one, all = every one.', 'One element is negative, so any(a < 0) is True and all(a > 0) is False. Two are positive.', NULL, NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True 2', 0), (@q, 'B', 'True True 2', 0), (@q, 'C', 'True False 2', 1), (@q, 'D', 'True False 3', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1, 2, 3])\nprint(np.array_equal(a, [1, 2, 3]), np.array_equal(a, [[1, 2, 3]]))\nprint((a == [[1, 2, 3]]).all())', 'python', 'True False\nTrue', 'array_equal also checks the shape; == broadcasts.', 'array_equal requires identical shapes, so (3,) vs (1, 3) is False. == broadcasts them and every pair matches, so .all() is True.', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True False\nFalse', 0), (@q, 'B', 'True False\nTrue', 1), (@q, 'C', 'True True\nFalse', 0), (@q, 'D', 'True True\nTrue', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 2, 'code_output', 'What does this print?', 'import numpy as np\nx = np.array([-3.0, 0.5, 7.0])\nprint(np.clip(x, 0, None))', 'python', '[0.  0.5 7. ]', 'None means ''no limit on that side''.', 'Only the lower bound applies, so negatives become 0. Equivalent to np.maximum(x, 0).', NULL, NULL, 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0.  0.5 7. ]', 1), (@q, 'B', '[0. 0. 0.]', 0), (@q, 'C', '[-3.   0.5  0. ]', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 3, 'code_output', 'What does this print?', 'import numpy as np\nx = np.array([0.0, 2.0])\nwith np.errstate(divide="raise"):\n    print(np.where(x != 0, 1 / x, 0))', 'python', 'FloatingPointError', 'Arguments are evaluated before the function runs.', 'np.where is a normal function: 1 / x is computed for EVERY element first, including 1/0. With divide=''raise'' that raises FloatingPointError. Normally it only warns, and where hides the inf. Use np.divide(..., where=...) to avoid it.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'FloatingPointError', 1), (@q, 'B', '[inf 0.5]', 0), (@q, 'C', 'ZeroDivisionError', 0), (@q, 'D', '[0.  0.5]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 3, 'code_output', 'What does this print?', 'import numpy as np\nscore = np.array([45, 72, 90])\ngrade = np.select([score >= 85, score >= 60], ["A", "B"], default="C")\nprint(grade)', 'python', '[''C'' ''B'' ''A'']', 'np.select takes the FIRST condition that is true.', '90 matches >= 85 first -> A. 72 fails the first but matches >= 60 -> B. 45 matches nothing -> default C. It is a vectorised if / elif / else.', NULL, NULL, 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''C'' ''B'' ''A'']', 1), (@q, 'B', '[''C'' ''A'' ''A'']', 0), (@q, 'C', '[''B'' ''B'' ''A'']', 0), (@q, 'D', '[''A'' ''B'' ''C'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 3, 'mcq', 'What dtype does np.where give when the two branches differ?', 'import numpy as np\nr = np.where(np.array([True, False]), 1, 0.5)\nprint(r, r.dtype)', 'python', '[1.  0.5] float64', 'Both branches must fit in one result dtype.', 'np.where promotes the two branches to a common dtype, int and float -> float64.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1 0] int64', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', '[1.  0.5] float64', 1), (@q, 'D', '[1 0.5] object', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([3, 1, 2])\nlo = np.array([2, 2, 2])\nhi = np.array([2, 5, 2])\nprint(np.clip(a, lo, hi))', 'python', '[2 2 2]', 'The bounds can be arrays and broadcast like everything else.', 'Per element: 3 clipped to [2, 2] -> 2; 1 clipped to [2, 5] -> 2; 2 clipped to [2, 2] -> 2.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2 2 2]', 1), (@q, 'B', '[2 1 2]', 0), (@q, 'C', '[3 1 2]', 0), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 4, 'true_false', '`np.where(cond, a, b)` short-circuits like `a if cond else b`, so `b` is only computed where `cond` is False.', NULL, NULL, 'False', 'np.where is a function call.', 'Both a and b are full arrays computed BEFORE np.where runs. Expensive or unsafe branches (log of negatives, division by zero) still run everywhere.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
