INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([30, 10, 20])\nprint(np.argsort(a))', 'python', '[1 2 0]', 'argsort gives the positions, in the order that would sort the array.', 'The smallest (10) is at index 1, then 20 at index 2, then 30 at index 0: [1 2 0]. a[np.argsort(a)] is sorted.', NULL, NULL, 51);
