INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([3, 1, 2])\nr = a.sort()\nprint(r, a)', 'python', 'None [1 2 3]', 'Methods that change the object in place usually return None.', 'a.sort() sorts a itself and returns None, like Python''s list.sort(). Use np.sort(a) for a sorted copy.', NULL, NULL, 52);
