INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 2, 'mcq', 'What do unique and its counts come out as?', 'import numpy as np\nvals, counts = np.unique(np.array([3, 1, 3, 2, 1, 3]), return_counts=True)\nprint(vals, counts)', 'python', '[1 2 3] [2 1 3]', 'unique returns the values SORTED.', 'np.unique sorts the distinct values and return_counts gives how often each appears: a quick class-balance check.', NULL, NULL, 53);
