INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 2, 'fill_blank', 'Reverse a sorted array to get descending order: `np.sort(a)[____]`', NULL, NULL, '::-1', 'A slice with step -1.', 'np.sort has no ''descending'' flag; reverse the result with [::-1], or sort the negated values.', NULL, NULL, 54);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([[3, 1], [2, 5]])\nprint(np.sort(a))\nprint(np.sort(a, axis=None))', 'python', '[[1 3]\n [2 5]]\n[1 2 3 5]', 'The default axis for sort is the LAST one.', 'np.sort sorts each row independently (axis=-1). axis=None flattens first.', NULL, NULL, 55);
