INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'mcq', 'What does argsort applied twice produce?', 'import numpy as np\na = np.array([40, 10, 30, 20])\nprint(a.argsort().argsort())', 'python', '[3 0 2 1]', 'argsort of an argsort turns positions into ranks.', 'The rank of each element (0 = smallest): 40 is rank 3, 10 rank 0, 30 rank 2, 20 rank 1.', NULL, NULL, 57);
