INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 1, 'true_false', 'For an int64 array `a`, `a.mean()` returns a float64 even though every element is an integer.', NULL, NULL, 'True', 'What is the mean of 1 and 2?', 'mean always uses floating point for integer input, so the result is float64 (1.5 for [1, 2]).', NULL, NULL, 152);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'vectorisation'), 2, 'true_false', 'Python loops over NumPy arrays are faster than loops over Python lists, because the data is in an array.', NULL, NULL, 'False', 'Each a[i] in a loop has to create something.', 'Indexing a NumPy array element by element creates a new NumPy scalar object each time, which is often SLOWER than reading a list. NumPy is only fast when you hand it the whole array.', NULL, NULL, 153);
