INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'mcq', 'What does NaN stand for in pandas?', NULL, NULL, 'Not a Number: the marker pandas uses for a missing numeric value', 'It''s a special float value.', 'NaN (Not a Number) is a special floating-point value that pandas uses to mark missing data. It is not 0 and not an empty string.', NULL, 'Like NULL in a SQL table: ''we don''t know this value''.', 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Null and Nothing: an empty string', 0), (@q, 'B', 'Not a Number: the marker pandas uses for a missing numeric value', 1), (@q, 'C', 'A zero that has not been calculated yet', 0), (@q, 'D', 'A row that has been deleted', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"a": [1, np.nan, 3], "b": [None, "x", "y"]})\nprint(df.isna().sum().tolist())', 'python', '[1, 1]', 'isna() marks each missing cell True; sum() counts the Trues per column.', 'Column a has one NaN, column b has one None; isna() treats both as missing, so each column counts 1.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 0]', 0), (@q, 'B', '[1, 1]', 1), (@q, 'C', '[2]', 0), (@q, 'D', '[1, 0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"a": [1, np.nan, 3], "b": [4, 5, np.nan]})\nprint(df.dropna().shape)', 'python', '(1, 2)', 'dropna() removes a row if ANY of its values is missing.', 'Row 1 has NaN in a, row 2 has NaN in b. Only row 0 is complete, so 1 row is left.', '     a     b     any NaN?   dropna()\n0    1     4     no         kept\n1   NaN    5     yes        dropped\n2    3    NaN    yes        dropped', NULL, 3);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(3, 2)', 0), (@q, 'B', '(0, 2)', 0), (@q, 'C', '(2, 2)', 0), (@q, 'D', '(1, 2)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ns = pd.Series([1, np.nan, 3])\nprint(s.fillna(0).tolist())', 'python', '[1.0, 0.0, 3.0]', 'fillna replaces missing values; the dtype stays float.', 'fillna(0) puts 0 where NaN was. The Series was float64 because of the NaN, and it stays float64 after filling.', NULL, NULL, 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 0, 3]', 0), (@q, 'B', '[1.0, 3.0]', 0), (@q, 'C', '[1.0, 0.0, 3.0]', 1), (@q, 'D', '[1.0, nan, 3.0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.nan == np.nan, None == None)', 'python', 'False True', 'NaN is defined as not equal to anything, even itself.', 'By the IEEE float rules NaN != NaN, so == can never find missing values. None == None is True in Python. Always use isna() to test for missing.', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True', 1), (@q, 'B', 'True True', 0), (@q, 'C', 'False False', 0), (@q, 'D', 'True False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 2, 'true_false', '`df[df[''a''] == np.nan]` returns the rows where column a is missing.', NULL, NULL, 'False', 'What is NaN == NaN?', 'Every comparison with NaN is False, so the mask is all False and you get an empty frame. Use df[df[''a''].isna()].', NULL, NULL, 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 2, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"a": [1, np.nan, np.nan], "b": [4, 5, np.nan]})\nprint(df.dropna(how="all").shape, df.dropna(subset=["b"]).shape, df.dropna(thresh=1).shape)', 'python', '(2, 2) (2, 2) (2, 2)', 'how=''all'' needs every value missing; subset limits which columns are checked; thresh = minimum non-missing values to keep.', 'Only row 2 is all-NaN, so how=''all'' keeps 2 rows. subset=[''b''] drops row 2 only. thresh=1 keeps rows with at least 1 value: rows 0 and 1.', NULL, NULL, 7);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(2, 2) (2, 2) (2, 2)', 1), (@q, 'B', '(3, 2) (2, 2) (1, 2)', 0), (@q, 'C', '(2, 2) (1, 2) (3, 2)', 0), (@q, 'D', '(1, 2) (2, 2) (2, 2)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 2, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ns = pd.Series([1, np.nan, np.nan, 4])\nprint(s.ffill().tolist(), s.bfill().tolist())', 'python', '[1.0, 1.0, 1.0, 4.0] [1.0, 4.0, 4.0, 4.0]', 'ffill carries the last seen value forward; bfill pulls the next value backward.', 'ffill copies 1 down into the gaps; bfill copies 4 up. Both are typical for time series (e.g. last known price).', 'value   ffill   bfill\n  1       1       1\n NaN      1 v     4 ^\n NaN      1 v     4 ^\n  4       4       4', NULL, 8);
