INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 2, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ns = pd.Series([1, np.nan, 3])\nprint(s.sum(), s.mean(), s.sum(skipna=False))', 'python', '4.0 2.0 nan', 'Aggregations skip NaN unless you tell them not to.', 'skipna=True is the default: sum is 1+3 and mean divides by the 2 present values. With skipna=False a single NaN poisons the result.', NULL, NULL, 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'nan nan nan', 0), (@q, 'B', '4.0 2.0 4.0', 0), (@q, 'C', '4.0 2.0 nan', 1), (@q, 'D', '4.0 1.3333333333333333 nan', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\nprint(pd.Series([np.nan, np.nan]).sum(), pd.Series([np.nan, np.nan]).mean())', 'python', '0.0 nan', 'The sum of nothing is the ''empty'' value for addition.', 'With all values skipped, sum returns 0.0 (sum of an empty set), but mean returns NaN (0/0). Use sum(min_count=1) to get NaN for an all-missing group.', NULL, NULL, 10);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'nan nan', 0), (@q, 'B', '0.0 0.0', 0), (@q, 'C', 'nan 0.0', 0), (@q, 'D', '0.0 nan', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 2, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"a": [1, np.nan], "b": [np.nan, 2]})\nprint(df.fillna({"a": 0, "b": -1}).values.tolist())', 'python', '[[1.0, -1.0], [0.0, 2.0]]', 'A dict lets you give each column its own fill value.', 'fillna({''a'': 0, ''b'': -1}) fills a''s NaN with 0 and b''s NaN with -1.', NULL, NULL, 11);
