INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["x", None, "y"])\nprint(s.dtype, s.isna().tolist(), s.fillna("missing").tolist())', 'python', 'object [False, True, False] [''x'', ''missing'', ''y'']', 'None in a text column stays None, but isna() still recognises it.', 'In an object column None is kept as None, and pandas treats both None and NaN as missing for isna/fillna/dropna.', NULL, NULL, 12);
