INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ns = pd.Series([1.0, np.nan, 3.0])\nprint(s.interpolate().tolist())', 'python', '[1.0, 2.0, 3.0]', 'interpolate draws a straight line between the neighbours.', 'Linear interpolation fills the gap with the midpoint of 1 and 3, which is 2.', NULL, NULL, 13);
