INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duplicates'), 1, 'true_false', '`df.duplicated()` with no arguments compares only the first column.', NULL, NULL, 'False', 'What does ''duplicate row'' mean by default?', 'With no subset, a row is a duplicate only if ALL its columns match an earlier row.', NULL, NULL, 24);
