INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 2, 'fill_blank', 'To get per-group totals with the key as a normal column (like SQL output), pass `as_index=____` to groupby.', NULL, NULL, 'False', 'The opposite of the default.', 'groupby(..., as_index=False) returns the keys as columns instead of the index.', NULL, NULL, 60);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["b", "a", "b"], "v": [1, 2, 3]})\nprint(list(df.groupby("g", sort=False).groups.keys()))', 'python', '[''b'', ''a'']', 'sort=False keeps keys in order of first appearance.', 'With sort=False, keys follow first appearance (b, then a). It can also speed up large groupbys.', NULL, NULL, 61);
