INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'concat'), 1, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"x": [1, 2]})\nb = pd.DataFrame({"x": [3]})\nprint(pd.concat([a, b], ignore_index=True).index.tolist())', 'python', '[0, 1, 2]', 'ignore_index throws away the old labels.', 'ignore_index=True renumbers the stacked rows 0, 1, 2.', NULL, NULL, 92);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 3]', 0), (@q, 'B', '[0, 1, 2]', 1), (@q, 'C', '[0, 1, 0]', 0), (@q, 'D', '[0, 0, 1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'concat'), 2, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"x": [1], "y": [2]})\nb = pd.DataFrame({"x": [3], "z": [4]})\nr = pd.concat([a, b], ignore_index=True)\nprint(r.columns.tolist(), r.isna().sum().sum())', 'python', '[''x'', ''y'', ''z''] 2', 'Columns are matched by name; missing ones are filled.', 'concat takes the union of columns (outer join on columns). a has no z and b has no y, so 2 cells are NaN. join=''inner'' would keep only x.', NULL, NULL, 93);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', '[''x''] 0', 0), (@q, 'C', '[''x'', ''y'', ''z''] 2', 1), (@q, 'D', '[''x'', ''y'', ''x'', ''z''] 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'concat'), 2, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"x": [1, 2]})\nb = pd.DataFrame({"y": [3, 4]})\nprint(pd.concat([a, b], axis=1).shape)', 'python', '(2, 2)', 'axis=1 places frames side by side.', 'axis=1 aligns rows on the index and puts the columns next to each other: 2 rows, 2 columns.', 'axis=0 (default)        axis=1\n  x    y                x  y\n  1   NaN               1  3\n  2   NaN               2  4\n NaN   3\n NaN   4', NULL, 94);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(2, 1)', 0), (@q, 'B', '(4, 2)', 0), (@q, 'C', '(2, 2)', 1), (@q, 'D', '(4, 1)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'concat'), 3, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"x": [1, 2]}, index=[0, 1])\nb = pd.DataFrame({"y": [3, 4]}, index=[1, 2])\nprint(pd.concat([a, b], axis=1).shape)', 'python', '(3, 2)', 'Side-by-side concat aligns on index labels, not positions.', 'The union of the indexes is 0, 1, 2, so the result has 3 rows with NaNs where a frame has no row. A common bug when the two parts were filtered differently.', NULL, NULL, 95);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', '(2, 2)', 0), (@q, 'C', '(4, 2)', 0), (@q, 'D', '(3, 2)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'concat'), 3, 'true_false', 'Appending rows one at a time with `df = pd.concat([df, new_row])` inside a loop is an efficient way to build a large DataFrame.', NULL, NULL, 'False', 'Each concat copies everything so far.', 'Every concat builds a brand-new frame, so a loop of n appends costs O(n^2). Collect rows in a Python list (of dicts) and build one DataFrame at the end.', NULL, 'Like rebuilding a whole array every time you push one element.', 96);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'concat'), 3, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.DataFrame({"v": [1]})\nb = pd.DataFrame({"v": [2]})\nr = pd.concat([a, b], keys=["jan", "feb"])\nprint(r.index.tolist())', 'python', '[(''jan'', 0), (''feb'', 0)]', 'keys adds an outer index level saying which piece each row came from.', 'keys=[''jan'', ''feb''] builds a MultiIndex (source, original label), handy for tracking which file a row came from.', NULL, NULL, 97);
