INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 2, 'code_output', 'What does this print?', 'import pandas as pd\nw = pd.DataFrame({"id": [1, 2], "q1": [5, 6], "q2": [7, 8]})\nprint(w.melt(id_vars="id"))', 'python', '   id variable  value\n0   1       q1      5\n1   2       q1      6\n2   1       q2      7\n3   2       q2      8', 'melt goes column by column: all of q1, then all of q2.', 'id_vars stays as an identifier; every other column is unpivoted into (variable, value) rows, in column order.', 'wide:  id q1 q2        long:  id variable value\n        1  5  7   ->           1   q1      5\n        2  6  8                2   q1      6\n                               1   q2      7\n                               2   q2      8', NULL, 100);
