INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.DataFrame({"d": ["x", "y"], "m": [1, 2], "n": [3, 4]}).set_index("d").stack()\nprint(s.index.tolist(), s.tolist())', 'python', '[(''x'', ''m''), (''x'', ''n''), (''y'', ''m''), (''y'', ''n'')] [1, 3, 2, 4]', 'stack moves the columns into the innermost index level, row by row.', 'stack walks each row and pushes its columns into the index, giving (row, column) tuples: x-m, x-n, y-m, y-n. unstack is the inverse.', NULL, NULL, 107);
