INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 4, 'true_false', '`pivot_table(..., aggfunc=''sum'')` and `groupby([a, b])[v].sum().unstack()` produce the same table.', NULL, NULL, 'True', 'pivot_table is built on groupby.', 'pivot_table groups by the index and columns keys, aggregates, then unstacks the column key. Both give the same numbers (pivot_table can add fill_value and margins conveniently).', NULL, NULL, 108);
