INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binning'), 1, 'code_output', 'What does this print?', 'import pandas as pd\nages = pd.Series([5, 25, 70])\nprint(pd.cut(ages, bins=[0, 18, 60, 100], labels=["kid", "adult", "senior"]).tolist())', 'python', '[''kid'', ''adult'', ''senior'']', 'cut puts each value into the bin whose edges surround it.', '5 falls in (0, 18] -> kid, 25 in (18, 60] -> adult, 70 in (60, 100] -> senior.', NULL, NULL, 109);
