INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nd = pd.to_datetime(pd.Series(["2024-01-31"]))\nprint((d + pd.Timedelta(days=1)).dt.strftime("%Y-%m-%d").tolist(), (d + pd.DateOffset(months=1)).dt.strftime("%Y-%m-%d").tolist())', 'python', '[''2024-02-01''] [''2024-02-29'']', 'Timedelta is a fixed length of time; DateOffset follows calendar rules.', 'Adding 1 day gives 1 Feb. Adding one calendar month to 31 Jan clips to the last day of February 2024 (a leap year): 29 Feb.', NULL, NULL, 119);
