INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, 2, 3, 4, 5])\nprint(s.rolling(3).mean().tolist())', 'python', '[nan, nan, 2.0, 3.0, 4.0]', 'A window of 3 needs 3 values before it can produce a result.', 'rolling(3).mean() averages each value with the two before it; the first two positions have incomplete windows, so NaN (unless min_periods is lowered).', 'values:   1   2   3   4   5\nwindow:  [1   2   3]           -> 2.0\n             [2   3   4]       -> 3.0\n                 [3   4   5]   -> 4.0\nresult:  NaN NaN 2.0 3.0 4.0', NULL, 122);
