INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nt = pd.Timestamp("2024-03-10 12:00", tz="UTC")\nprint(t.tz_convert("Asia/Kolkata").strftime("%H:%M"))', 'python', '17:30', 'India is UTC+5:30.', 'tz_convert changes the wall-clock representation of the same instant: 12:00 UTC is 17:30 IST. tz_localize, by contrast, attaches a zone without shifting.', NULL, NULL, 124);
