INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 1, 'code_output', 'What does this print?', 'import pandas as pd\nrows = [{"name": "Ann", "age": 30}, {"name": "Bob", "age": 25}]\ndf = pd.DataFrame(rows)\nprint(df.shape)', 'python', '(2, 2)', 'A list of dicts: each dict is one row.', 'A list of records (like rows from a JSON API) gives one row per dict and one column per key: 2 rows x 2 columns.', NULL, 'Exactly the shape of `res.json()` from a REST API returning an array of objects.', 9);
