INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 1, 'code_output', 'What does this print?', 'import io\nimport pandas as pd\ncsv = "id,score\\n1,90\\n2,85\\n3,70"\ndf = pd.read_csv(io.StringIO(csv))\nprint(df["score"].sum(), df.shape)', 'python', '245 (3, 2)', 'The first line is the header, not a data row.', 'read_csv uses the first line as column names, so there are 3 data rows and 2 columns. The scores are parsed as integers, so sum is 245.', NULL, NULL, 11);
