INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 1, 'fill_blank', 'To parse CSV text held in a Python string, wrap it in `io.____(text)` and pass that to pd.read_csv.', NULL, NULL, 'StringIO', 'It makes a string behave like an open file.', 'io.StringIO turns a string into an in-memory file object; read_csv accepts any file-like object.', NULL, NULL, 12);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'code_output', 'What does this print?', 'import io\nimport pandas as pd\ncsv = "id,score\\n1,90\\n2,85"\ndf = pd.read_csv(io.StringIO(csv), index_col="id")\nprint(df.columns.tolist(), df.index.tolist())', 'python', '[''score''] [1, 2]', 'index_col moves a column into the row labels.', 'index_col=''id'' makes the id column the index, so only ''score'' remains as a column and the index is [1, 2].', NULL, NULL, 13);
