INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 3, 'code_output', 'What does this print?', 'import io\nimport pandas as pd\ncsv = "id,code\\n1,007\\n2,042"\ndf = pd.read_csv(io.StringIO(csv))\ndf2 = pd.read_csv(io.StringIO(csv), dtype={"code": str})\nprint(df["code"].tolist(), df2["code"].tolist())', 'python', '[7, 42] [''007'', ''042'']', 'read_csv guesses types, and numbers lose leading zeros.', 'Type inference turns 007 into the integer 7. Pass dtype={''code'': str} for IDs, zip codes or phone numbers to keep the leading zeros.', NULL, NULL, 17);
