INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 3, 'code_output', 'What does this print?', 'import io\nimport pandas as pd\ncsv = "a,b\\n1,x\\nNA,y\\n3,"\ndf = pd.read_csv(io.StringIO(csv))\nprint(df["a"].dtype, df["b"].isna().sum())', 'python', 'float64 1', '''NA'' and an empty field are both read as missing by default.', 'read_csv treats ''NA'' and empty fields as NaN. A NaN in column a forces float64 (NumPy ints can''t hold NaN); b has one missing value.', NULL, NULL, 18);
