INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": [10, 20]})\nprint(df.apply(sum).tolist(), df.apply(sum, axis=1).tolist())', 'python', '[3, 30] [11, 22]', 'axis=0 (default) hands each COLUMN to the function.', 'Default axis=0 calls sum on each column (1+2, 10+20). axis=1 calls it on each row (1+10, 2+20).', '            a    b\nrow 0       1   10   -> axis=1 sums along a row: 11\nrow 1       2   20   ->                          22\n            |    |\naxis=0:     3   30   (sum down each column)', NULL, 79);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[33] [33]', 0), (@q, 'B', '[3, 30] [3, 30]', 0), (@q, 'C', '[3, 30] [11, 22]', 1), (@q, 'D', '[11, 22] [3, 30]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 2, 'mcq', 'You need `df[''bmi''] = weight / height**2` for a million rows. Which is the best approach?', NULL, NULL, 'df["bmi"] = df["weight"] / df["height"] ** 2', 'Column-level arithmetic beats row-by-row Python.', 'Plain column arithmetic is vectorised and runs in C. apply(axis=1) builds a Series per row, which is the slowest of all; the list comprehension is better but still Python-level.', NULL, NULL, 80);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A for loop with df.iterrows() appending to a list', 0), (@q, 'B', 'df["bmi"] = [w / h ** 2 for w, h in zip(df["weight"], df["height"])]', 0), (@q, 'C', 'df["bmi"] = df["weight"] / df["height"] ** 2', 1), (@q, 'D', 'df["bmi"] = df.apply(lambda r: r["weight"] / r["height"] ** 2, axis=1)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"t": [5, 15, 25]})\ndf["band"] = np.where(df["t"] > 10, "warm", "cold")\nprint(df["band"].tolist())', 'python', '[''cold'', ''warm'', ''warm'']', 'np.where(condition, value_if_true, value_if_false).', 'np.where is the vectorised if/else: 5 is cold, 15 and 25 are warm. It replaces apply with an if inside.', NULL, 'SQL: CASE WHEN t > 10 THEN ''warm'' ELSE ''cold'' END.', 81);
