INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": [10, 20]})\nprint((df - df.mean()).values.tolist())', 'python', '[[-0.5, -5.0], [0.5, 5.0]]', 'df.mean() is a Series indexed by column names.', 'DataFrame minus Series aligns the Series index with the COLUMNS and broadcasts down the rows: column a subtracts 1.5, column b subtracts 15.', NULL, NULL, 94);
