INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'mcq', 'What is a MultiIndex?', NULL, NULL, 'An index with more than one level, so each row label is a tuple like (''Pune'', 2024)', 'Think of a composite key.', 'A MultiIndex (hierarchical index) has several levels; each label is a tuple. groupby on several columns and pivot results often produce one.', NULL, 'A composite primary key (city, year) in SQL.', 123);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'An index that allows duplicate labels', 0), (@q, 'B', 'Several DataFrames stored inside one', 0), (@q, 'C', 'An index with more than one level, so each row label is a tuple like (''Pune'', 2024)', 1), (@q, 'D', 'An index of multiple dtypes at once', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Pune", "Goa"], "year": [2023, 2024, 2024], "sales": [5, 7, 3]})\nm = df.set_index(["city", "year"])\nprint(m.loc[("Pune", 2024), "sales"], m.index.nlevels)', 'python', '7 2', 'Each row label is now a (city, year) tuple.', 'set_index with two columns builds a 2-level MultiIndex; loc[(''Pune'', 2024)] selects that exact row.', '         level 0  level 1\nindex:   (Pune,   2023)  -> sales 5\n         (Pune,   2024)  -> sales 7\n         (Goa,    2024)  -> sales 3', NULL, 124);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '7 2', 1), (@q, 'B', 'KeyError', 0), (@q, 'C', '7 1', 0), (@q, 'D', '5 2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Pune", "Goa"], "year": [2023, 2024, 2024], "sales": [5, 7, 3]})\nm = df.set_index(["city", "year"])\nprint(m.loc["Pune"]["sales"].tolist(), m.loc["Pune"].index.tolist())', 'python', '[5, 7] [2023, 2024]', 'Selecting by the first level only drops that level.', 'loc[''Pune''] returns all rows for Pune, and the city level is dropped, leaving year as the index.', NULL, NULL, 125);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '[5] [2023]', 0), (@q, 'C', '[5, 7] [2023, 2024]', 1), (@q, 'D', '[5, 7] [(''Pune'', 2023), (''Pune'', 2024)]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Pune", "Goa"], "year": [2023, 2024, 2024], "sales": [5, 7, 3]})\ns = df.set_index(["city", "year"])["sales"]\nprint(s.xs(2024, level="year").to_dict())', 'python', '{''Pune'': 7, ''Goa'': 3}', 'xs takes a cross-section on an inner level.', 'xs(2024, level=''year'') picks every row whose year is 2024 and drops the year level, keeping the original row order.', NULL, NULL, 126);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '{''Pune'': 7, ''Goa'': 3}', 1), (@q, 'C', '{(''Pune'', 2024): 7, (''Goa'', 2024): 3}', 0), (@q, 'D', '{''Goa'': 3, ''Pune'': 7}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Pune", "Goa"], "year": [2023, 2024, 2024], "sales": [5, 7, 3]})\nw = df.set_index(["city", "year"])["sales"].unstack()\nprint(w.shape, w.columns.tolist(), w.isna().sum().sum())', 'python', '(2, 2) [2023, 2024] 1', 'unstack moves the innermost index level into the columns.', 'unstack pivots year into columns: rows Goa and Pune, columns 2023 and 2024. Goa has no 2023 row, so one cell is NaN.', '(city, year) sales        year  2023  2024\n(Pune, 2023)   5    ->   city\n(Pune, 2024)   7         Goa    NaN   3.0\n(Goa,  2024)   3         Pune   5.0   7.0', NULL, 127);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(2, 2) [''Goa'', ''Pune''] 1', 0), (@q, 'B', '(2, 2) [2023, 2024] 0', 0), (@q, 'C', '(2, 2) [2023, 2024] 1', 1), (@q, 'D', '(3, 1) [2024] 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "a", "b"], "v": [1, 2, 3]})\nr = df.groupby("g").agg(["sum", "max"])\nprint(r.columns.tolist())', 'python', '[(''v'', ''sum''), (''v'', ''max'')]', 'Several aggregations per column produce two levels of column labels.', 'agg with a list gives MultiIndex COLUMNS: (column, function). Flatten with [''_''.join(c) for c in r.columns] or use named aggregation.', NULL, NULL, 128);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''v'', ''sum'', ''max'']', 0), (@q, 'B', '[''v_sum'', ''v_max'']', 0), (@q, 'C', '[(''v'', ''sum''), (''v'', ''max'')]', 1), (@q, 'D', '[''sum'', ''max'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 4, 'true_false', 'Slicing a MultiIndex with `loc` by ranges (e.g. `m.loc[''A'':''C'']`) works reliably only when the index is lexsorted (call `sort_index()` first).', NULL, NULL, 'True', 'Range lookups need sorted keys.', 'On an unsorted MultiIndex, range slicing can raise UnsortedIndexError or be slow. sort_index() makes slicing work and lookups fast (binary search).', NULL, NULL, 129);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'index-alignment'), 2, 'mcq', 'In SQL terms, what does a DataFrame''s index most resemble?', NULL, NULL, 'A row key used to look up and align rows (like a primary key, though it may repeat)', 'It''s what loc looks things up by.', 'The index labels the rows: loc uses it for lookups and arithmetic aligns on it. Unlike a primary key, pandas allows duplicate labels.', NULL, NULL, 130);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A database index that only speeds up queries and is never visible', 0), (@q, 'B', 'An auto-increment column that can''t be changed', 0), (@q, 'C', 'A row key used to look up and align rows (like a primary key, though it may repeat)', 1), (@q, 'D', 'The list of column names', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 2, 'true_false', '`df.loc[:, ''a'':''c'']` and `df.iloc[:, 0:3]` select the same columns when the columns are a, b, c, d.', NULL, NULL, 'True', 'loc includes the end label; iloc excludes the end position.', 'loc ''a'':''c'' gives a, b, c. iloc 0:3 gives positions 0, 1, 2, which are also a, b, c.', NULL, NULL, 131);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 1, 'mcq', 'You have a DataFrame `df` indexed by user_id. Which gives the row for user_id 42?', NULL, NULL, 'df.loc[42]', 'user_id is a label, not a position.', 'loc[42] looks up the label 42. iloc[42] would be the 43rd row, whatever its id. df[42] looks for a COLUMN named 42.', NULL, NULL, 132);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df[42]', 0), (@q, 'B', 'df.get_row(42)', 0), (@q, 'C', 'df.loc[42]', 1), (@q, 'D', 'df.iloc[42]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 1, 'fill_blank', 'To keep only rows where column `city` is in a list, write `df[df[''city''].____([''Pune'', ''Goa''])]`.', NULL, NULL, 'isin', 'SQL''s IN.', 'Series.isin(values) returns a boolean mask that is True where the value is in the list.', NULL, NULL, 133);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 2, 'mcq', 'Which is the readable equivalent of `df[(df[''age''] > 30) & (df[''city''] == ''Pune'')]`?', NULL, NULL, 'df.query("age > 30 and city == ''Pune''")', 'One method takes a whole boolean expression as a string.', 'query() evaluates a string expression against the columns. df.filter selects columns/rows by LABEL name, not by value, and df.where keeps the shape and puts NaN where the condition is False.', NULL, NULL, 134);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.query("age > 30 and city == ''Pune''")', 1), (@q, 'B', 'df.filter("age > 30 and city == ''Pune''")', 0), (@q, 'C', 'df.where("age > 30 and city == ''Pune''")', 0), (@q, 'D', 'df.select("age > 30 & city == Pune")', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"v": [1, 5, 3]})\nprint(df.where(df["v"] > 2)["v"].tolist())', 'python', '[nan, 5.0, 3.0]', 'where keeps the shape and blanks out the rest.', 'df.where(cond) returns the same shape, with NaN where cond is False (so ints become float). Filtering with df[cond] drops rows instead.', NULL, NULL, 135);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[nan, 5.0, 3.0]', 1), (@q, 'B', '[1, 5, 3]', 0), (@q, 'C', '[5, 3]', 0), (@q, 'D', '[False, True, True]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 3, 'true_false', '`df.filter(like=''price'')` keeps the rows whose price column matches a condition.', NULL, NULL, 'False', 'filter is about labels, not values.', 'DataFrame.filter selects columns (or rows) whose LABELS match items/like/regex, e.g. every column with ''price'' in its name. Value filtering is df[mask] or query().', NULL, NULL, 136);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 2, 'mcq', 'You want to rename every column to lower case. Which works?', NULL, NULL, 'df.columns = df.columns.str.lower()', 'df.columns is an Index, and it has a .str accessor.', 'Assigning a new Index to df.columns renames everything. df.rename(columns=str.lower) also works; df.rename(str.lower) would rename the row labels.', NULL, NULL, 137);
