INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 2, 'fill_blank', 'To sort a DataFrame by its row labels rather than by a column, call `df.____()`.', NULL, NULL, 'sort_index', 'Sorting by the index.', 'sort_index() orders rows by the index labels; sort_values(col) orders by a column''s values.', NULL, NULL, 138);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 1, 'true_false', '`df.sort_values(''a'')` sorts df itself and returns None.', NULL, NULL, 'False', 'Which methods return a new object by default?', 'sort_values returns a new sorted DataFrame and leaves df as it was. Only inplace=True mutates df (and then returns None).', NULL, NULL, 139);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 2, 'mcq', 'Which statement about `Series.map` vs `Series.apply` is true?', NULL, NULL, 'map accepts a dict or Series as a lookup table; apply takes a function', 'Think about what you can pass as the argument.', 'map(dict) does a lookup (missing keys -> NaN); both map and apply also accept a function, which runs in Python per element. Neither mutates the Series.', NULL, NULL, 140);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'map is always vectorised C code; apply is always Python', 0), (@q, 'B', 'map accepts a dict or Series as a lookup table; apply takes a function', 1), (@q, 'C', 'map changes the Series in place', 0), (@q, 'D', 'apply works only on DataFrames', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 3, 'mcq', 'A senior reviewer says ''never use iterrows to compute a new column''. What is the best reason?', NULL, NULL, 'It is a Python loop that builds a Series per row, and it also upcasts mixed row dtypes', 'Two problems: speed and dtypes.', 'iterrows yields (index, Series) pairs: one Python object per row, which is slow, and each row Series has a single dtype, so ints can become floats. Use vectorised ops, or itertuples if you truly must loop.', NULL, NULL, 141);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It only works on numeric columns', 0), (@q, 'B', 'It is a Python loop that builds a Series per row, and it also upcasts mixed row dtypes', 1), (@q, 'C', 'It modifies the DataFrame while iterating', 0), (@q, 'D', 'It skips the first row', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 1, 'true_false', '`df[''a''].mean()` skips NaN values by default.', NULL, NULL, 'True', 'Look for the skipna parameter.', 'Reductions like mean, sum, max use skipna=True by default. NumPy''s np.mean on an array with NaN returns nan instead.', NULL, NULL, 142);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'mcq', 'What does `pd.options.mode.copy_on_write = ''warn''` do in pandas 2.2?', NULL, NULL, 'Keeps the old behaviour but warns wherever the result would change under copy-on-write', 'It''s a migration aid for pandas 3.0.', '''warn'' mode runs with today''s semantics but warns at every spot whose behaviour would change once copy-on-write is the default, so you can fix code before upgrading.', NULL, NULL, 143);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Copies every DataFrame on creation', 0), (@q, 'B', 'Disables SettingWithCopyWarning permanently', 0), (@q, 'C', 'Turns copy-on-write on and raises an error on chained assignment', 0), (@q, 'D', 'Keeps the old behaviour but warns wherever the result would change under copy-on-write', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 2, 'mcq', 'Under copy-on-write, which line is the correct way to set `b` to 0 for rows where `a > 1`?', NULL, NULL, 'df.loc[df["a"] > 1, "b"] = 0', 'One indexing operation, not two.', 'Only a single __setitem__ on df itself (via loc) modifies df. The other three are chained assignment: under copy-on-write they never update df.', NULL, NULL, 144);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.loc[df["a"] > 1, "b"] = 0', 1), (@q, 'B', 'df[df["a"] > 1]["b"] = 0', 0), (@q, 'C', 'df["b"][df["a"] > 1] = 0', 0), (@q, 'D', 'df.b[df.a > 1] = 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'mcq', 'A column of 10 million user_id strings with ~10 million distinct values is using lots of memory. Is `category` a good fit?', NULL, NULL, 'No: with almost all values unique, category stores every value anyway plus codes, so it saves little or nothing', 'When does category help?', 'category wins when the number of distinct values is small relative to rows. With near-unique values, the categories array is as big as the original plus a code array. Consider the ''string[pyarrow]'' dtype or an integer key instead.', NULL, NULL, 145);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'No: category can''t store strings', 0), (@q, 'B', 'Yes: category always halves memory', 0), (@q, 'C', 'No: with almost all values unique, category stores every value anyway plus codes, so it saves little or nothing', 1), (@q, 'D', 'Yes: category compresses strings with gzip', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 2, 'fill_blank', 'The nullable integer dtype that can hold missing values without becoming float is written `"____"` (capital letter matters).', NULL, NULL, 'Int64', 'Capital I.', '''Int64'' (capital I) is the pandas extension dtype with a mask; ''int64'' is the NumPy dtype that can''t hold NaN.', NULL, NULL, 146);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 1, 'true_false', 'In pandas, `df.shape` is a method, so you call it as `df.shape()`.', NULL, NULL, 'False', 'Is it an attribute or a function?', 'shape is an attribute holding a tuple (rows, cols). df.shape() raises TypeError: ''tuple'' object is not callable.', NULL, NULL, 147);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'mcq', 'What does `df.set_index([''city'', ''year''])` produce?', NULL, NULL, 'A DataFrame whose index is a 2-level MultiIndex of (city, year) tuples', 'A list of keys builds a composite key.', 'Passing a list to set_index creates a MultiIndex; each row label becomes a (city, year) tuple and both columns leave the data.', NULL, NULL, 148);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'An error, because set_index takes one column', 0), (@q, 'B', 'Two separate DataFrames, one per column', 0), (@q, 'C', 'A DataFrame with an index named ''city_year''', 0), (@q, 'D', 'A DataFrame whose index is a 2-level MultiIndex of (city, year) tuples', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'multiindex'), 3, 'mcq', 'You have a MultiIndex DataFrame and want plain columns again (e.g. before saving to CSV or feeding scikit-learn). What do you call?', NULL, NULL, 'reset_index()', 'Undo set_index.', 'reset_index() moves every index level back into ordinary columns and gives a fresh 0..n-1 RangeIndex.', NULL, NULL, 149);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'drop_index()', 0), (@q, 'B', 'unstack()', 0), (@q, 'C', 'reset_index()', 1), (@q, 'D', 'flatten()', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 4, 'mcq', 'Why does pandas insist that `bool(series)` raises instead of returning True/False?', NULL, NULL, 'It''s ambiguous: should it mean ''any element is True'', ''all are True'' or ''not empty''?', 'There are several reasonable meanings.', 'Unlike a list (truthy if non-empty), a Series could reasonably mean .any(), .all() or not .empty, so pandas refuses to guess. That is why `and`, `or` and `if series:` raise ValueError.', NULL, NULL, 150);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It''s ambiguous: should it mean ''any element is True'', ''all are True'' or ''not empty''?', 1), (@q, 'B', 'Because Series can contain strings', 0), (@q, 'C', 'Series objects are always truthy, so it would be useless', 0), (@q, 'D', 'For performance: computing truthiness is too slow', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'mcq', 'A pipeline does `X = df.drop(columns=''target'')` then `X[''age''] = X[''age''].fillna(0)`. Does this change `df`?', NULL, NULL, 'No: drop returns a new DataFrame, so writing to X doesn''t touch df', 'drop builds a new object.', 'drop returns a new frame that owns its data (or, under copy-on-write, shares it until written). Either way, assigning a column on X leaves df unchanged.', NULL, NULL, 151);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Yes, but only the age column', 0), (@q, 'B', 'No: drop returns a new DataFrame, so writing to X doesn''t touch df', 1), (@q, 'C', 'Yes: X is a view of df', 0), (@q, 'D', 'It raises SettingWithCopyWarning and changes df', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 1, 'mcq', 'In matplotlib, what is the difference between a Figure and an Axes?', NULL, NULL, 'The Figure is the whole canvas/window; an Axes is one plot area inside it, with its own x and y axis', 'One is the page, the other is a chart drawn on the page.', 'A Figure is the top-level container (the image you save). Each Axes is a single plot with its own data, ticks, labels and title. One Figure can hold many Axes.', '+---------------- Figure ----------------+\n|  +---- Axes ----+   +---- Axes ----+   |\n|  |  title       |   |  title       |   |\n|  |  y  /\\_/     |   |  y   . .     |   |\n|  |     x        |   |      x       |   |\n|  +--------------+   +--------------+   |\n+----------------------------------------+', 'Figure = the browser page; Axes = one chart component on that page.', 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The Figure is the x axis and the Axes is the y axis', 0), (@q, 'B', 'An Axes holds several Figures', 0), (@q, 'C', 'The Figure is the whole canvas/window; an Axes is one plot area inside it, with its own x and y axis', 1), (@q, 'D', 'They are two names for the same thing', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 1, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nprint(type(fig).__name__, type(ax).__name__, len(fig.axes))', 'python', 'Figure Axes 1', 'With no arguments, subplots makes one plot area.', 'plt.subplots() returns a (Figure, Axes) pair; the figure holds exactly one Axes.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Axes Figure 1', 0), (@q, 'B', 'Figure Axes 1', 1), (@q, 'C', 'Figure ndarray 1', 0), (@q, 'D', 'Figure Axes 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 1, 'fill_blank', 'The recommended way to start a plot is `fig, ax = plt.____()`.', NULL, NULL, 'subplots', 'It creates the figure and the axes in one call.', 'plt.subplots() returns the Figure and Axes objects so you can call methods on ax directly (the object-oriented style).', NULL, NULL, 3);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 1, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.plot([1, 2, 3], [4, 5, 6])\nax.plot([1, 2, 3], [6, 5, 4])\nprint(len(ax.lines))', 'python', '2', 'Each plot() call adds a line to the same Axes.', 'Calling ax.plot twice draws two lines on the same axes; ax.lines holds both Line2D objects.', NULL, NULL, 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0', 0), (@q, 'B', '6', 0), (@q, 'C', '1', 0), (@q, 'D', '2', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nresult = ax.plot([1, 2, 3])\nprint(type(result).__name__, len(result), type(result[0]).__name__)', 'python', 'list 1 Line2D', 'plot can draw several lines in one call, so it returns a container.', 'ax.plot returns a list of Line2D objects (one per line drawn). Hence the idiom `line, = ax.plot(...)` to unpack a single line.', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'list 3 float', 0), (@q, 'B', 'Line2D 1 Line2D', 0), (@q, 'C', 'Axes 1 Line2D', 0), (@q, 'D', 'list 1 Line2D', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 1, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.plot([1, 2, 3], [1, 4, 9])\nx, y = ax.lines[0].get_data()\nprint([int(v) for v in x], [int(v) for v in y])', 'python', '[1, 2, 3] [1, 4, 9]', 'plot(x, y): first argument is x.', 'With two arguments the first is x and the second is y. The Line2D object stores both.', NULL, NULL, 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 1, 2] [1, 4, 9]', 0), (@q, 'B', '[1, 2, 3] [1, 2, 3]', 0), (@q, 'C', '[1, 4, 9] [1, 2, 3]', 0), (@q, 'D', '[1, 2, 3] [1, 4, 9]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.plot([10, 20, 30])\nx, y = ax.lines[0].get_data()\nprint(list(map(int, x)))', 'python', '[0, 1, 2]', 'With one list, what does matplotlib use for x?', 'If you pass only y, matplotlib uses x = 0, 1, 2, ... (the positions). Training-loss plots made this way start at epoch 0.', NULL, NULL, 7);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 3]', 0), (@q, 'B', '[10, 20, 30]', 0), (@q, 'C', '[0, 1, 2]', 1), (@q, 'D', '[]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nprint(plt.rcParams["figure.figsize"], plt.rcParams["figure.dpi"])\nfig = plt.figure(figsize=(8, 3))\nprint(fig.get_size_inches().tolist())', 'python', '[6.4, 4.8] 100.0\n[8.0, 3.0]', 'figsize is (width, height) in inches.', 'The default size is 6.4 x 4.8 inches at 100 dpi (640 x 480 pixels). figsize=(8, 3) means 8 inches wide, 3 tall.', NULL, NULL, 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(6.4, 4.8) 100\n(8, 3)', 0), (@q, 'B', '[6.4, 4.8] 100.0\n[3.0, 8.0]', 0), (@q, 'C', '[6.4, 4.8] 100.0\n[8.0, 3.0]', 1), (@q, 'D', '[8.0, 6.0] 72.0\n[8.0, 3.0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig = plt.figure()\nax1 = fig.add_subplot(1, 2, 1)\nax2 = fig.add_subplot(1, 2, 2)\nax3 = ax1.twinx()\nprint(len(fig.axes))', 'python', '3', 'twinx creates a brand-new Axes sharing the x axis.', 'Two subplots plus a twin axes (a second y axis on the right of ax1) = 3 Axes objects in the figure.', NULL, NULL, 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4', 0), (@q, 'B', '2', 0), (@q, 'C', '3', 1), (@q, 'D', '1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 3, 'mcq', 'What is an ''Artist'' in matplotlib?', NULL, NULL, 'Any object that can be drawn on a figure: Figure, Axes, Line2D, Text, Patch, etc.', 'Everything you see is one.', 'Everything visible is an Artist. Containers (Figure, Axes) hold primitives (Line2D, Rectangle, Text). Calling ax.plot creates Line2D artists and adds them to the Axes.', NULL, NULL, 10);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A colour theme', 0), (@q, 'B', 'A function that saves a figure', 0), (@q, 'C', 'The backend that renders PNG files', 0), (@q, 'D', 'Any object that can be drawn on a figure: Figure, Axes, Line2D, Text, Patch, etc.', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 4, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.plot([1, 2])\nax.bar(["a", "b"], [1, 2])\nax.scatter([1, 2], [3, 4])\nax.text(0, 0, "hi")\nprint(len(ax.lines), len(ax.patches), len(ax.collections), len(ax.texts))', 'python', '1 2 1 1', 'Each chart type creates a different kind of Artist and stores it in a different list.', 'A line is a Line2D in ax.lines; each bar is a Rectangle patch (2 patches); scatter is one PathCollection in ax.collections; text goes to ax.texts.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 2 1 1', 1), (@q, 'B', '4 0 0 0', 0), (@q, 'C', '1 2 2 1', 0), (@q, 'D', '1 1 1 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fig-axes'), 2, 'mcq', 'Why does calling `ax.plot` twice put two lines on the same chart instead of replacing the first one?', NULL, NULL, 'An Axes is a container: every plotting call adds artists to it until you clear it', 'Think about what ax.plot does to ax.', 'An Axes accumulates artists. That is why overlaying train and val curves is just two plot calls, and why you must use ax.cla() or a new Axes to start fresh.', NULL, NULL, 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'matplotlib merges the two datasets into one line', 0), (@q, 'B', 'The second call creates a hidden second figure', 0), (@q, 'C', 'An Axes is a container: every plotting call adds artists to it until you clear it', 1), (@q, 'D', 'The first line is replaced but stays in memory', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 1, 'mcq', 'Which chart is best for showing how training loss changes over 50 epochs?', NULL, NULL, 'Line plot', 'Ordered x values, a trend over time.', 'A line plot connects values in order, which makes the trend (going down, levelling off, going up) easy to see.', NULL, NULL, 13);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Pie chart', 0), (@q, 'B', 'Line plot', 1), (@q, 'C', 'Bar chart of each epoch''s loss', 0), (@q, 'D', 'Box plot', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 1, 'mcq', 'Which chart shows the relationship between two numeric variables, such as height and weight for 500 people?', NULL, NULL, 'Scatter plot', 'One dot per person.', 'A scatter plot puts one point per row at (height, weight), so you can see correlation, clusters and outliers. A line plot would connect points in row order, which means nothing here.', NULL, NULL, 14);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Histogram', 0), (@q, 'B', 'Line plot', 0), (@q, 'C', 'Scatter plot', 1), (@q, 'D', 'Pie chart', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 1, 'mcq', 'What does a histogram show?', NULL, NULL, 'How the values of ONE numeric variable are distributed, by counting how many fall into each bin', 'Bins and counts.', 'A histogram splits the value range into bins and draws a bar for the count in each, showing the shape (skew, peaks, outliers) of the distribution.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'How two variables relate to each other', 0), (@q, 'B', 'How the values of ONE numeric variable are distributed, by counting how many fall into each bin', 1), (@q, 'C', 'Values over time', 0), (@q, 'D', 'Category totals in decreasing order', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nn, bins, patches = ax.hist([1, 2, 2, 3, 3, 3], bins=3)\nprint([int(c) for c in n], len(bins), len(patches))', 'python', '[1, 2, 3] 4 3', '3 bins need how many edges?', 'hist returns the counts per bin, the bin EDGES and the bar patches. 3 bins have 4 edges; the counts are 1, 2, 3.', NULL, NULL, 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3, 2, 1] 4 3', 0), (@q, 'B', '[1, 2, 3] 4 3', 1), (@q, 'C', '[1, 2, 3] 3 3', 0), (@q, 'D', '[6] 2 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nimport numpy as np\nfig, ax = plt.subplots()\nax.hist(np.arange(100))\nprint(len(ax.patches))', 'python', '10', 'What is the default number of bins?', 'hist uses bins=10 by default, so 10 rectangle patches. The default often hides detail; try bins=30 or bins=''auto''.', NULL, NULL, 17);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1', 0), (@q, 'B', '100', 0), (@q, 'C', '10', 1), (@q, 'D', '20', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nbars = ax.bar(["cat", "dog", "fish"], [5, 3, 1])\nprint(type(bars).__name__, len(bars), bars[0].get_height())', 'python', 'BarContainer 3 5', 'Each bar is a Rectangle; bar returns a container of them.', 'ax.bar returns a BarContainer holding one Rectangle per category; you can index it like a list and read each bar''s height.', NULL, NULL, 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Rectangle 3 5', 0), (@q, 'B', 'BarContainer 3 5', 1), (@q, 'C', 'BarContainer 1 5', 0), (@q, 'D', 'list 3 5', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nbp = ax.boxplot([1, 2, 3, 4, 100])\nprint(len(bp["fliers"][0].get_ydata()), len(bp["medians"]))', 'python', '1 1', 'Fliers are points beyond the whiskers (1.5 x IQR).', 'The box covers the middle 50% (2 to 4); whiskers extend at most 1.5 x IQR. 100 is far outside, so it is drawn as 1 flier (outlier). One box means one median line.', '   o        <- flier (100)\n\n  ---       <- whisker end\n   |\n +---+      <- Q3\n |---|      <- median\n +---+      <- Q1\n   |\n  ---', NULL, 19);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '5 1', 0), (@q, 'B', '1 5', 0), (@q, 'C', '0 1', 0), (@q, 'D', '1 1', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 2, 'mcq', 'When should you use a box plot instead of a histogram?', NULL, NULL, 'To compare the distribution of a value across several groups side by side (e.g. salary per department)', 'Box plots are compact.', 'Each box summarises a distribution in five numbers plus outliers, so many groups fit side by side. Overlaid histograms get messy beyond two or three groups.', NULL, NULL, 20);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'To show parts of a whole', 0), (@q, 'B', 'To show a trend over time', 0), (@q, 'C', 'To show one exact value', 0), (@q, 'D', 'To compare the distribution of a value across several groups side by side (e.g. salary per department)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.barh(["x", "y", "z"], [3, 1, 2])\nprint(len(ax.patches), [float(p.get_width()) for p in ax.patches])', 'python', '3 [3.0, 1.0, 2.0]', 'In a horizontal bar chart, the value is the bar''s width.', 'barh draws one horizontal Rectangle per category; the value sets the width. Horizontal bars are great when category names are long.', NULL, NULL, 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3 [1.0, 2.0, 3.0]', 0), (@q, 'B', '3 [0.8, 0.8, 0.8]', 0), (@q, 'C', '1 [3.0]', 0), (@q, 'D', '3 [3.0, 1.0, 2.0]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nsc = ax.scatter([1, 2, 3], [3, 1, 2], c=[0.1, 0.5, 0.9], s=[10, 20, 30])\nprint(type(sc).__name__, len(sc.get_offsets()), len(ax.collections))', 'python', 'PathCollection 3 1', 'A scatter is ONE collection of many markers.', 'scatter returns a single PathCollection holding all 3 points; c and s set per-point colour and size, letting you show 4 variables in one chart.', NULL, NULL, 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'PathCollection 1 3', 0), (@q, 'B', 'PathCollection 3 1', 1), (@q, 'C', 'Line2D 3 3', 0), (@q, 'D', 'list 3 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 4, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.plot([1, 2, 3], [1, 2, 3], "o")\nprint(ax.lines[0].get_linestyle(), ax.lines[0].get_marker(), len(ax.collections))', 'python', 'None o 0', 'A format string with only a marker means ''no connecting line''.', 'plot(x, y, ''o'') draws markers only (linestyle ''None''). It is still a Line2D, not a scatter collection, and is faster than scatter when all points share size and colour.', NULL, NULL, 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None o 1', 0), (@q, 'B', 'None o 0', 1), (@q, 'C', '- o 0', 0), (@q, 'D', '- None 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 3, 'mcq', 'You plot 1 million points with `ax.scatter` and the chart is a solid blob. What is the best fix?', NULL, NULL, 'Use small markers with transparency (alpha), or a 2-D density plot like hexbin / hist2d', 'Overplotting hides density.', 'When points overlap, you can''t tell 10 from 10,000. Lower alpha and marker size, sample the data, or switch to hexbin / hist2d, which show counts per region.', NULL, NULL, 24);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Plot only the first 10 points', 0), (@q, 'B', 'Use small markers with transparency (alpha), or a 2-D density plot like hexbin / hist2d', 1), (@q, 'C', 'Use a pie chart', 0), (@q, 'D', 'Use a thicker line', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'plot-types'), 4, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.errorbar([1, 2], [1, 2], yerr=0.1)\nax.fill_between([0, 1], [0, 1], [1, 2])\nax.axhline(0.5)\nprint(len(ax.lines), len(ax.collections), len(ax.containers))', 'python', '2 2 1', 'axhline is a line; fill_between is a collection; errorbar draws a line plus a collection of bars.', 'errorbar adds 1 data line plus a LineCollection for the error bars and an ErrorbarContainer; fill_between adds a PolyCollection; axhline adds a Line2D. So 2 lines, 2 collections, 1 container.', NULL, NULL, 25);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2 2 1', 1), (@q, 'B', '1 2 1', 0), (@q, 'C', '3 1 1', 0), (@q, 'D', '2 1 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'labels-legends'), 1, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.set_title("Loss")\nax.set_xlabel("epoch")\nprint(ax.get_title(), ax.get_xlabel(), repr(ax.get_ylabel()))', 'python', 'Loss epoch ''''', 'A label that was never set is an empty string.', 'set_title/set_xlabel store the text; get_ylabel returns '''' because no y label was set. Always label both axes (with units).', NULL, NULL, 26);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Loss epoch ''y''', 0), (@q, 'B', 'Loss epoch None', 0), (@q, 'C', '''Loss'' ''epoch'' ''''', 0), (@q, 'D', 'Loss epoch ''''', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'labels-legends'), 1, 'mcq', 'What does `ax.legend()` need to show an entry for a line?', NULL, NULL, 'The line must have a label, e.g. ax.plot(x, y, label=''train'')', 'Where does the legend text come from?', 'legend() collects artists that have a label. Lines without one are skipped (matplotlib warns ''No artists with labels found'').', NULL, NULL, 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Nothing: it lists every line automatically as ''line 1'', ''line 2''', 0), (@q, 'B', 'The line must have a label, e.g. ax.plot(x, y, label=''train'')', 1), (@q, 'C', 'You must call plt.show() first', 0), (@q, 'D', 'The line must be red', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'labels-legends'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.plot([1, 2], label="train")\nax.plot([2, 1], label="val")\nax.plot([1, 1])\nleg = ax.legend()\nprint([t.get_text() for t in leg.get_texts()])', 'python', '[''train'', ''val'']', 'Unlabelled lines don''t appear.', 'Only artists with a label are added to the legend; the third line has none.', NULL, NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''train'', ''val'', ''line2'']', 0), (@q, 'B', '[''train'', ''val'']', 1), (@q, 'C', '[]', 0), (@q, 'D', '[''train'', ''val'', '''']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'labels-legends'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.plot([1, 2], label="train")\nax.plot([2, 1], label="_baseline")\nprint(len(ax.legend().get_texts()))', 'python', '1', 'Labels starting with an underscore are special.', 'A label beginning with ''_'' tells legend() to ignore the artist. That''s how matplotlib hides helper artists.', NULL, NULL, 29);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0', 0), (@q, 'B', '1', 1), (@q, 'C', '2', 0), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'labels-legends'), 1, 'fill_blank', 'To set the title of an Axes object in the OO style, call `ax.____(''Accuracy'')`.', NULL, NULL, 'set_title', 'The OO setters start with set_.', 'ax.set_title sets the Axes title. The pyplot equivalent is plt.title.', NULL, NULL, 30);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'labels-legends'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.plot([0, 1], [0, 1], "r--")\nln = ax.lines[0]\nprint(ln.get_color(), ln.get_linestyle())', 'python', 'r --', 'The format string packs colour and line style.', '''r--'' means red, dashed. get_color returns the value as given (''r''); get_linestyle returns ''--''.', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'red dashed', 0), (@q, 'B', 'r -', 0), (@q, 'C', '#ff0000 --', 0), (@q, 'D', 'r --', 1);
