INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 1, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, axs = plt.subplots(2, 3)\nprint(axs.shape, len(fig.axes))', 'python', '(2, 3) 6', 'subplots(nrows, ncols).', 'subplots(2, 3) makes 2 rows x 3 columns = 6 Axes, returned as a 2-D NumPy array of shape (2, 3).', 'axs[0,0]  axs[0,1]  axs[0,2]\naxs[1,0]  axs[1,1]  axs[1,2]', 'Like a CSS grid with 2 rows and 3 columns: each cell is its own chart component.', 37);
