INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 2, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, axs = plt.subplots(2, 2)\nfor ax in axs.flat:\n    ax.plot([1, 2])\nprint(sum(len(ax.lines) for ax in fig.axes))', 'python', '4', 'axs.flat walks every Axes in the grid.', 'axs.flat (or axs.ravel()) iterates all 4 Axes regardless of grid shape; each gets one line.', NULL, NULL, 40);
