INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 2, 'mcq', 'What does `plt.subplots(2, 1, sharex=True)` do?', NULL, NULL, 'Both rows use the same x-axis range, so zooming/limits stay in sync and the top plot''s x tick labels can be hidden', 'Shared axis = shared limits.', 'sharex links the x limits of the Axes, ideal for stacking, say, loss and learning rate over the same epochs.', NULL, NULL, 42);
