INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'subplots'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nfig, axs = plt.subplots(2, 1, sharex=True)\naxs[0].plot([0, 10], [0, 1])\naxs[1].plot([0, 5], [0, 1])\nprint(axs[0].get_xlim() == axs[1].get_xlim())', 'python', 'True', 'Shared axes autoscale together.', 'With sharex=True both Axes use one x range that covers all data (0..10 plus margins), so the limits are equal.', NULL, NULL, 43);
