INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'pandas-plot'), 3, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nimport pandas as pd\ns = pd.Series(["cat", "dog", "cat", "cat"])\nax = s.value_counts().plot.bar()\nprint([t.get_text() for t in ax.get_xticklabels()], [float(p.get_height()) for p in ax.patches])', 'python', '[''cat'', ''dog''] [3.0, 1.0]', 'value_counts sorts by count, then the bar chart keeps that order.', 'value_counts gives cat 3, dog 1 (descending); plot.bar uses the index as tick labels. This is the quickest class-balance chart.', NULL, NULL, 53);
